/**
 * GLOBESKIMMERS API WORKER v7.12 - Cost Optimized
 * 
 * COST SAVINGS:
 * - Search endpoints: Advanced tier ($5/1K) - no reviews
 * - Details endpoint: Preferred tier ($20/1K) - with reviews, cached 90 days
 * - Estimated savings: ~75% on search API costs
 */

// Text Search ONLY uses the standard SEARCH mask PLUS Google's native AI
// fields. Pro/Enterprise SKU tier — same as our existing editorialSummary,
// so no per-call cost change. Scoped to handleTextSearch only so cost
// impact is isolated to text-search calls.
//
//   places.generativeSummary          — Gemini-powered place overview, lives
//                                       INSIDE each Place object.
//   contextualContents.reviews        — query-aware review snippets, lives
//                                       at the TOP LEVEL of the response as
//                                       a sibling to places[], index-aligned.
//   contextualContents.photos         — query-aware photo subset, same shape.
//
// EXPERIMENTAL — Google explicitly marks contextualContents experimental
// (per https://developers.google.com/maps/documentation/places/web-service/
//  experimental/places-generative). Field may change/disappear; integration
// is null-safe end-to-end so worst case we silently lose the feature.
//
// HISTORY: 'places.contextualContents' was tried on 2026-05-22 — Google
// returned 400 INVALID_ARGUMENT because contextualContents is NOT under
// places[]. The correct path (verified against Google's official searchText
// reference) uses no 'places.' prefix. handleTextSearch below merges the
// top-level array into each place by position before normalizePlace runs.
const TEXT_SEARCH_AI_FIELDS =
  'places.generativeSummary,contextualContents.reviews,contextualContents.photos';

const CONFIG = {
  CACHE_TTL: {
    // Fresh windows — within this age, cache is returned as-is.
    // 3 days (founder, 2026-10-07): ratings, hours and closures move slowly, and
    // "open now" is worked out fresh from the weekly hours on every read
    // (gsOpenNow) — never trusted from the cache.
    TEXT_SEARCH: 3 * 24 * 60 * 60,
    NEARBY_SEARCH: 3 * 24 * 60 * 60,
    // Google lets an app keep its data temporarily for at most 30 days (Maps
    // Platform terms 3.2.3); was 90. Reads also refuse older entries.
    DETAILS: 30 * 24 * 60 * 60,
    PHOTO: 30 * 24 * 60 * 60,
    DIETARY: 12 * 60 * 60,
    // Stale-while-revalidate windows — past the fresh window but within
    // FRESH + SWR, we return the cached response immediately AND trigger
    // a background refresh via ctx.waitUntil. KV expirationTtl is set to
    // FRESH + SWR so entries survive long enough to be served stale.
    TEXT_SEARCH_SWR: 4 * 24 * 60 * 60,  // 3d fresh + 4d stale = 7d total
    // A search that asked Google for "open now" goes stale within the hour.
    OPEN_NOW: 30 * 60,
    OPEN_NOW_SWR: 30 * 60,
    NEARBY_SEARCH_SWR: 4 * 24 * 60 * 60, // 3d fresh + 4d stale = 7d total
    STALE_WHILE_REVALIDATE: 60 * 60      // legacy constant (unused)
  },

  // SEARCH - Advanced tier ($5/1K) - NO reviews
  SEARCH_FIELD_MASK: [
    'places.id',
    'places.displayName',
    'places.formattedAddress',
    'places.shortFormattedAddress',
    'places.location',
    'places.rating',
    'places.userRatingCount',
    'places.priceLevel',
    'places.primaryType',
    'places.primaryTypeDisplayName',
    'places.types',
    'places.currentOpeningHours',
    'places.regularOpeningHours',
    'places.utcOffsetMinutes',
    'places.nationalPhoneNumber',
    'places.internationalPhoneNumber',
    'places.websiteUri',
    'places.googleMapsUri',
    'places.photos',
    'places.servesVegetarianFood',
    'places.servesBeer',
    'places.servesWine',
    'places.servesCoffee',
    'places.servesBreakfast',
    'places.servesLunch',
    'places.servesDinner',
    'places.servesBrunch',
    'places.takeout',
    'places.delivery',
    'places.dineIn',
    'places.reservable',
    'places.outdoorSeating',
    'places.liveMusic',
    'places.goodForChildren',
    'places.goodForGroups',
    'places.accessibilityOptions',
    'places.parkingOptions',
    'places.paymentOptions',
    'places.allowsDogs',
    'places.businessStatus',
    'places.servesCocktails',
    'places.editorialSummary',
    'places.menuForChildren'
  ].join(','),

  // DETAILS - Preferred tier ($20/1K) - WITH reviews
  DETAILS_FIELD_MASK: [
    'id',
    'displayName',
    'formattedAddress',
    'shortFormattedAddress',
    'location',
    'rating',
    'userRatingCount',
    'priceLevel',
    'primaryType',
    'primaryTypeDisplayName',
    'types',
    'currentOpeningHours',
    'regularOpeningHours',
    'utcOffsetMinutes',
    'nationalPhoneNumber',
    'internationalPhoneNumber',
    'websiteUri',
    'googleMapsUri',
    'photos',
    'reviews',
    'editorialSummary',
    'servesVegetarianFood',
    'servesBeer',
    'servesWine',
    'servesCoffee',
    'servesBreakfast',
    'servesLunch',
    'servesDinner',
    'servesBrunch',
    'takeout',
    'delivery',
    'dineIn',
    'reservable',
    'outdoorSeating',
    'liveMusic',
    'goodForChildren',
    'goodForGroups',
    'accessibilityOptions',
    'parkingOptions',
    'paymentOptions',
    'allowsDogs',
    'businessStatus',
    'servesCocktails',
    'menuForChildren'
  ].join(',')
};

const CORS_HEADERS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type, Authorization',
  'Access-Control-Max-Age': '86400'
};

function jsonResponse(data, status = 200) {
  return new Response(JSON.stringify(data), {
    status,
    headers: { 'Content-Type': 'application/json', ...CORS_HEADERS }
  });
}

function handleCORS() {
  return new Response(null, { status: 204, headers: CORS_HEADERS });
}

function roundCoordinate(coord, precision = 1) {
  return Math.round(coord * Math.pow(10, precision)) / Math.pow(10, precision);
}

function generateCacheKey(prefix, params) {
  const lat = roundCoordinate(parseFloat(params.latitude) || 0);
  const lng = roundCoordinate(parseFloat(params.longitude) || 0);
  const query = (params.textQuery || params.query || '').toLowerCase().trim();
  const types = (params.types || params.type || '').toLowerCase();
  const includedType = (params.includedType || '').toLowerCase();
  const radius = params.radius || '5000';
  return `${prefix}_${lat}_${lng}_${radius}_${query}_${types}_${includedType}`.replace(/\s+/g, '_');
}

async function getFromCache(env, key) {
  if (!env.GLOBESKIMMERS_KV) return null;
  try {
    const cached = await env.GLOBESKIMMERS_KV.get(key, { type: 'json' });
    if (cached) {
      const age = Date.now() - (cached.timestamp || 0);
      // Place details written under the old 90-day rule: past 30 days = a miss.
      if (key.startsWith('details_') && age > CONFIG.CACHE_TTL.DETAILS * 1000) return null;
      return { data: cached.data, age, timestamp: cached.timestamp };
    }
  } catch (e) {
    console.error('Cache read error:', e);
  }
  return null;
}

async function setInCache(env, key, data, ttl) {
  if (!env.GLOBESKIMMERS_KV) return;
  try {
    await env.GLOBESKIMMERS_KV.put(
      key,
      JSON.stringify({ data, timestamp: Date.now() }),
      { expirationTtl: ttl }
    );
  } catch (e) {
    console.error('Cache write error:', e);
  }
}

// Stale-while-revalidate cache check. Returns one of:
//   { status: 'fresh', data, cacheAge }  — within fresh TTL; serve as-is.
//   { status: 'stale', data, cacheAge }  — past fresh, within fresh+SWR;
//                                          serve immediately AND schedule
//                                          a background refresh.
//   null                                 — miss, or beyond SWR window;
//                                          caller must fetch upstream.
// `refresher` is an async closure that re-fetches from upstream and re-caches.
// Set `expirationTtl` on writes to (freshTtl + swrTtl) so entries persist
// long enough to be served stale.
async function tryCacheWithSWR(env, ctx, cacheKey, freshTtl, swrTtl, refresher) {
  const cached = await getFromCache(env, cacheKey);
  if (!cached) return null;
  const ageSec = cached.age / 1000;
  if (ageSec < freshTtl) {
    return { status: 'fresh', data: cached.data, cacheAge: Math.round(ageSec) };
  }
  if (ageSec < freshTtl + swrTtl) {
    if (ctx && typeof ctx.waitUntil === 'function') {
      ctx.waitUntil(refresher().catch(e => console.error(`SWR refresh failed for ${cacheKey}:`, e)));
    }
    return { status: 'stale', data: cached.data, cacheAge: Math.round(ageSec) };
  }
  return null;
}

function normalizePlace(place, baseUrl = '', includeReviews = false) {
  const photos = (place.photos || []).map(photo => {
    const photoName = photo.name || '';
    return {
      name: photoName,
      url: baseUrl ? `${baseUrl}/places/photo?name=${encodeURIComponent(photoName)}&maxWidth=400` : null,
      thumbnail: baseUrl ? `${baseUrl}/places/photo?name=${encodeURIComponent(photoName)}&maxWidth=200` : null,
      full: baseUrl ? `${baseUrl}/places/photo?name=${encodeURIComponent(photoName)}&maxWidth=800` : null,
      attribution: photo.authorAttributions?.[0]?.displayName || null
    };
  });

  let priceLevel = place.priceLevel;
  if (typeof priceLevel === 'string') {
    if (priceLevel.includes('FREE')) priceLevel = 0;
    else if (priceLevel.includes('INEXPENSIVE')) priceLevel = 1;
    else if (priceLevel.includes('MODERATE')) priceLevel = 2;
    else if (priceLevel.includes('EXPENSIVE') && !priceLevel.includes('VERY')) priceLevel = 3;
    else if (priceLevel.includes('VERY_EXPENSIVE')) priceLevel = 4;
    else priceLevel = null;
  }

  const hours = place.currentOpeningHours?.weekdayDescriptions ||
                place.regularOpeningHours?.weekdayDescriptions || [];
  const isOpen = place.currentOpeningHours?.openNow ?? null;

  const normalized = {
    id: place.id,
    placeId: place.id,
    name: place.displayName?.text || place.name || 'Unknown',
    displayName: place.displayName || { text: place.displayName?.text || place.name || 'Unknown' },
    address: place.formattedAddress || place.address || '',
    formattedAddress: place.formattedAddress || '',
    shortAddress: place.shortFormattedAddress || (place.formattedAddress || '').split(',')[0],
    shortFormattedAddress: place.shortFormattedAddress || '',
    location: place.location,
    latitude: place.location?.latitude,
    longitude: place.location?.longitude,
    rating: place.rating || null,
    reviewCount: place.userRatingCount || 0,
    userRatingCount: place.userRatingCount || 0,
    priceLevel,
    primaryType: place.primaryType || null,
    primaryTypeDisplay: place.primaryTypeDisplayName?.text || null,
    editorialSummary: place.editorialSummary?.text || null,   // Google's one-liner; a Why-visit input (2026-10-11)
    types: place.types || [],
    phone: place.nationalPhoneNumber || place.internationalPhoneNumber || null,
    nationalPhoneNumber: place.nationalPhoneNumber || '',
    internationalPhoneNumber: place.internationalPhoneNumber || '',
    website: place.websiteUri || null,
    websiteUri: place.websiteUri || '',
    googleMapsUrl: place.googleMapsUri || null,
    googleMapsUri: place.googleMapsUri || '',
    hours,
    isOpen,
    currentOpeningHours: place.currentOpeningHours || null,
    regularOpeningHours: place.regularOpeningHours || null,
    utcOffsetMinutes: place.utcOffsetMinutes ?? null,
    photos,
    servesVegetarianFood: place.servesVegetarianFood || false,
    servesBeer: place.servesBeer || false,
    servesWine: place.servesWine || false,
    servesCoffee: place.servesCoffee || false,
    servesBreakfast: place.servesBreakfast || false,
    servesLunch: place.servesLunch || false,
    servesDinner: place.servesDinner || false,
    servesBrunch: place.servesBrunch || false,
    takeout: place.takeout || false,
    delivery: place.delivery || false,
    dineIn: place.dineIn || false,
    reservable: place.reservable || false,
    outdoorSeating: place.outdoorSeating || false,
    liveMusic: place.liveMusic || false,
    goodForChildren: place.goodForChildren || false,
    goodForGroups: place.goodForGroups || false,
    allowsDogs: place.allowsDogs || false,
    parkingOptions: place.parkingOptions || null,
    paymentOptions: place.paymentOptions || null,
    accessibilityOptions: place.accessibilityOptions || null,
    businessStatus: place.businessStatus || null,
    servesCocktails: place.servesCocktails || false,
    // Native Google Places API (New) AI fields. Only populated for places
    // Google has analyzed AND only returned when requested via field mask
    // (currently scoped to handleTextSearch via TEXT_SEARCH_AI_FIELDS).
    generativeSummary: place.generativeSummary || null,
    contextualContents: place.contextualContents || null
  };

  if (includeReviews) {
    normalized.reviews = (place.reviews || []).slice(0, 5).map(r => ({
      author: r.authorAttribution?.displayName || 'Anonymous',
      rating: r.rating,
      text: r.text?.text || r.originalText?.text || '',
      time: r.relativePublishTimeDescription || '',
      publishTime: r.publishTime
    }));
    normalized.editorialSummary = place.editorialSummary?.text || null;
    normalized.customer_favorites = extractCustomerFavorites(place.reviews || []);
    normalized.top_reviews = normalized.reviews.slice(0, 3);
  } else {
    normalized.reviews = [];
    normalized.editorialSummary = null;
    normalized.customer_favorites = [];
    normalized.top_reviews = [];
    normalized.needsDetailsFetch = true;
  }

  return normalized;
}

// The old regex "customer favorites" is retired: on real places it surfaced
// phrases like "Just As Expected" and "Back Of The Shop". Dishes now come from
// the AI Details top-dishes list, whose counts are computed by code below.
function extractCustomerFavorites() { return []; }

async function handleTextSearch(request, env, ctx) {
  const url = new URL(request.url);
  const params = Object.fromEntries(url.searchParams);
  const textQuery = params.textQuery || params.query || '';
  const latitude = parseFloat(params.latitude) || 0;
  const longitude = parseFloat(params.longitude) || 0;
  const radius = Math.min(parseInt(params.radius) || 5000, 50000);
  const maxResults = Math.min(parseInt(params.maxResults) || 20, 60);
  const forceRefresh = params.forceRefresh === 'true';

  if (!textQuery) {
    return jsonResponse({ error: 'textQuery is required', places: [] }, 400);
  }

  const apiKey = env.GOOGLE_API_KEY;
  const baseUrl = url.origin;
  const cacheKey = generateCacheKey('text', params);
  const FRESH = CONFIG.CACHE_TTL.TEXT_SEARCH;
  const SWR = CONFIG.CACHE_TTL.TEXT_SEARCH_SWR;

  const fetchAndCache = async () => {
    const response = await fetch('https://places.googleapis.com/v1/places:searchText', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Goog-Api-Key': apiKey,
        'X-Goog-FieldMask': CONFIG.SEARCH_FIELD_MASK + ',' + TEXT_SEARCH_AI_FIELDS
      },
      body: JSON.stringify({
        textQuery,
        languageCode: "en",
        maxResultCount: maxResults,
        locationBias: { circle: { center: { latitude, longitude }, radius } },
        ...(params.includedType ? { includedType: params.includedType, strictTypeFiltering: false } : {})
      })
    });
    if (!response.ok) {
      const errorText = await response.text();
      const err = new Error(errorText);
      err.upstreamStatus = response.status;
      throw err;
    }
    const data = await response.json();
    // contextualContents is a top-level array, index-aligned with places[].
    // Inject each entry onto its place so normalizePlace's existing
    // passthrough (line ~295) surfaces it on the normalized object.
    const contextualContents = data.contextualContents || [];
    const places = (data.places || []).map((p, i) => {
      p.contextualContents = contextualContents[i] || null;
      return normalizePlace(p, baseUrl, false);
    });
    await setInCache(env, cacheKey, places, FRESH + SWR);
    return places;
  };

  if (!forceRefresh) {
    const hit = await tryCacheWithSWR(env, ctx, cacheKey, FRESH, SWR, fetchAndCache);
    if (hit) {
      const live = gsFreshOpen(hit.data);
      return jsonResponse({ places: live, count: live.length, cached: true, stale: hit.status === 'stale', cacheAge: hit.cacheAge });
    }
  }

  try {
    const places = gsFreshOpen(await fetchAndCache());
    return jsonResponse({ places, count: places.length, cached: false, stale: false });
  } catch (error) {
    return jsonResponse({ error: 'Google Places API error', status: error.upstreamStatus, details: error.message, places: [] }, 200);
  }
}

async function handleNearbySearch(request, env, ctx) {
  const url = new URL(request.url);
  const params = Object.fromEntries(url.searchParams);
  const latitude = parseFloat(params.latitude) || 0;
  const longitude = parseFloat(params.longitude) || 0;
  const types = params.types || params.type || 'restaurant';
  const radius = Math.min(parseInt(params.radius) || 5000, 50000);
  const maxResults = Math.min(parseInt(params.maxResults) || 20, 20);
  const forceRefresh = params.forceRefresh === 'true';
  const openNow = params.openNow === 'true';
  const minRating = parseFloat(params.minRating) || 0;
  const priceLevels = params.priceLevels ? params.priceLevels.split(',') : [];

  // v3: ONE unfiltered list per area; open-now / rating / price are applied on
  // every read — a cached "open now" list was wrong within hours.
  const cacheKey = generateCacheKey('nearby', { ...params, types }) + '_v3';

  const apiKey = env.GOOGLE_API_KEY;
  const baseUrl = url.origin;
  const FRESH = CONFIG.CACHE_TTL.NEARBY_SEARCH;
  const SWR = CONFIG.CACHE_TTL.NEARBY_SEARCH_SWR;

  const requestBody = {
    includedTypes: types.split(',').map(t => t.trim()),
    languageCode: "en",
    maxResultCount: maxResults,
    locationRestriction: { circle: { center: { latitude, longitude }, radius } },
    rankPreference: params.rankBy === 'DISTANCE' ? 'DISTANCE' : 'POPULARITY'
  };

  // Google's searchNearby accepts NONE of openNow / minRating / priceLevels
  // (those are searchText-only). Sending them failed the whole request, so any
  // browse with Open now, a rating or a price filter silently lost its nearby
  // fan-out (found 2026-10-07: Tokyo, price <= 2 → 3 results). Fetch unfiltered,
  // then filter the normalized places here.
  const PRICE_NUM = { PRICE_LEVEL_FREE: 0, PRICE_LEVEL_INEXPENSIVE: 1, PRICE_LEVEL_MODERATE: 2, PRICE_LEVEL_EXPENSIVE: 3, PRICE_LEVEL_VERY_EXPENSIVE: 4 };
  const allowedPrice = new Set(priceLevels.map((x) => PRICE_NUM[x]).filter((n) => n != null));
  const applyFilters = (list) => list.filter((pl) =>
    (!openNow || pl.isOpen === true) &&
    (!(minRating > 0) || (pl.rating || 0) >= minRating) &&
    (!allowedPrice.size || pl.priceLevel == null || allowedPrice.has(pl.priceLevel)));

  const fetchAndCache = async () => {
    const response = await fetch('https://places.googleapis.com/v1/places:searchNearby', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Goog-Api-Key': apiKey,
        // Include generativeSummary (Gemini AI overview) so ThingsToDo nearby
        // results carry historical/contextual content for the "About This Place"
        // panel, same as the text-search and restaurant-search endpoints.
        // Same Pro/Enterprise SKU, no per-call cost change.
        'X-Goog-FieldMask': CONFIG.SEARCH_FIELD_MASK + ',places.generativeSummary'
      },
      body: JSON.stringify(requestBody)
    });
    if (!response.ok) {
      const errorText = await response.text();
      const err = new Error(errorText);
      err.upstreamStatus = response.status;
      throw err;
    }
    const data = await response.json();
    const places = (data.places || []).map(p => normalizePlace(p, baseUrl, false));
    await setInCache(env, cacheKey, places, FRESH + SWR);
    return places;
  };

  if (!forceRefresh) {
    const hit = await tryCacheWithSWR(env, ctx, cacheKey, FRESH, SWR, fetchAndCache);
    if (hit) {
      const live = applyFilters(gsFreshOpen(hit.data));
      return jsonResponse({ places: live, count: live.length, cached: true, stale: hit.status === 'stale', cacheAge: hit.cacheAge });
    }
  }

  try {
    const places = applyFilters(gsFreshOpen(await fetchAndCache()));
    return jsonResponse({ places, count: places.length, cached: false, stale: false });
  } catch (error) {
    return jsonResponse({ error: 'Google Places API error', status: error.upstreamStatus, details: error.message, places: [] }, 200);
  }
}

async function handlePlaceDetails(request, env) {
  const url = new URL(request.url);
  const pathname = url.pathname;
  const pathParts = pathname.split('/');
  const placeId = pathParts[pathParts.length - 1];

  if (!placeId) {
    return jsonResponse({ error: 'Place ID required' }, 400);
  }

  const forceRefresh = url.searchParams.get('forceRefresh') === 'true';
  const cacheKey = `details_${placeId}`;

  if (!forceRefresh) {
    const cached = await getFromCache(env, cacheKey);
    if (cached) {
      return jsonResponse({ place: cached.data, cached: true, cacheAge: Math.round(cached.age / 1000) });
    }
  }

  const apiKey = env.GOOGLE_API_KEY;
  const baseUrl = url.origin;

  try {
    const response = await fetch(`https://places.googleapis.com/v1/places/${placeId}?languageCode=en`, {
      method: 'GET',
      headers: {
        'X-Goog-Api-Key': apiKey,
        'X-Goog-FieldMask': CONFIG.DETAILS_FIELD_MASK
      }
    });

    if (!response.ok) {
      const errorText = await response.text();
      return jsonResponse({ error: 'Place not found', status: response.status, details: errorText }, 404);
    }

    const place = await response.json();
    const normalized = normalizePlace(place, baseUrl, true);
    await setInCache(env, cacheKey, normalized, CONFIG.CACHE_TTL.DETAILS);
    return jsonResponse({ place: normalized, cached: false });
  } catch (error) {
    return jsonResponse({ error: error.message }, 500);
  }
}

// Photo widths we serve (each is a separate Google charge + cache entry): a
// request snaps UP to the nearest one, so nobody can bill arbitrary widths.
const PHOTO_WIDTHS = [200, 400, 800, 1200];
async function handlePhotoProxy(request, env) {
  const url = new URL(request.url);
  const photoName = url.searchParams.get('name');
  const asked = parseInt(url.searchParams.get('maxWidth') || '400', 10) || 400;
  const maxWidth = String(PHOTO_WIDTHS.find((w) => w >= asked) || PHOTO_WIDTHS[PHOTO_WIDTHS.length - 1]);

  if (!photoName) {
    return jsonResponse({ error: 'Photo name required' }, 400);
  }
  // Only a real Places photo name may reach a Google URL signed with our key.
  if (!/^places\/[A-Za-z0-9_-]{10,300}\/photos\/[A-Za-z0-9_-]{10,1200}$/.test(photoName)) {
    return jsonResponse({ error: 'Bad photo name' }, 400);
  }

  // KV keys cap at 512 bytes; long photo names hash so they still cache (an
  // uncacheable name was a fresh Google charge on every single view).
  const rawKey = `photo_${photoName}_${maxWidth}`;
  const cacheKey = rawKey.length > 480 ? `photo_h_${(await sha256Hex(photoName)).slice(0, 40)}_${maxWidth}` : rawKey;

  if (env.GLOBESKIMMERS_KV) {
    try {
      // Photos carry their save time; untimed ones are from the old 90-day rule.
      const { value: cached, metadata } = await env.GLOBESKIMMERS_KV.getWithMetadata(cacheKey, { type: 'arrayBuffer' });
      if (cached && Date.now() - (metadata?.t || 0) <= CONFIG.CACHE_TTL.PHOTO * 1000) {
        return new Response(cached, {
          headers: { 'Content-Type': 'image/jpeg', 'Cache-Control': 'public, max-age=604800', 'X-Cache': 'HIT', ...CORS_HEADERS }
        });
      }
    } catch (e) {
      console.error('Photo cache read error:', e);
    }
  }

  const apiKey = env.GOOGLE_API_KEY;
  const photoUrl = `https://places.googleapis.com/v1/${photoName}/media?maxWidthPx=${maxWidth}&key=${apiKey}`;

  try {
    let photoRes = await fetch(photoUrl);
    if (!photoRes.ok && (photoRes.status === 400 || photoRes.status === 404)) {
      // Google photo names go stale. Self-heal: ask the place for a fresh
      // photo list (the photos field rides the IDs-only Details tier) and
      // serve its first photo — then the bytes cache under the STALE key too,
      // so every later request for this old link is a free KV hit.
      const pid = photoName.split('/')[1];
      try {
        const fr = await fetch(`https://places.googleapis.com/v1/places/${pid}`, { headers: { 'X-Goog-Api-Key': apiKey, 'X-Goog-FieldMask': 'photos' } });
        const fresh = fr.ok ? (await fr.json())?.photos?.[0]?.name : null;
        if (fresh && /^places\/[A-Za-z0-9_-]+\/photos\/[A-Za-z0-9_-]+$/.test(fresh)) {
          photoRes = await fetch(`https://places.googleapis.com/v1/${fresh}/media?maxWidthPx=${maxWidth}&key=${apiKey}`);
        }
      } catch { /* fall through to not-found */ }
    }
    if (!photoRes.ok) {
      return jsonResponse({ error: 'Photo not found' }, 404);
    }

    const photoBuffer = await photoRes.arrayBuffer();
    const contentType = photoRes.headers.get('Content-Type') || 'image/jpeg';

    if (env.GLOBESKIMMERS_KV) {
      try {
        await env.GLOBESKIMMERS_KV.put(cacheKey, photoBuffer, { expirationTtl: CONFIG.CACHE_TTL.PHOTO, metadata: { t: Date.now() } });
      } catch (e) {
        console.error('Photo cache write error:', e);
      }
    }

    return new Response(photoBuffer, {
      headers: { 'Content-Type': contentType, 'Cache-Control': 'public, max-age=604800', 'X-Cache': 'MISS', ...CORS_HEADERS }
    });
  } catch (error) {
    return jsonResponse({ error: error.message }, 500);
  }
}

async function handleDietarySearch(request, env) {
  const url = new URL(request.url);
  const params = Object.fromEntries(url.searchParams);
  const dietary = params.dietary || '';
  const latitude = parseFloat(params.latitude) || 0;
  const longitude = parseFloat(params.longitude) || 0;
  const radius = Math.min(parseInt(params.radius) || 5000, 50000);
  const maxResults = Math.min(parseInt(params.maxResults) || 20, 60);
  const forceRefresh = params.forceRefresh === 'true';

  const dietaryQueries = {
    vegetarian: 'vegetarian restaurant',
    vegan: 'vegan restaurant',
    glutenFree: 'gluten free restaurant',
    halal: 'halal restaurant',
    kosher: 'kosher restaurant'
  };

  const textQuery = dietaryQueries[dietary] || `${dietary} restaurant`;
  const cacheKey = generateCacheKey('dietary', { latitude, longitude, radius, textQuery: dietary });

  if (!forceRefresh) {
    const cached = await getFromCache(env, cacheKey);
    if (cached && cached.age < CONFIG.CACHE_TTL.DIETARY * 1000) {
      return jsonResponse({ places: cached.data, count: cached.data.length, dietary, cached: true, cacheAge: Math.round(cached.age / 1000) });
    }
  }

  const apiKey = env.GOOGLE_API_KEY;
  const baseUrl = url.origin;

  try {
    const response = await fetch('https://places.googleapis.com/v1/places:searchText', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Goog-Api-Key': apiKey,
        'X-Goog-FieldMask': CONFIG.SEARCH_FIELD_MASK
      },
      body: JSON.stringify({
        textQuery,
        languageCode: "en",
        maxResultCount: maxResults,
        locationBias: { circle: { center: { latitude, longitude }, radius } }
      })
    });

    if (!response.ok) {
      const errorText = await response.text();
      return jsonResponse({ error: 'Dietary search failed', details: errorText, places: [] }, 200);
    }

    const data = await response.json();
    let places = (data.places || []).map(p => normalizePlace(p, baseUrl, false));
    // Native boolean verification: Google Places API (New) only exposes
    // servesVegetarianFood (there is no servesVeganFood field). Use it to
    // prefer verified vegetarian places, but fall back to the full set if
    // Google hasn't populated the boolean for most results.
    if (dietary === 'vegetarian') {
      const verified = places.filter(p => p.servesVegetarianFood === true);
      if (verified.length >= 3) places = verified;
    }
    await setInCache(env, cacheKey, places, CONFIG.CACHE_TTL.DIETARY);
    return jsonResponse({ places, count: places.length, dietary, cached: false });
  } catch (error) {
    return jsonResponse({ error: error.message, places: [] }, 200);
  }
}

async function handleCoffeeSearch(request, env) {
  const url = new URL(request.url);
  const params = Object.fromEntries(url.searchParams);
  const latitude = parseFloat(params.latitude) || 0;
  const longitude = parseFloat(params.longitude) || 0;
  const radius = Math.min(parseInt(params.radius) || 5000, 50000);
  const maxResults = Math.min(parseInt(params.maxResults) || 20, 40);
  const query = params.query || 'coffee shop cafe';
  const forceRefresh = params.forceRefresh === 'true';

  const cacheKey = generateCacheKey('coffee', { latitude, longitude, radius, textQuery: query });

  if (!forceRefresh) {
    const cached = await getFromCache(env, cacheKey);
    if (cached && cached.age < CONFIG.CACHE_TTL.TEXT_SEARCH * 1000) {
      return jsonResponse({ places: gsFreshOpen(cached.data), count: cached.data.length, cached: true });
    }
  }

  const apiKey = env.GOOGLE_API_KEY;
  const baseUrl = url.origin;

  try {
    const response = await fetch('https://places.googleapis.com/v1/places:searchText', {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'X-Goog-Api-Key': apiKey,
        'X-Goog-FieldMask': CONFIG.SEARCH_FIELD_MASK
      },
      body: JSON.stringify({
        textQuery: query,
        languageCode: "en",
        maxResultCount: maxResults,
        locationBias: { circle: { center: { latitude, longitude }, radius } }
      })
    });

    if (!response.ok) {
      const errorText = await response.text();
      return jsonResponse({ error: 'Coffee search failed', details: errorText, places: [] }, 200);
    }

    const data = await response.json();
    const places = (data.places || []).map(p => normalizePlace(p, baseUrl, false));
    await setInCache(env, cacheKey, places, CONFIG.CACHE_TTL.TEXT_SEARCH);
    return jsonResponse({ places: gsFreshOpen(places), count: places.length, cached: false });
  } catch (error) {
    return jsonResponse({ error: error.message, places: [] }, 200);
  }
}

async function handleRestaurantSearch(request, env, ctx) {
  try {
    const body = await request.json();
    const { latitude, longitude, radiusMiles = 10, query = '', category = '', cuisineType = '', dietary = '', forceRefresh = false, openNow = false, minRating = 0, priceLevels = [], includedType = '' } = body;

    if (!latitude || !longitude) {
      return jsonResponse({ error: 'Latitude and longitude required', restaurants: [] }, 400);
    }

    const radiusMeters = Math.min(radiusMiles * 1609.34, 50000);
    const apiKey = env.GOOGLE_API_KEY;
    const url = new URL(request.url);
    const baseUrl = url.origin;

    let searchQuery = query || 'restaurant';
    if (cuisineType && cuisineType !== 'all') searchQuery = `${cuisineType} restaurant`;
    if (category && category !== 'all' && category !== 'All Food') searchQuery = `${category} restaurant`;
    if (dietary) searchQuery = `${dietary} ${searchQuery}`;

    const filterSuffix = [openNow ? 'open' : '', minRating > 0 ? `r${minRating}` : '', priceLevels?.length ? priceLevels.join('-') : '', includedType ? `t-${includedType}` : '', `rad${Math.round(radiusMiles)}`].filter(Boolean).join('_');
    const cacheKey = generateCacheKey('restaurants', { latitude, longitude, radius: radiusMeters, textQuery: searchQuery }) + (filterSuffix ? `_${filterSuffix}` : '');
    // Google answered "open now" for the moment it was asked: keep that 30 min.
    const FRESH = openNow ? CONFIG.CACHE_TTL.OPEN_NOW : CONFIG.CACHE_TTL.TEXT_SEARCH;
    const SWR = openNow ? CONFIG.CACHE_TTL.OPEN_NOW_SWR : CONFIG.CACHE_TTL.TEXT_SEARCH_SWR;
    const liveList = (list) => { const l = gsFreshOpen(list); return openNow ? l.filter((p) => p.isOpen !== false) : l; };

    const requestBody = {
      textQuery: searchQuery,
      languageCode: "en",
      maxResultCount: 60,
      rankPreference: 'RELEVANCE',
      locationBias: { circle: { center: { latitude, longitude }, radius: radiusMeters } }
    };

    if (openNow) requestBody.openNow = true;
    if (minRating > 0) requestBody.minRating = minRating;
    if (priceLevels?.length) requestBody.priceLevels = priceLevels;
    if (includedType) { requestBody.includedType = includedType; requestBody.strictTypeFiltering = false; }

    const fetchAndCache = async () => {
      const response = await fetch('https://places.googleapis.com/v1/places:searchText', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Goog-Api-Key': apiKey,
          // POST / is the main search endpoint the Base44 orchestration layer
          // calls. Include the AI fields here (same as handleTextSearch above)
          // so generativeSummary + contextualContents flow on every search,
          // not just the fallback path.
          'X-Goog-FieldMask': CONFIG.SEARCH_FIELD_MASK + ',' + TEXT_SEARCH_AI_FIELDS
        },
        body: JSON.stringify(requestBody)
      });
      if (!response.ok) {
        const errorText = await response.text();
        const err = new Error(errorText);
        err.upstreamStatus = response.status;
        throw err;
      }
      const data = await response.json();
      // contextualContents is a top-level array, index-aligned with places[].
      // Inject each entry onto its place so normalizePlace's existing
      // passthrough surfaces it on the normalized object.
      const contextualContents = data.contextualContents || [];
      const restaurants = (data.places || []).map((p, i) => {
        p.contextualContents = contextualContents[i] || null;
        const normalized = normalizePlace(p, baseUrl, false);
        return { ...normalized, customer_favorites: [], top_reviews: [], needsDetailsFetch: true };
      });
      await setInCache(env, cacheKey, restaurants, FRESH + SWR);
      return restaurants;
    };

    if (!forceRefresh) {
      const hit = await tryCacheWithSWR(env, ctx, cacheKey, FRESH, SWR, fetchAndCache);
      if (hit) {
        const live = liveList(hit.data);
        return jsonResponse({ restaurants: live, places: live, count: live.length, cached: true, stale: hit.status === 'stale', cacheAge: hit.cacheAge });
      }
    }

    const restaurants = liveList(await fetchAndCache());
    return jsonResponse({ restaurants, places: restaurants, count: restaurants.length, cached: false, stale: false, note: 'Reviews available via /places/details/{id}' });
  } catch (error) {
    return jsonResponse({ error: error.message, restaurants: [], places: [] }, 200);
  }
}

// ── P3 — /log-event endpoint (Phase 2 analytics scaffold) ─────────────────
// Accepts POST body { event_type, page, payload?, session_id?, user_id?,
// ua_summary? } and inserts a row into the D1 events table.
//
// Until the D1 binding is provisioned (wrangler d1 create + uncomment
// wrangler.toml block + run analytics-schema.sql), this endpoint NO-OPs
// gracefully: returns 200 { logged: false, reason: 'no_db_binding' } so
// the frontend can fire events without crashing.
//
// Once the binding is live, env.DB will be defined and the endpoint will
// actually persist rows. ts is server-issued (don't trust client clocks).
// ── The founder's bell (founder, 2026-10-05) ────────────────────────────────
// Instant alerts to the founder's own phone: a new phone's first open (the
// real-time face of a store download — stores only report counts next day) and
// every stamp. Transport: ntfy push when NTFY_TOPIC is set (free; the ntfy app
// subscribes to the secret topic) and/or a Twilio SMS when TWILIO_SID,
// TWILIO_TOKEN, TWILIO_FROM and FOUNDER_PHONE are set. Never blocks the request.
// Capped so a busy day — or a script — can never flood a phone or a bill, and
// so no kind of alert can silence another (go-live rounds 2 and 3): each tag
// has its own daily allowance (BELL_CAPS) — 'urgent' (a child-safety report)
// 50, 'report' (reports and blocks) 200, 'ops' (a clean-up that keeps
// failing) 20, 'new' (downloads, new members, the morning digest) 100, and
// everything else ('bell': stamps) 400. opts.by (the reporter's user id):
// one person's reports and blocks ring at most 10 times a day, and their
// child-safety reports at most 3 more on their own allowance, so neither a
// run of ordinary blocks nor anyone's flood can use up someone's child-safety
// ring. What is filed past a cap still reaches Admin → Safety reports, just
// without a ring; the first alert past a tag's daily allowance rings once
// instead, to say that tag is paused for the day. The counts are D1 rows
// counted atomically (gbDayCount), so a burst of parallel requests can't
// slip past them.
// opts.click (2026-10-13): where tapping the ntfy alert goes (ntfy's Click
// header), e.g. an app deep link. SMS has no tap target, so Twilio ignores it.
// A topic name on ntfy.sh is all anyone needs to read its alerts, so it is a
// secret: never write it into this (public) repo. NTFY_TOKEN, when set, is an
// ntfy.sh access token for a reserved topic that denies anonymous access; the
// alert then carries it, and knowing the topic name is no longer enough.
const BELL_CAPS = { urgent: 50, report: 200, ops: 20, new: 100, bell: 400, mail: 300 };
const BELL_PER_REPORTER_MAX = 10;
const BELL_URGENT_PER_REPORTER_MAX = 3;
const BELL_PAUSED = {
  urgent: 'Child-safety alerts paused for today after 50 — more are waiting in Admin → Safety reports.',
  report: 'Report and block alerts paused for today after 200 — the rest are in Admin → Safety reports.',
  ops: 'Clean-up alerts paused for today after 20.',
  new: 'New download and new member alerts paused for today after 100.',
  bell: 'Stamp alerts paused for today after 400.',
  mail: 'Postcard and telegram alerts paused for today after 300.',
};
async function founderAlert(env, text, tag = 'bell', opts = {}) {
  try {
    if (!env.NTFY_TOPIC && !env.TWILIO_SID) return;
    const bucket = Object.prototype.hasOwnProperty.call(BELL_CAPS, tag) ? tag : 'bell';
    // The person first: past their own allowance, nothing of the day's is used.
    const by = typeof opts?.by === 'string' && opts.by ? opts.by : null;
    if (by) {
      const urgent = bucket === 'urgent';
      const mine = await gbDayCount(env, `bell:${urgent ? 'byu' : 'by'}:${by}`);
      if (mine != null && mine > (urgent ? BELL_URGENT_PER_REPORTER_MAX : BELL_PER_REPORTER_MAX)) return;
    }
    const n = await gbDayCount(env, `bell:${bucket}`);
    const cap = BELL_CAPS[bucket];
    if (n != null && n > cap) {
      if (n === cap + 1) await gbBellSend(env, `⚠️ ${BELL_PAUSED[bucket]}`, bucket === 'urgent' ? 'urgent' : 'ops');
      return;
    }
    await gbBellSend(env, text, tag, opts);
  } catch { /* the bell never breaks the app */ }
}
// Who, for the founder's bell only (founder, 2026-10-28: "allow admin to know name of who is stamping, name and
// from what location"): the member's first name, @username and member number — "You" for an admin. These words
// reach the founder's private topic and nothing member-facing.
async function gbWhoLine(env, user) {
  const mine = ADMIN_EMAILS_WORKER.includes(String(user?.email || '').trim().toLowerCase());
  if (mine) return { who: 'You', n: null };
  const [n, pr, sh] = await Promise.all([
    gbMemberNumber(env, user.id).catch(() => null),
    gbRest(env, `profiles?id=eq.${user.id}&select=first_name,display_name`, { headers: { 'Accept-Profile': 'public' } }).then((r) => (r.ok ? r.json() : [])).catch(() => []),
    gbRest(env, `passport_shares?user_id=eq.${user.id}&select=handle`, {}).then((r) => (r.ok ? r.json() : [])).catch(() => []),
  ]);
  const name = String(pr[0]?.first_name || pr[0]?.display_name || '').trim();
  const handle = sh[0]?.handle ? `@${sh[0].handle}` : '';
  const label = [name, handle].filter(Boolean).join(' ');
  return { who: label ? `${label}${n ? ` (#${n})` : ''}` : n ? `Member #${n}` : 'A member', n };
}
// Where, for the bell: the connection's city and region as Cloudflare reads the network (not the member's GPS),
// then the country gbConnectionPlace names. "" when nothing is known.
function gbWhereLine(request) {
  try {
    const cf = request?.cf || {};
    const local = [cf.city, cf.region].filter((v) => typeof v === 'string' && v.trim()).join(', ');
    const place = gbConnectionPlace(request);
    if (place && place !== 'via Tor') return ` · from ${local ? `${local}, ` : ''}${place.replace(/^in /, '')}`;
    return place ? ` · ${place}` : local ? ` · from ${local}` : '';
  } catch { return ''; }
}
// The founder's activity bell for usernames and mail (founder, 2026-10-26: "i want to get a notification when a
// @handle is created, when postcard or when telegram is sent"). Who (name, @username and member number since
// 2026-10-28 — "You" for an admin) and where they connected from, and what kind and how many; never a message's
// words, photo or place, nor who it went to: mail stays between its sender and its recipients. A tap opens the
// member in Admin. line(who) → the alert's text.
async function gbActivityBell(env, user, tag, line, request = null) {
  try {
    const { who, n } = await gbWhoLine(env, user);
    await founderAlert(env, `${line(who)}${gbWhereLine(request)}`, tag, n ? { click: gbMemberLink(n) } : {});
  } catch { /* the bell never breaks the app */ }
}
const gbPeople = (k) => `${k} ${k === 1 ? 'person' : 'people'}`;
// The transport: ntfy and/or Twilio, whichever are configured. Each send gets one retry (after
// a network error, a 5xx or a 429), and one that still fails is recorded as 'bell_failed' in
// the events DB: the transport, the alert's kind and the status, never the text or the topic
// (2026-10-14: a stamp alert the founder never saw could not be traced).
async function gbBellSend(env, text, tag, opts = {}) {
  const sends = [];
  if (env.NTFY_TOPIC) {
    // Only a plain printable-ASCII link can ride in a header; anything else is dropped, never the alert.
    const click = typeof opts?.click === 'string' && /^[\x21-\x7e]{1,500}$/.test(opts.click) ? opts.click : null;
    sends.push(['ntfy', () => fetch(`https://ntfy.sh/${env.NTFY_TOPIC}`, {
      method: 'POST', body: text,
      headers: {
        // Every alert is high priority (4: time-sensitive on an iPhone, so it shows through
        // a Focus; stamp alerts too since 2026-10-14, when one at 3 went unseen); 'urgent'
        // (a child-safety report, 24h triage) is 5. The tag tells them apart.
        Title: 'GlobeSkimmers', Tags: tag === 'new' ? 'tada' : tag === 'urgent' ? 'rotating_light' : tag === 'report' ? 'triangular_flag_on_post' : tag === 'ops' ? 'warning' : tag === 'mail' ? 'envelope' : 'round_pushpin', Priority: tag === 'urgent' ? '5' : '4',
        ...(click ? { Click: click } : {}),
        ...(env.NTFY_TOKEN ? { Authorization: `Bearer ${env.NTFY_TOKEN}` } : {}),
      },
    })]);
  }
  if (env.TWILIO_SID && env.TWILIO_TOKEN && env.TWILIO_FROM && env.FOUNDER_PHONE) {
    sends.push(['sms', () => fetch(`https://api.twilio.com/2010-04-01/Accounts/${env.TWILIO_SID}/Messages.json`, {
      method: 'POST',
      headers: { Authorization: 'Basic ' + btoa(`${env.TWILIO_SID}:${env.TWILIO_TOKEN}`), 'Content-Type': 'application/x-www-form-urlencoded' },
      body: new URLSearchParams({ To: env.FOUNDER_PHONE, From: env.TWILIO_FROM, Body: text }),
    })]);
  }
  const ok = await Promise.all(sends.map(([via, go]) => gbBellTry(env, via, tag, go)));
  // Nothing is lost (2026-10-20: ntfy answered 429 to 47 alerts in a week — anonymous sends from
  // Cloudflare's shared addresses share one allowance): a refused alert waits in KV and goes out
  // in the hourly roundup (gbBellFlush), by ntfy if it answers, else by email to the founder.
  if (ok.length && !ok.some(Boolean)) await gbBellQueue(env, text, tag);
}
const BELL_Q = 'bellq:v1';
async function gbBellQueue(env, text, tag) {
  const kv = env.GLOBESKIMMERS_KV;
  if (!kv) return;
  try {
    let q = []; try { q = JSON.parse((await kv.get(BELL_Q)) || '[]'); } catch { q = []; }
    q.push({ t: String(text || '').slice(0, 400), tag: String(tag || 'bell'), at: Date.now() });
    await kv.put(BELL_Q, JSON.stringify(q.slice(-200)), { expirationTtl: 7 * 86400 });
  } catch { /* the bell never breaks the app */ }
}
// The hourly roundup of alerts that couldn't go out: one ntfy message, else one email.
async function gbBellFlush(env) {
  const kv = env.GLOBESKIMMERS_KV;
  if (!kv) return;
  let q = []; try { q = JSON.parse((await kv.get(BELL_Q)) || '[]'); } catch { q = []; }
  if (!q.length) return;
  const fmt = (x) => `• ${new Date(x.at).toISOString().slice(11, 16)} UTC — ${x.t}`;
  const lines = q.map(fmt);
  const head = `${q.length} alert${q.length === 1 ? '' : 's'} waited while ntfy was busy:`;
  let body = `${head}\n${lines.join('\n')}`;
  if (body.length > 3800) body = `${head}\n${lines.slice(-40).join('\n')}\n…and ${Math.max(0, lines.length - 40)} earlier.`;
  let sent = false;
  if (env.NTFY_TOPIC) {
    try {
      const r = await fetch(`https://ntfy.sh/${env.NTFY_TOPIC}`, { method: 'POST', body, headers: { Title: 'GlobeSkimmers - alerts that waited', Tags: 'inbox_tray', Priority: '4', ...(env.NTFY_TOKEN ? { Authorization: `Bearer ${env.NTFY_TOKEN}` } : {}) } });
      sent = r.ok;
    } catch { sent = false; }
  }
  if (!sent && env.RESEND_API_KEY) {
    try {
      const r = await fetch('https://api.resend.com/emails', {
        method: 'POST',
        headers: { Authorization: `Bearer ${env.RESEND_API_KEY}`, 'Content-Type': 'application/json' },
        body: JSON.stringify({ from: env.RESEND_FROM || 'GlobeSkimmers <hello@globeskimmers.io>', to: [env.FOUNDER_ALERT_EMAIL || 'founder@globeskimmers.io'], subject: `GlobeSkimmers: ${q.length} alert${q.length === 1 ? '' : 's'} that waited`, text: body }),
        signal: AbortSignal.timeout(8000),
      });
      sent = r.ok;
      if (sent) await gbLogEvent(env, 'bell_emailed', { n: q.length });
    } catch { sent = false; }
  }
  if (sent) await kv.delete(BELL_Q).catch(() => {});
}
// One alert over one transport: true once it's accepted; else a retry, then a record.
async function gbBellTry(env, via, tag, go) {
  let status = 'network';
  for (let i = 0; i < 2; i++) {
    try {
      const r = await go();
      if (r.ok) return true;
      status = r.status;
      if (r.status < 500 && r.status !== 429) break; // a refusal won't change on a retry
    } catch { status = 'network'; }
    if (i === 0) await new Promise((res) => setTimeout(res, 1500));
  }
  await gbLogEvent(env, 'bell_failed', { via, tag, status });
  return false;
}

// ── Daily counters (go-live round 3) ────────────────────────────────────────
// Caps that must hold under a burst — the bell, safety filings, uploads —
// count in D1 (events DB), one row per counter per UTC day: an INSERT … ON
// CONFLICT DO UPDATE … RETURNING is one atomic statement, so parallel requests
// each get their own number (a KV read-then-write let a burst all read the
// same count, and KV takes about one write a second per key). Returns the new
// count, or null when nothing could count (a caller then lets the action
// through: these are abuse caps, never what keeps the app working). Without
// D1 the count falls back to KV, as before. Rows older than two days are
// deleted by the daily cron (gbDayCountsPrune).
const DAY_COUNTS_SQL = 'CREATE TABLE IF NOT EXISTS day_counts (k TEXT PRIMARY KEY, day TEXT NOT NULL, n INTEGER NOT NULL)';
let DAY_COUNTS_READY = false;
async function gbDayCount(env, name, now = new Date()) {
  const day = now.toISOString().slice(0, 10);
  if (env.DB) {
    try {
      if (!DAY_COUNTS_READY) { await env.DB.prepare(DAY_COUNTS_SQL).run(); DAY_COUNTS_READY = true; }
      const r = await env.DB.prepare('INSERT INTO day_counts (k, day, n) VALUES (?1, ?2, 1) ON CONFLICT(k) DO UPDATE SET n = n + 1 RETURNING n').bind(`${name}:${day}`, day).first();
      if (r && Number.isFinite(Number(r.n))) return Number(r.n);
    } catch { /* KV below */ }
  }
  const kv = env.GLOBESKIMMERS_KV;
  if (!kv) return null;
  try {
    const k = `cnt:${name}:${day}`;
    const n = (Number(await kv.get(k)) || 0) + 1;
    await kv.put(k, String(n), { expirationTtl: 2 * 86400 });
    return n;
  } catch { return null; }
}
async function gbDayCountsPrune(env, now = new Date()) {
  if (!env.DB) return;
  await env.DB.prepare(DAY_COUNTS_SQL).run();
  await env.DB.prepare('DELETE FROM day_counts WHERE day < ?1').bind(new Date(now.getTime() - 2 * 86400000).toISOString().slice(0, 10)).run();
}

// ── Member numbers (founder, 2026-10-13) ────────────────────────────────────
// The privacy policy keeps names out of every alert (§2: "a member number
// instead of your name"), so the bell says WHO by number. Tapping the alert
// opens Admin → Newest members (gbMemberLink), where the founder sees the name.
// A number belongs to one account for good. member_numbers (events D1) hands
// them out: AUTOINCREMENT never hands a number out twice, even after its row
// is deleted, and D1 runs writes one at a time, so two accounts can't share
// one. (A count of profiles could not promise that: every deleted account
// lowered the count, and the next sign-up got a number someone already had.)
// The table's first use numbers every existing account, oldest first by
// (profiles.created_at, id): the id breaks ties, since the rows of the
// one-time profiles backfill share one created_at. After that an account gets
// the next number the first time it is seen: its new-member alert, a stamp
// alert, or the admin list, which numbers the members it shows that have none,
// oldest first. Deleting an account deletes its row, and so does the
// under-13 clean-up (gbPurgeUserContent step 1l, retried like its other steps).
const gbMemberLink = (n) => `globeskimmers://admin/members?m=${n}`;
const MEMBER_NUMBERS_SQL = `CREATE TABLE IF NOT EXISTS member_numbers (
  n INTEGER PRIMARY KEY AUTOINCREMENT,
  user_id TEXT NOT NULL UNIQUE,
  belled_at TEXT
)`;
// Numbers each id in the JSON array ?1 that has none yet, in array order.
// NOT EXISTS rather than INSERT OR IGNORE: an ignored insert still uses up an
// AUTOINCREMENT number and leaves a gap. The ids must be distinct.
const MEMBER_NUMBER_NEW_SQL = `INSERT INTO member_numbers (user_id)
  SELECT j.value FROM json_each(?1) j
  WHERE NOT EXISTS (SELECT 1 FROM member_numbers m WHERE m.user_id = j.value)
  ORDER BY j.key`;
const gbMemberN = (v) => { const n = Number(v); return Number.isInteger(n) && n > 0 ? n : null; };
// True once this isolate has seen member_numbers exist and seeded; a failure
// leaves it false for the next call to retry. A flag, like psEnsure's, not a
// shared promise: a promise awaited across requests is tied to the request
// that made it.
let GB_MEMBERS_READY = false;
async function gbMembersReady(env) {
  if (GB_MEMBERS_READY) return true;
  if (!env.DB) return false;
  try { GB_MEMBERS_READY = (await gbMembersSeed(env)) === true; } catch { GB_MEMBERS_READY = false; }
  return GB_MEMBERS_READY;
}
// An empty table is seeded with every account, oldest first, in one batch
// (a D1 batch is one transaction): all or nothing, so a failed read can never
// number a later account ahead of an earlier one. Two isolates seeding at once
// is harmless: the second batch finds every row already there.
async function gbMembersSeed(env) {
  await env.DB.prepare(MEMBER_NUMBERS_SQL).run();
  if (await env.DB.prepare('SELECT 1 AS x FROM member_numbers LIMIT 1').first()) return true;
  const ids = [];
  for (let off = 0, pages = 0; ; pages++) {
    if (pages >= 200) return false;
    const q = await gbRest(env, `profiles?select=id&order=created_at.asc,id.asc&offset=${off}&limit=1000`, { headers: { 'Accept-Profile': 'public' } });
    const page = q.ok ? await q.json().catch(() => null) : null;
    if (!Array.isArray(page)) return false;
    if (!page.length) break;
    for (const r of page) { const id = String(r?.id || '').toLowerCase(); if (BL_UUID.test(id)) ids.push(id); }
    off += page.length;
  }
  const uniq = [...new Set(ids)];
  if (!uniq.length) return true;
  const stmts = [];
  for (let i = 0; i < uniq.length; i += 500) stmts.push(env.DB.prepare(MEMBER_NUMBER_NEW_SQL).bind(JSON.stringify(uniq.slice(i, i + 500))));
  await env.DB.batch(stmts);
  return true;
}
// A member's number, handed out the first time it's asked for. null on any
// failure; callers then leave the number out and never wait on a retry.
async function gbMemberNumber(env, userId) {
  try {
    const id = String(userId || '').toLowerCase();
    if (!BL_UUID.test(id) || !(await gbMembersReady(env))) return null;
    const had = await env.DB.prepare('SELECT n FROM member_numbers WHERE user_id = ?1').bind(id).first();
    if (had) return gbMemberN(had.n);
    const [, got] = await env.DB.batch([
      env.DB.prepare(MEMBER_NUMBER_NEW_SQL).bind(JSON.stringify([id])),
      env.DB.prepare('SELECT n FROM member_numbers WHERE user_id = ?1').bind(id),
    ]);
    return gbMemberN(got?.results?.[0]?.n);
  } catch { return null; }
}
// Claims a numbered member's one new-member alert. A single UPDATE, so exactly
// one caller ever gets true; false = already sent; null = D1 couldn't say.
async function gbMemberBellOnce(env, userId) {
  try {
    const r = await env.DB.prepare('UPDATE member_numbers SET belled_at = ?2 WHERE user_id = ?1 AND belled_at IS NULL')
      .bind(String(userId || '').toLowerCase(), new Date().toISOString()).run();
    return Number(r?.meta?.changes) === 1;
  } catch { return null; }
}
const GB_PROVIDER_LABEL = new Map([['apple', 'Sign in with Apple'], ['google', 'Google'], ['facebook', 'Facebook'], ['email', 'email']]);
function gbProviderLabel(p) {
  const k = String(p || '').trim().toLowerCase();
  return GB_PROVIDER_LABEL.get(k) || (k ? k.slice(0, 20) : null);
}
// What sent the request. The iOS app's native HTTP (CapacitorHttp → URLSession)
// sends "App/14 CFNetwork/… Darwin/…", which names no model, so an iPhone and
// an iPad read the same; Android's sends "Dalvik/… (Linux; U; Android …)".
// Every browser sends "Mozilla/…": that is the web app, on any device.
function gbDeviceLabel(ua) {
  const s = String(ua || '');
  if (/Mozilla\//.test(s)) return 'web';
  if (/Android|Dalvik|okhttp/i.test(s)) return 'Android';
  if (/iPad/.test(s)) return 'iPad';
  if (/iPhone|iPod/.test(s)) return 'iPhone';
  if (/CFNetwork|Darwin/.test(s)) return 'iPhone/iPad';
  return null;
}
// Where the request's internet connection is, by Cloudflare's country code:
// "in United States" ("in" because it isn't the member's home country, which
// Admin shows); the code when ICU has no name; "via Tor" for T1; nothing for
// unknown (XX).
function gbConnectionPlace(request) {
  const c = String(request.cf?.country || request.headers.get('CF-IPCountry') || '').trim().toUpperCase();
  if (c === 'T1') return 'via Tor';
  if (!/^[A-Z]{2}$/.test(c) || c === 'XX') return null;
  let name = c;
  try { const n = new Intl.DisplayNames(['en'], { type: 'region' }).of(c); if (n && n !== c) name = n; } catch { /* no ICU */ }
  return `in ${name}`;
}
// "Oct 9", on the founder's own (Pacific) calendar.
function gbDayLabel(ms) {
  try { return new Date(ms).toLocaleDateString('en-US', { month: 'short', day: 'numeric', timeZone: 'America/Los_Angeles' }); }
  catch { return new Date(ms).toISOString().slice(5, 10); }
}

// ── The new-member bell (founder, 2026-10-13) ───────────────────────────────
// One alert per account, the first time a brand-new account (made in the last
// 7 days) reaches gbUser: "🎉 New member #57 · Google · Android · in United
// States", plus "(joined Oct 9)" when the account is over an hour old (an
// email sign-up that confirmed later). Nothing is awaited in the request: the
// checks before the hand-off are in memory, and the rest runs in waitUntil,
// on the ctx fetch() files under the request in GB_REQ_CTX. Older accounts
// cost one date comparison. A per-isolate Set absorbs the burst of parallel
// calls an app launch makes, and the KV mark (bell:user:<id>) cheaply stops
// repeats everywhere else. D1 decides who actually sends it
// (gbMemberBellOnce): KV has no compare-and-set, so two isolates of one
// launch burst could both read "not sent" and both send it. Without a D1
// verdict the KV mark alone decides, written BEFORE the alert so a failed
// write sends nothing.
const GB_REQ_CTX = new WeakMap();   // request → ctx, set at the top of fetch()
const GB_BELL_SEEN = new Set();     // user ids this isolate has already handled
function gbBellNewMember(request, env, u) {
  try {
    if (!env.NTFY_TOPIC && !env.TWILIO_SID) return;
    const kv = env.GLOBESKIMMERS_KV;
    const ctx = GB_REQ_CTX.get(request);
    if (!kv || !ctx || !u?.id) return;
    const born = Date.parse(u.created_at || '');
    const age = Date.now() - born;
    if (!(age < 7 * 86400000)) return;   // a week or older, or no date: nothing at all
    if (GB_BELL_SEEN.has(u.id)) return;
    if (GB_BELL_SEEN.size >= 5000) GB_BELL_SEEN.clear();
    GB_BELL_SEEN.add(u.id);
    const parts = [
      gbProviderLabel(u.app_metadata?.provider),
      gbDeviceLabel(request.headers.get('User-Agent')),
      gbConnectionPlace(request),
    ].filter(Boolean);
    const joined = age > 3600000 ? ` (joined ${gbDayLabel(born)})` : '';
    ctx.waitUntil((async () => {
      const key = `bell:user:${u.id}`;
      if (await kv.get(key)) return;
      const n = await gbMemberNumber(env, u.id);
      const won = n ? await gbMemberBellOnce(env, u.id) : null;
      if (won === null) await kv.put(key, '1');
      else {
        await kv.put(key, '1').catch(() => {});
        if (!won) return;
      }
      const { who } = await gbWhoLine(env, u).catch(() => ({ who: n ? `Member #${n}` : 'A member' }));
      await founderAlert(env, `🎉 New member: ${who}${parts.map((p) => ` · ${p}`).join('')}${joined}`, 'new', n ? { click: gbMemberLink(n) } : {});
    })().catch(() => {}));
  } catch { /* the bell never touches sign-in */ }
}

// ── The morning digest (founder, 2026-10-05): yesterday's OFFICIAL store
// downloads, by the stores' own daily reports, texted to the founder's bell.
// Apple: App Store Connect Sales Reports (ES256 JWT from an API key; gzipped
// TSV; ready ~5–8am PT for the previous day — we try yesterday, then the day
// before). Google: the Play Console stats CSV in its GCS bucket (service
// account; UTF-16 CSV; 1–2 days behind). Each source runs only when its
// secrets exist and never breaks the cron.
const b64url = (buf) => btoa(String.fromCharCode(...new Uint8Array(buf))).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
const pemToDer = (pem) => {
  const b = String(pem).replace(/-----[^-]+-----/g, '').replace(/\s+/g, '');
  return Uint8Array.from(atob(b), (c) => c.charCodeAt(0)).buffer;
};
async function ascToken(env) {
  const key = await crypto.subtle.importKey('pkcs8', pemToDer(env.ASC_PRIVATE_KEY), { name: 'ECDSA', namedCurve: 'P-256' }, false, ['sign']);
  const now = Math.floor(Date.now() / 1000);
  const head = b64url(new TextEncoder().encode(JSON.stringify({ alg: 'ES256', kid: env.ASC_KEY_ID, typ: 'JWT' })));
  const body = b64url(new TextEncoder().encode(JSON.stringify({ iss: env.ASC_ISSUER_ID, iat: now, exp: now + 1100, aud: 'appstoreconnect-v1' })));
  const sig = await crypto.subtle.sign({ name: 'ECDSA', hash: 'SHA-256' }, key, new TextEncoder().encode(`${head}.${body}`));
  return `${head}.${body}.${b64url(sig)}`;
}
async function appleDownloads(env, isoDate) {
  if (!env.ASC_ISSUER_ID || !env.ASC_KEY_ID || !env.ASC_PRIVATE_KEY || !env.ASC_VENDOR_NUMBER) return null;
  const jwt = await ascToken(env);
  const u = `https://api.appstoreconnect.apple.com/v1/salesReports?filter[frequency]=DAILY&filter[reportType]=SALES&filter[reportSubType]=SUMMARY&filter[version]=1_1&filter[vendorNumber]=${env.ASC_VENDOR_NUMBER}&filter[reportDate]=${isoDate}`;
  const r = await fetch(u, { headers: { Authorization: `Bearer ${jwt}`, Accept: 'application/a-gzip' } });
  if (!r.ok) return r.status === 404 ? { units: null, empty: true } : null;
  const text = await new Response(r.body.pipeThrough(new DecompressionStream('gzip'))).text();
  const lines = text.split('\n').filter(Boolean);
  const cols = lines[0].split('\t');
  const iU = cols.indexOf('Units'), iT = cols.indexOf('Product Type Identifier');
  let units = 0;
  for (const line of lines.slice(1)) {
    const c = line.split('\t');
    // 1 / 1F / 1T / F1 = first-time app downloads (iPhone / universal / iPad / Mac).
    if (/^(1|1F|1T|F1)$/.test(String(c[iT] || '').trim())) units += Number(c[iU]) || 0;
  }
  return { units };
}
async function googleDownloads(env, isoDate) {
  if (!env.GPLAY_SA_EMAIL || !env.GPLAY_SA_KEY || !env.GPLAY_BUCKET) return null;
  const key = await crypto.subtle.importKey('pkcs8', pemToDer(env.GPLAY_SA_KEY), { name: 'RSASSA-PKCS1-v1_5', hash: 'SHA-256' }, false, ['sign']);
  const now = Math.floor(Date.now() / 1000);
  const head = b64url(new TextEncoder().encode(JSON.stringify({ alg: 'RS256', typ: 'JWT' })));
  const claims = b64url(new TextEncoder().encode(JSON.stringify({
    iss: env.GPLAY_SA_EMAIL, scope: 'https://www.googleapis.com/auth/devstorage.read_only',
    aud: 'https://oauth2.googleapis.com/token', iat: now, exp: now + 1800,
  })));
  const sig = await crypto.subtle.sign('RSASSA-PKCS1-v1_5', key, new TextEncoder().encode(`${head}.${claims}`));
  const tr = await fetch('https://oauth2.googleapis.com/token', {
    method: 'POST', headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
    body: new URLSearchParams({ grant_type: 'urn:ietf:params:oauth:grant-type:jwt-bearer', assertion: `${head}.${claims}.${b64url(sig)}` }),
  });
  if (!tr.ok) return null;
  const token = (await tr.json()).access_token;
  const pkg = 'com.globeskimmers.app';
  const obj = encodeURIComponent(`stats/installs/installs_${pkg}_${isoDate.slice(0, 7).replace('-', '')}_overview.csv`);
  const gr = await fetch(`https://storage.googleapis.com/storage/v1/b/${env.GPLAY_BUCKET}/o/${obj}?alt=media`, { headers: { Authorization: `Bearer ${token}` } });
  if (!gr.ok) return { units: null, empty: true };
  const csv = new TextDecoder('utf-16le').decode(await gr.arrayBuffer()).replace(/^﻿/, '');
  const lines = csv.split('\n').map((l) => l.replace(/\r$/, '')).filter(Boolean);
  const cols = lines[0].split(',');
  const iD = cols.findIndex((c) => /^date$/i.test(c.trim()));
  const iU = cols.findIndex((c) => /daily user installs/i.test(c));
  for (const line of lines.slice(1)) {
    const c = line.split(',');
    if ((c[iD] || '').trim() === isoDate) return { units: Number(c[iU]) || 0 };
  }
  return { units: null, empty: true };
}
async function morningDigest(env) {
  if (!env.NTFY_TOPIC && !env.TWILIO_SID) return;
  const day = (back) => new Date(Date.now() - back * 86400000).toISOString().slice(0, 10);
  const parts = [];
  try {
    let a = await appleDownloads(env, day(1));
    let aDay = day(1);
    if (a && a.empty) { a = await appleDownloads(env, day(2)); aDay = day(2); }
    // Apple publishes no report for a day with no sales: two empty days in a row read 0, not silence.
    if (a && a.units != null) parts.push(`${a.units} App Store (${aDay.slice(5)})`);
    else if (a && a.empty) parts.push(`0 App Store (${aDay.slice(5)})`);
  } catch { /* apple skipped */ }
  try {
    let g = await googleDownloads(env, day(2));   // Play lags a day more
    let gDay = day(2);
    if (g && g.empty) { g = await googleDownloads(env, day(3)); gDay = day(3); }
    if (g && g.units != null) parts.push(`${g.units} Google Play (${gDay.slice(5)})`);
  } catch { /* google skipped */ }
  try {
    if (env.DB) {
      const since = Math.floor(Date.now() / 1000) - 86400;
      const r = await env.DB.prepare(`SELECT COUNT(*) n FROM events WHERE event_type = 'passport_stamp' AND ts >= ?1`).bind(since).first();
      if (r) parts.push(`${r.n} stamps in 24h`);
    }
  } catch { /* stamps skipped */ }
  if (parts.length) await founderAlert(env, `☀️ Downloads: ${parts.join(' · ')}`, 'new');
}

async function handleLogEvent(request, env) {
  try {
    const body = await request.json();
    if (!body?.event_type) {
      return jsonResponse({ logged: false, reason: 'missing_event_type' }, 400);
    }
    if (!env.DB) {
      // D1 not bound yet — graceful no-op so the frontend can ship events
      // before the analytics DB is provisioned.
      return jsonResponse({ logged: false, reason: 'no_db_binding' });
    }
    const ts = Math.floor(Date.now() / 1000);
    const base = [
      ts,
      body.user_id || null,
      body.session_id || 'anon',
      body.event_type,
      body.page || null,
      body.payload ? JSON.stringify(body.payload) : null,
      body.ua_summary || null,
    ];
    try {
      // Preferred: store the durable per-device anon_id (retention cohorts).
      await env.DB.prepare(
        `INSERT INTO events (ts, user_id, session_id, event_type, page, payload, ua_summary, anon_id)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?)`
      ).bind(...base, body.anon_id || null).run();
    } catch {
      // Fallback if the anon_id column isn't added yet (run scripts/analytics/
      // alter_anon_id.sql then re-deploy) — analytics never breaks on ordering.
      await env.DB.prepare(
        `INSERT INTO events (ts, user_id, session_id, event_type, page, payload, ua_summary)
         VALUES (?, ?, ?, ?, ?, ?, ?)`
      ).bind(...base).run();
    }
    // A device we've never seen before = someone just downloaded and opened
    // the app; the alert fires once per phone. KV remembers a phone's id for
    // 400 days (go-live round 3: kept forever, a script with fresh ids wrote
    // keys without end). This door needs no sign-in, so one internet address
    // rings for at most 3 first opens a day (the 'new' allowance in
    // founderAlert caps the rest): only a one-way hash of the address and the
    // day is counted, and the count is deleted after two days. A phone past
    // that limit is simply not remembered yet; it rings on a later open.
    // Only the app's first open on a phone is a download (2026-10-26: the alerts outran the stores — a
    // browser, Claude's screenshot runs and the demo account all rang as "new downloads"). The app says
    // where it runs (body.platform, since 1.0.2610261…); older builds are told by their user agent: the
    // iPhone app's has no "Safari" (ua_summary 'other'), Android's reads 'android-chrome'. A browser of
    // any kind, or a phone signed in as an admin or the App Review account, never rings.
    const plat = ['ios', 'android', 'web'].includes(body.platform) ? body.platform
      : body.ua_summary === 'other' ? 'ios' : body.ua_summary === 'android-chrome' ? 'android' : 'web';
    try {
      const anon = String(body.anon_id || '').slice(0, 64);
      if (anon && plat !== 'web' && env.GLOBESKIMMERS_KV && (env.NTFY_TOPIC || env.TWILIO_SID)) {
        const seen = await env.GLOBESKIMMERS_KV.get(`bell:dev:${anon}`);
        const tester = !seen && body.user_id ? (await gbTestAccountIds(env)).includes(String(body.user_id).toLowerCase()) : false;
        const ip = request.headers.get('cf-connecting-ip') || '';
        const fromIp = !seen && !tester && ip ? await gbDayCount(env, `dl:${(await sha256Hex(`gs-dl:${new Date().toISOString().slice(0, 10)}:${ip}`)).slice(0, 32)}`) : null;
        if (!seen && !tester && (fromIp == null || fromIp <= 3)) {
          await env.GLOBESKIMMERS_KV.put(`bell:dev:${anon}`, '1', { expirationTtl: 400 * 86400 });
          await founderAlert(env, `🎉 New download! First open on ${plat === 'ios' ? 'iPhone' : 'Android'}`, 'new');
        }
      }
    } catch { /* never blocks logging */ }
    return jsonResponse({ logged: true, ts });
  } catch (e) {
    return jsonResponse({ logged: false, error: e.message }, 500);
  }
}

// ── Account deletion (Apple Guideline 5.1.1(v) / Google Play) ─────────────
// Lets a signed-in user permanently delete their OWN account + data from
// inside the app. The frontend calls POST /delete-account via callWorker,
// which attaches the user's Supabase JWT as `Authorization: Bearer <jwt>`.
// Flow: (1) resolve that JWT to a user via GoTrue and delete ONLY the id the
// token resolves to (never a client-supplied id); (2) hard-delete that auth
// user with the SERVICE ROLE key. Removing the auth.users row cascades
// public.profiles + public.login_events (FK ON DELETE CASCADE).
// Requires the Worker secret SUPABASE_SERVICE_ROLE_KEY (`wrangler secret put`).
// Everything a traveler created, removed: guestbook notes anonymized and
// their photos down (a child's notes deleted, see step 1b), stamps + memory
// photos + R2 objects, tags, share link,
// postcards they sent or received (and their photos), follow edges both
// ways, their "I'm here" reports, their place suggestions (and photos) and
// likes, dish and drink posts (and photos), messages to place owners,
// signatures, doodles, reactions and co-signs (theirs, and everyone's on
// their own pages), the profile photo, luggage, virtual items, saved places
// and username/Seal requests (founder, 2026-10-13: deletion removes what the
// privacy policy promises). The social profile: account deletion removes the
// row (with the birthday) and the blocks both ways; the under-13 freeze
// (keepAccount: the auth user stays so an appeal can restore ACCESS) clears
// the profile but keeps the age record — birth year, month/day, tier and
// gate country — so the account stays frozen and the appeal has something
// to correct. Content reports a traveler filed are safety records and stay.
// A failing step never stops the next; the result says which steps failed
// ({ ok, failed }) so the sweeps retry. Photos come down BEFORE the rows that
// name them, and a row group whose photos failed is kept, so a retry can
// still find them.
// ── Guestbook uploads from before the per-uploader prefix (go-live round 3) ──
// Uploads used to be stored as gb/<place id>/<uid>/<file>; now they go under
// gb/u/<uid>/, so the older keys are a fixed set. A child clean-up that read
// all of gb/ for them cost one R2 list per 1,000 uploads (anyone's), and past
// 50,000 it failed every day. A one-time pass in the daily cron
// (gbLegacyIndexPass, resumable: KV gbidx:cursor, then gbidx:done) records
// each older key with its uploader in D1 (gb_legacy); after it, a child's
// older files are one D1 read. Until it has finished, a clean-up reads gb/
// itself when that takes at most GB_LEGACY_INLINE_PAGES pages, and otherwise
// leaves the mark gbsweep:<uid>: the pass deletes a marked uploader's files
// as it reaches them, and the ones it had already indexed when it finishes.
// (A clean-up counts as done when it has left the mark.)
const GB_LEGACY_SQL = 'CREATE TABLE IF NOT EXISTS gb_legacy (key TEXT PRIMARY KEY, uid TEXT NOT NULL)';
const GB_LEGACY_UID_SQL = 'CREATE INDEX IF NOT EXISTS gb_legacy_uid ON gb_legacy (uid)';
const GB_LEGACY_INLINE_PAGES = 3;
const GB_LEGACY_PASS_PAGES = 20;
const gbIsLegacyUpload = (key) => !String(key || '').startsWith('gb/u/') && !!gbUploadOwner(key);
// One uploader's older files: deleted, or left to the pass. False when a
// step failed (the clean-up retries); throws are failures too.
async function gbLegacyFilesDrop(env, userId) {
  const u = String(userId).toLowerCase();
  const kv = env.GLOBESKIMMERS_KV;
  if (!env.MEDIA || typeof env.MEDIA.list !== 'function') return true;
  if (kv && await kv.get('gbidx:done')) {
    if (!env.DB) return false;
    await env.DB.prepare(GB_LEGACY_SQL).run();
    const { results } = await env.DB.prepare('SELECT key FROM gb_legacy WHERE uid = ?1').bind(u).all();
    const keys = (results || []).map((r) => r.key);
    for (let i = 0; i < keys.length; i += 1000) await env.MEDIA.delete(keys.slice(i, i + 1000));
    await env.DB.prepare('DELETE FROM gb_legacy WHERE uid = ?1').bind(u).run();
    return true;
  }
  let cursor;
  for (let i = 0; i < GB_LEGACY_INLINE_PAGES; i++) {
    const page = await env.MEDIA.list({ prefix: 'gb/', cursor, limit: 1000 });
    const mine = (page.objects || []).map((o) => o.key).filter((k) => gbIsLegacyUpload(k) && gbUploadOwner(k) === u);
    if (mine.length) await env.MEDIA.delete(mine);
    if (!page.truncated) return true;
    cursor = page.cursor;
  }
  if (!kv) return false;
  await kv.put(`gbsweep:${u}`, new Date().toISOString());
  return true;
}
// An account deleted on the adult path: its never-posted older uploads stay
// (privacy §6), its index rows go.
async function gbLegacyIndexForget(env, userId) {
  if (!env.DB || !env.GLOBESKIMMERS_KV || !(await env.GLOBESKIMMERS_KV.get('gbidx:done'))) return;
  await env.DB.prepare(GB_LEGACY_SQL).run();
  await env.DB.prepare('DELETE FROM gb_legacy WHERE uid = ?1').bind(String(userId).toLowerCase()).run();
}
// Daily, until done: up to GB_LEGACY_PASS_PAGES pages of gb/ a run.
async function gbLegacyIndexPass(env, now = new Date()) {
  const out = { pages: 0, indexed: 0, swept: 0, done: false };
  const kv = env.GLOBESKIMMERS_KV;
  if (!kv || !env.DB || !env.MEDIA || typeof env.MEDIA.list !== 'function') return out;
  if (await kv.get('gbidx:done')) { out.done = true; return out; }
  await env.DB.prepare(GB_LEGACY_SQL).run();
  await env.DB.prepare(GB_LEGACY_UID_SQL).run();
  const marks = async () => {
    const set = new Set(); let c;
    do { const p = await kv.list({ prefix: 'gbsweep:', cursor: c }); for (const k of p.keys || []) set.add(k.name.slice('gbsweep:'.length)); c = p.list_complete ? null : p.cursor; } while (c);
    return set;
  };
  const marked = await marks();
  let cursor = (await kv.get('gbidx:cursor')) || undefined;
  for (let i = 0; i < GB_LEGACY_PASS_PAGES; i++) {
    if (gbBudgetLeft(env) < 20) break;   // a page, its deletes and the cursor; the rest tomorrow
    const page = await env.MEDIA.list({ prefix: 'gb/', cursor, limit: 1000 });
    out.pages++;
    const rows = [], drop = [];
    for (const { key } of page.objects || []) {
      if (!gbIsLegacyUpload(key)) continue;
      const u = gbUploadOwner(key);
      if (marked.has(u)) drop.push(key); else rows.push({ k: key, u });
    }
    if (drop.length) { await env.MEDIA.delete(drop); out.swept += drop.length; }
    for (let j = 0; j < rows.length; j += 250) {
      await env.DB.prepare("INSERT OR IGNORE INTO gb_legacy (key, uid) SELECT json_extract(value, '$.k'), json_extract(value, '$.u') FROM json_each(?1)").bind(JSON.stringify(rows.slice(j, j + 250))).run();
    }
    out.indexed += rows.length;
    if (!page.truncated) {
      // Done: a marked uploader's files the pass had indexed before the mark go too.
      for (const u of await marks()) {
        const { results } = await env.DB.prepare('SELECT key FROM gb_legacy WHERE uid = ?1').bind(u).all();
        const keys = (results || []).map((r) => r.key);
        for (let j = 0; j < keys.length; j += 1000) await env.MEDIA.delete(keys.slice(j, j + 1000));
        await env.DB.prepare('DELETE FROM gb_legacy WHERE uid = ?1').bind(u).run();
        await kv.delete(`gbsweep:${u}`);
        out.swept += keys.length;
      }
      await kv.put('gbidx:done', now.toISOString());
      await kv.delete('gbidx:cursor');
      out.done = true;
      return out;
    }
    cursor = page.cursor;
    await kv.put('gbidx:cursor', cursor);
  }
  return out;
}

// The personal columns of public.profiles a freeze clears (step 1k); the
// settings columns (units, currency, language, toggles) stay.
const GB_PROFILE_PERSONAL_COLS = [
  'first_name', 'display_name', 'home_city', 'home_country', 'home_city_country', 'home_lat', 'home_lng', 'home_timezone',
  'dietary_prefs', 'accessibility_needs', 'travel_frequency', 'travel_purpose', 'traveler_type', 'frequent_countries',
  'next_destination', 'travel_budget', 'accommodation_style', 'referral_source',
];
async function gbPurgeUserContent(env, userId, opts = {}) {
  const keepAccount = !!opts.keepAccount;
  const failed = [];
  const SUPABASE_URL = env.SUPABASE_URL || 'https://bkaxadiyehddzkiuheea.supabase.co';
  const SERVICE_KEY = env.SUPABASE_SERVICE_ROLE_KEY || env.SUPABASE_SERVICE_KEY;
  if (!SERVICE_KEY || !userId) return { ok: false, failed: ['config'] };
  // One PostgREST call; null (and the step noted as failed) unless it answered 2xx.
  const call = async (step, path, init = {}) => {
    try {
      const r = await fetch(`${SUPABASE_URL}/rest/v1/${path}`, { ...init, headers: { apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}`, 'Content-Type': 'application/json', ...(init.headers || {}) } });
      if (!r.ok) { failed.push(step); return null; }
      return r;
    } catch { failed.push(step); return null; }
  };
  // Every row (pages of 1000 — PostgREST's cap), or null when a page failed.
  const rows = async (step, path) => {
    const out = [];
    for (let off = 0; off < 50000; off += 1000) {
      const r = await call(step, `${path}&limit=1000&offset=${off}`);
      if (!r) return null;
      let page;
      try { page = (await r.json()) || []; } catch { failed.push(step); return null; }
      out.push(...page);
      if (page.length < 1000) break;
    }
    return out;
  };
  const del = (step, path) => call(step, path, { method: 'DELETE', headers: { Prefer: 'return=minimal' } });
  // R2 objects (≤1000 per call); true when every key is gone.
  const r2 = async (step, keys) => {
    const list = [...new Set((keys || []).filter((k) => typeof k === 'string' && k))];
    if (!list.length) return true;
    if (!env.MEDIA) { failed.push(step); return false; }
    try {
      for (let i = 0; i < list.length; i += 1000) await env.MEDIA.delete(list.slice(i, i + 1000));
      return true;
    } catch { failed.push(step); return false; }
  };
  // Everything under a per-user R2 prefix (pp/<uid>/, dish/<uid>/, bl/<uid>/)
  // — catches objects whose rows went first (an older delete, a failed insert).
  const r2Prefix = async (step, prefix) => {
    if (!env.MEDIA || typeof env.MEDIA.list !== 'function') return true;
    try {
      let cursor;
      for (let i = 0; i < 50; i++) {
        const page = await env.MEDIA.list({ prefix, cursor, limit: 1000 });
        const keys = (page.objects || []).map((o) => o.key).filter(Boolean);
        if (keys.length) await env.MEDIA.delete(keys);
        if (!page.truncated) break;
        cursor = page.cursor;
      }
      return true;
    } catch { failed.push(step); return false; }
  };
  const uidOk = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(String(userId));
  // 1b) Guestbook. Their photos come DOWN first (Apple 5.1.1 / GDPR) and their
  //     PRIVATE visit records go. Account deletion keeps their PUBLIC notes,
  //     anonymized (keep the tip, drop the identity). A child's notes are
  //     DELETED (go-live round 2): at the under-13 clean-up (keepAccount),
  //     and when a frozen account is deleted at once from its frozen screen
  //     (opts.child, see handleDeleteAccount), every note row goes, the ones
  //     the child had deleted themselves too (a soft delete kept the text),
  //     once the photos the notes name are gone; then every file under
  //     gb/<place>/<uid>/ goes, uploads that never became a note included.
  //     Who is a child (go-live round 3): the under-13 clean-up, a record
  //     that says so (opts.child), or a stored birthday that is under 13 —
  //     read here, before anything is deleted, so an account whose freeze
  //     marker couldn't be read, or an orphan of a deletion from before
  //     go-live (no marker, no flag), still gets the child clean-up. When the
  //     birthday can't be read, nothing is guessed: the notes are neither
  //     deleted nor anonymized and the social profile (the birthday) stays,
  //     so the retry decides (step 'age_read'). A child found by its
  //     birthday is in the result (child: true), so a retry record keeps it
  //     once the profile is gone.
  let child = keepAccount || opts.child === true;
  const told = child;
  let ageKnown = true;
  if (!child) {
    const aq = await call('age_read', `social_profiles?user_id=eq.${userId}&select=birth_year,birth_md,country_at_gate`);
    let row = null;
    if (!aq) ageKnown = false;
    else { try { row = ((await aq.json()) || [])[0] || null; } catch { ageKnown = false; failed.push('age_read'); } }
    if (row?.birth_year && socialTierFor(row.birth_year, row.country_at_gate, row.birth_md) === 'blocked') child = true;
  }
  const gbPhotos = ageKnown ? await rows('guestbook_photos', `guestbook_entries?user_id=eq.${userId}&photo_key=not.is.null&select=photo_key`) : null;
  // Only files this account uploaded (gbUploadOwner): a note that named
  // someone else's goes without taking their file.
  const myUploads = (list) => list.map((r) => r.photo_key).filter((k) => gbUploadOwner(k) === String(userId).toLowerCase());
  if (gbPhotos && await r2('guestbook_photos_r2', myUploads(gbPhotos))) {
    if (child) await del('guestbook_entries', `guestbook_entries?user_id=eq.${userId}`);
    else {
      await call('guestbook_entries', `guestbook_entries?user_id=eq.${userId}`, {
        method: 'PATCH', headers: { Prefer: 'return=minimal' },
        body: JSON.stringify({ user_id: null, display_name: 'A traveler', home_city: null, photo_key: null, photo_url: null }),
      });
    }
  }
  //     The files: the uploader's own prefix (gb/u/<uid>/), then the older
  //     keys, which name the place first (gbLegacyFilesDrop: one D1 read once
  //     they are indexed). An adult's never-posted uploads stay; their index
  //     rows go.
  if (child && uidOk) {
    if (await r2Prefix('guestbook_files', `gb/u/${String(userId).toLowerCase()}/`)) {
      try { if (!(await gbLegacyFilesDrop(env, userId))) failed.push('guestbook_files'); } catch { failed.push('guestbook_files'); }
    }
  } else if (uidOk && ageKnown) {
    try { await gbLegacyIndexForget(env, userId); } catch { failed.push('guestbook_index'); }
  }
  await del('guestbook_visits', `guestbook_visits?user_id=eq.${userId}`);

  // 1c) Passport is PRIVATE (not public UGC) → fully DELETE the user's stamps +
  //     memory photos + their R2 objects, tags both ways, and their share link.
  const ppPhotos = await rows('passport_photos', `passport_stamp_photos?user_id=eq.${userId}&select=photo_key`);
  if (ppPhotos && await r2('passport_photos_r2', ppPhotos.map((r) => r.photo_key))) {
    await del('passport_stamps', `passport_stamps?user_id=eq.${userId}`);   // cascades the photo rows
  }
  if (uidOk) await r2Prefix('passport_photos_prefix', `pp/${userId}/`);
  await del('passport_tags', `passport_tags?or=(from_user_id.eq.${userId},to_user_id.eq.${userId})`);
  await del('passport_shares', `passport_shares?user_id=eq.${userId}`);

  // 1d) Their "I'm here, but the app is saying I'm not" reports (events D1,
  //     keyed by the same anonymous code the report used).
  try {
    if (env.DB) {
      await env.DB.prepare(STAMP_REPORT_SQL).run();
      const code = (await sha256Hex(`${userId}:stamp-report`)).slice(0, 8);
      await env.DB.prepare('DELETE FROM stamp_reports WHERE user_code = ?').bind(code).run();
    }
  } catch { failed.push('stamp_reports'); }

  // 1e) Postcards they sent or received (+ their R2 photos) and follow edges both ways.
  const pcSent = await rows('postcards_sent', `postcards?sender_id=eq.${userId}&select=photo_key`);
  if (pcSent && await r2('postcards_sent_r2', pcSent.map((r) => r.photo_key))) {
    await del('postcards_sent', `postcards?sender_id=eq.${userId}`);
  }
  const pcGot = await rows('postcards_received', `postcards?to_user_id=eq.${userId}&select=photo_key`);
  if (pcGot && await r2('postcards_received_r2', pcGot.map((r) => r.photo_key))) {
    await del('postcards_received', `postcards?to_user_id=eq.${userId}`);
  }
  // Postcards and telegrams they sent that still wait for an email address (2026-10-18 /
  // 2026-10-24). An undelivered card's photo is its own; a delivered one's went with postcards_sent.
  const pcWait = await rows('pending_postcards', `pending_postcards?sender_id=eq.${userId}&delivered_at=is.null&select=photo_key`);
  if (pcWait && await r2('pending_postcards_r2', pcWait.map((r) => r.photo_key))) {
    await del('pending_postcards', `pending_postcards?sender_id=eq.${userId}`);
  }
  await del('pending_telegrams', `pending_telegrams?sender_id=eq.${userId}`);
  // Links they made to text or share (2026-10-24), and each one's photo; claimed copies went with
  // postcards_sent / telegrams above.
  const lk = await rows('message_links', `message_links?sender_id=eq.${userId}&select=photo_key`);
  if (lk && await r2('message_links_r2', lk.map((r) => r.photo_key))) {
    await del('message_links', `message_links?sender_id=eq.${userId}`);
  }
  await del('message_link_claims', `message_link_claims?user_id=eq.${userId}`);
  // Telegrams they sent or received (2026-10-19); no media.
  await del('telegrams', `telegrams?or=(sender_id.eq.${userId},to_user_id.eq.${userId})`);
  await del('user_follows', `user_follows?or=(follower_id.eq.${userId},followee_id.eq.${userId})`);
  // Postcards they kept (2026-10-14); a worker that runs before that table exists has none.
  try {
    const rk = await fetch(`${SUPABASE_URL}/rest/v1/postcard_keeps?user_id=eq.${userId}`, { method: 'DELETE', headers: { apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}`, Prefer: 'return=minimal' } });
    if (!rk.ok && rk.status !== 404) failed.push('postcard_keeps');
  } catch { failed.push('postcard_keeps'); }
  // Which App Store downloads were theirs (RESCIND_CONSENT lookups, 2026-10-14).
  try {
    const ra = await fetch(`${SUPABASE_URL}/rest/v1/app_store_links?user_id=eq.${userId}`, { method: 'DELETE', headers: { apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}`, Prefer: 'return=minimal' } });
    if (!ra.ok && ra.status !== 404) failed.push('app_store_links');
  } catch { failed.push('app_store_links'); }

  // 1f) Dish and drink posts (+ photos), and messages to place owners.
  const dishes = await rows('dish_posts', `place_dishes?user_id=eq.${userId}&select=photo_key`);
  if (dishes && await r2('dish_photos_r2', dishes.map((r) => r.photo_key))) {
    await del('dish_posts', `place_dishes?user_id=eq.${userId}`);
  }
  if (uidOk) await r2Prefix('dish_photos_prefix', `dish/${userId}/`);
  // City Board contributions (2026-10-27): the files, then the rows, then anything left under bc/<uid>/.
  const contribs = await rows('board_contributions', `board_contributions?user_id=eq.${userId}&select=photo_key`);
  if (contribs && await r2('board_contributions_r2', contribs.map((r) => r.photo_key))) {
    await del('board_contributions', `board_contributions?user_id=eq.${userId}`);
  }
  if (uidOk) await r2Prefix('board_contributions_prefix', `bc/${userId}/`);
  await del('owner_notes', `owner_notes?user_id=eq.${userId}`);

  // 1g) The Blotter: signatures and doodles they left (co-signs under them
  //     cascade), their reactions and co-signs, and everything left on their
  //     own pages (those pages are gone with the stamps).
  const signed = await rows('blotter_signed', `blotter_entries?author_user_id=eq.${userId}&select=doodle_key`);
  if (signed && await r2('blotter_signed_r2', signed.map((r) => r.doodle_key))) {
    await del('blotter_signed', `blotter_entries?author_user_id=eq.${userId}`);
  }
  await del('blotter_marks', `blotter_marks?user_id=eq.${userId}`);
  await del('blotter_cosigns', `blotter_cosigns?user_id=eq.${userId}`);
  const onMine = await rows('blotter_on_mine', `blotter_entries?owner_user_id=eq.${userId}&select=doodle_key`);
  if (onMine && await r2('blotter_on_mine_r2', onMine.map((r) => r.doodle_key))) {
    await del('blotter_on_mine', `blotter_entries?owner_user_id=eq.${userId}`);
  }
  await del('blotter_marks_on_mine', `blotter_marks?owner_user_id=eq.${userId}`);
  if (uidOk) await r2Prefix('blotter_doodles_prefix', `bl/${userId}/`);

  // 1h) Luggage, virtual items, saved places, username/Seal requests.
  await del('luggage_state', `luggage_state?user_id=eq.${userId}`);
  await del('profile_gear', `profile_gear?user_id=eq.${userId}`);
  await del('user_saves', `user_saves?user_id=eq.${userId}`);
  await del('handle_requests', `handle_requests?user_id=eq.${userId}`);

  // 1i) The social profile and its photo. A freeze keeps only the age record;
  //     a birthday that couldn't be read (step 1b) stays for the retry.
  const prof = ageKnown ? await rows('social_profile', `social_profiles?user_id=eq.${userId}&select=avatar_key`) : null;
  if (prof && await r2('avatar_r2', prof.map((r) => r.avatar_key))) {
    if (keepAccount) {
      if (prof.length) {
        await call('social_profile', `social_profiles?user_id=eq.${userId}`, {
          method: 'PATCH', headers: { Prefer: 'return=minimal' },
          body: JSON.stringify({ display_name: null, bio: null, website: null, favorites: null, dreams: null, avatar_key: null, mailbox_seen_at: null, updated_at: new Date().toISOString() }),
        });
      }
    } else {
      await del('social_profile', `social_profiles?user_id=eq.${userId}`);
    }
  }
  // Blocks are safety settings: they go with the account, never with a freeze;
  // so do the @handle notes of those blocks, both ways (gbBlockNoteKey).
  if (!keepAccount) {
    await del('user_blocks', `user_blocks?or=(user_id.eq.${userId},blocked_user_id.eq.${userId})`);
    if (uidOk && !(await gbBlockNotesDrop(env, userId))) failed.push('block_notes');
  }

  // 1k) A freeze keeps the sign-in and the age record, nothing personal
  //     (go-live review, 2026-10-13): the first name, home city, country,
  //     pin and timezone, diet and accessibility needs and the old onboarding
  //     answers in public.profiles are cleared, and the sign-in history goes.
  //     (Account deletion removes both with the auth user.) Only columns the
  //     row actually has are named — the table grew by hand, and a PATCH that
  //     names a missing column would fail this step every day.
  if (keepAccount && uidOk) {
    const pr = await call('profiles_personal', `profiles?id=eq.${userId}&select=*`, { headers: { 'Accept-Profile': 'public' } });
    let row = null;
    if (pr) { try { row = ((await pr.json()) || [])[0] || null; } catch { failed.push('profiles_personal'); } }
    if (row) {
      const patch = {};
      for (const c of GB_PROFILE_PERSONAL_COLS) if (c in row && row[c] !== null) patch[c] = null;
      if (Object.keys(patch).length) {
        await call('profiles_personal', `profiles?id=eq.${userId}`, { method: 'PATCH', headers: { Prefer: 'return=minimal', 'Content-Profile': 'public' }, body: JSON.stringify(patch) });
      }
    }
    await call('login_events', `login_events?user_id=eq.${userId}`, { method: 'DELETE', headers: { Prefer: 'return=minimal', 'Content-Profile': 'public' } });
  }

  // 1l) The member number (events D1, see gbMemberNumber): the bell's
  //     alerts named the account by it. It goes with the account and at the
  //     under-13 clean-up (go-live round 2), as a step like the others, so a
  //     failure is queued and retried (account deletion used to try it once,
  //     best-effort, after the purge). A table that doesn't exist yet is
  //     created empty, so there is simply nothing to delete.
  try {
    if (env.DB) {
      await env.DB.prepare(MEMBER_NUMBERS_SQL).run();
      await env.DB.prepare('DELETE FROM member_numbers WHERE user_id = ?1').bind(String(userId).toLowerCase()).run();
    }
  } catch { failed.push('member_number'); }

  // 1j) Their place suggestions (+ their photos in R2), likes, reports and
  //     daily counts (events D1). A place only they had suggested goes too —
  //     its name and pin were theirs — unless the founder already decided it
  //     (an approved place has other people's stamps; a declined or removed
  //     one keeps its decision). A place others suggested stays, without them.
  try {
    if (env.DB) {
      await psEnsure(env);
      const { results } = await env.DB.prepare('SELECT place_id, photo_key FROM ps_votes WHERE user_id = ?').bind(userId).all();
      if (await r2('suggestion_photos_r2', (results || []).map((r) => r.photo_key))) {
        await env.DB.batch([
          env.DB.prepare('DELETE FROM ps_votes WHERE user_id = ?').bind(userId),
          env.DB.prepare('DELETE FROM ps_likes WHERE user_id = ?').bind(userId),
          env.DB.prepare('DELETE FROM ps_reports WHERE user_id = ?').bind(userId),
          env.DB.prepare('DELETE FROM ps_rate WHERE user_id = ?').bind(userId),
        ]);
        const ids = [...new Set((results || []).map((r) => r.place_id))];
        for (let i = 0; i < ids.length; i += 90) {   // D1 binds at most 100 values a query
          const chunk = ids.slice(i, i + 90);
          const { results: gone } = await env.DB.prepare(`SELECT id FROM ps_places WHERE id IN (${chunk.map(() => '?').join(',')})
              AND status IN ('open', 'held') AND NOT EXISTS (SELECT 1 FROM ps_votes v WHERE v.place_id = ps_places.id)`).bind(...chunk).all();
          const g = (gone || []).map((r) => r.id);
          if (!g.length) continue;
          const qs = g.map(() => '?').join(',');
          await env.DB.batch([
            env.DB.prepare(`DELETE FROM ps_likes WHERE place_id IN (${qs})`).bind(...g),
            env.DB.prepare(`DELETE FROM ps_reports WHERE place_id IN (${qs})`).bind(...g),
            env.DB.prepare(`DELETE FROM ps_places WHERE id IN (${qs})`).bind(...g),
          ]);
        }
      }
    }
  } catch { failed.push('suggestions'); }

  return { ok: failed.length === 0, failed, ...(child && !told ? { child: true } : {}) };
}

async function handleDeleteAccount(request, env) {
  try {
    const authHeader = request.headers.get('Authorization') || '';
    const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7).trim() : '';
    if (!token) return jsonResponse({ error: 'Not signed in' }, 401);

    const SUPABASE_URL = env.SUPABASE_URL || 'https://bkaxadiyehddzkiuheea.supabase.co';
    const SERVICE_KEY = env.SUPABASE_SERVICE_ROLE_KEY;
    if (!SERVICE_KEY) return jsonResponse({ error: 'Server not configured for deletion' }, 500);

    // 1) Verify + resolve the caller from their JWT — the id comes from the
    //    token, so a user can only ever delete themselves.
    const whoRes = await fetch(`${SUPABASE_URL}/auth/v1/user`, {
      headers: { apikey: SERVICE_KEY, Authorization: `Bearer ${token}` },
    });
    if (whoRes.status !== 200) return jsonResponse({ error: 'Invalid or expired session' }, 401);
    const who = await whoRes.json();
    const userId = who?.id;
    if (!userId) return jsonResponse({ error: 'Could not identify account' }, 401);

    // 1b) An intent record first: if this request dies after the auth delete,
    //     the daily cron (purgeRetrySweep) still finishes the clean-up.
    //     A frozen account deleted at once from its frozen screen loses its
    //     guestbook notes too, as the 7-day clean-up would have deleted them
    //     (go-live round 2): child rides in the record, so a retry deletes
    //     them as well. A child is a stored birthday under 13, or an under-13
    //     purge clock (freeze:<uid>) still running for one who has turned 13
    //     since. Both are read before anything is deleted, failing closed
    //     (go-live round 3: a marker read that failed counted as "not a
    //     child", and the notes stayed up as "A traveler" for good): when the
    //     answer can't be read, nothing is deleted and the person is asked to
    //     try again.
    const kv = env.GLOBESKIMMERS_KV;
    const sp = await gbSocialProfile(env, userId).catch(() => undefined);
    if (sp === undefined) return jsonResponse({ error: 'Couldn’t check your account — try again', code: 'age_unknown' }, 503);
    let child = gbUnderAge(sp);
    if (!child && kv) {
      let marker;
      try { marker = await kv.get(`freeze:${userId}`); } catch { return jsonResponse({ error: 'Couldn’t check your account — try again', code: 'age_unknown' }, 503); }
      child = !!marker;
    }
    const tagChild = child ? { child: true } : {};
    if (kv) await gbPurgeRecordPut(kv, userId, { at: new Date().toISOString(), failed_steps: ['pending'], ...tagChild }).catch(() => {});

    // 2) Hard-delete the auth user FIRST (cascades profiles + login_events). If
    //    it fails, nothing is purged: the age record and the blocks stay, so a
    //    frozen account stays frozen and the person can simply try again. The
    //    intent record stays too: the cron checks the account before it purges
    //    anything, drops the record while the account is alive, and finishes
    //    the job if the delete did land after all (an answer lost on the way
    //    back). A 404 means the account is already gone.
    const delRes = await fetch(`${SUPABASE_URL}/auth/v1/admin/users/${userId}`, {
      method: 'DELETE',
      headers: { apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}` },
    }).catch(() => null);
    if (!delRes || ![200, 204, 404].includes(delRes.status)) {
      // A definite refusal (4xx) means the account is still there: its
      // pending record goes now, so others' pages don't show it as deleted
      // until the cron gets to it (go-live round 3). A 5xx or no answer
      // keeps it: the delete may have landed.
      if (kv && delRes && delRes.status >= 400 && delRes.status < 500) await kv.delete(`purge:${userId}`).catch(() => {});
      const detail = delRes ? await delRes.text().catch(() => '') : 'no answer';
      return jsonResponse({ error: `Deletion failed (${delRes ? delRes.status : 'network'})`, detail: detail.slice(0, 300) }, 502);
    }

    // 2b) Then everything else. A step that failed stays queued (purge:<uid>)
    //     for the daily cron, so the account is never left half-deleted for good.
    const purge = await gbPurgeUserContent(env, userId, { child });
    if (kv) {
      if (purge.ok) await kv.delete(`purge:${userId}`).catch(() => {});
      else await gbPurgeRecordPut(kv, userId, { at: new Date().toISOString(), failed_steps: purge.failed.slice(0, 12), ...tagChild, ...(purge.child ? { child: true } : {}) }).catch(() => {});
    }

    // 3) Their member number went in the purge (step 1l, retried with the
    //    rest; AUTOINCREMENT never gives the number to anyone else). Their
    //    new-member mark goes too (best-effort).
    if (env.GLOBESKIMMERS_KV) {
      await env.GLOBESKIMMERS_KV.delete(`bell:user:${userId}`).catch(() => {});
      await env.GLOBESKIMMERS_KV.delete(`freeze:${userId}`).catch(() => {});   // nothing left to purge
    }

    return jsonResponse({ ok: true });
  } catch (e) {
    return jsonResponse({ error: e.message || 'Deletion failed' }, 500);
  }
}

// ── Admin user stats — aggregate metrics from Supabase profiles ───────────
// User data lives in Supabase now (not Base44), so the admin dashboard reads it
// here with the SERVICE ROLE key (bypasses RLS). Gated to admin emails, verified
// from the caller's JWT. Returns ONLY aggregates (counts / distributions) — no
// per-user rows, emails, or PII ever leave the Worker.
// Keep ADMIN_EMAILS_WORKER in sync with src/lib/admins.js.
const ADMIN_EMAILS_WORKER = [
  'maizasimeon@gmail.com', 'founder@globeskimmers.io',
];
// The accounts Admin's people counts leave out (growth plan week 1, done 2026-10-20): the admins
// and the App Review demo, which Claude's screenshot runs also sign in as. Resolved to account ids
// once a day (KV); a device that ever signed in as one of them is left out too.
const ANALYTICS_EXCLUDE_EMAILS = [...ADMIN_EMAILS_WORKER, 'appreview@globeskimmers.io'];
async function gbTestAccountIds(env) {
  const kv = env.GLOBESKIMMERS_KV;
  const ck = 'an:excl:v1';
  try { const c = kv ? await kv.get(ck) : null; if (c) return JSON.parse(c); } catch { /* resolve again */ }
  const ids = [];
  for (const email of ANALYTICS_EXCLUDE_EMAILS) {
    try {
      const r = await gbRest(env, 'rpc/user_id_by_email', { method: 'POST', body: JSON.stringify({ p_email: email }) });
      if (!r.ok) continue;
      const v = await r.json().catch(() => null);
      const id = String((typeof v === 'string' ? v : Array.isArray(v) ? v[0] : v?.user_id) || '').toLowerCase();
      if (/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/.test(id)) ids.push(id);
    } catch { /* that one stays counted */ }
  }
  if (kv && ids.length) await kv.put(ck, JSON.stringify(ids), { expirationTtl: 86400 }).catch(() => {});
  return ids;
}
// The SQL that drops those accounts and their devices from an events query (ids are UUID-checked).
const gbNotTestSql = (ids) => {
  const list = (ids || []).filter((x) => /^[0-9a-f-]{36}$/.test(x)).map((x) => `'${x}'`).join(',');
  return list ? ` AND COALESCE(user_id,'') NOT IN (${list}) AND (anon_id IS NULL OR anon_id NOT IN (SELECT DISTINCT anon_id FROM events WHERE anon_id IS NOT NULL AND user_id IN (${list})))` : '';
};

async function handleAdminUserStats(request, env) {
  try {
    const authHeader = request.headers.get('Authorization') || '';
    const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7).trim() : '';
    if (!token) return jsonResponse({ error: 'Not signed in' }, 401);

    const SUPABASE_URL = env.SUPABASE_URL || 'https://bkaxadiyehddzkiuheea.supabase.co';
    const SERVICE_KEY = env.SUPABASE_SERVICE_ROLE_KEY;
    if (!SERVICE_KEY) return jsonResponse({ error: 'Server not configured' }, 500);

    // Verify the caller from their JWT, then gate to admins.
    const whoRes = await fetch(`${SUPABASE_URL}/auth/v1/user`, {
      headers: { apikey: SERVICE_KEY, Authorization: `Bearer ${token}` },
    });
    if (whoRes.status !== 200) return jsonResponse({ error: 'Invalid or expired session' }, 401);
    const who = await whoRes.json();
    const email = String(who?.email || '').trim().toLowerCase();
    if (!ADMIN_EMAILS_WORKER.includes(email)) return jsonResponse({ error: 'Forbidden' }, 403);

    // Read all profiles with the service key (bypasses RLS). select=* is safe —
    // PostgREST won't error on columns that don't exist. profiles lives in the
    // `public` schema; PostgREST's default here is `api`, so without the
    // Accept-Profile header this read 404s (PGRST205) and the route 502s.
    const res = await fetch(`${SUPABASE_URL}/rest/v1/profiles?select=*`, {
      headers: { apikey: SERVICE_KEY, Authorization: `Bearer ${SERVICE_KEY}`, 'Accept-Profile': 'public' },
    });
    if (res.status !== 200) {
      const detail = await res.text().catch(() => '');
      return jsonResponse({ error: `profiles read failed (${res.status})`, detail: detail.slice(0, 200) }, 502);
    }
    const list = await res.json().then((r) => (Array.isArray(r) ? r : [])).catch(() => []);

    const tally = (key) => {
      const m = {};
      for (const r of list) {
        const v = r?.[key];
        if (v == null || v === '') continue;
        m[v] = (m[v] || 0) + 1;
      }
      return Object.entries(m).map(([label, count]) => ({ label, count })).sort((a, b) => b.count - a.count);
    };

    // Sign-ups per day (last 30d) if a timestamp column exists.
    const dateKey = list.some((r) => r?.created_at) ? 'created_at' : (list.some((r) => r?.inserted_at) ? 'inserted_at' : null);
    let signupsByDay = [];
    if (dateKey) {
      const m = {};
      const cutoff = Date.now() - 30 * 24 * 60 * 60 * 1000;
      for (const r of list) {
        const t = Date.parse(r[dateKey]);
        if (!Number.isFinite(t) || t < cutoff) continue;
        const day = new Date(t).toISOString().slice(0, 10);
        m[day] = (m[day] || 0) + 1;
      }
      signupsByDay = Object.entries(m).map(([day, count]) => ({ day, count })).sort((a, b) => a.day.localeCompare(b.day));
    }

    // Age mix — from the social age gate (social_profiles.birth_year). Only
    // users who have passed the gate appear; ageKnown says how many that is.
    let ageMix = [], ageKnown = 0;
    try {
      const sp = await gbRest(env, 'social_profiles?select=birth_year', {});
      const rows = sp.ok ? await sp.json() : [];
      const yearNow = new Date().getFullYear();
      const buckets = [['13-17', 13, 17], ['18-24', 18, 24], ['25-34', 25, 34], ['35-44', 35, 44], ['45-54', 45, 54], ['55-64', 55, 64], ['65+', 65, 200]];
      const counts = {};
      for (const r of (Array.isArray(rows) ? rows : [])) {
        const y = Number(r?.birth_year);
        if (!(y >= 1900 && y <= yearNow)) continue;
        const a = yearNow - y; ageKnown++;
        const bk = buckets.find(([, lo, hi]) => a >= lo && a <= hi);
        if (bk) counts[bk[0]] = (counts[bk[0]] || 0) + 1;
      }
      ageMix = buckets.map(([label]) => ({ label, count: counts[label] || 0 })).filter((x) => x.count > 0);
    } catch { /* best-effort */ }

    return jsonResponse({
      totalUsers: list.length,
      ageMix, ageKnown,
      onboardingCompleted: list.filter((r) => r?.onboarding_completed === true).length,
      byCountry: tally('home_country').slice(0, 15),
      byLanguage: tally('preferred_language').slice(0, 15),
      byCurrency: tally('preferred_currency').slice(0, 15),
      signupsByDay,
      generatedAt: Date.now(),
    });
  } catch (e) {
    return jsonResponse({ error: e.message || 'admin stats failed' }, 500);
  }
}

// ── Analytics query endpoint — read-only allowlisted SELECTs against D1 ───
// Browser sends { type: 'page_views_7d' | 'top_zero_results' | ... }, NOT
// raw SQL. Each type maps to a hardcoded prepared statement. This is the
// only safe way to expose D1 reads to the frontend.
//
// Auth: this endpoint relies on the calling Deno function (getAnalytics)
// having already verified the admin email. The Worker itself doesn't do
// auth — anyone hitting this URL directly will get analytics data, which
// is acceptable for now (the data is aggregate, no PII), but if that
// changes we'd add a shared-secret header check here.
const ANALYTICS_QUERIES = {
  // The growth funnel: shares → landing views → store taps, by day.
  share_funnel_30d: `SELECT date(created_at) AS day,
      SUM(CASE WHEN event_type = 'passport_share' THEN 1 ELSE 0 END) AS shares,
      SUM(CASE WHEN event_type = 'share_landing_view' THEN 1 ELSE 0 END) AS landing_views,
      SUM(CASE WHEN event_type = 'share_landing_store' THEN 1 ELSE 0 END) AS store_taps
    FROM events
    WHERE created_at >= datetime('now','-30 days')
      AND event_type IN ('passport_share','share_landing_view','share_landing_store')
    GROUP BY day ORDER BY day DESC`,
  // ── Discover / behavior ("what people pick") — from the events table via the
  //    canonical logDiscover shape {city,country,intent,payload}. No PII; aggregate. ──
  discover_top_destinations: `
    SELECT json_extract(payload,'$.city') AS city, json_extract(payload,'$.country') AS country,
      COUNT(*) AS views,
      SUM(CASE WHEN json_extract(payload,'$.intent')='planning' THEN 1 ELSE 0 END) AS planning,
      SUM(CASE WHEN json_extract(payload,'$.intent')='present' THEN 1 ELSE 0 END) AS present
    FROM events
    WHERE event_type='home_rows_view' AND IFNULL(json_extract(payload,'$.city'),'')<>''
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY city, country ORDER BY views DESC LIMIT 40
  `,
  discover_destinations_periods: `
    SELECT
      (SELECT COUNT(DISTINCT json_extract(payload,'$.city')) FROM events WHERE event_type='home_rows_view' AND IFNULL(json_extract(payload,'$.city'),'')<>'' AND date(ts,'unixepoch')=date('now')) AS today,
      (SELECT COUNT(DISTINCT json_extract(payload,'$.city')) FROM events WHERE event_type='home_rows_view' AND IFNULL(json_extract(payload,'$.city'),'')<>'' AND ts>=strftime('%s','now','-7 days')) AS week,
      (SELECT COUNT(DISTINCT json_extract(payload,'$.city')) FROM events WHERE event_type='home_rows_view' AND IFNULL(json_extract(payload,'$.city'),'')<>'' AND ts>=strftime('%s','now','-30 days')) AS month
  `,
  discover_trending_foods: `
    SELECT json_extract(payload,'$.dish') AS dish, json_extract(payload,'$.city') AS city,
      SUM(CASE WHEN json_extract(payload,'$.viral')=1 OR json_extract(payload,'$.viral')='true' THEN 1 ELSE 0 END) AS viral_taps,
      COUNT(*) AS taps
    FROM events
    WHERE event_type='right_now_tap' AND json_extract(payload,'$.where')='dish' AND IFNULL(json_extract(payload,'$.dish'),'')<>''
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY dish, city ORDER BY taps DESC LIMIT 40
  `,
  discover_hotel_areas: `
    SELECT json_extract(payload,'$.area') AS area, json_extract(payload,'$.city') AS city, COUNT(*) AS taps
    FROM events
    WHERE event_type='where_to_stay_area_tap' AND IFNULL(json_extract(payload,'$.area'),'')<>''
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY area, city ORDER BY taps DESC LIMIT 40
  `,
  discover_escapes: `
    SELECT json_extract(payload,'$.name') AS trip, json_extract(payload,'$.city') AS base, COUNT(*) AS taps
    FROM events
    WHERE event_type='escape_card_tap' AND IFNULL(json_extract(payload,'$.name'),'')<>''
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY trip, base ORDER BY taps DESC LIMIT 40
  `,
  // ── Search-intent graph ("what people search, and where") — from the canonical
  //    logSearch/logDiscover 'search' events. Every query carries city/country +
  //    intent (present=there now | planning=dreaming about it). NO PII; aggregate. ──
  // Top queries by (city,country) with the present/planning split — answers
  // "cheap souvenirs: Tokyo?" and "AC hotel: Paris or Berlin?".
  searches_by_city: `
    SELECT json_extract(payload,'$.query') AS query,
      json_extract(payload,'$.category') AS category,
      json_extract(payload,'$.city') AS city,
      json_extract(payload,'$.country') AS country,
      COUNT(*) AS searches,
      SUM(CASE WHEN json_extract(payload,'$.intent')='planning' THEN 1 ELSE 0 END) AS planning,
      SUM(CASE WHEN json_extract(payload,'$.intent')='present' THEN 1 ELSE 0 END) AS present
    FROM events
    WHERE event_type='search' AND IFNULL(json_extract(payload,'$.query'),'')<>''
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY query, category, city, country
    ORDER BY searches DESC LIMIT 60
  `,
  // Demand MIX per city — what a place's visitors mostly want (eat vs shop vs
  // stay vs do). Answers "when people go to Tokyo, what do they search for?".
  search_categories_by_city: `
    SELECT json_extract(payload,'$.city') AS city,
      json_extract(payload,'$.country') AS country,
      json_extract(payload,'$.category') AS category,
      COUNT(*) AS searches
    FROM events
    WHERE event_type='search' AND IFNULL(json_extract(payload,'$.city'),'')<>''
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY city, country, category
    ORDER BY searches DESC LIMIT 60
  `,
  // Rides: airport transfer vs rental car vs rideshare, by city — answers "are
  // they looking for more transfers or more rentals, and where?".
  transfer_vs_rental: `
    SELECT json_extract(payload,'$.type') AS ride_type,
      json_extract(payload,'$.city') AS city,
      json_extract(payload,'$.country') AS country,
      COUNT(*) AS taps
    FROM events
    WHERE event_type='ride_option_tap' AND IFNULL(json_extract(payload,'$.type'),'')<>''
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY ride_type, city, country
    ORDER BY taps DESC LIMIT 60
  `,
  // Zero-result searches by city — the highest-value signal: demand we can't
  // yet serve = where to expand coverage or inventory.
  zero_results_by_city: `
    SELECT json_extract(payload,'$.query') AS query,
      json_extract(payload,'$.category') AS category,
      json_extract(payload,'$.city') AS city,
      json_extract(payload,'$.country') AS country,
      COUNT(*) AS misses
    FROM events
    WHERE event_type='search_zero_results' AND IFNULL(json_extract(payload,'$.query'),'')<>''
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY query, category, city, country
    ORDER BY misses DESC LIMIT 60
  `,
  // ── SMART-SEARCH SPINE (source='smart_search') — the unified Home search's
  //    demand signals: HOW people scope, WHICH worlds it opens, WHICH places
  //    they name. First-party moat data; NO PII; aggregate. ──
  smart_search_by_scope: `
    SELECT json_extract(payload,'$.scope') AS scope,
      COUNT(*) AS searches
    FROM events
    WHERE event_type='search' AND json_extract(payload,'$.source')='smart_search'
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY scope
    ORDER BY searches DESC LIMIT 20
  `,
  smart_search_by_category: `
    SELECT json_extract(payload,'$.category') AS category,
      COUNT(*) AS searches,
      SUM(CASE WHEN json_extract(payload,'$.parsed_by')='ai' THEN 1 ELSE 0 END) AS ai_parsed
    FROM events
    WHERE event_type='search' AND json_extract(payload,'$.source')='smart_search'
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY category
    ORDER BY searches DESC LIMIT 30
  `,
  smart_search_top_places: `
    SELECT json_extract(payload,'$.place') AS place,
      COUNT(*) AS searches
    FROM events
    WHERE event_type='search' AND json_extract(payload,'$.source')='smart_search'
      AND IFNULL(json_extract(payload,'$.place'),'')<>''
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY place
    ORDER BY searches DESC LIMIT 40
  `,
  // ── Affiliate (from affiliate_clicks; needs scripts/affiliate/01_schema.sql) ──
  affiliate_by_partner_30d: `
    SELECT partner,
      COUNT(*) AS clicks,
      SUM(CASE WHEN converted = 1 THEN 1 ELSE 0 END) AS conversions,
      ROUND(COALESCE(SUM(commission), 0), 2) AS commission
    FROM affiliate_clicks
    WHERE ts >= strftime('%s','now','-30 days')
      AND (intent IS NULL OR intent != 'sandbox')
    GROUP BY partner
    ORDER BY clicks DESC
  `,
  affiliate_by_day_14d: `
    SELECT date(ts,'unixepoch') AS day, COUNT(*) AS clicks
    FROM affiliate_clicks
    WHERE ts >= strftime('%s','now','-14 days')
    GROUP BY day
    ORDER BY day
  `,
  affiliate_top_products_30d: `
    SELECT product_name AS name, partner, category, COUNT(*) AS clicks
    FROM affiliate_clicks
    WHERE ts >= strftime('%s','now','-30 days') AND product_name IS NOT NULL AND product_name <> ''
    GROUP BY product_name, partner
    ORDER BY clicks DESC
    LIMIT 20
  `,
  affiliate_by_country_30d: `
    SELECT dest_country AS country, COUNT(*) AS clicks
    FROM affiliate_clicks
    WHERE ts >= strftime('%s','now','-30 days') AND dest_country IS NOT NULL AND dest_country <> ''
    GROUP BY dest_country
    ORDER BY clicks DESC
    LIMIT 20
  `,
  // ── THE MONEY FUNNEL (joins events↔affiliate_clicks by session_id) ──
  // 4 stages of distinct sessions: any session → engaged (tapped something) →
  // clicked an affiliate link → booked. 'booked' stays 0 until the conversion
  // backfill (offline import) lands. Works for anonymous users via session_id.
  affiliate_funnel_30d: `
    SELECT
      (SELECT COUNT(DISTINCT session_id) FROM events
        WHERE ts >= strftime('%s','now','-30 days') AND session_id IS NOT NULL) AS sessions,
      (SELECT COUNT(DISTINCT session_id) FROM events
        WHERE ts >= strftime('%s','now','-30 days')
        AND event_type IN ('discover_select','home_row_card_tap','directions_tap','event_tap','right_now_tap','escape_card_tap','where_to_stay_area_tap','wishlist_add','deal_tap','dream_gallery_open','dream_gallery_build_trip','dream_tease_build','dream_shelf_tap','dreamer_corner_anywhere','event_window','exp_view')) AS engaged_sessions,
      (SELECT COUNT(DISTINCT session_id) FROM affiliate_clicks
        WHERE ts >= strftime('%s','now','-30 days') AND session_id IS NOT NULL) AS click_sessions,
      (SELECT COUNT(DISTINCT session_id) FROM affiliate_clicks
        WHERE ts >= strftime('%s','now','-30 days') AND converted = 1
        AND (intent IS NULL OR intent != 'sandbox')) AS booked_sessions
  `,
  affiliate_clicks_by_intent_30d: `
    SELECT COALESCE(intent,'(unknown)') AS intent,
      COUNT(*) AS clicks,
      SUM(CASE WHEN converted = 1 THEN 1 ELSE 0 END) AS conversions
    FROM affiliate_clicks
    WHERE ts >= strftime('%s','now','-30 days')
      AND (intent IS NULL OR intent != 'sandbox')
    GROUP BY intent ORDER BY clicks DESC
  `,
  // ── Affiliate REVENUE by partner (filled once /aff/import backfills conversions) ──
  // 90-day window because bookings lag the click. commission is only summed for
  // converted rows; 'confirmed' is the subset that also shows in My Trip.
  affiliate_revenue_90d: `
    SELECT partner,
      COUNT(*) AS clicks,
      SUM(CASE WHEN converted = 1 THEN 1 ELSE 0 END) AS conversions,
      SUM(CASE WHEN status = 'confirmed' THEN 1 ELSE 0 END) AS confirmed,
      COALESCE(currency,'USD') AS currency,
      ROUND(SUM(CASE WHEN converted = 1 THEN COALESCE(commission,0) ELSE 0 END), 2) AS commission
    FROM affiliate_clicks
    WHERE ts >= strftime('%s','now','-90 days')
      AND (intent IS NULL OR intent != 'sandbox')
    GROUP BY partner, currency ORDER BY commission DESC, clicks DESC
  `,
  // ── RETENTION COHORTS — the make-or-break metric for an episodic-travel app,
  // keyed on the DURABLE anon_id (added 2026-08-22), so it survives sessions unlike
  // the older session-based active_users/retention_7d. For devices first seen in the
  // last 90 days: did they come back on day+1, in week 1 (day+7), after day 30, or
  // EVER (the best episodic signal)? NOTE the CAST: in a CTE, MIN(ts) has no column
  // affinity, so an uncast TEXT strftime bound silently makes numeric<text false.
  retention_cohorts_90d: `
    WITH fs AS (SELECT anon_id, MIN(ts) AS f FROM events WHERE anon_id IS NOT NULL /*NOT_TEST*/ GROUP BY anon_id)
    SELECT
      COUNT(*) AS new_users,
      SUM(CASE WHEN EXISTS (SELECT 1 FROM events e WHERE e.anon_id=fs.anon_id AND e.ts>=fs.f+86400 AND e.ts<fs.f+2*86400) THEN 1 ELSE 0 END) AS d1,
      SUM(CASE WHEN EXISTS (SELECT 1 FROM events e WHERE e.anon_id=fs.anon_id AND e.ts>=fs.f+7*86400 AND e.ts<fs.f+8*86400) THEN 1 ELSE 0 END) AS d7,
      SUM(CASE WHEN EXISTS (SELECT 1 FROM events e WHERE e.anon_id=fs.anon_id AND e.ts>=fs.f+30*86400) THEN 1 ELSE 0 END) AS d30_plus,
      SUM(CASE WHEN EXISTS (SELECT 1 FROM events e WHERE e.anon_id=fs.anon_id AND e.ts>fs.f+86400) THEN 1 ELSE 0 END) AS ever_returned
    FROM fs WHERE fs.f >= CAST(strftime('%s','now','-90 days') AS INTEGER)
  `,
  // ── Wishlist DEMAND (from 'wishlist_add' events; payload kind/title/city/country) ──
  // The Demand Radar's first-party signal: what people WANT (dream destinations,
  // experiences, shows) — aggregate + anonymizable, no PII. Drives affiliate targeting.
  wishlist_top_30d: `
    SELECT json_extract(payload,'$.title') AS title,
      json_extract(payload,'$.kind') AS kind,
      json_extract(payload,'$.city') AS city,
      COUNT(*) AS wishes,
      COUNT(DISTINCT COALESCE(user_id, session_id)) AS people
    FROM events
    WHERE event_type='wishlist_add' AND ts >= strftime('%s','now','-30 days')
      AND json_extract(payload,'$.title') IS NOT NULL AND json_extract(payload,'$.title') <> ''
    GROUP BY title, kind, city ORDER BY wishes DESC LIMIT 40
  `,
  wishlist_by_city_30d: `
    SELECT json_extract(payload,'$.city') AS city,
      json_extract(payload,'$.country') AS country,
      COUNT(*) AS wishes,
      COUNT(DISTINCT COALESCE(user_id, session_id)) AS people
    FROM events
    WHERE event_type='wishlist_add' AND ts >= strftime('%s','now','-30 days')
      AND json_extract(payload,'$.city') IS NOT NULL AND json_extract(payload,'$.city') <> ''
    GROUP BY city, country ORDER BY wishes DESC LIMIT 40
  `,
  wishlist_by_kind_30d: `
    SELECT json_extract(payload,'$.kind') AS kind, COUNT(*) AS wishes
    FROM events
    WHERE event_type='wishlist_add' AND ts >= strftime('%s','now','-30 days')
    GROUP BY kind ORDER BY wishes DESC
  `,
  // ── Directions taps — the HIGHEST-INTENT signal ("actually going here"); one
  // event covers every finder. Feeds ranking + merchant/foot-traffic proof. ──
  directions_by_place_30d: `
    SELECT json_extract(payload,'$.place_name') AS place,
      json_extract(payload,'$.city') AS city,
      json_extract(payload,'$.country') AS country,
      COUNT(*) AS taps,
      COUNT(DISTINCT COALESCE(user_id, session_id)) AS people
    FROM events
    WHERE event_type='directions_tap' AND ts >= strftime('%s','now','-30 days')
      AND json_extract(payload,'$.place_name') IS NOT NULL AND json_extract(payload,'$.place_name') <> ''
    GROUP BY place, city ORDER BY taps DESC LIMIT 100
  `,
  // ── Persona (party-composition) segments — who's using the app, and what each
  // segment wants. Powers segment-aware curation + affiliate targeting. ──
  persona_distribution_30d: `
    SELECT json_extract(payload,'$.persona') AS persona,
      COUNT(*) AS events,
      COUNT(DISTINCT COALESCE(user_id, session_id)) AS people
    FROM events
    WHERE ts >= strftime('%s','now','-30 days')
      AND json_extract(payload,'$.persona') IS NOT NULL AND json_extract(payload,'$.persona') <> ''
    GROUP BY persona ORDER BY people DESC
  `,
  wishlist_by_persona_30d: `
    SELECT json_extract(payload,'$.persona') AS persona,
      json_extract(payload,'$.title') AS title,
      COUNT(*) AS wishes
    FROM events
    WHERE event_type='wishlist_add' AND ts >= strftime('%s','now','-30 days')
      AND json_extract(payload,'$.persona') IS NOT NULL AND json_extract(payload,'$.persona') <> ''
    GROUP BY persona, title ORDER BY wishes DESC LIMIT 60
  `,
  // ── Wishlist → booking-CTA funnel (the wishlist→affiliate money step). ──
  wishlist_cta_30d: `
    SELECT json_extract(payload,'$.action') AS action,
      json_extract(payload,'$.kind') AS kind,
      json_extract(payload,'$.city') AS city,
      COUNT(*) AS taps
    FROM events
    WHERE event_type='wishlist_cta' AND ts >= strftime('%s','now','-30 days')
    GROUP BY action, kind, city ORDER BY taps DESC LIMIT 60
  `,
  // ── Passport stamps (from 'passport_stamp' events; payload has kind/country/city/name) ──
  passport_totals: `
    SELECT COUNT(*) AS total_stamps,
      COUNT(DISTINCT json_extract(payload,'$.country')) AS countries,
      SUM(CASE WHEN json_extract(payload,'$.kind')='attraction' THEN 1 ELSE 0 END) AS attraction_stamps,
      SUM(CASE WHEN json_extract(payload,'$.kind')='city' THEN 1 ELSE 0 END) AS city_stamps,
      SUM(CASE WHEN json_extract(payload,'$.kind')='airport' THEN 1 ELSE 0 END) AS airport_stamps,
      SUM(CASE WHEN json_extract(payload,'$.kind')='country' THEN 1 ELSE 0 END) AS country_stamps
    FROM events WHERE event_type='passport_stamp'
  `,
  passport_by_country: `
    SELECT json_extract(payload,'$.country') AS country, COUNT(*) AS stamps
    FROM events
    WHERE event_type='passport_stamp' AND json_extract(payload,'$.country') IS NOT NULL AND json_extract(payload,'$.country') <> ''
    GROUP BY country ORDER BY stamps DESC LIMIT 100
  `,
  passport_by_city: `
    SELECT json_extract(payload,'$.city') AS city, json_extract(payload,'$.country') AS country, COUNT(*) AS stamps
    FROM events
    WHERE event_type='passport_stamp' AND json_extract(payload,'$.city') IS NOT NULL AND json_extract(payload,'$.city') <> ''
    GROUP BY city, country ORDER BY stamps DESC LIMIT 100
  `,
  passport_by_attraction: `
    SELECT json_extract(payload,'$.name') AS name, json_extract(payload,'$.city') AS city, json_extract(payload,'$.country') AS country, COUNT(*) AS stamps
    FROM events
    WHERE event_type='passport_stamp' AND json_extract(payload,'$.kind')='attraction' AND json_extract(payload,'$.name') IS NOT NULL
    GROUP BY name, city ORDER BY stamps DESC LIMIT 100
  `,
  passport_by_day_30d: `
    SELECT date(ts,'unixepoch') AS day, COUNT(*) AS stamps
    FROM events WHERE event_type='passport_stamp' AND ts >= strftime('%s','now','-30 days')
    GROUP BY day ORDER BY day
  `,
  passport_by_month_12m: `
    SELECT strftime('%Y-%m', ts, 'unixepoch') AS month, COUNT(*) AS stamps
    FROM events WHERE event_type='passport_stamp' AND ts >= strftime('%s','now','-365 days')
    GROUP BY month ORDER BY month
  `,
  // Passport shares (client 'passport_share' events, founder ask 2026-09-28):
  // per month × platform × use. platform = the app iOS reported from the share
  // sheet, else the destination picked in the preview, else 'unknown' (Android
  // and browser shares don't say). use = 'message' for messaging apps, else the
  // size picked in the preview (story / post).
  passport_shares_by_month_12m: `
    SELECT strftime('%Y-%m', ts, 'unixepoch') AS month,
           COALESCE(NULLIF(json_extract(payload,'$.platform'),''),'unknown') AS platform,
           CASE WHEN json_extract(payload,'$.platform') IN ('whatsapp','messages','messenger','mail') THEN 'message'
                ELSE COALESCE(NULLIF(json_extract(payload,'$.format'),''),'unknown') END AS use,
           COUNT(*) AS shares,
           SUM(COALESCE(json_extract(payload,'$.images'),1)) AS images
    FROM events WHERE event_type='passport_share' AND ts >= strftime('%s','now','-365 days')
    GROUP BY month, platform, use ORDER BY month DESC, shares DESC
  `,
  passport_share_funnel_12m: `
    SELECT strftime('%Y-%m', ts, 'unixepoch') AS month,
           SUM(CASE WHEN event_type='passport_share_open' THEN 1 ELSE 0 END) AS previews,
           SUM(CASE WHEN event_type='passport_share' THEN 1 ELSE 0 END) AS shared,
           SUM(CASE WHEN event_type='passport_share_cancel' THEN 1 ELSE 0 END) AS cancelled
    FROM events WHERE event_type IN ('passport_share_open','passport_share','passport_share_cancel')
      AND ts >= strftime('%s','now','-365 days')
    GROUP BY month ORDER BY month DESC
  `,
  passport_by_year: `
    SELECT strftime('%Y', ts, 'unixepoch') AS year, COUNT(*) AS stamps
    FROM events WHERE event_type='passport_stamp'
    GROUP BY year ORDER BY year
  `,
  // Distinct countries stamped in the last day / week / month (single row).
  passport_countries_periods: `
    SELECT
      (SELECT COUNT(DISTINCT json_extract(payload,'$.country')) FROM events WHERE event_type='passport_stamp' AND IFNULL(json_extract(payload,'$.country'),'')<>'' AND date(ts,'unixepoch')=date('now')) AS today,
      (SELECT COUNT(DISTINCT json_extract(payload,'$.country')) FROM events WHERE event_type='passport_stamp' AND IFNULL(json_extract(payload,'$.country'),'')<>'' AND ts>=strftime('%s','now','-7 days')) AS week,
      (SELECT COUNT(DISTINCT json_extract(payload,'$.country')) FROM events WHERE event_type='passport_stamp' AND IFNULL(json_extract(payload,'$.country'),'')<>'' AND ts>=strftime('%s','now','-30 days')) AS month
  `,
  // Distinct countries + total stamps per calendar month (12 months).
  passport_countries_by_month: `
    SELECT strftime('%Y-%m', ts,'unixepoch') AS month,
      COUNT(DISTINCT json_extract(payload,'$.country')) AS countries,
      COUNT(*) AS stamps
    FROM events WHERE event_type='passport_stamp' AND ts>=strftime('%s','now','-365 days')
    GROUP BY month ORDER BY month
  `,
  // What hour of day people stamp (local hour when logged, else UTC), split by kind.
  passport_by_hour: `
    SELECT CAST(COALESCE(json_extract(payload,'$.local_hour'), CAST(strftime('%H', ts,'unixepoch') AS INTEGER)) AS INTEGER) AS hour,
      SUM(CASE WHEN json_extract(payload,'$.kind')='airport' THEN 1 ELSE 0 END) AS airport,
      SUM(CASE WHEN IFNULL(json_extract(payload,'$.kind'),'')<>'airport' THEN 1 ELSE 0 END) AS attraction,
      COUNT(*) AS total
    FROM events WHERE event_type='passport_stamp'
    GROUP BY hour ORDER BY hour
  `,
  // Stamps per day (30d), split airport vs attraction.
  passport_by_day_kind_30d: `
    SELECT date(ts,'unixepoch') AS day,
      SUM(CASE WHEN json_extract(payload,'$.kind')='airport' THEN 1 ELSE 0 END) AS airport,
      SUM(CASE WHEN IFNULL(json_extract(payload,'$.kind'),'')<>'airport' THEN 1 ELSE 0 END) AS attraction,
      COUNT(*) AS total
    FROM events WHERE event_type='passport_stamp' AND ts>=strftime('%s','now','-30 days')
    GROUP BY day ORDER BY day
  `,
  // Stamps per ISO-ish week (12 weeks), split airport vs destination — the
  // founder's cut: "airports vs destinations, per day/week/month".
  passport_by_week_kind_12w: `
    SELECT strftime('%Y-W%W', ts,'unixepoch') AS week,
      SUM(CASE WHEN json_extract(payload,'$.kind')='airport' THEN 1 ELSE 0 END) AS airport,
      SUM(CASE WHEN IFNULL(json_extract(payload,'$.kind'),'')<>'airport' THEN 1 ELSE 0 END) AS attraction,
      COUNT(*) AS total
    FROM events WHERE event_type='passport_stamp' AND ts>=strftime('%s','now','-84 days')
    GROUP BY week ORDER BY week
  `,
  // Stamps per calendar month (12m), split airport vs destination.
  passport_by_month_kind_12m: `
    SELECT strftime('%Y-%m', ts,'unixepoch') AS month,
      SUM(CASE WHEN json_extract(payload,'$.kind')='airport' THEN 1 ELSE 0 END) AS airport,
      SUM(CASE WHEN IFNULL(json_extract(payload,'$.kind'),'')<>'airport' THEN 1 ELSE 0 END) AS attraction,
      COUNT(*) AS total
    FROM events WHERE event_type='passport_stamp' AND ts>=strftime('%s','now','-365 days')
    GROUP BY month ORDER BY month
  `,
  // WHICH airports get stamped (IATA in entity_id when present).
  passport_top_airports: `
    SELECT json_extract(payload,'$.name') AS name,
      json_extract(payload,'$.entity_id') AS iata,
      json_extract(payload,'$.country') AS country, COUNT(*) AS stamps
    FROM events
    WHERE event_type='passport_stamp' AND json_extract(payload,'$.kind')='airport' AND json_extract(payload,'$.name') IS NOT NULL
    GROUP BY name, country ORDER BY stamps DESC LIMIT 50
  `,
  // Total events + unique sessions in the last 7 days
  totals_7d: `
    SELECT
      COUNT(*) AS total_events,
      COUNT(DISTINCT session_id) AS unique_sessions
    FROM events
    WHERE ts >= strftime('%s','now','-7 days')
  `,
  // Page view counts per page, last 7 days
  page_views_7d: `
    SELECT page, COUNT(*) AS views
    FROM events
    WHERE event_type = 'page_view' AND ts >= strftime('%s','now','-7 days')
    GROUP BY page
    ORDER BY views DESC
  `,
  // Event type breakdown, last 7 days
  event_type_breakdown_7d: `
    SELECT event_type, COUNT(*) AS count
    FROM events
    WHERE ts >= strftime('%s','now','-7 days')
    GROUP BY event_type
    ORDER BY count DESC
  `,
  // Top 20 queries that returned zero results — the most actionable analytic
  top_zero_results: `
    SELECT
      json_extract(payload, '$.query') AS query,
      json_extract(payload, '$.cuisine') AS cuisine,
      COUNT(*) AS hits
    FROM events
    WHERE event_type = 'search_zero_results'
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY query, cuisine
    ORDER BY hits DESC
    LIMIT 20
  `,
  // Top successful search queries, last 7 days
  top_searches_7d: `
    SELECT
      json_extract(payload, '$.query') AS query,
      COUNT(*) AS hits,
      AVG(CAST(json_extract(payload, '$.resultCount') AS INTEGER)) AS avg_results
    FROM events
    WHERE event_type = 'search'
      AND ts >= strftime('%s','now','-7 days')
      AND json_extract(payload, '$.query') IS NOT NULL
    GROUP BY query
    ORDER BY hits DESC
    LIMIT 20
  `,
  // Events per day for the last 14 days (sparkline data)
  events_by_day_14d: `
    SELECT
      date(ts, 'unixepoch') AS day,
      COUNT(*) AS count
    FROM events
    WHERE ts >= strftime('%s','now','-14 days')
    GROUP BY day
    ORDER BY day ASC
  `,
  // Most recent 50 events (raw feed for debugging)
  recent_events: `
    SELECT ts, page, event_type, payload, session_id
    FROM events
    ORDER BY ts DESC
    LIMIT 50
  `,
  // AI Details opens per day across all users (14-day sparkline)
  ai_details_opens_by_day_14d: `
    SELECT
      date(ts, 'unixepoch') AS day,
      COUNT(*) AS opens
    FROM events
    WHERE event_type = 'ai_details_opened'
      AND ts >= strftime('%s','now','-14 days')
    GROUP BY day
    ORDER BY day ASC
  `,
  // Per-session: how many distinct restaurants did each user open AI
  // Details for, plus their total opens. Top 20 sessions in last 7 days.
  // Each session_id ≈ one user visit (per-browser-tab, sessionStorage).
  ai_details_per_session_7d: `
    SELECT
      session_id,
      COUNT(DISTINCT json_extract(payload, '$.placeId')) AS distinct_places_opened,
      COUNT(*) AS total_opens
    FROM events
    WHERE event_type = 'ai_details_opened'
      AND ts >= strftime('%s','now','-7 days')
      AND json_extract(payload, '$.placeId') IS NOT NULL
    GROUP BY session_id
    ORDER BY distinct_places_opened DESC
    LIMIT 20
  `,
  // PAID AI Details fetches per day (cache MISS only). Each row = $0.025
  // of Claude+Place-Details spend. Total cost = COUNT × $0.025.
  ai_details_paid_by_day_14d: `
    SELECT
      date(ts, 'unixepoch') AS day,
      COUNT(*) AS paid_fetches
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND json_extract(payload, '$.cache') != 'hit'
      AND ts >= strftime('%s','now','-14 days')
    GROUP BY day
    ORDER BY day ASC
  `,
  // FREE AI Details fetches per day (cache HIT). Each one is value
  // delivered at $0 cost — the cache earning its keep.
  ai_details_free_by_day_14d: `
    SELECT
      date(ts, 'unixepoch') AS day,
      COUNT(*) AS free_fetches
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND json_extract(payload, '$.cache') = 'hit'
      AND ts >= strftime('%s','now','-14 days')
    GROUP BY day
    ORDER BY day ASC
  `,
  // Per-session breakdown of paid vs cached. Top 20 sessions by paid
  // count — these are the most expensive users for the AI Details
  // feature. Useful for understanding which user behavior drives cost.
  ai_details_cost_per_session_7d: `
    SELECT
      session_id,
      SUM(CASE WHEN json_extract(payload, '$.cache') != 'hit' THEN 1 ELSE 0 END) AS paid_opens,
      SUM(CASE WHEN json_extract(payload, '$.cache') = 'hit' THEN 1 ELSE 0 END) AS free_opens,
      COUNT(DISTINCT CASE WHEN json_extract(payload, '$.cache') != 'hit' THEN json_extract(payload, '$.placeId') END) AS distinct_paid_places,
      COUNT(DISTINCT CASE WHEN json_extract(payload, '$.cache') = 'hit' THEN json_extract(payload, '$.placeId') END) AS distinct_free_places
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND ts >= strftime('%s','now','-7 days')
    GROUP BY session_id
    ORDER BY paid_opens DESC
    LIMIT 20
  `,
  // Cache hit rate over last 7 days — % of fetches served from cache
  // (no Google or Claude call needed). Single-row summary metric.
  ai_details_cache_rate_7d: `
    SELECT
      SUM(CASE WHEN json_extract(payload, '$.cache') = 'hit' THEN 1 ELSE 0 END) AS hits,
      SUM(CASE WHEN json_extract(payload, '$.cache') != 'hit' THEN 1 ELSE 0 END) AS misses,
      COUNT(*) AS total_fetches
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND ts >= strftime('%s','now','-7 days')
  `,
  // ── ATM AI DETAILS COST SPLIT ───────────────────────────────────────────
  // Same shape as ai_details_paid/free_by_day_14d but filtered to kind='atm'.
  // Lets the dashboard show the ATM-specific cost line alongside the global
  // numbers — important because the ATM redesign drives net-new Haiku spend
  // and we want to verify the cache earns its keep on the ATM panel
  // specifically.
  atm_ai_details_paid_by_day_14d: `
    SELECT
      date(ts, 'unixepoch') AS day,
      COUNT(*) AS paid_fetches
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND json_extract(payload, '$.kind') = 'atm'
      AND json_extract(payload, '$.cache') != 'hit'
      AND ts >= strftime('%s','now','-14 days')
    GROUP BY day
    ORDER BY day ASC
  `,
  atm_ai_details_free_by_day_14d: `
    SELECT
      date(ts, 'unixepoch') AS day,
      COUNT(*) AS free_fetches
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND json_extract(payload, '$.kind') = 'atm'
      AND json_extract(payload, '$.cache') = 'hit'
      AND ts >= strftime('%s','now','-14 days')
    GROUP BY day
    ORDER BY day ASC
  `,
  // ATM-specific cache hit rate over last 7 days. Lower-than-global hit
  // rate here means the ATM cache (or its TTL) needs tuning.
  atm_ai_details_cache_rate_7d: `
    SELECT
      SUM(CASE WHEN json_extract(payload, '$.cache') = 'hit' THEN 1 ELSE 0 END) AS hits,
      SUM(CASE WHEN json_extract(payload, '$.cache') != 'hit' THEN 1 ELSE 0 END) AS misses,
      COUNT(*) AS total_fetches
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND json_extract(payload, '$.kind') = 'atm'
      AND ts >= strftime('%s','now','-7 days')
  `,
  // ── PER-KIND AI DETAILS COST QUERIES ────────────────────────────────────
  // CONVENTION (for any future AI Details surface — restaurant, coffee,
  // attraction, restroom, atm, and anything we add later): every kind
  // gets its own paid_by_day_14d / free_by_day_14d / cache_rate_7d trio
  // so the dashboard can isolate that surface's Haiku spend and cache
  // health.
  //
  // The events these queries read are already emitted by every AI Details
  // renderer in the app (AIDetailsSection.jsx, AttractionAIDetails.jsx,
  // AtmAIDetails.jsx) with a `kind` payload field. If you add a new AI
  // Details surface (e.g. ShoppingFinder → kind='shopping'), copy the
  // three queries below for the new kind and add them to this block.
  //
  // Schemas:
  //   {kind}_ai_details_paid_by_day_14d  → daily cache MISSES (each row
  //     costs ~$0.025 Claude+Place-Details spend).
  //   {kind}_ai_details_free_by_day_14d  → daily cache HITS (each row is
  //     value delivered at $0 cost).
  //   {kind}_ai_details_cache_rate_7d    → 7-day hits/misses/total roll-up.
  attraction_ai_details_paid_by_day_14d: `
    SELECT date(ts, 'unixepoch') AS day, COUNT(*) AS paid_fetches
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND json_extract(payload, '$.kind') = 'attraction'
      AND json_extract(payload, '$.cache') != 'hit'
      AND ts >= strftime('%s','now','-14 days')
    GROUP BY day ORDER BY day ASC
  `,
  attraction_ai_details_free_by_day_14d: `
    SELECT date(ts, 'unixepoch') AS day, COUNT(*) AS free_fetches
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND json_extract(payload, '$.kind') = 'attraction'
      AND json_extract(payload, '$.cache') = 'hit'
      AND ts >= strftime('%s','now','-14 days')
    GROUP BY day ORDER BY day ASC
  `,
  attraction_ai_details_cache_rate_7d: `
    SELECT
      SUM(CASE WHEN json_extract(payload, '$.cache') = 'hit' THEN 1 ELSE 0 END) AS hits,
      SUM(CASE WHEN json_extract(payload, '$.cache') != 'hit' THEN 1 ELSE 0 END) AS misses,
      COUNT(*) AS total_fetches
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND json_extract(payload, '$.kind') = 'attraction'
      AND ts >= strftime('%s','now','-7 days')
  `,
  restaurant_ai_details_paid_by_day_14d: `
    SELECT date(ts, 'unixepoch') AS day, COUNT(*) AS paid_fetches
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND json_extract(payload, '$.kind') = 'restaurant'
      AND json_extract(payload, '$.cache') != 'hit'
      AND ts >= strftime('%s','now','-14 days')
    GROUP BY day ORDER BY day ASC
  `,
  restaurant_ai_details_free_by_day_14d: `
    SELECT date(ts, 'unixepoch') AS day, COUNT(*) AS free_fetches
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND json_extract(payload, '$.kind') = 'restaurant'
      AND json_extract(payload, '$.cache') = 'hit'
      AND ts >= strftime('%s','now','-14 days')
    GROUP BY day ORDER BY day ASC
  `,
  restaurant_ai_details_cache_rate_7d: `
    SELECT
      SUM(CASE WHEN json_extract(payload, '$.cache') = 'hit' THEN 1 ELSE 0 END) AS hits,
      SUM(CASE WHEN json_extract(payload, '$.cache') != 'hit' THEN 1 ELSE 0 END) AS misses,
      COUNT(*) AS total_fetches
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND json_extract(payload, '$.kind') = 'restaurant'
      AND ts >= strftime('%s','now','-7 days')
  `,
  coffee_ai_details_paid_by_day_14d: `
    SELECT date(ts, 'unixepoch') AS day, COUNT(*) AS paid_fetches
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND json_extract(payload, '$.kind') = 'coffee'
      AND json_extract(payload, '$.cache') != 'hit'
      AND ts >= strftime('%s','now','-14 days')
    GROUP BY day ORDER BY day ASC
  `,
  coffee_ai_details_free_by_day_14d: `
    SELECT date(ts, 'unixepoch') AS day, COUNT(*) AS free_fetches
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND json_extract(payload, '$.kind') = 'coffee'
      AND json_extract(payload, '$.cache') = 'hit'
      AND ts >= strftime('%s','now','-14 days')
    GROUP BY day ORDER BY day ASC
  `,
  coffee_ai_details_cache_rate_7d: `
    SELECT
      SUM(CASE WHEN json_extract(payload, '$.cache') = 'hit' THEN 1 ELSE 0 END) AS hits,
      SUM(CASE WHEN json_extract(payload, '$.cache') != 'hit' THEN 1 ELSE 0 END) AS misses,
      COUNT(*) AS total_fetches
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND json_extract(payload, '$.kind') = 'coffee'
      AND ts >= strftime('%s','now','-7 days')
  `,
  restroom_ai_details_paid_by_day_14d: `
    SELECT date(ts, 'unixepoch') AS day, COUNT(*) AS paid_fetches
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND json_extract(payload, '$.kind') = 'restroom'
      AND json_extract(payload, '$.cache') != 'hit'
      AND ts >= strftime('%s','now','-14 days')
    GROUP BY day ORDER BY day ASC
  `,
  restroom_ai_details_free_by_day_14d: `
    SELECT date(ts, 'unixepoch') AS day, COUNT(*) AS free_fetches
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND json_extract(payload, '$.kind') = 'restroom'
      AND json_extract(payload, '$.cache') = 'hit'
      AND ts >= strftime('%s','now','-14 days')
    GROUP BY day ORDER BY day ASC
  `,
  restroom_ai_details_cache_rate_7d: `
    SELECT
      SUM(CASE WHEN json_extract(payload, '$.cache') = 'hit' THEN 1 ELSE 0 END) AS hits,
      SUM(CASE WHEN json_extract(payload, '$.cache') != 'hit' THEN 1 ELSE 0 END) AS misses,
      COUNT(*) AS total_fetches
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND json_extract(payload, '$.kind') = 'restroom'
      AND ts >= strftime('%s','now','-7 days')
  `,
  // Per-kind cost breakdown over the last 30 days. Each row =
  // { kind, paid, free, total } so the dashboard can show every AI Details
  // line item (atm, attraction, restaurant, coffee, restroom) and their
  // share of overall Haiku spend. Sort by paid DESC so the most expensive
  // surface is on top.
  ai_details_by_kind_30d: `
    SELECT
      COALESCE(json_extract(payload, '$.kind'), 'unknown') AS kind,
      SUM(CASE WHEN json_extract(payload, '$.cache') != 'hit' THEN 1 ELSE 0 END) AS paid,
      SUM(CASE WHEN json_extract(payload, '$.cache') = 'hit' THEN 1 ELSE 0 END) AS free,
      COUNT(*) AS total
    FROM events
    WHERE event_type = 'ai_details_fetched'
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY kind
    ORDER BY paid DESC
  `,
  // ── PHASE 2 INTENT FALLBACK ANALYTICS ───────────────────────────────────
  // Track adoption + cache rate + cost of the /parse-intent LLM fallback.
  // Each 'intent_llm_fallback' event:
  //   { query, cache: 'hit'|'miss', success, dishLabel?, cuisine?, strict?,
  //     confidence?, latencyMs, error? }
  intent_llm_fallback_by_day_14d: `
    SELECT
      date(ts, 'unixepoch') AS day,
      COUNT(*) AS calls,
      SUM(CASE WHEN json_extract(payload, '$.cache') = 'hit' THEN 1 ELSE 0 END) AS cache_hits,
      SUM(CASE WHEN json_extract(payload, '$.cache') = 'miss' THEN 1 ELSE 0 END) AS cache_misses,
      SUM(CASE WHEN json_extract(payload, '$.success') = 1 THEN 0 ELSE 1 END) AS failures
    FROM events
    WHERE event_type = 'intent_llm_fallback'
      AND ts >= strftime('%s','now','-14 days')
    GROUP BY day
    ORDER BY day ASC
  `,
  // Cache hit rate summary -- single-row metric for the dashboard.
  // Hits = $0 cost. Misses = ~$0.0009 each.
  intent_llm_fallback_cache_rate_7d: `
    SELECT
      SUM(CASE WHEN json_extract(payload, '$.cache') = 'hit' THEN 1 ELSE 0 END) AS hits,
      SUM(CASE WHEN json_extract(payload, '$.cache') = 'miss' THEN 1 ELSE 0 END) AS misses,
      COUNT(*) AS total,
      ROUND(AVG(CAST(json_extract(payload, '$.latencyMs') AS INTEGER))) AS avg_latency_ms
    FROM events
    WHERE event_type = 'intent_llm_fallback'
      AND ts >= strftime('%s','now','-7 days')
  `,
  // Top queries that triggered the LLM fallback -- shows what dishes
  // users are searching that the keyword parser doesn't recognize.
  // Direct input for future DISH_MAP additions.
  intent_llm_fallback_top_queries_30d: `
    SELECT
      json_extract(payload, '$.query') AS query,
      COUNT(*) AS hits,
      json_extract(payload, '$.cuisine') AS llm_cuisine,
      json_extract(payload, '$.dishLabel') AS llm_dish,
      AVG(CAST(json_extract(payload, '$.confidence') AS REAL)) AS avg_confidence
    FROM events
    WHERE event_type = 'intent_llm_fallback'
      AND json_extract(payload, '$.success') = 1
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY query
    ORDER BY hits DESC
    LIMIT 50
  `,
  // Top cuisines the LLM assigned -- shows which cuisines are most often
  // missing dedicated DISH_MAP entries.
  intent_llm_fallback_top_cuisines_30d: `
    SELECT
      json_extract(payload, '$.cuisine') AS cuisine,
      COUNT(*) AS hits,
      AVG(CAST(json_extract(payload, '$.confidence') AS REAL)) AS avg_confidence
    FROM events
    WHERE event_type = 'intent_llm_fallback'
      AND json_extract(payload, '$.success') = 1
      AND json_extract(payload, '$.cuisine') IS NOT NULL
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY cuisine
    ORDER BY hits DESC
    LIMIT 30
  `,
  // Raw feed of last 50 fallback events -- spot-check what Claude returned.
  intent_llm_fallback_recent_50: `
    SELECT
      ts,
      json_extract(payload, '$.query') AS query,
      json_extract(payload, '$.cache') AS cache,
      json_extract(payload, '$.success') AS success,
      json_extract(payload, '$.dishLabel') AS dish_label,
      json_extract(payload, '$.cuisine') AS cuisine,
      json_extract(payload, '$.strict') AS strict,
      json_extract(payload, '$.confidence') AS confidence,
      json_extract(payload, '$.latencyMs') AS latency_ms,
      json_extract(payload, '$.error') AS error
    FROM events
    WHERE event_type = 'intent_llm_fallback'
    ORDER BY ts DESC
    LIMIT 50
  `,
  // ── Travel-demand data product (from engagement-row logging) ──────────────
  // demand_by_city: which cities people are active in / planning, by intent.
  demand_by_city: `
    SELECT
      json_extract(payload, '$.city') AS city,
      json_extract(payload, '$.country') AS country,
      json_extract(payload, '$.intent') AS intent,
      COUNT(*) AS views
    FROM events
    WHERE event_type = 'home_rows_view'
      AND json_extract(payload, '$.city') IS NOT NULL
      AND json_extract(payload, '$.city') != ''
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY city, country, intent
    ORDER BY views DESC
    LIMIT 100
  `,
  // trending_places: most-tapped places (what's converting) by city/category.
  trending_places: `
    SELECT
      json_extract(payload, '$.place_name') AS place,
      json_extract(payload, '$.city') AS city,
      json_extract(payload, '$.category') AS category,
      COUNT(*) AS taps
    FROM events
    WHERE event_type = 'home_row_card_tap'
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY place, city, category
    ORDER BY taps DESC
    LIMIT 100
  `,

  // ── Demand intel v2 (11_demand_intel.sql era) ────────────────────────────
  // These query the RAW events table on purpose: events are kept 180 days (the
  // nightly analyticsRollup trims older rows after compacting them into
  // events_daily), so a 30/90-day window is always fully covered by raw rows.
  // events_daily exists for long-horizon retention, not for these dashboards.
  //
  // Where people are browsing, by destination — card-level taps + views that
  // carry the logDiscover {city,country} context. Deliberately excludes
  // home_rows_view (one per Home render; discover_top_destinations covers it).
  demand_top_browsed_30d: `
    SELECT COALESCE(json_extract(payload,'$.city'),'') AS city,
      COALESCE(json_extract(payload,'$.country'),'') AS country,
      COUNT(*) AS actions,
      COUNT(DISTINCT session_id) AS sessions
    FROM events
    WHERE event_type IN ('home_row_card_tap','discover_select','event_tap','event_view','right_now_tap','escape_card_tap','escape_view','today_card_tap','deal_tap','deal_view','exp_view','where_to_stay_view','where_to_stay_area_tap','dream_gallery_open','dream_tease_view','dream_shelf_tap','home_stamp_tap')
      AND ts >= strftime('%s','now','-30 days')
      AND (IFNULL(json_extract(payload,'$.city'),'') <> '' OR IFNULL(json_extract(payload,'$.country'),'') <> '')
    GROUP BY city, country
    ORDER BY actions DESC
    LIMIT 40
  `,
  // What people type into search (src/lib/logSearch.js: {category, query}).
  // query is null for pure category browses — only real typed queries rank.
  demand_top_searches_30d: `
    SELECT json_extract(payload,'$.query') AS query,
      COALESCE(json_extract(payload,'$.category'),'') AS category,
      COUNT(*) AS searches
    FROM events
    WHERE event_type = 'search'
      AND IFNULL(json_extract(payload,'$.query'),'') <> ''
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY query, category
    ORDER BY searches DESC
    LIMIT 40
  `,
  // Attention time by surface + place. Emitters shipped with this wave:
  // DreamGallery (per-gallery session) and SmartPackages (page dwell) — both
  // send the payload contract {ms, surface, place_name}.
  demand_dwell_30d: `
    SELECT COALESCE(json_extract(payload,'$.surface'),'(unknown)') AS surface,
      COALESCE(json_extract(payload,'$.place_name'),'') AS place,
      COUNT(*) AS dwells,
      SUM(COALESCE(json_extract(payload,'$.ms'),0)) AS total_ms
    FROM events
    WHERE event_type = 'dwell'
      AND ts >= strftime('%s','now','-30 days')
    GROUP BY surface, place
    ORDER BY total_ms DESC
    LIMIT 40
  `,
  // Where the MONEY is going — real conversions only (sandbox test bookings
  // are tagged intent='sandbox' by nuiteeRecordBooking and excluded here).
  demand_bookings_by_country_90d: `
    SELECT COALESCE(dest_country,'(unknown)') AS country, partner,
      COUNT(*) AS bookings,
      ROUND(COALESCE(SUM(commission),0), 2) AS commission
    FROM affiliate_clicks
    WHERE converted = 1
      AND (intent IS NULL OR intent != 'sandbox')
      AND ts >= strftime('%s','now','-90 days')
    GROUP BY country, partner
    ORDER BY bookings DESC
    LIMIT 40
  `,
  // Package tier mix. HONEST PLACEHOLDER until flight tiers exist: today
  // package_orders holds hotel-stay drafts, so "tier" is just the order status
  // lifecycle. paid_test (Stripe TEST-mode) is its own bucket — a test key must
  // never inflate a founder revenue metric (same doctrine as the sandbox filter).
  demand_tier_mix_90d: `
    SELECT CASE WHEN status = 'paid_test' THEN 'test (not revenue)' WHEN status LIKE 'paid%' THEN 'paid' ELSE status END AS tier,
      COUNT(*) AS orders
    FROM package_orders
    WHERE created >= strftime('%s','now','-90 days') * 1000
    GROUP BY tier
    ORDER BY orders DESC
  `,
  // Post-stay feedback (trip_feedback, 11_demand_intel.sql; written by the
  // public POST /trip/feedback). Admin-gated like every /analytics-query type.
  trip_feedback_recent: `
    SELECT created, rating, problems, hotel_name, city, country, checkout
    FROM trip_feedback
    ORDER BY created DESC
    LIMIT 50
  `,
  // booking_ref deliberately NOT selected: the page never renders it, and it
  // joins 1:1 to affiliate_clicks.user_id — omitting it keeps the response
  // as anonymous as the page claims.

  // ── Growth & retention ────────────────────────────────────────────────────
  // Unique active users use COALESCE(user_id, session_id) so anonymous devices
  // count too. DAU/WAU/MAU in one row.
  // People, not sessions (growth plan, 2026-10-19): an account, else the device before sign-in
  // (anon_id), else the session; the worker's own 'server' row never counts as a person.
  active_users: `
    SELECT
      COUNT(DISTINCT CASE WHEN ts >= strftime('%s','now','-1 day')  THEN COALESCE(user_id, anon_id, session_id) END) AS dau,
      COUNT(DISTINCT CASE WHEN ts >= strftime('%s','now','-7 days')  THEN COALESCE(user_id, anon_id, session_id) END) AS wau,
      COUNT(DISTINCT CASE WHEN ts >= strftime('%s','now','-30 days') THEN COALESCE(user_id, anon_id, session_id) END) AS mau,
      COUNT(DISTINCT CASE WHEN ts >= strftime('%s','now','-30 days') AND user_id IS NOT NULL THEN user_id END) AS mau_accounts
    FROM events
    WHERE session_id <> 'server' /*NOT_TEST*/
  `,
  active_users_by_day_30d: `
    SELECT date(ts,'unixepoch') AS day, COUNT(DISTINCT COALESCE(user_id, anon_id, session_id)) AS active
    FROM events
    WHERE ts >= strftime('%s','now','-30 days') AND session_id <> 'server' /*NOT_TEST*/
    GROUP BY day
    ORDER BY day
  `,
  // New vs returning among users active in the last 7d (returning = first seen >7d ago).
  retention_7d: `
    SELECT
      COUNT(DISTINCT id) AS active,
      COUNT(DISTINCT CASE WHEN first_seen < strftime('%s','now','-7 days') THEN id END) AS returning
    FROM (
      SELECT COALESCE(user_id, session_id) AS id, MIN(ts) AS first_seen, MAX(ts) AS last_seen
      FROM events
      WHERE session_id <> 'server' /*NOT_TEST*/
      GROUP BY id
    )
    WHERE last_seen >= strftime('%s','now','-7 days')
  `,
  // Engagement-row taps per session (the spec KPI).
  rows_per_session_7d: `
    SELECT AVG(taps) AS avg_taps, COUNT(*) AS sessions
    FROM (
      SELECT session_id, COUNT(*) AS taps
      FROM events
      WHERE event_type = 'home_row_card_tap' AND ts >= strftime('%s','now','-7 days')
      GROUP BY session_id
    )
  `,
};

// ── WEBSITE CONTACT FORM ──────────────────────────────────────────────────
// POST /contact from globeskimmers.io (travelers, partners, investors, press).
// Stored in the events D1 (table created lazily, so no manual SQL step) and
// read back by the admin page through POST /admin/contact. Rate-limited per
// IP in KV (5 per hour); a filled honeypot field is accepted and dropped.
const CONTACT_WHO = ['traveler', 'partner', 'investor', 'press', 'other'];
const CONTACT_TABLE_SQL = `CREATE TABLE IF NOT EXISTS contact_messages (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  created_at TEXT NOT NULL,
  who TEXT NOT NULL,
  name TEXT NOT NULL,
  email TEXT NOT NULL,
  company TEXT,
  message TEXT NOT NULL,
  page TEXT,
  ip_hash TEXT,
  user_agent TEXT,
  handled INTEGER NOT NULL DEFAULT 0
)`;

// sha256Hex() is the worker's existing helper (defined once, above).

async function handleContactSubmit(request, env) {
  try {
    if (!env.DB) return jsonResponse({ ok: false, reason: 'unavailable' }, 200);
    // A full form is well under 6 KB; refuse oversized bodies before buffering them.
    if (Number(request.headers.get('Content-Length') || 0) > 16384) return jsonResponse({ ok: false, reason: 'bad_request' }, 200);
    let body;
    try { body = await request.json(); } catch { return jsonResponse({ ok: false, reason: 'bad_request' }, 200); }
    const str = (v, max) => String(v == null ? '' : v).replace(/\s+/g, ' ').trim().slice(0, max);
    const name = str(body.name, 120);
    const email = str(body.email, 200).toLowerCase();
    const company = str(body.company, 160);
    const message = String(body.message == null ? '' : body.message).trim().slice(0, 4000);
    const who = CONTACT_WHO.includes(String(body.who || '').toLowerCase()) ? String(body.who).toLowerCase() : 'other';
    const page = str(body.page, 200);
    // Honeypot: real visitors never see the `website` field. Say ok, store nothing.
    if (str(body.website, 50)) return jsonResponse({ ok: true }, 200);
    if (!name || !message) return jsonResponse({ ok: false, reason: 'missing_fields' }, 200);
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email)) return jsonResponse({ ok: false, reason: 'bad_email' }, 200);
    if (message.length < 10) return jsonResponse({ ok: false, reason: 'too_short' }, 200);

    const ip = request.headers.get('CF-Connecting-IP') || request.headers.get('x-forwarded-for') || '';
    const ipHash = ip ? (await sha256Hex(ip)).slice(0, 32) : null;
    if (env.GLOBESKIMMERS_KV && ipHash) {
      const key = `contact:rl:${ipHash}`;
      const n = parseInt((await env.GLOBESKIMMERS_KV.get(key).catch(() => null)) || '0', 10) || 0;
      if (n >= 5) return jsonResponse({ ok: false, reason: 'rate_limited' }, 200);
      await env.GLOBESKIMMERS_KV.put(key, String(n + 1), { expirationTtl: 60 * 60 }).catch(() => {});
    }
    await env.DB.prepare(CONTACT_TABLE_SQL).run();
    await env.DB.prepare(
      'INSERT INTO contact_messages (created_at, who, name, email, company, message, page, ip_hash, user_agent) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)'
    ).bind(new Date().toISOString(), who, name, email, company || null, message, page || null, ipHash, str(request.headers.get('User-Agent'), 300) || null).run();
    return jsonResponse({ ok: true }, 200);
  } catch (e) {
    console.error('contact submit failed', e?.message || e);
    return jsonResponse({ ok: false, reason: 'error' }, 200);
  }
}

// POST /admin/contact {limit?, handledToo?} → the newest messages; {markHandled: id}
// flips one to handled. Admin-only (Supabase session + ADMIN_EMAILS_WORKER).
async function handleAdminContact(request, env) {
  const denied = await requireAdmin(request, env);
  if (denied) return denied;
  try {
    if (!env.DB) return jsonResponse({ error: 'DB not configured', messages: [] }, 500);
    await env.DB.prepare(CONTACT_TABLE_SQL).run();
    const body = await request.json().catch(() => ({}));
    const markId = parseInt(body?.markHandled, 10);
    if (Number.isFinite(markId)) {
      await env.DB.prepare('UPDATE contact_messages SET handled = 1 WHERE id = ?').bind(markId).run();
    }
    const limit = Math.min(200, Math.max(1, parseInt(body?.limit, 10) || 50));
    const where = body?.handledToo ? '' : 'WHERE handled = 0';
    const { results } = await env.DB.prepare(
      `SELECT id, created_at, who, name, email, company, message, page, handled FROM contact_messages ${where} ORDER BY id DESC LIMIT ?`
    ).bind(limit).all();
    const { results: totals } = await env.DB.prepare('SELECT COUNT(*) AS total, SUM(CASE WHEN handled = 0 THEN 1 ELSE 0 END) AS open FROM contact_messages').all();
    return jsonResponse({ messages: results || [], total: totals?.[0]?.total || 0, open: totals?.[0]?.open || 0 });
  } catch (e) {
    return jsonResponse({ error: e?.message || 'Failed', messages: [] }, 500);
  }
}

// One cell of an admin spreadsheet export. Text a user typed must never run as
// a formula when Excel opens the file: a leading = + - @ tab or CR gets an
// apostrophe (numbers and coordinates don't). Shared by every admin CSV.
function csvCell(v) {
  let t = v == null ? '' : String(v);
  if (typeof v === 'string' && /^[=+\-@\t\r]/.test(t) && !/^-?\d+(\.\d+)?(, -?\d+(\.\d+)?)?$/.test(t)) t = `'${t}`;
  return /[",\n\r]/.test(t) ? `"${t.replace(/"/g, '""')}"` : t;
}

// POST /admin/stamp-reports { op?: 'list' | 'status' | 'csv', id?, status?, open? }
// The founder's "I'm here, but the app is saying I'm not" list (2026-10-10):
// every report, newest first; 'status' marks one new / fixed / ignored; 'csv'
// returns the whole list as a spreadsheet Excel opens directly. Also returns
// the quiet refusals per place (last 30 days, no positions) from the events log.
const STAMP_REPORT_STATUSES = ['new', 'fixed', 'ignored'];
async function handleAdminStampReports(request, env) {
  const denied = await requireAdmin(request, env);
  if (denied) return denied;
  try {
    if (!env.DB) return jsonResponse({ error: 'DB not configured', reports: [] }, 500);
    await env.DB.prepare(STAMP_REPORT_SQL).run();
    const body = await request.json().catch(() => ({}));
    const op = ['list', 'status', 'csv'].includes(body?.op) ? body.op : 'list';
    if (op === 'status') {
      const id = parseInt(body?.id, 10);
      const status = STAMP_REPORT_STATUSES.includes(body?.status) ? body.status : null;
      if (!Number.isFinite(id) || !status) return jsonResponse({ error: 'id and status required' }, 400);
      await env.DB.prepare('UPDATE stamp_reports SET status = ? WHERE id = ?').bind(status, id).run();
      return jsonResponse({ ok: true });
    }
    const openOnly = body?.open ? "status = 'new'" : null;
    let reports = [];
    let truncated = false;
    if (op === 'csv') {
      // Every report, paged 5,000 at a time (the list on screen stops at 500).
      // A hard stop at 50,000 rows says so in the file and the response.
      const CSV_MAX = 20000;   // a JSON export holds rows, lines, CSV and JSON at once: ~2.5 KB a row
      let before = null;
      for (;;) {
        const conds = [openOnly, before != null ? 'id < ?' : null].filter(Boolean);
        const stmt = env.DB.prepare(`SELECT * FROM stamp_reports ${conds.length ? `WHERE ${conds.join(' AND ')}` : ''} ORDER BY id DESC LIMIT 5000`);
        const { results: page } = before != null ? await stmt.bind(before).all() : await stmt.all();
        const rows = page || [];
        reports.push(...rows);
        if (rows.length < 5000) break;
        if (reports.length >= CSV_MAX) {
          // Exactly at the cap is complete; only a row beyond it means "more".
          const more = await env.DB.prepare(`SELECT id FROM stamp_reports WHERE ${[openOnly, 'id < ?'].filter(Boolean).join(' AND ')} LIMIT 1`)
            .bind(rows[rows.length - 1].id).first().catch(() => null);
          truncated = !!more;
          break;
        }
        before = rows[rows.length - 1].id;
      }
    } else {
      const limit = Math.min(500, Math.max(1, parseInt(body?.limit, 10) || 200));
      const { results } = await env.DB.prepare(`SELECT * FROM stamp_reports ${openOnly ? `WHERE ${openOnly}` : ''} ORDER BY id DESC LIMIT ?`).bind(limit).all();
      reports = results || [];
    }
    if (op === 'csv') {
      // Formula-safe cells (csvCell): text a user typed never runs in Excel.
      const cell = csvCell;
      const head = ['Report', 'Date (UTC)', 'Place', 'City', 'Country', 'Place ID', 'Spot (about 1 block)', 'Map link', 'Distance from our pin (m)', 'Allowed distance (m)', 'GPS accuracy (m)', 'Why GPS said no', 'Result', 'Phone', 'App version', 'User code', 'Status'];
      const why = { not_here: 'Outside our map for this place', other_variant: 'At another park or rim of this place', proof_needed: 'No GPS reading', unlocatable: 'Place not on our map', unconfirmed: 'GPS not trusted (VPN or travel speed)' };
      const lines = reports.map((r) => {
        const spot = r.spot_lat != null && r.spot_lng != null ? `${r.spot_lat}, ${r.spot_lng}` : '';
        const map = spot ? `https://www.google.com/maps/search/?api=1&query=${r.spot_lat},${r.spot_lng}` : '';
        return [
          'I’m here, but the app is saying I’m not', String(r.created_at || '').replace('T', ' ').slice(0, 16), r.place_name, r.city, r.country, r.entity_id,
          spot, map, r.distance_m, r.radius_m, r.accuracy_m, why[r.refusal] || (r.refusal ? r.refusal : 'GPS passed on retry'), r.outcome, r.platform, r.app_version, r.user_code, r.status,
        ].map(cell).join(',');
      });
      // The byte-order mark makes Excel read accents and curly quotes correctly.
      if (truncated) lines.push(cell(`(Export stopped at the newest ${reports.length} reports — ask for the rest)`));
      const csv = '﻿' + [head.map(cell).join(','), ...lines].join('\r\n');
      const filename = `stamp-reports-${new Date().toISOString().slice(0, 10)}.csv`;
      // The app's admin page asks for it as JSON (its HTTP layer reads JSON, not a
      // raw text/csv body) and hands it to the share sheet; a browser gets the file.
      if (body?.as === 'json') return jsonResponse({ filename, csv, rows: reports.length, truncated });
      return new Response(csv, { status: 200, headers: { 'Content-Type': 'text/csv; charset=utf-8', 'Content-Disposition': `attachment; filename="${filename}"`, ...CORS_HEADERS } });
    }
    const since = Math.floor(Date.now() / 1000) - 30 * 86400;
    // refusals = Stamp taps GPS refused; reported = report taps. A report
    // resends the refused request, so it is counted under reported only —
    // never again as a refusal (that read as a quiet failure that didn't happen).
    const { results: quiet } = await env.DB.prepare(
      `SELECT json_extract(payload, '$.name') AS name, json_extract(payload, '$.entity_id') AS entity_id,
              SUM(CASE WHEN json_extract(payload, '$.reported') THEN 0 ELSE 1 END) AS refusals,
              SUM(CASE WHEN json_extract(payload, '$.reported') THEN 1 ELSE 0 END) AS reported
         FROM events WHERE event_type = 'passport_stamp_refused' AND ts >= ?
        GROUP BY entity_id ORDER BY COUNT(*) DESC LIMIT 50`
    ).bind(since).all().catch(() => ({ results: [] }));
    const { results: totals } = await env.DB.prepare("SELECT COUNT(*) AS total, SUM(CASE WHEN status = 'new' THEN 1 ELSE 0 END) AS open FROM stamp_reports").all();
    return jsonResponse({ reports, total: totals?.[0]?.total || 0, open: totals?.[0]?.open || 0, refusals_30d: quiet || [] });
  } catch (e) {
    return jsonResponse({ error: e?.message || 'Failed', reports: [] }, 500);
  }
}

// Admin gate — verify the caller's Supabase JWT + confirm they're an admin.
// Returns null when authorized, or a Response to return otherwise. Mirrors
// handleAdminUserStats so /analytics-query is no longer world-readable (it exposes
// monetizable aggregate demand intel).
async function requireAdmin(request, env) {
  const authHeader = request.headers.get('Authorization') || '';
  const token = authHeader.startsWith('Bearer ') ? authHeader.slice(7).trim() : '';
  if (!token) return jsonResponse({ error: 'Not signed in' }, 401);
  const SUPABASE_URL = env.SUPABASE_URL || 'https://bkaxadiyehddzkiuheea.supabase.co';
  const SERVICE_KEY = env.SUPABASE_SERVICE_ROLE_KEY;
  if (!SERVICE_KEY) return jsonResponse({ error: 'Server not configured' }, 500);
  const whoRes = await fetch(`${SUPABASE_URL}/auth/v1/user`, {
    headers: { apikey: SERVICE_KEY, Authorization: `Bearer ${token}` },
  }).catch(() => null);
  if (!whoRes || whoRes.status !== 200) return jsonResponse({ error: 'Invalid or expired session' }, 401);
  const who = await whoRes.json().catch(() => ({}));
  const email = String(who?.email || '').trim().toLowerCase();
  if (!ADMIN_EMAILS_WORKER.includes(email)) return jsonResponse({ error: 'Forbidden' }, 403);
  return null; // authorized
}

// POST /admin/passport-monthly — stamps per month for the last 12 months from
// the SOURCE OF TRUTH (Supabase passport_stamps.created_at), by kind. The D1
// 'passport_stamp' events can't be trusted for history: the server logger lost
// every one of them until 2026-09-28 (see gbLogEvent). Paged 1,000 rows at a
// time (PostgREST's row cap), stopping at 50,000 — move to an RPC with GROUP BY
// before stamps outgrow that.
async function handleAdminPassportMonthly(request, env) {
  try {
    const denied = await requireAdmin(request, env);
    if (denied) return denied;
    const since = new Date(Date.UTC(new Date().getUTCFullYear(), new Date().getUTCMonth() - 11, 1)).toISOString();
    const months = new Map();
    let offset = 0, total = 0;
    for (let pageNo = 0; pageNo < 50; pageNo++) {
      const q = await gbRest(env, `passport_stamps?select=created_at,kind&created_at=gte.${encodeURIComponent(since)}&order=created_at.asc&limit=1000&offset=${offset}`, {});
      if (!q.ok) return jsonResponse({ error: `passport_stamps read failed (${q.status})` }, 502);
      const rows = await q.json().catch(() => []);
      for (const r of rows) {
        const m = String(r.created_at || '').slice(0, 7);
        if (!m) continue;
        const x = months.get(m) || { month: m, stamps: 0, by_kind: {} };
        x.stamps += 1; x.by_kind[r.kind || 'other'] = (x.by_kind[r.kind || 'other'] || 0) + 1;
        months.set(m, x);
      }
      total += rows.length;
      if (rows.length < 1000) break;
      offset += 1000;
    }
    return jsonResponse({ since, total, months: Array.from(months.values()).sort((a, b) => (a.month < b.month ? 1 : -1)) });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// The passport counts, with each country and city counted once however it was spelled (founder,
// 2026-10-26: the stats page counted "US" and "United States" as two countries, and two spellings
// of one city as two). Airport stamps log a country code, other stamps its name; a city folds
// accents, case and spacing. Computed in the worker from the raw stamp events, in the same
// shapes the SQL answered. "cities" is now distinct cities; "city_stamps" stays the count of
// city stamps.
const PP_NORM_TYPES = new Set(['passport_totals', 'passport_by_country', 'passport_by_city', 'passport_countries_periods', 'passport_countries_by_month']);
const ppNormCountry = (v) => {
  const n = pcCountryName(String(v || '').trim());
  return pcIsUSName(n) ? 'United States' : /^(uk|great britain|britain)$/i.test(n) ? 'United Kingdom' : n;
};
async function ppNormStats(env, type) {
  const { results } = await env.DB.prepare(`SELECT ts, json_extract(payload,'$.kind') AS kind, json_extract(payload,'$.country') AS country, json_extract(payload,'$.city') AS city, json_extract(payload,'$.name') AS name FROM events WHERE event_type='passport_stamp'`).all();
  const rows = (results || []).map((r) => ({ ts: Number(r.ts) || 0, kind: r.kind || null, country: r.country ? ppNormCountry(r.country) : '', city: String(r.city || '').trim() }));
  const cityKey = (r) => `${pcFold(r.city)}|${pcFold(r.country)}`;
  const withCountry = rows.filter((r) => r.country);
  if (type === 'passport_totals') {
    const n = (k) => rows.filter((r) => r.kind === k).length;
    return [{ total_stamps: rows.length, countries: new Set(withCountry.map((r) => r.country)).size, cities: new Set(rows.filter((r) => r.city).map(cityKey)).size, attraction_stamps: n('attraction'), city_stamps: n('city'), airport_stamps: n('airport'), country_stamps: n('country') }];
  }
  if (type === 'passport_by_country') {
    const by = {};
    for (const r of withCountry) by[r.country] = (by[r.country] || 0) + 1;
    return Object.entries(by).map(([country, stamps]) => ({ country, stamps })).sort((a, b) => b.stamps - a.stamps).slice(0, 100);
  }
  if (type === 'passport_by_city') {
    const by = new Map();
    for (const r of rows.filter((x) => x.city)) {
      const k = cityKey(r);
      const e = by.get(k) || { stamps: 0, names: {}, country: r.country || null };
      e.stamps += 1; e.names[r.city] = (e.names[r.city] || 0) + 1;
      by.set(k, e);
    }
    // Each city under its most used spelling.
    return [...by.values()].map((e) => ({ city: Object.entries(e.names).sort((a, b) => b[1] - a[1])[0][0], country: e.country, stamps: e.stamps })).sort((a, b) => b.stamps - a.stamps).slice(0, 100);
  }
  const now = Date.now() / 1000;
  const todayUtc = new Date().toISOString().slice(0, 10);
  if (type === 'passport_countries_periods') {
    const count = (f) => new Set(withCountry.filter(f).map((r) => r.country)).size;
    return [{ today: count((r) => new Date(r.ts * 1000).toISOString().slice(0, 10) === todayUtc), week: count((r) => r.ts >= now - 7 * 86400), month: count((r) => r.ts >= now - 30 * 86400) }];
  }
  // passport_countries_by_month: the last 12 months.
  const by = new Map();
  for (const r of rows.filter((x) => x.ts >= now - 365 * 86400)) {
    const m = new Date(r.ts * 1000).toISOString().slice(0, 7);
    const e = by.get(m) || { month: m, stamps: 0, set: new Set() };
    e.stamps += 1; if (r.country) e.set.add(r.country);
    by.set(m, e);
  }
  return [...by.values()].map((e) => ({ month: e.month, countries: e.set.size, stamps: e.stamps })).sort((a, b) => a.month.localeCompare(b.month));
}

async function handleAnalyticsQuery(request, env) {
  try {
    // Admin-only: the Admin page already sends the caller's JWT via callWorker.
    const denied = await requireAdmin(request, env);
    if (denied) return denied;
    if (!env.DB) {
      return jsonResponse({ error: 'D1 not bound', results: [] }, 503);
    }
    const url = new URL(request.url);
    const type = url.searchParams.get('type');
    if (!type) {
      return jsonResponse({
        error: 'type param required',
        available: Object.keys(ANALYTICS_QUERIES),
      }, 400);
    }
    if (PP_NORM_TYPES.has(type)) return jsonResponse({ type, results: await ppNormStats(env, type) });
    const sql = ANALYTICS_QUERIES[type];
    if (!sql) {
      return jsonResponse({
        error: `unknown query type: ${type}`,
        available: Object.keys(ANALYTICS_QUERIES),
      }, 400);
    }
    // Optional ?param=... for a query with a LIKE ? filter. Wraps in % for LIKE matching.
    const param = url.searchParams.get('param');
    const stmt = env.DB.prepare(sql.includes('/*NOT_TEST*/') ? sql.split('/*NOT_TEST*/').join(gbNotTestSql(await gbTestAccountIds(env))) : sql);
    const bound = param ? stmt.bind(`%${param}%`) : stmt;
    const { results } = await bound.all();
    return jsonResponse({ type, results: results || [] });
  } catch (e) {
    return jsonResponse({ error: e.message, results: [] }, 500);
  }
}

async function handleCacheStats(request, env) {
  return jsonResponse({
    status: 'ok',
    version: '7.12-optimized',
    kvBound: !!env.GLOBESKIMMERS_KV,
    costOptimization: { search: 'Advanced tier ($5/1K)', details: 'Preferred tier ($20/1K) - cached 90 days' },
    cacheTTLs: {
      textSearch: '12 hours fresh + 12 hours SWR (24 hours total)',
      nearbySearch: '3 days fresh + 4 days SWR (7 days total)',
      dietary: '12 hours',
      details: '90 days',
      photo: '90 days'
    },
    timestamp: new Date().toISOString()
  });
}

// ============================================================================
// PHOTO LABELER + MENU OCR — Haiku 4.5 vision, 180-day KV cache
// Powers dish-first photo ordering on PlacesToEat AND Tier 4 "Serves It"
// detection. One Haiku call per photo: classifies as exterior/interior/menu/
// dish, and for menu photos also extracts the visible dish list.
// ============================================================================

const PHOTO_LABEL_TTL_SECONDS = 180 * 24 * 60 * 60;  // 6 months

const PHOTO_LABEL_PROMPT = `Classify the photo and extract menu items if it is a menu.

Return STRICT JSON, no markdown, no prose:
{
  "label": "exterior" | "interior" | "menu" | "dish:<short name>" | "other",
  "dishes": [ "<dish 1>", "<dish 2>", ... ]
}

Rules:
- "label":
  - "exterior" — building exterior, signage, storefront, parking
  - "interior" — dining room, seating area, counter, bar
  - "menu" — printed menu board, paper menu, sandwich board with dishes
  - "dish:<name>" — close-up of a specific food/drink. Replace <name> with the dish (e.g., "dish:pancakes", "dish:pizza", "dish:ramen", "dish:burger", "dish:salad", "dish:latte"). One short dish name only.
  - "other" — staff, customers, abstract, unclear
- "dishes":
  - Empty array unless "label" is "menu"
  - For menu photos: list each visible dish name (just the name, no price), lowercase, deduped
  - Examples: ["pancakes", "french toast", "bacon and eggs", "avocado toast"]
  - If unreadable, return []

Output JSON only.`;

async function handleLabelPhotos(request, env) {
  if (!env.ANTHROPIC_API_KEY) {
    return jsonResponse({ error: 'ANTHROPIC_API_KEY not configured', labels: {}, dishes: [] }, 500);
  }
  let body;
  try { body = await request.json(); } catch (_e) {
    return jsonResponse({ error: 'Invalid JSON body', labels: {}, dishes: [] }, 400);
  }
  if (!body?.placeId || !Array.isArray(body.photos)) {
    return jsonResponse({ error: 'placeId + photos[] required', labels: {}, dishes: [] }, 400);
  }

  // Cache key includes version so format changes invalidate cleanly.
  const cacheKey = `place:${body.placeId}:photo_labels_v2`;
  if (env.GLOBESKIMMERS_KV) {
    const cached = await env.GLOBESKIMMERS_KV.get(cacheKey, { type: 'json' }).catch(() => null);
    if (cached) {
      return jsonResponse({ labels: cached.labels || {}, dishes: cached.dishes || [], _cache: 'hit' });
    }
  }

  // Fetch image → base64 → Haiku 4.5 vision per photo, in parallel.
  const labelOne = async (photo) => {
    const photoName = photo?.name || photo;
    if (!photoName || typeof photoName !== 'string') return [photoName, null];
    try {
      const photoUrl = `https://places.googleapis.com/v1/${photoName}/media?key=${env.GOOGLE_API_KEY}&maxWidthPx=400`;
      const imgRes = await fetch(photoUrl);
      if (!imgRes.ok) return [photoName, null];
      const buf = await imgRes.arrayBuffer();
      // Convert to base64 in chunks to avoid call-stack overflow on large images.
      const bytes = new Uint8Array(buf);
      let binary = '';
      const CHUNK = 0x8000;
      for (let i = 0; i < bytes.length; i += CHUNK) {
        binary += String.fromCharCode.apply(null, bytes.subarray(i, i + CHUNK));
      }
      const base64 = btoa(binary);

      const apiRes = await fetch('https://api.anthropic.com/v1/messages', {
        method: 'POST',
        headers: {
          'x-api-key': env.ANTHROPIC_API_KEY,
          'anthropic-version': '2023-06-01',
          'content-type': 'application/json'
        },
        body: JSON.stringify({
          model: 'claude-haiku-4-5-20251001',
          max_tokens: 300,
          system: PHOTO_LABEL_PROMPT,
          messages: [{
            role: 'user',
            content: [
              { type: 'image', source: { type: 'base64', media_type: 'image/jpeg', data: base64 } },
              { type: 'text', text: 'Classify this photo.' }
            ]
          }]
        })
      });
      if (!apiRes.ok) return [photoName, null];
      const data = await apiRes.json();
      const raw = data?.content?.[0]?.text?.trim() || '';
      // Strip any accidental markdown fences before parsing.
      const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
      try {
        const parsed = JSON.parse(cleaned);
        return [photoName, parsed];
      } catch (_e) {
        return [photoName, null];
      }
    } catch (_e) {
      return [photoName, null];
    }
  };

  const results = await Promise.all((body.photos || []).slice(0, 10).map(labelOne));

  // Roll up: labels map (per-photo) + global dishes list (deduped across all menu photos).
  const labels = {};
  const dishSet = new Set();
  for (const [photoName, parsed] of results) {
    if (!photoName) continue;
    const label = (parsed?.label || 'unknown').toString().toLowerCase();
    labels[photoName] = label;
    if (Array.isArray(parsed?.dishes)) {
      for (const d of parsed.dishes) {
        if (typeof d === 'string' && d.trim()) dishSet.add(d.trim().toLowerCase());
      }
    }
  }
  const dishes = Array.from(dishSet);

  // Cache 180 days.
  if (env.GLOBESKIMMERS_KV) {
    await env.GLOBESKIMMERS_KV.put(
      cacheKey,
      JSON.stringify({ labels, dishes }),
      { expirationTtl: PHOTO_LABEL_TTL_SECONDS }
    ).catch(() => {});
  }
  return jsonResponse({ labels, dishes, _cache: 'miss' });
}

// ============================================================================
// AI DETAILS — Haiku 4.5 synthesizes a structured "AI Details" panel from
// the place's reviews + metadata. Used across PlacesToEat, CoffeeFinder,
// (future) ThingsToDo, (future) RestroomFinder.
//
// Voice rules (POSITIVE-ONLY policy, enforced in prompt):
// - Do NOT write anything that would deter a customer from trying the place.
// - Do NOT cite specific complaints from reviewers. Omit negatives entirely.
// - DO mention factual planning info (busy hours, customer favorites,
//   best time, what to order, language tips, payment notes).
// - Always lead with what people love.
//
// GS Verdict scoring (stars, replaces old 1-10 number):
// - restaurant/coffee: gsStars 1-5 (minimum 1, even for mixed reviews).
//   gsRedFlag always false.
// - attraction: gsStars 1-5. gsRedFlag=true ONLY if reviews flag genuine
//   safety concerns (renders as red flag instead of stars).
// - restroom: gsStars 0-5 (0 if consistently dirty/smelly). gsRedFlag=true
//   if safety concerns. Restroom-specific fields favor toilet paper,
//   soap, paid/free, squat/sit, etc.
//
// Cache key includes prompt version (v2) + kind so a prompt or schema
// change invalidates cleanly and different kinds get separate cache lines.
// ============================================================================

const AI_DETAILS_TTL_SECONDS = 30 * 24 * 60 * 60;  // 30 days

const AI_DETAILS_PROMPT_VERSION = 'v13';  // v12 -> v13: a review counts only if the AI says it is about the dish AND it literally names it (true lower bound); terms also come from the dish name minus generic words. Literal-only v12 shifted with the AI's word lists. v9 -> v10: food/coffee name up to 5 candidate dishes with literal match words; CODE counts review mentions and keeps the top 3 (topDishes). v8 -> v9: accessibility claims are never asserted by AI copy ("ADA compliant", "accessible room guaranteed", "wheelchair-friendly"…) — only what the place lists or Google reports. v7 -> v8: added practical.tipping (service charge / cover charge / tip norms). Surfaces the #1 traveler-anxiety cluster ("money surprises") directly in the Practical row instead of relying on it accidentally landing in goodToKnow.

function buildAIDetailsSystemPrompt(kind) {
  const safeKind = ['restaurant', 'coffee', 'attraction', 'restroom', 'atm'].includes(kind) ? kind : 'restaurant';

  const isFood = safeKind === 'restaurant' || safeKind === 'coffee';
  const isAttraction = safeKind === 'attraction';
  const isRestroom = safeKind === 'restroom';
  const isATM = safeKind === 'atm';
  // Family / age-fit signals apply to restaurants, coffee shops, attractions.
  // Not relevant for restrooms or ATMs.
  const supportsAgeFit = isFood || isAttraction;

  const starRules = isFood
    ? `- gsStars MUST be an integer 1-5. NEVER 0. Even places with mixed reviews get at least 1 star — every business gets the benefit of the doubt.
- gsRedFlag MUST be false.`
    : isAttraction
      ? `- gsStars MUST be an integer 1-5 (minimum 1).
- gsRedFlag = true ONLY if multiple reviews flag a GENUINE worldwide safety concern (e.g. crime in area, unsafe structures, recent incidents). Otherwise false.`
      : isRestroom
        ? `- gsStars MUST be an integer 0-5. Set gsStars = 0 ONLY if multiple recent reviews say the restroom is consistently dirty or smelly. Otherwise 1-5.
- gsRedFlag = true if reviews flag safety concerns (unsafe area, unsanitary risk, etc.). Otherwise false.`
        : isATM
          ? `- gsStars MUST be an integer 1-5 (minimum 1, even for ATMs with mixed reviews).
- gsRedFlag = true ONLY if reviews show genuine safety concerns at this specific ATM location (e.g., past skimmer reports, multiple recent reviews mentioning unsafe area at night, robbery incidents). Otherwise false.`
          : '- gsStars 1-5, gsRedFlag false.';

  const kindFieldGuidance = isFood
    ? `- topDishes: up to 5 candidate dishes/drinks that the REVIEWS or editorialSummary actually name, most-mentioned first, as an array of { name, context, match, reviews } objects. name = the dish as reviewers/menu call it (include native script in parens if relevant). context = one short positive line (≤90 chars) — why people love it. match = 1-3 short lowercase words or phrases a review would LITERALLY contain when it talks about this dish (e.g. "Chicken Xiao Long Bao" → ["xiao long bao", "soup dumpling"]; "Tonkotsu Ramen" → ["tonkotsu"]; "Pastrami on Rye (#19)" → ["pastrami", "#19"]). Never a bare category word like "ramen", "pizza" or "coffee". reviews = the "n" of every review snippet that talks about THIS specific dish (a mole-sampler review is not a Mole Negro review; "their pastrami" at a pastrami-sandwich deli is); [] if only the editorialSummary names it. Never invent a dish the data doesn't name; fewer than 5 is fine. Our code counts the mentions — do NOT write counts or numbers of reviews anywhere.
- bestDish = null and alsoRecommended = [] (built from topDishes by code).
- photoWorthy: 1 short line naming any standout photo-worthy dish or drink (visually striking presentation, vibrant colors, unique vessel, frequently photographed). Include the dish name + WHY it's photo-worthy. Examples: "The rainbow milk tea — served in a clear hourglass jar with layered colors, frequently photographed", "Charcoal-black sushi roll plated on a bed of dry ice — a popular shot among visitors". NULL if no reviewer mentions visual / photo / shareable appeal.
- awards: 1 short line listing notable awards, recognitions, or critical mentions. Examples: "★ 1 Michelin star (2024)", "Bib Gourmand listed (2023)", "James Beard Foundation Award winner — Best Chef Mid-Atlantic", "Top 50 Asia Restaurants 2024 #12", "Featured in Netflix's Chef's Table". NULL if no awards/recognitions are mentioned in reviews/editorialSummary/data.
- worthIt: ONE of "worth_the_stop" | "strong_nearby_pick" | "craving_match" | "know_before_you_go" | "better_if_convenient". Pick the most accurate tier:
  - "worth_the_stop" = standout reviewers say is worth a detour (high enthusiasm, unique, destination-worthy).
  - "strong_nearby_pick" = solid, reliable choice if you're already in the area.
  - "craving_match" = good ONLY if you specifically want this cuisine / vibe / experience (niche but excellent at its thing).
  - "know_before_you_go" = decent food / experience BUT meaningful planning friction (cash-only, long waits, hard-to-find, limited hours, language barrier, etc.) that travelers should know up front.
  - "better_if_convenient" = fine everyday option, not a destination — only stop if it's already on your route.
  Default to "strong_nearby_pick" when truly unsure. NEVER "skip" or negative framing.
- practical: { payment, englishMenu, reservation, dietary, tipping } object with these factual fields (any can be null):
  - payment: short factual line about payment methods (e.g. "Cards + tap accepted; cash also OK", "Cash only — bring local currency", "Card-only, no cash"). NULL if reviews don't say.
  - englishMenu: short factual line about menu language + staff English (e.g. "Menu in English; staff speaks English", "English menu available; limited staff English", "Menu in local language only; photos help"). NULL if unclear.
  - reservation: short factual line (e.g. "Walk-in fine; weekend dinner gets busy", "Reservation recommended for dinner", "Reservations required — book ahead"). NULL if unclear.
  - dietary: short factual line covering vegetarian/vegan/gluten-free/halal/allergens IF mentioned (e.g. "Vegetarian options available; ask staff about gluten-free", "Limited vegetarian options", "Halal-certified"). NULL if no dietary info in reviews.
  - tipping: ONE short factual line about tipping norms / service charges / cover charges / hidden fees AT THIS SPECIFIC PLACE if reviews mention them, OR the COUNTRY-LEVEL tipping norm if the venue itself is silent. Examples: "10% service charge auto-added — no extra tip expected", "15–20% tip standard in the US; servers prefer cash", "No tipping culture — rounding up is appreciated but not required", "Cover charge ~€2 per person", "Service NOT included — leave 5–10% in cash". NEVER editorialize ("overpriced", "rip-off"). NULL only when both review evidence AND country norms are unknown.
- crowd: who eats here — short concrete labels (e.g. "Mostly local diners; family crowd", "Food-focused regulars more than ambiance seekers"). Avoid vague phrasing.
- bestTime: CONCRETE recommendation a traveler can act on. Don't say "weekday lunch is calmer" — say "Aim for weekday lunch around 12:30, or weekend brunch before 11 to avoid the rush". Always pair a SPECIFIC suggested window with a brief reason. Avoid vague "anytime is good" answers.
- vibe: 1 direct sentence describing atmosphere (casual, group-friendly, romantic, energetic, quiet, etc.). Avoid decorative language ("charming", "delightful"). Be concrete.
- value: traveler-friendly value language. Use words travelers actually say: "cheap", "fair for the cuisine", "expensive for what it is", "good for sharing", "small portions, order 2-3", "splurge-worthy". Always include the price tier ($/$$/$$$) AND a 1-line judgment. Examples: "Cheap ($) — generous portions, great for groups", "Fair for the cuisine ($$); order 2-3 small plates to share", "Splurge-worthy ($$$$); tasting menu runs about 2 hours".
- goodToKnow: 2-4 SHORT verified facts that change how a traveler plans the visit. ONLY include items DIRECTLY supported by the reviews or place metadata — do NOT invent or assume. Prioritize: ordering quirks (QR code, table service), kitchen-pace ("Noodles made fresh daily"), parking realities, hours quirks ("Closed Mondays", "Lunch break 3-5pm"), BYOB / corkage, dress code, payment surcharges, busy windows specific enough to act on. AVOID generic platitudes ("good food", "nice place"). If reviews don't support a fact, omit it.
- travelerNotes: practical tips for travelers (best dish to try first, ordering, language).
- whatYouSee: null (restaurant doesn't use this).
- aboutAndHistory: null (restaurant doesn't use this).`
    : isAttraction
      ? `- bestDish = null.
- alsoRecommended: TOP 3 must-see/must-do items at this attraction, as an array of { name, context } objects. name = the item (exhibit, view, ride, etc.), context = short reason (≤90 chars). Aim for 3 — fewer only if data is thin.
- photoWorthy: 1 short line naming a standout photo-worthy spot/exhibit/view at this attraction. Examples: "The cherry blossom canopy walkway at sunset — peak photo season early April", "The infinity-mirror room — most-photographed spot in the museum". NULL if no obvious photo-worthy feature is mentioned.
- awards: 1 short line listing UNESCO status, top-tourist-attraction rankings, Michelin Green Guide stars, or notable recognitions. Examples: "UNESCO World Heritage Site (1996)", "Michelin Green Guide 3-star", "TripAdvisor Travelers' Choice 2024". NULL if no recognitions are mentioned.
- worthIt: ONE of "worth_the_stop" | "strong_nearby_pick" | "craving_match" | "know_before_you_go" | "better_if_convenient". For famous landmarks / UNESCO sites default to "worth_the_stop"; for local parks default to "strong_nearby_pick". Use "know_before_you_go" if there's meaningful planning friction (timed entry, bag check restrictions, limited access). Use "craving_match" if niche-interest only (specific museum types, themed exhibits).
- practical: { payment, englishMenu, reservation, dietary } — for attractions, "payment" = ticket purchase methods, "englishMenu" = signage/audio guide language + staff English, "reservation" = timed entry / advance booking, "dietary" = null (not relevant for attractions).
- whatYouSee: 1-2 short sentences describing what is physically present at the attraction (the buildings, exhibits, sculptures, rides, displays, scenery). Be concrete: "Three immersive haunted houses, a sculpture garden, an IMAX dome, a rooftop observation deck with city views." NULL if reviews/data don't describe what's there.
- aboutAndHistory: 1-2 short sentences on the attraction's purpose / origin / brief history. Be factual and concise: "Built in 1872 as a Meiji-era symbol of modernization. Original wooden structure burned in the 1923 earthquake; current reconstruction completed 1957." NULL if data is silent.
- crowd: who visits — short concrete labels (e.g. "Families with kids; school groups on weekdays", "Photographers and history fans"). Avoid vague phrasing.
- bestTime: CONCRETE actionable recommendation. Don't say "mornings are calmer" — say "Arrive at opening (9 AM) on a weekday to avoid the crowds, or after 3 PM when tour buses leave". Pair a SPECIFIC suggested window with a brief reason.
- vibe: 1 direct sentence describing atmosphere (busy/quiet, contemplative/energetic, kid-friendly/adult-focused). Avoid decorative language.
- value: traveler-friendly admission framing. Use direct words: "free", "cheap", "fair", "pricey but worth it", "splurge-only". Include the actual admission tier and a 1-line judgment. Examples: "Free entry — fully worth a 2-hour visit", "Cheap (~$10); fair for what you see", "Pricey ($25-30); worth it if you have 3+ hours".
- goodToKnow: 2-4 SHORT verified facts that change how a traveler plans the visit. ONLY include items DIRECTLY supported by reviews/metadata. Prioritize: bag-check rules, photography restrictions, accessibility realities, kid-friendliness specifics, audio-guide availability, dress code (temples/religious sites), what to bring, hours quirks, day-of-the-week closures. AVOID generic platitudes.
- travelerNotes: practical traveler tips to make the visit better.`
      : isRestroom
        ? `- bestDish = null. alsoRecommended = [].
- worthIt = null. practical = null.
- crowd = null (typically not relevant).
- bestTime: best time to use it (less busy windows).
- vibe: cleanliness, comfort level (only describe positively or neutrally; if dirty, use gsStars=0 instead of writing it negatively).
- value: paid vs free (e.g. "Free to use" or "Small fee, around X").
- goodToKnow: presence of toilet paper, soap, hand dryer, squat vs sit toilet, accessibility, anything cool/unique.
- travelerNotes: practical tips (carry tissue, bring small change, etc.).`
        : isATM
          ? `- bestDish = null. alsoRecommended = [].
- worthIt = null. practical = null.
- crowd = null (usually not relevant for ATMs).
- bestTime: when access is best — lobby hours, drive-thru hours, when it's less busy or safer (e.g. "Lobby vestibule accessible 6 AM-11 PM. Drive-thru 24/7. Quietest before 8 AM"). Travelers care a lot about this.
- vibe: where the ATM is PHYSICALLY located — this is the most important field. Be specific: inside lobby vestibule, outside on building wall, drive-thru, behind store counter, inside 7-Eleven by the entrance, etc. Reviewers consistently mention location specifics; extract them.
- value: surcharge / fees (e.g. "Free for Chase customers. $3.50 surcharge for non-Chase cards") or "No surcharge".
- goodToKnow: practical facts — foreign card acceptance (Visa/Mastercard/Maestro/Amex), max withdrawal per transaction, currency dispensed (large bills only?), lit at night, surveillance cameras, PIN length supported, languages on screen.
- travelerNotes: practical tips for travelers — e.g. "Press 'English' before inserting card", "Accepts foreign chip cards; magstripe-only may be rejected", "Dispenses ¥10,000 notes only — bring smaller bills elsewhere".`
          : '';

  return `You are GlobeSkimmers' AI Details engine. Generate practical, helpful insights for a traveler about to visit a place.

KIND: ${safeKind}

VOICE RULES (ABSOLUTE — these are inviolable):
- DO NOT write ANYTHING that would deter a customer from trying the business. The app shows these notes publicly; negative content creates legal/reputational risk.
- FORBIDDEN words/phrases: "inconsistent", "complaints", "issues", "concerns", "problems", "poor", "rude", "disappointed", "frustrating", "unreliable", "complained", "service issues", "quality concerns", "questionable", "lacking", "subpar", "stay away", "avoid", "skip", "don't go".
- ACCESSIBILITY CLAIMS: never write "ADA compliant", "accessible room(s) guaranteed", "wheelchair-friendly", "fully accessible", "assistance booked" or "your ticket reflects your disability". State accessibility ONLY as something the place itself lists or Google reports (e.g. "wheelchair-accessible entrance reported"); otherwise write "accessibility not confirmed".
- DO NOT cite specific reviewer complaints. If reviewers said something negative, OMIT it entirely. Do not paraphrase a complaint as a "factual note".
- DO mention factual planning info that helps the visit go better: busy hours (framed neutrally as "weekend dinner is the busiest window" not "long waits"), customer favorites, best time to visit, what to order, language tips, payment methods, parking notes (positive framing only).
- ALWAYS lead with what people love.
- If there is genuinely nothing positive to say about a field, set that field to null. Do NOT invent positives. Do NOT fall back to a complaint.
- The goal: help travelers have a great visit AND protect the business from lost customers due to public negative content.

PER-KIND FIELDS:
${kindFieldGuidance}

GS VERDICT SCORING:
${starRules}
- gsVerdict: 1-2 short sentences matching the chosen worthIt tier. CAN fold in atmosphere-fit caveats using the EXACT pattern "Best if you ... Not ideal for [atmosphere/occasion mismatch]." Atmosphere caveats are allowed; quality complaints are NOT (same FORBIDDEN word list applies). Examples:
  - worth_the_stop: "Locals' choice for authentic sisig — destination-worthy for Filipino BBQ fans."
  - strong_nearby_pick: "Reliable Shanghainese spot for a casual lunch or dinner."
  - craving_match: "Best if you are specifically craving soup dumplings or casual Shanghainese comfort food. Not ideal for late-night dining, fancy ambiance, or a rushed meal."
  - know_before_you_go: "Excellent ramen worth the trip — bring cash and expect a 30-minute weekend wait."
  - better_if_convenient: "Decent coffee stop if you are already in the neighborhood."
  The "Not ideal for ..." clause MUST describe atmosphere/occasion mismatch only (never quality). Keep the whole verdict under 200 chars.

OUTPUT JSON ONLY (no markdown fences, no prose outside the JSON):
{
  "topDishes": [ { "name": "<dish>", "context": "<short reason, ≤90 chars>", "match": ["<literal review word>", ...], "reviews": [<n>, ...] }, ... ] (restaurant/coffee only; [] otherwise),
  "bestDish": { "name": "<name>", "context": "<one short positive line, ≤120 chars>" } | null,
  "alsoRecommended": [
    { "name": "<dish/item name>", "context": "<short reason, ≤90 chars>" },
    ...
  ] (aim for 4 for restaurants/coffee, 3 for attractions, fewer only if data truly doesn't support more),
  "photoWorthy": "<one line: standout photo-worthy dish/spot + why>" | null,
  "awards": "<one line: Michelin, James Beard, UNESCO, top-50 lists, etc.>" | null,
  "worthIt": "worth_the_stop" | "strong_nearby_pick" | "craving_match" | "know_before_you_go" | "better_if_convenient" (food/coffee/attraction only; null otherwise),
  "practical": {
    "payment": "<short factual line about payment methods>" | null,
    "englishMenu": "<short factual line about menu language + staff English>" | null,
    "reservation": "<short factual line>" | null,
    "dietary": "<short factual line about veg/vegan/GF/halal options>" | null,
    "tipping": "<short factual line about tipping norms / service charges / cover charges>" | null
  } | null (food/coffee/attraction only; null otherwise),
  "whatYouSee": "<short concrete description of physical features (attraction only)>" | null,
  "aboutAndHistory": "<short factual purpose / history (attraction only)>" | null,
  "crowd": "<one short sentence>" | null,
  "bestTime": "<concrete actionable recommendation with specific window + reason>" | null,
  "vibe": "<one short concrete sentence>" | null,
  "value": "<price tier + traveler-language judgment>" | null,
  "goodToKnow": ["<short verified fact that changes planning>", ...] (2-4 strings when reviews support; [] otherwise),
  "travelerNotes": "<practical tip>" | null,
  "gsStars": <integer per per-kind rules above>,
  "gsRedFlag": <boolean per per-kind rules above>,
  "gsVerdict": "<one short positive/neutral summary, NO negative wording>"
}

If any field has no positive content to draw from, set it to null/empty. Do NOT fabricate.

Return JSON only.`;
}

// Top dishes, counted honestly: the AI names candidates, this code counts how many
// of the reviews we actually read mention each one. No number comes from the AI.
const DISH_GENERIC = new Set(['food', 'dish', 'dishes', 'meal', 'menu', 'ramen', 'pizza', 'sushi', 'burger', 'taco', 'coffee', 'latte', 'tea', 'drink', 'noodle', 'rice', 'chicken', 'beef', 'pork', 'soup', 'salad', 'bread', 'cake', 'pasta', 'curry', 'bbq', 'steak', 'fish', 'sandwich', 'dessert', 'breakfast', 'brunch', 'lunch', 'dinner', 'special', 'combo', 'plate', 'bowl']);
const dishNorm = (v) => String(v || '').normalize('NFKD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
function dishTerms(d) {
  const out = new Set();
  const core = dishNorm(d.name).replace(/\([^)]*\)/g, ' ').replace(/[#*"\u201c\u201d]/g, ' ').split(/\s+/)
    .filter((w) => w && !/^\d+$/.test(w) && !DISH_GENERIC.has(w) && !DISH_GENERIC.has(w.replace(/e?s$/, ''))).join(' ');
  // The name's core ("fried" from "Fried Rice") is only safe behind the AI's review list.
  const useCore = Array.isArray(d.reviews) && core.length >= 4;
  for (const raw of [d.name, useCore ? core : '', ...(Array.isArray(d.match) ? d.match.slice(0, 3) : [])]) {
    const v = dishNorm(raw);
    const parts = [v.replace(/\([^)]*\)/g, ' '), ...[...v.matchAll(/\(([^)]*)\)/g)].map((m) => m[1])];
    for (const part of parts) {
      const t = part.replace(/[#*"\u201c\u201d]/g, ' ').replace(/\s+/g, ' ').trim();
      const generic = DISH_GENERIC.has(t) || DISH_GENERIC.has(t.replace(/s$/, '')) || DISH_GENERIC.has(t.replace(/es$/, ''));
      if (t.length >= 3 && !/^\d+$/.test(t) && !generic) out.add(t);
    }
  }
  return [...out];
}
function dishMentioned(text, term) {
  if (/^[a-z0-9 '&.-]+$/.test(term)) {
    const esc = term.replace(/[.*+?^${}()|[\]\\]/g, '\\$&').replace(/ /g, '[\\s-]+');
    return new RegExp(`(^|[^a-z0-9])${esc}(e?s)?($|[^a-z0-9])`).test(text);
  }
  return text.includes(term); // CJK and other unspaced scripts
}
// A review counts for a dish only when the AI says that review is about the dish
// AND its text literally contains one of the dish's words, so every number shown
// is a true lower bound and the AI never supplies a count. When the AI gives no
// review list, words shared with another candidate ("mole" in "Mole Negro" and
// "Sweet Mole") or with the place's own name/type ("pho" at Pho 79) don't count.
function rankTopDishes(candidates, reviewTexts, placeWords = '') {
  const texts = reviewTexts.map(dishNorm);
  const where = dishNorm(placeWords).replace(/_/g, ' ');
  const seen = new Set();
  const list = (Array.isArray(candidates) ? candidates : []).slice(0, 6)
    .map((d, i) => {
      const name = typeof d?.name === 'string' ? d.name.trim().slice(0, 80) : '';
      const key = dishNorm(name);
      if (!name || seen.has(key)) return null;
      seen.add(key);
      const claimed = Array.isArray(d.reviews) ? new Set(d.reviews.map(Number).filter((n) => Number.isInteger(n) && n >= 0 && n < texts.length)) : null;
      const context = typeof d.context === 'string' && d.context.trim() ? d.context.trim().slice(0, 120) : null;
      return { name, context, terms: dishTerms(d), claimed, i, bare: key.replace(/\([^)]*\)/g, ' ').replace(/\s+/g, ' ').trim() };
    })
    .filter(Boolean);
  return list
    .map((d) => {
      const terms = d.claimed ? d.terms : d.terms.filter((t) => !list.some((o) => o !== d && dishMentioned(o.bare, t)) && !(where && !t.includes(' ') && dishMentioned(where, t)));
      const mentions = terms.length
        ? texts.filter((t, n) => (!d.claimed || d.claimed.has(n)) && terms.some((term) => dishMentioned(t, term))).length
        : 0;
      return { name: d.name, context: d.context, mentions, i: d.i };
    })
    .sort((a, b) => b.mentions - a.mentions || a.i - b.i)
    .slice(0, 3)
    .map(({ i, ...d }) => d);
}

async function handleAIDetails(request, env) {
  if (!env.ANTHROPIC_API_KEY) {
    return jsonResponse({ error: 'ANTHROPIC_API_KEY not configured' }, 500);
  }
  let body;
  try { body = await request.json(); } catch (_e) {
    return jsonResponse({ error: 'Invalid JSON body' }, 400);
  }
  const placeId = body?.placeId;
  if (!placeId) {
    return jsonResponse({ error: 'placeId required' }, 400);
  }
  // Kind drives the voice rules and star-scoring scheme. Allowlist + default
  // to 'restaurant' so old callers (no kind param) still work.
  const allowedKinds = ['restaurant', 'coffee', 'attraction', 'restroom', 'atm'];
  const kind = allowedKinds.includes(body?.kind) ? body.kind : 'restaurant';

  // Owned (planet-DB) ids are UUIDs, not Google place ids. Resolve to a Google id
  // via a cached text search so the rich review-based AI details still work on-tap.
  // Falls back to name-only synthesis below if there's no Google match.
  let resolvedId = placeId;
  if (/^[0-9a-f]{8}-[0-9a-f]{4}-/i.test(placeId) && body?.name) {
    const mapKey = `owned2gid:${placeId}`;
    const mapped = env.GLOBESKIMMERS_KV ? await env.GLOBESKIMMERS_KV.get(mapKey).catch(() => null) : null;
    if (mapped) {
      resolvedId = mapped;
    } else if (env.GOOGLE_API_KEY) {
      try {
        const payload = { textQuery: body.name };
        if (Number.isFinite(body.lat) && Number.isFinite(body.lng)) {
          payload.locationBias = { circle: { center: { latitude: body.lat, longitude: body.lng }, radius: 800 } };
        }
        const sr = await fetch('https://places.googleapis.com/v1/places:searchText', {
          method: 'POST',
          headers: { 'X-Goog-Api-Key': env.GOOGLE_API_KEY, 'X-Goog-FieldMask': 'places.id', 'Content-Type': 'application/json' },
          body: JSON.stringify(payload),
        });
        if (sr.ok) {
          const gid = (await sr.json())?.places?.[0]?.id;
          if (gid) { resolvedId = gid; if (env.GLOBESKIMMERS_KV) await env.GLOBESKIMMERS_KV.put(mapKey, gid, { expirationTtl: 180 * 24 * 60 * 60 }).catch(() => {}); }
        }
      } catch { /* fall through to name-only synthesis */ }
    }
  }

  // 1) Check AI Details cache (30-day TTL). Key includes prompt version
  //    (so prompt changes invalidate cleanly) and kind (so a place opened
  //    from PlacesToEat vs RestroomFinder gets separate cached outputs
  //    with kind-appropriate voice and star scheme).
  const aiCacheKey = `place:${placeId}:ai_details_${AI_DETAILS_PROMPT_VERSION}:${kind}`;
  if (env.GLOBESKIMMERS_KV) {
    const cached = await env.GLOBESKIMMERS_KV.get(aiCacheKey, { type: 'json' }).catch(() => null);
    if (cached) {
      return jsonResponse({ aiDetails: cached, _cache: 'hit' });
    }
  }

  // 2) Load Place Details — prefer the existing details_{placeId} cache (90d)
  //    so a popular place doesn't pay the $0.02 Google call here again.
  const detailsCacheKey = `details_${resolvedId}`;
  // Name-only fallback place (owned rows with no Google match still get a panel).
  const ownedStub = () => ({ name: body?.name || '', formattedAddress: body?.address || '', primaryType: body?.category || '', reviews: [] });
  let place;
  const cachedDetails = await getFromCache(env, detailsCacheKey);
  if (cachedDetails && cachedDetails.data) {
    place = cachedDetails.data;
  } else {
    // Fresh fetch from Google. Cache the normalized result for 90 days
    // so any later handlePlaceDetails call benefits too.
    try {
      const apiKey = env.GOOGLE_API_KEY;
      const detailsRes = await fetch(`https://places.googleapis.com/v1/places/${resolvedId}?languageCode=en`, {
        method: 'GET',
        headers: {
          'X-Goog-Api-Key': apiKey,
          'X-Goog-FieldMask': CONFIG.DETAILS_FIELD_MASK
        }
      });
      if (!detailsRes.ok) {
        if (body?.name) { place = ownedStub(); }
        else return jsonResponse({ error: 'Place details fetch failed', status: detailsRes.status }, 502);
      } else {
        const raw = await detailsRes.json();
        place = normalizePlace(raw, new URL(request.url).origin, true);
        await setInCache(env, detailsCacheKey, place, CONFIG.CACHE_TTL.DETAILS);
      }
    } catch (e) {
      if (body?.name) { place = ownedStub(); }
      else return jsonResponse({ error: 'Place details error: ' + e.message }, 502);
    }
  }

  // 3) Build Claude input — reviews + key metadata only
  const reviewSnippets = (place.reviews || []).slice(0, 5).map(r => ({
    text: r.text || '',
    rating: r.rating,
    when: r.time || '',
  })).filter(r => r.text).map((r, n) => ({ n, ...r }));

  const placeMeta = {
    name: place.name || place.displayName?.text,
    address: place.address || place.formattedAddress,
    rating: place.rating,
    reviewCount: place.userRatingCount,
    priceLevel: place.priceLevel,
    primaryType: place.primaryTypeDisplay || place.primaryType,
    editorialSummary: place.editorialSummary,
    websiteUri: place.websiteUri,
  };

  if (reviewSnippets.length === 0 && !placeMeta.editorialSummary) {
    // Nothing to synthesize from. Return a minimal stub. Stars default to
    // 1 for restaurant/coffee/attraction (minimum allowed), 1 for restroom
    // (we don't know if it's dirty without reviews, so give benefit of doubt).
    const stub = {
      bestDish: null,
      alsoRecommended: [],
      photoWorthy: null,
      awards: null,
      worthIt: null,
      practical: null,
      whatYouSee: null,
      aboutAndHistory: null,
      crowd: null,
      bestTime: null,
      vibe: null,
      value: null,
      goodToKnow: [],
      ageFit: null,
      travelerNotes: null,
      gsStars: 1,
      gsRedFlag: false,
      gsVerdict: 'Not enough review data yet — check back as more visitors share their experience.',
      websiteUri: placeMeta.websiteUri || null,
      placeName: placeMeta.name || null,
    };
    if (env.GLOBESKIMMERS_KV) {
      await env.GLOBESKIMMERS_KV.put(aiCacheKey, JSON.stringify(stub), { expirationTtl: AI_DETAILS_TTL_SECONDS }).catch(() => {});
    }
    return jsonResponse({ aiDetails: stub, _cache: 'miss-stub' });
  }

  const userContent = `PLACE METADATA:\n${JSON.stringify(placeMeta, null, 2)}\n\nREVIEW SNIPPETS (up to 5 from Google):\n${JSON.stringify(reviewSnippets, null, 2)}\n\nGenerate the AI Details JSON per the voice rules above.`;

  // 4) Call Claude Haiku 4.5
  let aiDetails;
  try {
    const apiRes = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'x-api-key': env.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        // v7: dropped goodFor/notIdealFor/headsUp (duplicates of verdict +
        // goodToKnow), so the response is leaner again. ~1500 covers the
        // remaining fields with headroom for richer bestTime/value copy.
        // v10+: topDishes carries up to 5 candidates with words + review lists.
        max_tokens: 2000,
        system: buildAIDetailsSystemPrompt(kind),
        messages: [{ role: 'user', content: userContent }]
      })
    });
    if (!apiRes.ok) {
      const errText = await apiRes.text();
      return jsonResponse({ error: 'Claude API error', status: apiRes.status, details: errText }, 502);
    }
    const data = await apiRes.json();
    const raw = data?.content?.[0]?.text?.trim() || '';
    const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
    aiDetails = JSON.parse(cleaned);
    aiDetails.websiteUri = placeMeta.websiteUri || null;
    aiDetails.placeName = placeMeta.name || null;

    // Defensive clamping — enforce per-kind star rules even if Claude slips.
    // Restaurants/coffee: 1-5 minimum. Restroom: 0-5. Attraction: 1-5.
    // Red flag only allowed for restroom + attraction.
    let stars = parseInt(aiDetails.gsStars, 10);
    if (isNaN(stars)) stars = 1;
    if (stars > 5) stars = 5;
    if (kind === 'restroom') {
      if (stars < 0) stars = 0;
    } else {
      if (stars < 1) stars = 1;
    }
    aiDetails.gsStars = stars;
    const redFlagAllowed = (kind === 'restroom' || kind === 'attraction' || kind === 'atm');
    aiDetails.gsRedFlag = redFlagAllowed ? !!aiDetails.gsRedFlag : false;

    // New v4 fields — normalize shape so frontend doesn't get surprises.
    // whatYouSee / aboutAndHistory only meaningful for attractions.
    if (kind !== 'attraction') {
      aiDetails.whatYouSee = null;
      aiDetails.aboutAndHistory = null;
    } else {
      aiDetails.whatYouSee = typeof aiDetails.whatYouSee === 'string' && aiDetails.whatYouSee.trim() ? aiDetails.whatYouSee.trim() : null;
      aiDetails.aboutAndHistory = typeof aiDetails.aboutAndHistory === 'string' && aiDetails.aboutAndHistory.trim() ? aiDetails.aboutAndHistory.trim() : null;
    }
    // photoWorthy + awards apply to restaurant/coffee/attraction only.
    const photoAwardsAllowed = (kind === 'restaurant' || kind === 'coffee' || kind === 'attraction');
    if (!photoAwardsAllowed) {
      aiDetails.photoWorthy = null;
      aiDetails.awards = null;
    } else {
      aiDetails.photoWorthy = typeof aiDetails.photoWorthy === 'string' && aiDetails.photoWorthy.trim() ? aiDetails.photoWorthy.trim() : null;
      aiDetails.awards = typeof aiDetails.awards === 'string' && aiDetails.awards.trim() ? aiDetails.awards.trim() : null;
    }
    // ageFit / goodFor / notIdealFor / headsUp are deprecated in v7 but
    // we normalize to safe-empty shapes so any legacy frontend code reading
    // them gets a stable response (no crash on undefined access).
    aiDetails.ageFit = null;
    aiDetails.goodFor = [];
    aiDetails.notIdealFor = [];
    aiDetails.headsUp = [];

    // v7 fields — worthIt / practical. These apply to restaurant / coffee /
    // attraction only.
    const v7Allowed = (kind === 'restaurant' || kind === 'coffee' || kind === 'attraction');
    const sanitizeStr = (v) => (typeof v === 'string' && v.trim() ? v.trim() : null);

    // worthIt: enum or null. v6 expanded to 5 tiers.
    const WORTH_ENUM = new Set([
      'worth_the_stop',
      'strong_nearby_pick',
      'craving_match',
      'know_before_you_go',
      'better_if_convenient',
    ]);
    if (!v7Allowed || !WORTH_ENUM.has(aiDetails.worthIt)) {
      aiDetails.worthIt = v7Allowed ? 'strong_nearby_pick' : null;
    }

    // practical: object with 5 string|null fields (v8 added `tipping`)
    if (!v7Allowed || !aiDetails.practical || typeof aiDetails.practical !== 'object') {
      aiDetails.practical = null;
    } else {
      const p = aiDetails.practical;
      const cleanedP = {
        payment: sanitizeStr(p.payment),
        englishMenu: sanitizeStr(p.englishMenu),
        reservation: sanitizeStr(p.reservation),
        dietary: sanitizeStr(p.dietary),
        tipping: sanitizeStr(p.tipping),
      };
      const anyPresent = Object.values(cleanedP).some(v => v !== null);
      aiDetails.practical = anyPresent ? cleanedP : null;
    }

    // alsoRecommended v5: array of {name, context} objects. Accept legacy
    // string form too in case a stale Haiku response slips through — coerce
    // "Name — context" strings into objects.
    if (!Array.isArray(aiDetails.alsoRecommended)) {
      aiDetails.alsoRecommended = [];
    } else {
      aiDetails.alsoRecommended = aiDetails.alsoRecommended
        .map(item => {
          if (item && typeof item === 'object') {
            const name = sanitizeStr(item.name);
            const context = sanitizeStr(item.context);
            return name ? { name, context } : null;
          }
          if (typeof item === 'string' && item.trim()) {
            const parts = item.split(/\s+—\s+|\s+-\s+/);
            const name = sanitizeStr(parts[0]);
            const context = parts.length > 1 ? sanitizeStr(parts.slice(1).join(' — ')) : null;
            return name ? { name, context } : null;
          }
          return null;
        })
        .filter(Boolean)
        .slice(0, 4);
    }

    if (kind === 'restaurant' || kind === 'coffee') {
      const top = rankTopDishes(aiDetails.topDishes, reviewSnippets.map((r) => r.text), `${placeMeta.name || ''} ${place.primaryType || ''}`);
      aiDetails.topDishes = top;
      aiDetails.dishReviewsRead = reviewSnippets.length;
      // Older app builds read bestDish / alsoRecommended.
      if (top.length) {
        aiDetails.bestDish = { name: top[0].name, context: top[0].context };
        aiDetails.alsoRecommended = top.slice(1).map(({ name, context }) => ({ name, context }));
      }
    } else {
      aiDetails.topDishes = [];
    }
  } catch (e) {
    return jsonResponse({ error: 'Claude parse error: ' + e.message }, 500);
  }

  // 5) Cache the AI Details JSON for 30 days
  if (env.GLOBESKIMMERS_KV) {
    await env.GLOBESKIMMERS_KV.put(
      aiCacheKey,
      JSON.stringify(aiDetails),
      { expirationTtl: AI_DETAILS_TTL_SECONDS }
    ).catch(() => {});
  }

  return jsonResponse({ aiDetails, _cache: 'miss' });
}

// ============================================================================
// ATTRACTION AI DETAILS — Things-To-Do redesign, Phase 2.
// ============================================================================
// Forked from handleAIDetails / buildAIDetailsSystemPrompt above so the
// attraction layout can evolve without touching restaurant/coffee/restroom
// code paths. Per the redesign handoff's HARD SCOPE FENCE.
//
// What's new vs the shared /ai-details endpoint:
//   1. Dedicated cache prefix (`attr_ai_details_*`) so attraction iterations
//      don't invalidate the restaurant cache.
//   2. `verifiedFacts` block pre-filled from Google Places data (price band,
//      rating, accessibility flags, reservable). These are HARD facts and
//      get the Verified source stamp in the UI.
//   3. `_sources` map — every renderable field tagged with its source tier
//      ('verified' | 'reviews' | 'forecast' | 'call'). The frontend drives
//      its per-field source-stamp badges from this map.
//   4. Honesty-first prompt: explicit "do not invent" guardrails, omit-when-
//      unknown over guess, conditional sections (sell-out nudge, smart tip)
//      stay null unless evidence is present.
//
// Same Haiku model + voice rules as the shared endpoint; the system prompt
// just adds the per-field tagging and the omission rules. Same restaurant
// red-flag policy (gsRedFlag true only on genuine worldwide safety concerns).
// ============================================================================

const ATTRACTION_AI_DETAILS_TTL_SECONDS = 30 * 24 * 60 * 60;  // 30 days, matches /ai-details
const ATTRACTION_AI_DETAILS_PROMPT_VERSION = 'a2';            // a1 -> a2: added smartTip, typicalDurationMin, wait object (Phase 2.5)

// Cafe "work-friendly" profile (laptop/remote-work signals from reviews).
const CAFE_WORK_TTL_SECONDS = 30 * 24 * 60 * 60;             // 30 days KV secondary
const CAFE_WORK_PROMPT_VERSION = 'w1';                        // bump to regenerate all profiles

function buildAttractionAIDetailsSystemPrompt() {
  return `You are GlobeSkimmers' Things-To-Do AI Details engine. Generate practical, honest insights for a traveler about to visit an ATTRACTION (museum, landmark, park, theme park, viewpoint, religious site, etc.).

KIND: attraction

VOICE RULES (ABSOLUTE):
- DO NOT write ANYTHING that would deter a traveler from visiting. Content is public.
- FORBIDDEN words/phrases: "inconsistent", "complaints", "issues", "concerns", "problems", "poor", "rude", "disappointed", "frustrating", "unreliable", "questionable", "lacking", "subpar", "stay away", "avoid", "skip", "don't go".
- ACCESSIBILITY CLAIMS: never write "ADA compliant", "accessible room(s) guaranteed", "wheelchair-friendly", "fully accessible", "assistance booked" or "your ticket reflects your disability". State accessibility ONLY as something the place itself lists or Google reports (e.g. "wheelchair-accessible entrance reported"); otherwise write "accessibility not confirmed".
- DO mention factual planning info that helps the visit go better.
- ALWAYS lead with what people love.

HONESTY RULES (CRITICAL — these are NEW for the attraction endpoint):
- If a field has no positive content to draw from in the reviews/metadata, set it to null/empty. NEVER invent to fill a slot.
- Do NOT fabricate facts you cannot tie back to the reviews or place metadata.
- For each renderable text field, set its source tier in the "_sources" object using:
    "verified"  → Hard fact from Google place metadata (priceLevel, accessibilityOptions, rating, reservable, editorialSummary).
    "reviews"   → Inferred from review snippets.
    "forecast"  → Computed from external signal (weather, elevation). Not used in this prompt — leave fields null rather than guess.
    "call"      → Not in our data; user should call/visit the venue's website. Use this when you HAVE to render a field but lack supporting evidence.

PER-FIELD FIELDS:
- bestDish = null. (Attractions don't have dishes.)
- alsoRecommended: TOP 3 must-see/must-do items at this attraction, as an array of { name, context } objects. name = the item (exhibit, view, ride, garden, etc.), context = short reason (≤90 chars). Aim for 3 — fewer only if data is thin.
- photoWorthy: 1 short line naming a standout photo-worthy spot/exhibit/view. NULL if no obvious photo-worthy feature is mentioned.
- awards: 1 short line listing UNESCO status, top-tourist-attraction rankings, Michelin Green Guide stars, or notable recognitions. NULL if none.
- worthIt: ONE of "worth_the_stop" | "strong_nearby_pick" | "craving_match" | "know_before_you_go" | "better_if_convenient". For famous landmarks / UNESCO sites default to "worth_the_stop"; for local parks default to "strong_nearby_pick". Use "know_before_you_go" if there's meaningful planning friction (timed entry, bag check, limited access). Use "craving_match" for niche-interest venues.
- practical: { payment, englishMenu, reservation, dietary } object. For attractions:
  - payment: ticket purchase methods (e.g. "Card or cash at gate; book online for skip-the-line"). NULL if unclear.
  - englishMenu: signage/audio-guide language + staff English (e.g. "Audio guide in English available", "Signage in local language only"). NULL if unclear.
  - reservation: timed entry / advance booking (e.g. "Timed-entry tickets recommended for weekends", "Walk-in fine on weekdays"). NULL if unclear.
  - dietary: null for attractions.
- whatYouSee: 1-2 short concrete sentences describing what is physically present (buildings, exhibits, sculptures, rides, displays, scenery). NULL if data is silent.
- aboutAndHistory: 1-2 short factual sentences on purpose / origin / brief history. NULL if data is silent.
- crowd: who visits — short concrete labels (e.g. "Families with kids; school groups on weekdays", "Photographers and history fans"). Avoid vague phrasing.
- bestTime: CONCRETE actionable recommendation. Don't say "mornings are calmer" — say "Arrive at opening (9 AM) on a weekday to avoid crowds, or after 3 PM when tour buses leave". Pair a SPECIFIC suggested window with a brief reason.
- vibe: 1 direct sentence describing atmosphere (busy/quiet, contemplative/energetic, kid-friendly/adult-focused). Avoid decorative language.
- value: traveler-friendly admission framing. Use direct words: "free", "cheap", "fair", "pricey but worth it", "splurge-only". Include actual admission tier + 1-line judgment. Examples: "Free entry — fully worth a 2-hour visit", "Cheap (~$10); fair for what you see".
- goodToKnow: 2-4 SHORT verified facts that change how a traveler plans the visit. ONLY include items DIRECTLY supported by reviews/metadata. Prioritize: bag-check rules, photography restrictions, accessibility realities, kid-friendliness, audio-guide availability, dress code (temples/religious sites), what to bring, hours quirks, day-of-the-week closures.
- travelerNotes: practical traveler tips to make the visit better.
- typicalDurationMin: integer minutes — typical visit duration (NOT wait time; the time the average traveler spends INSIDE this attraction). Examples: 30 (quick viewpoint), 90 (mid-size museum), 240 (theme park half-day), 480 (full-day park). Set to null if reviews don't converge on a window — DO NOT guess. Better to omit than to invent.
- wait: object describing line / queue mechanics. Fill ONLY when reviews mention queueing, capacity, or ride-style throughput. Set the whole field to null for places where waiting isn't a thing (parks, viewpoints, walk-around museums with no entry queue).
    { "builtIn": "...", "crowdDriven": "...", "typicalMinutes": <int> }
    - builtIn: STRUCTURAL wait that timing won't fix — capacity, one-at-a-time mechanics, scheduled entry, etc. State the mechanism confidently (e.g. "One rider at a time on the cliff zipline", "Single-file pathway through the cave"). null if not applicable.
    - crowdDriven: TIMING-FIXABLE bottleneck — weekend rush, after-school crowds, peak-season queues. Pair the time window with the queue (e.g. "Weekends 12–2 PM see ~30-min entry queues"). null if not applicable.
    - typicalMinutes: integer rough wait estimate from reviews. null if reviews don't support a confident number.
- smartTip: ONE concrete planning win travelers learn from reviews — a real save in money, time, or mistake-avoidance. Strict examples ONLY:
    "Book the combo ticket online for ~30% off the gate price."
    "Enter through the south gate to skip the main queue."
    "Bring water — none sold inside; gates close at sunset."
    "The audio guide is included free at the info desk; don't pay extra at the kiosk."
  DEFAULT TO NULL. If no review-supported concrete save exists, return null. NEVER write platitudes ("great place", "go early"), opinions, or vague advice. NEVER invent a tip to fill the slot.

GS VERDICT SCORING:
- gsStars MUST be an integer 1-5 (minimum 1).
- gsRedFlag = true ONLY if multiple reviews flag a GENUINE worldwide safety concern (e.g. crime in area, unsafe structures, recent incidents). Otherwise false.
- gsVerdict: 1-2 short sentences matching the chosen worthIt tier. CAN fold in atmosphere-fit caveats using the EXACT pattern "Best if you ... Not ideal for [atmosphere/occasion mismatch]." Atmosphere caveats are allowed; quality complaints are NOT. Keep under 200 chars.

OUTPUT JSON ONLY (no markdown fences, no prose outside the JSON):
{
  "bestDish": null,
  "alsoRecommended": [ { "name": "...", "context": "..." }, ... ],
  "photoWorthy": "..." | null,
  "awards": "..." | null,
  "worthIt": "worth_the_stop" | "strong_nearby_pick" | "craving_match" | "know_before_you_go" | "better_if_convenient",
  "practical": { "payment": "..." | null, "englishMenu": "..." | null, "reservation": "..." | null, "dietary": null } | null,
  "whatYouSee": "..." | null,
  "aboutAndHistory": "..." | null,
  "crowd": "..." | null,
  "bestTime": "..." | null,
  "vibe": "..." | null,
  "value": "..." | null,
  "goodToKnow": [ "...", ... ],
  "travelerNotes": "..." | null,
  "typicalDurationMin": <integer> | null,
  "wait": { "builtIn": "..." | null, "crowdDriven": "..." | null, "typicalMinutes": <integer> | null } | null,
  "smartTip": "..." | null,
  "gsStars": <1-5>,
  "gsRedFlag": <boolean>,
  "gsVerdict": "...",
  "_sources": {
    "alsoRecommended": "reviews" | "verified" | "call",
    "photoWorthy": "reviews" | "call",
    "awards": "reviews" | "verified" | "call",
    "worthIt": "reviews",
    "practical.payment": "reviews" | "verified" | "call",
    "practical.englishMenu": "reviews" | "verified" | "call",
    "practical.reservation": "reviews" | "verified" | "call",
    "whatYouSee": "reviews" | "verified" | "call",
    "aboutAndHistory": "reviews" | "verified" | "call",
    "crowd": "reviews" | "call",
    "bestTime": "reviews" | "call",
    "vibe": "reviews" | "call",
    "value": "reviews" | "verified" | "call",
    "goodToKnow": "reviews" | "call",
    "travelerNotes": "reviews" | "call",
    "typicalDurationMin": "reviews",
    "wait.builtIn": "reviews",
    "wait.crowdDriven": "reviews",
    "wait.typicalMinutes": "reviews",
    "smartTip": "reviews",
    "gsVerdict": "reviews"
  }
}

Rules for _sources tagging:
- If a field is null/empty/[], you may omit its key OR set it to "call" — either is fine; the frontend treats both the same.
- Use "verified" ONLY when the field clearly mirrors the place metadata (e.g. aboutAndHistory written from editorialSummary, awards naming Michelin/UNESCO etc. that appeared in metadata).
- Default to "reviews" for everything else that you actually filled in from review snippets.

Return JSON only.`;
}

// D1 stamp id → Google place id (for the AI panel): an IDs-only text search for
// the name, restricted to a box sized to the attraction's footprint. A
// "places:<googleId>" id already carries it. Cached 180 days ('none' 30).
async function resolveStampGid(env, id) {
  const direct = id.match(/^places:([A-Za-z0-9_-]{10,})$/);
  if (direct) return direct[1];
  const kv = env.GLOBESKIMMERS_KV, key = `d1gid:${id}`;
  const hit = kv ? await kv.get(key).catch(() => null) : null;
  if (hit) return hit === 'none' ? null : hit;
  if (!env.ATTRACTIONS_DB || !env.GOOGLE_API_KEY) return null;
  const row = await env.ATTRACTIONS_DB.prepare('SELECT * FROM attractions WHERE id = ?1 LIMIT 1').bind(id).first().catch(() => null);
  if (!row || !row.name || !Number.isFinite(+row.lat) || !Number.isFinite(+row.lng)) return null;
  const lat = +row.lat, lng = +row.lng;
  const m = Math.max(400, Math.min(ppStampRadius(row), 3000));
  const dLat = m / 111320, dLng = m / (111320 * Math.max(0.2, Math.cos(lat * Math.PI / 180)));
  let gid = null;
  try {
    const r = await fetch('https://places.googleapis.com/v1/places:searchText', {
      method: 'POST',
      headers: { 'X-Goog-Api-Key': env.GOOGLE_API_KEY, 'X-Goog-FieldMask': 'places.id', 'Content-Type': 'application/json' },
      body: JSON.stringify({ textQuery: String(row.name), pageSize: 1, locationRestriction: { rectangle: { low: { latitude: lat - dLat, longitude: lng - dLng }, high: { latitude: lat + dLat, longitude: lng + dLng } } } }),
    });
    if (r.ok) gid = (await r.json())?.places?.[0]?.id || null;
  } catch { gid = null; }
  if (kv) await kv.put(key, gid || 'none', { expirationTtl: (gid ? 180 : 30) * 86400 }).catch(() => {});
  const stampable = (row.tier === 'secret' || ['world', 'national', 'regional'].includes(row.founder_scope || row.scope)) && row.class_ban !== 'duplicate';
  if (kv && gid && stampable) await kv.put(`gid2d1v4:${gid}`, JSON.stringify(ttdStampSummary(row)), { expirationTtl: 30 * 86400 }).catch(() => {});
  return gid;
}

async function handleAttractionAIDetails(request, env) {
  if (!env.ANTHROPIC_API_KEY) {
    return jsonResponse({ error: 'ANTHROPIC_API_KEY not configured' }, 500);
  }
  let body;
  try { body = await request.json(); } catch (_e) {
    return jsonResponse({ error: 'Invalid JSON body' }, 400);
  }
  let placeId = body?.placeId;
  if (!placeId) {
    return jsonResponse({ error: 'placeId required' }, 400);
  }
  // A stamp's attraction page passes its D1 id: resolve the Google twin so the
  // page shares the same AI panel (and cache) as the Things to Do card.
  // (auto-seeded rows use all-lowercase "cc-city-name" slugs; Google ids are mixed-case)
  if (/^[a-z]+:/.test(String(placeId)) || /^[a-z]{2}-[a-z0-9-]+$/.test(String(placeId))) {
    const gid = await resolveStampGid(env, String(placeId));
    if (!gid) return jsonResponse({ error: 'No details for this place yet' }, 404);
    placeId = gid;
  }

  // 0) D1 permanent cache — Phase C. Pay Haiku once per placeId, ever.
  // The D1 row outlives KV's 30-day TTL, so popular attractions
  // (Eiffel Tower, Pyramids, etc.) never re-trigger a Haiku call once
  // they've been generated. KV check below stays for unmigrated entries
  // and acts as a fast secondary read path.
  const d1Cached = await readAttractionAiFromD1(env, placeId, ATTRACTION_AI_DETAILS_PROMPT_VERSION);
  if (d1Cached) {
    return jsonResponse({ aiDetails: d1Cached, _cache: 'hit-d1' });
  }

  // 1) Check attraction AI Details cache (30-day TTL, dedicated key prefix).
  const aiCacheKey = `place:${placeId}:attr_ai_details_${ATTRACTION_AI_DETAILS_PROMPT_VERSION}`;
  if (env.GLOBESKIMMERS_KV) {
    const cached = await env.GLOBESKIMMERS_KV.get(aiCacheKey, { type: 'json' }).catch(() => null);
    if (cached) {
      // Backfill D1 from KV so subsequent reads are served from the
      // permanent layer — and once KV expires, the D1 row keeps
      // serving without paying Haiku.
      await writeAttractionAiToD1(env, placeId, ATTRACTION_AI_DETAILS_PROMPT_VERSION, cached, body?.placeName || null);
      return jsonResponse({ aiDetails: cached, _cache: 'hit-kv-backfilled' });
    }
  }

  // 2) Load Place Details (prefer the existing details_{placeId} cache so
  //    we don't pay Google again for a popular place).
  const detailsCacheKey = `details_${placeId}`;
  let place;
  const cachedDetails = await getFromCache(env, detailsCacheKey);
  if (cachedDetails && cachedDetails.data) {
    place = cachedDetails.data;
  } else {
    try {
      const apiKey = env.GOOGLE_API_KEY;
      const detailsRes = await fetch(`https://places.googleapis.com/v1/places/${placeId}?languageCode=en`, {
        method: 'GET',
        headers: {
          'X-Goog-Api-Key': apiKey,
          'X-Goog-FieldMask': CONFIG.DETAILS_FIELD_MASK
        }
      });
      if (!detailsRes.ok) {
        return jsonResponse({ error: 'Place details fetch failed', status: detailsRes.status }, 502);
      }
      const raw = await detailsRes.json();
      place = normalizePlace(raw, new URL(request.url).origin, true);
      await setInCache(env, detailsCacheKey, place, CONFIG.CACHE_TTL.DETAILS);
    } catch (e) {
      return jsonResponse({ error: 'Place details error: ' + e.message }, 502);
    }
  }

  // 3) Build the verifiedFacts block from Google data. These are HARD facts
  //    that the UI renders with a green Verified stamp.
  const PRICE_BAND_LABELS = ['Free', '$', '$$', '$$$', '$$$$'];
  const accessibility = place.accessibilityOptions || null;
  const verifiedFacts = {
    priceBand: (typeof place.priceLevel === 'number' && place.priceLevel >= 0 && place.priceLevel <= 4)
      ? PRICE_BAND_LABELS[place.priceLevel]
      : null,
    rating: typeof place.rating === 'number' ? place.rating : null,
    ratingCount: typeof place.userRatingCount === 'number' ? place.userRatingCount : null,
    reservable: typeof place.reservable === 'boolean' ? place.reservable : null,
    accessibility: accessibility
      ? {
          // Google's accessibilityOptions returns booleans (or undefined). Keep
          // null when the field is absent so the UI can distinguish "no data"
          // from "false". Verified stamp ONLY when the value is present.
          wheelchairAccessibleEntrance: typeof accessibility.wheelchairAccessibleEntrance === 'boolean' ? accessibility.wheelchairAccessibleEntrance : null,
          wheelchairAccessibleParking:  typeof accessibility.wheelchairAccessibleParking  === 'boolean' ? accessibility.wheelchairAccessibleParking  : null,
          wheelchairAccessibleRestroom: typeof accessibility.wheelchairAccessibleRestroom === 'boolean' ? accessibility.wheelchairAccessibleRestroom : null,
          wheelchairAccessibleSeating:  typeof accessibility.wheelchairAccessibleSeating  === 'boolean' ? accessibility.wheelchairAccessibleSeating  : null,
        }
      : null,
    hasEditorialSummary: !!place.editorialSummary,
  };

  // 4) Build Claude input — reviews + key metadata.
  const reviewSnippets = (place.reviews || []).slice(0, 5).map(r => ({
    text: r.text || '',
    rating: r.rating,
    when: r.time || '',
  })).filter(r => r.text);

  const placeMeta = {
    name: place.name || place.displayName?.text,
    address: place.address || place.formattedAddress,
    rating: place.rating,
    reviewCount: place.userRatingCount,
    priceLevel: place.priceLevel,
    primaryType: place.primaryTypeDisplay || place.primaryType,
    editorialSummary: place.editorialSummary,
    websiteUri: place.websiteUri,
  };

  // 5) If reviews + editorial summary are both empty, return a stub.
  if (reviewSnippets.length === 0 && !placeMeta.editorialSummary) {
    const stub = {
      bestDish: null,
      alsoRecommended: [],
      photoWorthy: null,
      awards: null,
      worthIt: 'strong_nearby_pick',
      practical: null,
      whatYouSee: null,
      aboutAndHistory: null,
      crowd: null,
      bestTime: null,
      vibe: null,
      value: null,
      goodToKnow: [],
      travelerNotes: null,
      typicalDurationMin: null,
      wait: null,
      smartTip: null,
      gsStars: 1,
      gsRedFlag: false,
      gsVerdict: 'Not enough review data yet — check back as more visitors share their experience.',
      verifiedFacts,
      _sources: { worthIt: 'forecast', gsVerdict: 'forecast' },   // canned fallback verdict is an estimate, not review-derived (T2.3)
      websiteUri: placeMeta.websiteUri || null,
      placeName: placeMeta.name || null,
    };
    if (env.GLOBESKIMMERS_KV) {
      await env.GLOBESKIMMERS_KV.put(aiCacheKey, JSON.stringify(stub), { expirationTtl: ATTRACTION_AI_DETAILS_TTL_SECONDS }).catch(() => {});
    }
    // Persist stub to D1 too. A stub is the right cached answer for
    // attractions without enough review signal; if the place later
    // accumulates reviews and we want to regenerate, bump the prompt
    // version and the cache miss will trigger a full Haiku run.
    await writeAttractionAiToD1(env, placeId, ATTRACTION_AI_DETAILS_PROMPT_VERSION, stub, placeMeta.name);
    return jsonResponse({ aiDetails: stub, _cache: 'miss-stub' });
  }

  const userContent = `PLACE METADATA:\n${JSON.stringify(placeMeta, null, 2)}\n\nVERIFIED FACTS (Google place data — already known):\n${JSON.stringify(verifiedFacts, null, 2)}\n\nREVIEW SNIPPETS (up to 5 from Google):\n${JSON.stringify(reviewSnippets, null, 2)}\n\nGenerate the Attraction AI Details JSON per the voice and honesty rules above. Tag each filled field's source in _sources.`;

  // 6) Call Claude Haiku 4.5.
  let aiDetails;
  try {
    const apiRes = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'x-api-key': env.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 1900,  // a1 1700 → a2 1900 for the smartTip / typicalDurationMin / wait fields
        system: buildAttractionAIDetailsSystemPrompt(),
        messages: [{ role: 'user', content: userContent }]
      })
    });
    if (!apiRes.ok) {
      const errText = await apiRes.text();
      return jsonResponse({ error: 'Claude API error', status: apiRes.status, details: errText }, 502);
    }
    const data = await apiRes.json();
    const raw = data?.content?.[0]?.text?.trim() || '';
    const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
    aiDetails = JSON.parse(cleaned);
    aiDetails.websiteUri = placeMeta.websiteUri || null;
    aiDetails.placeName = placeMeta.name || null;
    aiDetails.verifiedFacts = verifiedFacts;

    // Defensive clamping.
    let stars = parseInt(aiDetails.gsStars, 10);
    if (isNaN(stars)) stars = 1;
    if (stars < 1) stars = 1;
    if (stars > 5) stars = 5;
    aiDetails.gsStars = stars;
    aiDetails.gsRedFlag = !!aiDetails.gsRedFlag;

    // bestDish is always null for attractions.
    aiDetails.bestDish = null;

    // Normalize alsoRecommended into {name, context}[] shape.
    if (!Array.isArray(aiDetails.alsoRecommended)) {
      aiDetails.alsoRecommended = [];
    } else {
      aiDetails.alsoRecommended = aiDetails.alsoRecommended
        .map(item => {
          if (item && typeof item === 'object') {
            const name = typeof item.name === 'string' && item.name.trim() ? item.name.trim() : null;
            const context = typeof item.context === 'string' && item.context.trim() ? item.context.trim() : null;
            return name ? { name, context } : null;
          }
          if (typeof item === 'string' && item.trim()) {
            const parts = item.split(/\s+—\s+|\s+-\s+/);
            const name = parts[0]?.trim() || null;
            const context = parts.length > 1 ? parts.slice(1).join(' — ').trim() : null;
            return name ? { name, context } : null;
          }
          return null;
        })
        .filter(Boolean)
        .slice(0, 3);
    }

    // Normalize practical object.
    if (!aiDetails.practical || typeof aiDetails.practical !== 'object') {
      aiDetails.practical = null;
    } else {
      const p = aiDetails.practical;
      const sanitize = (v) => (typeof v === 'string' && v.trim() ? v.trim() : null);
      const cleaned = {
        payment: sanitize(p.payment),
        englishMenu: sanitize(p.englishMenu),
        reservation: sanitize(p.reservation),
        dietary: null,  // attractions don't use this
      };
      const anyPresent = Object.values(cleaned).some(v => v !== null);
      aiDetails.practical = anyPresent ? cleaned : null;
    }

    // Normalize goodToKnow.
    if (!Array.isArray(aiDetails.goodToKnow)) {
      aiDetails.goodToKnow = [];
    } else {
      aiDetails.goodToKnow = aiDetails.goodToKnow
        .map(s => (typeof s === 'string' && s.trim() ? s.trim() : null))
        .filter(Boolean)
        .slice(0, 4);
    }

    // worthIt enum guard.
    const WORTH_ENUM = new Set([
      'worth_the_stop', 'strong_nearby_pick', 'craving_match',
      'know_before_you_go', 'better_if_convenient',
    ]);
    if (!WORTH_ENUM.has(aiDetails.worthIt)) {
      aiDetails.worthIt = 'strong_nearby_pick';
    }

    // Phase 2.5 fields — clamp / defensive null-out.
    // typicalDurationMin: positive integer or null. Cap at 12h so a bad
    // model response doesn't render as "Allow 47h".
    const dur = parseInt(aiDetails.typicalDurationMin, 10);
    aiDetails.typicalDurationMin = (Number.isFinite(dur) && dur > 0 && dur <= 720) ? dur : null;

    // wait object: each sub-field independently nullable; whole object
    // null if every sub-field is null after sanitization.
    if (!aiDetails.wait || typeof aiDetails.wait !== 'object') {
      aiDetails.wait = null;
    } else {
      const w = aiDetails.wait;
      const sanitizeWait = (v) => (typeof v === 'string' && v.trim() ? v.trim() : null);
      const wm = parseInt(w.typicalMinutes, 10);
      const cleanedW = {
        builtIn: sanitizeWait(w.builtIn),
        crowdDriven: sanitizeWait(w.crowdDriven),
        typicalMinutes: (Number.isFinite(wm) && wm > 0 && wm <= 600) ? wm : null,
      };
      const anyWait = cleanedW.builtIn || cleanedW.crowdDriven || cleanedW.typicalMinutes != null;
      aiDetails.wait = anyWait ? cleanedW : null;
    }

    // smartTip: string or null. Hard cap at 200 chars so the prompt can't
    // smuggle a paragraph in.
    if (typeof aiDetails.smartTip === 'string' && aiDetails.smartTip.trim()) {
      const trimmed = aiDetails.smartTip.trim();
      aiDetails.smartTip = trimmed.length > 200 ? trimmed.slice(0, 198).trim() + '…' : trimmed;
    } else {
      aiDetails.smartTip = null;
    }

    // Normalize _sources map.
    if (!aiDetails._sources || typeof aiDetails._sources !== 'object') {
      aiDetails._sources = {};
    } else {
      const VALID_TIERS = new Set(['verified', 'reviews', 'forecast', 'call']);
      const cleanedSources = {};
      for (const [k, v] of Object.entries(aiDetails._sources)) {
        if (typeof v === 'string' && VALID_TIERS.has(v)) cleanedSources[k] = v;
      }
      aiDetails._sources = cleanedSources;
    }
  } catch (e) {
    return jsonResponse({ error: 'Claude parse error: ' + e.message }, 500);
  }

  // 7) Cache the AI Details JSON for 30 days under the dedicated attraction key.
  if (env.GLOBESKIMMERS_KV) {
    await env.GLOBESKIMMERS_KV.put(
      aiCacheKey,
      JSON.stringify(aiDetails),
      { expirationTtl: ATTRACTION_AI_DETAILS_TTL_SECONDS }
    ).catch(() => {});
  }

  // 8) D1 permanent cache (Phase C). Pay Haiku ONCE per attraction,
  // ever. The KV write above stays for fast read-paths, but the D1
  // row is what survives past the 30-day KV expiry — and what stops
  // popular attractions like Eiffel Tower from triggering a fresh
  // Haiku call every month.
  await writeAttractionAiToD1(env, placeId, ATTRACTION_AI_DETAILS_PROMPT_VERSION, aiDetails, placeMeta.name);

  return jsonResponse({ aiDetails, _cache: 'miss' });
}

// ============================================================================
// CAFE WORK-FRIENDLY PROFILE — "Good for working" signals from reviews.
// Mirrors the attraction AI-details pattern: D1 permanent cache → KV 30d →
// Place Details (reused cache) → Haiku → cache. Pay Haiku once per cafe, ever.
// ============================================================================
function buildCafeWorkSystemPrompt() {
  return `You analyze a coffee shop's Google reviews + editorial summary to judge how good it is for getting WORK done (laptop / remote work / studying). Output STRICT JSON only — no prose, no markdown fences.

HONESTY RULES:
- Use ONLY what the reviews/summary actually say. If a topic is not mentioned, set its status to "unknown" — NEVER guess or infer from vibe.
- Prefer recent, repeated signals. One offhand mention = low confidence (reflect in evidenceCount).
- State negatives plainly but neutrally (e.g. "reviewers say outlets are limited").

Return EXACTLY this JSON shape:
{
  "laptopFriendly": "great" | "ok" | "not_ideal" | "unknown",
  "wifi":    { "status": "yes" | "no" | "unknown", "note": "<=8 words or empty string" },
  "outlets": { "status": "yes" | "limited" | "no" | "unknown", "note": "<=8 words or empty string" },
  "tables":  { "status": "yes" | "limited" | "no" | "unknown", "note": "<=8 words (work-suitable tables/space) or empty string" },
  "ac":      { "status": "yes" | "no" | "unknown", "note": "<=8 words or empty string" },
  "seatingComfort": "comfy" | "basic" | "cramped" | "unknown",
  "noise": "quiet" | "moderate" | "lively" | "unknown",
  "summary": "<=18 words, one honest line about working here",
  "bestForWork": "<=8 words (e.g. weekday mornings) or null",
  "evidenceCount": 0
}

evidenceCount = how many of the provided reviews actually touched on work topics (wifi/outlets/seating/noise/working).
laptopFriendly: "great" = several positive work signals; "ok" = mixed/some positives; "not_ideal" = reviews say loud/cramped/no outlets/no wifi/laptops discouraged; "unknown" = reviews do not cover it.`;
}

// Core cafe work-profile resolver — shared by the single-cafe endpoint AND the
// list-time batch. Returns { workProfile, _cache }; workProfile is the object,
// the UNKNOWN stub, or null (unresolved / compute skipped / error). Pass
// allowCompute:false for a FREE cache-only read (D1+KV) — no Google/Haiku spend —
// which the batch uses to fold in already-known cafes at zero cost.
async function getCafeWorkProfile(env, origin, { placeId, placeName, lat, lng, allowCompute = true }) {
  if (!placeId) return { workProfile: null, _cache: 'no-id' };

  // 0) D1 permanent cache — pay Haiku once per cafe, ever.
  const d1Cached = await readCafeWorkFromD1(env, placeId, CAFE_WORK_PROMPT_VERSION);
  if (d1Cached) return { workProfile: d1Cached, _cache: 'hit-d1' };

  // 1) KV 30-day secondary (backfills D1 on hit).
  const kvKey = `place:${placeId}:cafe_work_${CAFE_WORK_PROMPT_VERSION}`;
  if (env.GLOBESKIMMERS_KV) {
    const cached = await env.GLOBESKIMMERS_KV.get(kvKey, { type: 'json' }).catch(() => null);
    if (cached) {
      await writeCafeWorkToD1(env, placeId, CAFE_WORK_PROMPT_VERSION, cached, placeName || null);
      return { workProfile: cached, _cache: 'hit-kv' };
    }
  }

  // Cache-only mode → stop here (no spend).
  if (!allowCompute) return { workProfile: null, _cache: 'miss-skip' };
  if (!env.ANTHROPIC_API_KEY) return { workProfile: null, _cache: 'no-key' };

  // 2) Resolve owned (UUID) → Google id, then reuse the details_{gid} cache
  //    (shared with enrich-owned; no new Google cost when warm).
  const gid = await resolveOwnedGid(env, placeId, placeName, lat, lng);
  if (!gid) return { workProfile: null, _cache: 'unresolved' };
  const detailsCacheKey = `details_${gid}`;
  let place;
  const cachedDetails = await getFromCache(env, detailsCacheKey);
  if (cachedDetails && cachedDetails.data) {
    place = cachedDetails.data;
  } else {
    try {
      const detailsRes = await fetch(`https://places.googleapis.com/v1/places/${gid}?languageCode=en`, {
        method: 'GET',
        headers: { 'X-Goog-Api-Key': env.GOOGLE_API_KEY, 'X-Goog-FieldMask': CONFIG.DETAILS_FIELD_MASK }
      });
      if (!detailsRes.ok) return { workProfile: null, _cache: 'details-fail' };
      place = normalizePlace(await detailsRes.json(), origin, true);
      await setInCache(env, detailsCacheKey, place, CONFIG.CACHE_TTL.DETAILS);
    } catch { return { workProfile: null, _cache: 'details-error' }; }
  }

  const reviewSnippets = (place.reviews || []).slice(0, 5).map(r => ({ text: r.text || '', rating: r.rating })).filter(r => r.text);
  const resolvedName = place.name || place.displayName?.text || placeName || null;
  const editorialSummary = place.editorialSummary || null;

  const UNKNOWN = {
    laptopFriendly: 'unknown',
    wifi: { status: 'unknown', note: '' },
    outlets: { status: 'unknown', note: '' },
    tables: { status: 'unknown', note: '' },
    ac: { status: 'unknown', note: '' },
    seatingComfort: 'unknown',
    noise: 'unknown',
    summary: 'Not enough reviews yet to assess work-friendliness.',
    bestForWork: null,
    evidenceCount: 0,
    placeName: resolvedName,
  };

  // 3) No review/editorial signal → cache an "unknown" stub so we do not re-check.
  if (reviewSnippets.length === 0 && !editorialSummary) {
    if (env.GLOBESKIMMERS_KV) await env.GLOBESKIMMERS_KV.put(kvKey, JSON.stringify(UNKNOWN), { expirationTtl: CAFE_WORK_TTL_SECONDS }).catch(() => {});
    await writeCafeWorkToD1(env, placeId, CAFE_WORK_PROMPT_VERSION, UNKNOWN, resolvedName);
    return { workProfile: UNKNOWN, _cache: 'miss-stub' };
  }

  const userContent = `CAFE: ${JSON.stringify({ name: resolvedName, primaryType: place.primaryTypeDisplay || place.primaryType, editorialSummary })}\n\nREVIEW SNIPPETS (up to 5 from Google):\n${JSON.stringify(reviewSnippets, null, 2)}\n\nReturn the work-friendliness JSON per the rules. Use "unknown" for anything the reviews do not mention — never guess.`;

  let workProfile;
  try {
    const apiRes = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 700,
        system: buildCafeWorkSystemPrompt(),
        messages: [{ role: 'user', content: userContent }]
      })
    });
    if (!apiRes.ok) return { workProfile: null, _cache: 'llm-fail' };
    const data = await apiRes.json();
    const raw = data?.content?.[0]?.text?.trim() || '';
    const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
    workProfile = JSON.parse(cleaned);

    // Defensive normalization.
    const VERDICTS = new Set(['great', 'ok', 'not_ideal', 'unknown']);
    if (!VERDICTS.has(workProfile.laptopFriendly)) workProfile.laptopFriendly = 'unknown';
    for (const k of ['wifi', 'outlets', 'tables', 'ac']) {
      if (!workProfile[k] || typeof workProfile[k] !== 'object') workProfile[k] = { status: 'unknown', note: '' };
    }
    workProfile.evidenceCount = Number.isFinite(workProfile.evidenceCount) ? workProfile.evidenceCount : 0;
    workProfile.placeName = resolvedName;
  } catch { return { workProfile: null, _cache: 'parse-fail' }; }

  if (env.GLOBESKIMMERS_KV) await env.GLOBESKIMMERS_KV.put(kvKey, JSON.stringify(workProfile), { expirationTtl: CAFE_WORK_TTL_SECONDS }).catch(() => {});
  await writeCafeWorkToD1(env, placeId, CAFE_WORK_PROMPT_VERSION, workProfile, resolvedName);
  return { workProfile, _cache: 'miss' };
}

async function handleCafeWorkProfile(request, env) {
  let body;
  try { body = await request.json(); } catch (_e) { return jsonResponse({ error: 'Invalid JSON body' }, 400); }
  if (!body?.placeId) return jsonResponse({ error: 'placeId required' }, 400);
  const { workProfile, _cache } = await getCafeWorkProfile(env, new URL(request.url).origin, {
    placeId: body.placeId, placeName: body.placeName, lat: body.lat ?? body.latitude, lng: body.lng ?? body.longitude, allowCompute: true,
  });
  return jsonResponse({ workProfile, _cache });
}

// List-time work-profile batch — powers the "Good for working" / Outlets / Quiet
// / AC filters. Reads the FREE cache (D1+KV) for every listed cafe, then computes
// up to `maxCompute` of the still-unknown ones on demand (Haiku+Google, cached
// forever) so a work filter returns real results in a new area WITHOUT an
// unbounded bill. Only ever called on explicit work-intent (a work filter tapped).
// The client sends cafes pre-sorted (nearest/best first) so the compute budget is
// spent on the most relevant. Returns { profiles: { placeId: workProfile } }.
async function handleCafeWorkProfilesBatch(request, env, ctx) {
  try {
    const b = await request.json().catch(() => ({}));
    const cafes = Array.isArray(b.cafes) ? b.cafes.slice(0, 30) : [];
    if (!cafes.length) return jsonResponse({ profiles: {} });
    const maxCompute = Math.min(Math.max(parseInt(b.maxCompute, 10) || 8, 0), 12);
    const origin = new URL(request.url).origin;
    const profiles = {};

    // 1) FREE cache reads for everyone.
    const unknown = [];
    for (const c of cafes) {
      if (!c?.placeId) continue;
      const { workProfile } = await getCafeWorkProfile(env, origin, { placeId: c.placeId, placeName: c.placeName, lat: c.lat, lng: c.lng, allowCompute: false });
      if (workProfile) profiles[c.placeId] = workProfile; else unknown.push(c);
    }

    // 2) Bounded on-demand compute for the first N unknowns (parallel, cached forever).
    const toCompute = unknown.slice(0, maxCompute);
    const results = await Promise.all(toCompute.map((c) =>
      getCafeWorkProfile(env, origin, { placeId: c.placeId, placeName: c.placeName, lat: c.lat, lng: c.lng, allowCompute: true })
        .then((r) => ({ id: c.placeId, wp: r.workProfile }))
        .catch(() => ({ id: c.placeId, wp: null }))
    ));
    for (const r of results) if (r.wp) profiles[r.id] = r.wp;

    return jsonResponse({ profiles, computed: toCompute.length });
  } catch (e) { return jsonResponse({ profiles: {}, error: e.message }); }
}

// ============================================================================
// RESTROOM AI DETAILS — traveler/tourist/elderly/family restroom intel.
// Dedicated endpoint (not the generic /ai-details restaurant voice). Returns 7
// honest restroom-specific sections + a structured restroomAmenities object
// with confidence labels. KV-cached 90d (pay Haiku ~once per place).
// ============================================================================
const RESTROOM_AI_PROMPT_VERSION = 'r1';   // bump to regenerate all restroom details

function buildRestroomAIDetailsSystemPrompt() {
  return `You are GlobeSkimmers' RESTROOM AI Details engine. A traveler, tourist, elderly user, family, or someone with an URGENT restroom need is about to walk to this place. Help them quickly understand what kind of restroom this is, what supplies it may have, and whether it is easy/safe to use. Output STRICT JSON only — no prose, no markdown fences.

PRIORITY ORDER (what matters most): 1) Access 2) Toilet setup 3) Supplies 4) Cleanliness 5) Accessibility 6) Family/elderly comfort 7) Safety.

HONESTY RULES (CRITICAL):
- Use ONLY what the reviews + place metadata actually support. NEVER guess or present unknown amenities as facts.
- Amenity confidence values: "confirmed" (hard metadata or repeated explicit reviews), "reported" (a review explicitly mentions it), "likely" (strongly implied by venue type but not stated — use SPARINGLY, only for soap / toilet paper / hand-drying at a normal staffed indoor business), "not_confirmed" (no evidence either way — THE DEFAULT), "unknown" (truly no basis).
- Prefer "not_confirmed" over inventing. Do NOT claim "has bidet" unless evidence confirms it — mark bidet "not_confirmed".
- Soft wording for gaps in the section text: "not confirmed", "may need to ask staff", "bring wipes just in case", "confirm at location if needed".

USE THE METADATA YOU ARE GIVEN:
- If accessibilityOptions.wheelchairAccessibleRestroom is true → restroomAmenities.accessibleStall = "confirmed".
- Venue category coffee/cafe/restaurant/fast food → purchaseRequired "likely"; in US/Canada/UK/W.Europe/Australia toiletType "western"; soap & toilet paper "likely" at a normal staffed indoor business.
- Gas station / convenience store → keyOrCodeRequired may be "likely" (ask staff for a key).
- Squat toilets only appear in parts of Asia / Middle East — only mark "squat"/"both" with regional or review support; otherwise "western" (with support) or "unknown".

SECTION TEXT — each 1-2 short, plain, traveler-friendly sentences (no marketing fluff):
- verdict: Is this a good restroom option right now? Name WHAT it is (inside a coffee shop / mall / gas station / transit station / public building / hotel / airport, etc.) and any access caveat.
- toiletSetup: toilet type + bidet / seat-cover status, using "not confirmed" honestly.
- supplies: toilet paper / soap / hand drying with confidence + a "bring wipes" nudge when there are gaps.
- accessRules: how to get in (public, customer-only, purchase may be required, ask staff for key/code, inside business/mall/transit, may close with the business).
- accessibility: wheelchair / stall / grab bars / doorway / stairs / elevator / walker — use confirm-at-location wording when unsure.
- familyElderly: suitability for elderly travelers, kids, families; baby-changing / family-restroom status (honest); note if it is a staffed indoor location.
- safety: short comfort/safety note (staffed indoor vs isolated public; best used during open hours).

Return EXACTLY this JSON shape:
{
  "verdict": "...",
  "toiletSetup": "...",
  "supplies": "...",
  "accessRules": "...",
  "accessibility": "...",
  "familyElderly": "...",
  "safety": "...",
  "restroomAmenities": {
    "toiletType": "western" | "squat" | "both" | "unknown",
    "bidet": "confirmed" | "reported" | "not_confirmed" | "unknown",
    "toiletPaper": "confirmed" | "reported" | "likely" | "not_confirmed" | "unknown",
    "toiletSeatCovers": "confirmed" | "reported" | "not_confirmed" | "unknown",
    "soap": "confirmed" | "reported" | "likely" | "not_confirmed" | "unknown",
    "handDryerOrPaperTowels": "confirmed" | "reported" | "likely" | "not_confirmed" | "unknown",
    "babyChangingTable": "confirmed" | "reported" | "not_confirmed" | "unknown",
    "familyRestroom": "confirmed" | "reported" | "not_confirmed" | "unknown",
    "accessibleStall": "confirmed" | "reported" | "not_confirmed" | "unknown",
    "keyOrCodeRequired": "confirmed" | "reported" | "likely" | "not_confirmed" | "unknown",
    "purchaseRequired": "confirmed" | "reported" | "likely" | "not_confirmed" | "unknown"
  }
}`;
}

async function handleRestroomAIDetails(request, env) {
  if (!env.ANTHROPIC_API_KEY) return jsonResponse({ error: 'ANTHROPIC_API_KEY not configured' }, 500);
  let body;
  try { body = await request.json(); } catch (_e) { return jsonResponse({ error: 'Invalid JSON body' }, 400); }
  const placeId = body?.placeId;
  if (!placeId) return jsonResponse({ error: 'placeId required' }, 400);
  const ctxVenue = body?.venueLabel || body?.venueCategory || null;
  const ctxAccess = body?.accessType || null;

  // KV 90-day cache — pay Haiku ~once per place.
  const kvKey = `place:${placeId}:restroom_ai_${RESTROOM_AI_PROMPT_VERSION}`;
  if (env.GLOBESKIMMERS_KV) {
    const cached = await env.GLOBESKIMMERS_KV.get(kvKey, { type: 'json' }).catch(() => null);
    if (cached) return jsonResponse({ restroomDetails: cached, _cache: 'hit-kv' });
  }

  // Place Details — reuse the details_{placeId} cache (no new Google cost when warm).
  const detailsCacheKey = `details_${placeId}`;
  let place;
  const cachedDetails = await getFromCache(env, detailsCacheKey);
  if (cachedDetails && cachedDetails.data) {
    place = cachedDetails.data;
  } else {
    try {
      const detailsRes = await fetch(`https://places.googleapis.com/v1/places/${placeId}?languageCode=en`, {
        method: 'GET',
        headers: { 'X-Goog-Api-Key': env.GOOGLE_API_KEY, 'X-Goog-FieldMask': CONFIG.DETAILS_FIELD_MASK }
      });
      if (!detailsRes.ok) return jsonResponse({ error: 'Place details fetch failed', status: detailsRes.status }, 502);
      place = normalizePlace(await detailsRes.json(), new URL(request.url).origin, true);
      await setInCache(env, detailsCacheKey, place, CONFIG.CACHE_TTL.DETAILS);
    } catch (e) {
      return jsonResponse({ error: 'Place details error: ' + e.message }, 502);
    }
  }

  const placeName = place.name || place.displayName?.text || body?.placeName || null;
  const reviewSnippets = (place.reviews || []).slice(0, 5).map(r => ({ text: r.text || '', rating: r.rating })).filter(r => r.text);
  const accessibility = place.accessibilityOptions || null;

  const userContent = `PLACE: ${JSON.stringify({
    name: placeName,
    venue: ctxVenue,
    primaryType: place.primaryTypeDisplay || place.primaryType,
    types: (place.types || []).slice(0, 8),
    accessFromFinder: ctxAccess,
    editorialSummary: place.editorialSummary || null,
    accessibilityOptions: accessibility,
  })}\n\nREVIEW SNIPPETS (up to 5 from Google):\n${JSON.stringify(reviewSnippets, null, 2)}\n\nReturn the restroom AI Details JSON per the rules. Use "not_confirmed" / "unknown" for anything not supported — never guess.`;

  let restroomDetails;
  try {
    const apiRes = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 1000,
        system: buildRestroomAIDetailsSystemPrompt(),
        messages: [{ role: 'user', content: userContent }]
      })
    });
    if (!apiRes.ok) { const t = await apiRes.text(); return jsonResponse({ error: 'Claude API error', status: apiRes.status, details: t }, 502); }
    const data = await apiRes.json();
    const raw = data?.content?.[0]?.text?.trim() || '';
    const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
    restroomDetails = JSON.parse(cleaned);
  } catch (e) {
    return jsonResponse({ error: 'Claude parse error: ' + e.message }, 500);
  }

  // Defensive normalization + hard-metadata override.
  const A = (restroomDetails && typeof restroomDetails.restroomAmenities === 'object' && restroomDetails.restroomAmenities) || {};
  const amenityKeys = ['toiletType','bidet','toiletPaper','toiletSeatCovers','soap','handDryerOrPaperTowels','babyChangingTable','familyRestroom','accessibleStall','keyOrCodeRequired','purchaseRequired'];
  for (const k of amenityKeys) if (!A[k]) A[k] = 'unknown';
  if (accessibility?.wheelchairAccessibleRestroom === true) A.accessibleStall = 'confirmed';
  restroomDetails.restroomAmenities = A;
  restroomDetails.placeName = placeName;

  if (env.GLOBESKIMMERS_KV) await env.GLOBESKIMMERS_KV.put(kvKey, JSON.stringify(restroomDetails), { expirationTtl: 60 * 60 * 24 * 90 }).catch(() => {});
  return jsonResponse({ restroomDetails, _cache: 'miss' });
}

// ============================================================================
// ATM AI DETAILS — ATM Finder redesign, Phase A3.
// ============================================================================
// Forked from handleAIDetails / buildAIDetailsSystemPrompt above so the
// ATM panel can evolve a richer schema (cardCompatibility, atmOperatorFee,
// withdrawalLimits, locationContext, safety, dccWarning) without touching
// restaurant or attraction code paths. Per the redesign HARD SCOPE FENCE.
//
// What's new vs the shared /ai-details endpoint:
//   1. Dedicated cache prefix (`atm_ai_details_*`) so ATM iterations
//      don't invalidate the restaurant cache.
//   2. `verifiedFacts` block pre-filled from Google Places (open status,
//      hours, primary type, accessibility, address).
//   3. ATM-specific schema fields the AtmAIDetails.jsx component already
//      reads in Phase A2 — those sections will start rendering real data
//      the moment this endpoint is deployed.
//   4. `_sources` per-field map driving the source-stamp badges.
//   5. Voice rules tuned for INFRASTRUCTURE, not businesses-to-protect:
//      safety warnings (outdoor at night, skimmer reports, no-cameras)
//      ARE allowed and important. Fee facts are reported neutrally.
//
// Same Haiku 4.5 model as the shared endpoint.
// ============================================================================

const ATM_AI_DETAILS_TTL_SECONDS = 30 * 24 * 60 * 60;  // 30 days
const ATM_AI_DETAILS_PROMPT_VERSION = 'atm1';

function buildAtmAIDetailsSystemPrompt() {
  return `You are GlobeSkimmers' ATM Finder AI Details engine. Generate practical, honest insights for a traveler about to use this ATM.

KIND: atm

CORE PRINCIPLE — this is INFRASTRUCTURE, not a business we're protecting from negative reviews:
- Travelers' safety and money come first. Honest safety warnings benefit the user.
- Fee facts are stated neutrally. "Operator fee: 220 THB (reported by travelers)" is correct; "expensive ATM" is not.
- We do NOT editorialize or attack operators. We DO surface risk signals (skimmer reports, outdoor location after dark, no cameras).

FORBIDDEN words/phrases (still no inflammatory language): "rip-off", "scam", "garbage", "trash", "stay away" — these are emotional, not informative. Use neutral terms: "high fee compared to nearby ATMs", "outdoor location — use caution at night", "reports of card-skimming incidents — be cautious".
ACCESSIBILITY CLAIMS: never write "ADA compliant", "wheelchair-friendly" or "fully accessible". State accessibility ONLY as Google reports it (e.g. "wheelchair-accessible entrance reported"); otherwise "accessibility not confirmed".

HONESTY RULES (CRITICAL):
- For every renderable field, set its source tier in "_sources":
    "verified"  → From Google place metadata (hours, openNow, accessibilityOptions, address, primaryType).
    "confirmed" → Stated by the operator's official channel (rare — use sparingly, only if reviewers cite the official posted fee schedule).
    "reported"  → Multiple traveler reports back the same number/fact.
    "reviews"   → Inferred from one or two review snippets.
    "estimated" → Country/operator pattern-based estimate (e.g. "Bangkok Bank ATMs in Thailand typically charge 220 THB").
    "call"      → Not in our data; user should call/visit the operator's site. Use when the field MUST render but lacks evidence.
- DEFAULT TO NULL when you can't tie a fact back to reviews/metadata/known patterns. Empty beats invented.
- Operator-fee CONFIDENCE field must match the source tier you set for atmOperatorFee in _sources.

PER-FIELD GUIDANCE:

- bestDish = null. alsoRecommended = []. (ATMs don't have these.)

- worthIt: ONE of "worth_the_stop" | "strong_nearby_pick" | "craving_match" | "know_before_you_go" | "better_if_convenient":
  - "worth_the_stop" = inside a bank branch, low/no surcharge, accepts global networks, safe location. The ATM you'd send a traveler to.
  - "strong_nearby_pick" = solid bank-network ATM in a normal location. Most common pick.
  - "craving_match" = specific bank-branch ATM for travelers wanting that bank's fee waiver (use sparingly).
  - "know_before_you_go" = meaningful friction: high surcharge, limited network compatibility, awkward access, language barrier on screen, or safety caveat.
  - "better_if_convenient" = independent / convenience-store ATM with reasonable fees but not a destination.
  Default to "strong_nearby_pick" when unsure. NEVER "skip".

- gsStars: integer 1–5 (minimum 1, even for ATMs with mixed reviews).
- gsRedFlag: true ONLY if reviews show GENUINE safety concerns at this specific ATM (past skimmer reports, multiple recent reviews mentioning unsafe area at night, robbery incidents). Otherwise false.
- gsVerdict: 1–2 short sentences synthesizing the verdict. Mention the network/operator + location type + key fee/safety signal. Example: "Good ATM for most travelers — inside a bank branch with a reported 220 THB operator fee and Visa/Mastercard/Plus/Cirrus support. Decline ATM-side currency conversion for a better rate."

- cardCompatibility: array of { network, accepted } objects covering ONLY networks travelers commonly need. Valid network keys: "visa", "mastercard", "plus", "cirrus", "maestro", "unionpay", "jcb", "discover", "amex". Set accepted=true ONLY when reviews/metadata indicate the network works at this ATM (or when the operator's bank brand reliably accepts it). Set accepted=false ONLY when explicit reviews say it doesn't. Omit unknown networks rather than guessing true. If you can't confidently judge ANY network, return null and let the UI show the safe-default copy.

- atmOperatorFee: object { amount, currency, confidence } | null.
  - amount: numeric, in local currency. NEVER include the foreign-transaction-fee or your-home-bank-fee here; this is the surcharge the ATM operator charges at withdrawal time only.
  - currency: ISO 4217 code matching the country (e.g. "THB" for Thailand).
  - confidence: "confirmed" | "reported" | "estimated".
  - Return null if you have no confident grounding. DO NOT estimate randomly. Estimating is fine when the operator brand has a well-documented pattern (e.g. Bangkok Bank, Wells Fargo, CIBC); not fine when the operator is unknown.

- withdrawalLimits: object { perTransaction, daily, currency, dependsOnCard, confidence } | null.
  - perTransaction / daily: numeric, in local currency. Either can be null while the other is filled.
  - dependsOnCard: true when the actual limit varies by the traveler's home bank/card (almost always true). Default true.
  - confidence: "confirmed" | "reported" | "estimated".
  - Return null if you can't ground a number.

- locationContext: { venueType, subLocation, summary } | null.
  - venueType: ONE of "airport" | "bank_branch" | "mall" | "grocery" | "convenience" | "hotel" | "restaurant" | "transit" | "outdoor" | "other".
  - subLocation: short specific phrase like "Terminal 3 Arrivals near baggage claim" or "Inside 7-Eleven by the front entrance". Null if not in reviews.
  - summary: 1 short sentence combining the two, e.g. "Located inside Terminal 3 Arrivals near baggage claim.".

- safety: object | null with the following boolean (or null when unknown) flags. Include a flag ONLY when reviews / metadata support a confident verdict; OMIT the field entirely otherwise.
    indoor:           ATM is inside a building.
    wellLit:          Area is well-lit.
    securityGuard:    Visible security staff or guard.
    bankBranch:       ATM is at a bank branch (strongest safety signal).
    cameras:          Visible CCTV at or near the ATM.
    highFootTraffic:  Busy area (passive safety from foot traffic).
    open24h:          Vestibule / area accessible 24/7.
    skimmerReports:   true if MULTIPLE reviews mention card-skimming incidents at THIS ATM. Use sparingly; this is a strong claim.
  Return null for the entire safety object if you have no signals at all.

- dccWarning: boolean. Almost always true — most ATMs offer Dynamic Currency Conversion at withdrawal time. Set false only when reviews specifically say this ATM doesn't ask.

- crowd: who uses this ATM (short — e.g. "Mostly arriving international travelers"). Avoid vague phrasing.
- bestTime: CONCRETE actionable window. e.g. "Before 8 AM weekdays for the shortest queue. Avoid 11 PM–5 AM if the area is dark.".
- vibe: physical-location detail. KEEP THIS POPULATED for back-compat with current ATM panel — even if locationContext.summary covers similar ground.
- value: short fee-framing line in traveler language. e.g. "Mid-range surcharge for a bank-branch ATM" or "Free if you bank with Chase". NOT a duplicate of atmOperatorFee.
- goodToKnow: 2–4 SHORT verified facts that change planning. e.g. "Drive-thru only after 10 PM", "Dispenses 1000-THB notes; bring smaller bills for taxis".
- travelerNotes: 1 practical tip beyond what's above. e.g. "Press 'English' BEFORE inserting your card to avoid the local-language flow.".

OUTPUT JSON ONLY (no markdown fences, no prose outside the JSON):
{
  "bestDish": null,
  "alsoRecommended": [],
  "worthIt": "worth_the_stop" | "strong_nearby_pick" | "craving_match" | "know_before_you_go" | "better_if_convenient",
  "cardCompatibility": [ { "network": "visa", "accepted": true|false }, ... ] | null,
  "atmOperatorFee": { "amount": <number>, "currency": "<ISO>", "confidence": "confirmed"|"reported"|"estimated" } | null,
  "withdrawalLimits": { "perTransaction": <number>|null, "daily": <number>|null, "currency": "<ISO>", "dependsOnCard": <bool>, "confidence": "confirmed"|"reported"|"estimated" } | null,
  "locationContext": { "venueType": "airport"|..., "subLocation": "..."|null, "summary": "..." } | null,
  "safety": { "indoor": <bool>, "wellLit": <bool>, "securityGuard": <bool>, "bankBranch": <bool>, "cameras": <bool>, "highFootTraffic": <bool>, "open24h": <bool>, "skimmerReports": <bool> } | null,
  "dccWarning": <bool>,
  "crowd": "..." | null,
  "bestTime": "..." | null,
  "vibe": "..." | null,
  "value": "..." | null,
  "goodToKnow": [ "...", ... ],
  "travelerNotes": "..." | null,
  "gsStars": <1-5>,
  "gsRedFlag": <boolean>,
  "gsVerdict": "...",
  "_sources": {
    "worthIt": "reviews",
    "cardCompatibility": "verified"|"reviews"|"estimated"|"call",
    "atmOperatorFee": "confirmed"|"reported"|"estimated"|"call",
    "withdrawalLimits": "confirmed"|"reported"|"estimated"|"call",
    "locationContext": "verified"|"reviews"|"call",
    "safety": "verified"|"reviews"|"call",
    "crowd": "reviews"|"call",
    "bestTime": "reviews"|"call",
    "vibe": "reviews"|"call",
    "value": "reviews"|"call",
    "goodToKnow": "reviews"|"call",
    "travelerNotes": "reviews"|"call",
    "gsVerdict": "reviews"
  }
}

Return JSON only.`;
}

async function handleAtmAIDetails(request, env) {
  if (!env.ANTHROPIC_API_KEY) {
    return jsonResponse({ error: 'ANTHROPIC_API_KEY not configured' }, 500);
  }
  let body;
  try { body = await request.json(); } catch (_e) {
    return jsonResponse({ error: 'Invalid JSON body' }, 400);
  }
  const placeId = body?.placeId;
  if (!placeId) {
    return jsonResponse({ error: 'placeId required' }, 400);
  }

  const aiCacheKey = `place:${placeId}:atm_ai_details_${ATM_AI_DETAILS_PROMPT_VERSION}`;
  if (env.GLOBESKIMMERS_KV) {
    const cached = await env.GLOBESKIMMERS_KV.get(aiCacheKey, { type: 'json' }).catch(() => null);
    if (cached) {
      return jsonResponse({ aiDetails: cached, _cache: 'hit' });
    }
  }

  // Load Place Details (reuse the existing 90-day cached payload).
  const detailsCacheKey = `details_${placeId}`;
  let place;
  const cachedDetails = await getFromCache(env, detailsCacheKey);
  if (cachedDetails && cachedDetails.data) {
    place = cachedDetails.data;
  } else {
    try {
      const apiKey = env.GOOGLE_API_KEY;
      const detailsRes = await fetch(`https://places.googleapis.com/v1/places/${placeId}?languageCode=en`, {
        method: 'GET',
        headers: {
          'X-Goog-Api-Key': apiKey,
          'X-Goog-FieldMask': CONFIG.DETAILS_FIELD_MASK,
        }
      });
      if (!detailsRes.ok) {
        return jsonResponse({ error: 'Place details fetch failed', status: detailsRes.status }, 502);
      }
      const raw = await detailsRes.json();
      place = normalizePlace(raw, new URL(request.url).origin, true);
      await setInCache(env, detailsCacheKey, place, CONFIG.CACHE_TTL.DETAILS);
    } catch (e) {
      return jsonResponse({ error: 'Place details error: ' + e.message }, 502);
    }
  }

  // Pre-fill verifiedFacts from Google data — these get the Verified
  // stamp in the UI without any LLM involvement.
  const accessibility = place.accessibilityOptions || null;
  const verifiedFacts = {
    openNow: place.regularOpeningHours?.openNow ?? place.currentOpeningHours?.openNow ?? null,
    open24h: !!place.is24Hours || /24[\s\-/]?hours?|24[\s\-/]?7|always open/i.test(place.regularOpeningHours?.weekdayDescriptions?.join(' ') || ''),
    hours: place.regularOpeningHours?.weekdayDescriptions || null,
    address: place.formattedAddress || place.shortFormattedAddress || null,
    primaryType: place.primaryTypeDisplay || place.primaryType || null,
    rating: typeof place.rating === 'number' ? place.rating : null,
    ratingCount: typeof place.userRatingCount === 'number' ? place.userRatingCount : null,
    accessibility: accessibility
      ? {
          wheelchairAccessibleEntrance: typeof accessibility.wheelchairAccessibleEntrance === 'boolean' ? accessibility.wheelchairAccessibleEntrance : null,
          wheelchairAccessibleParking:  typeof accessibility.wheelchairAccessibleParking  === 'boolean' ? accessibility.wheelchairAccessibleParking  : null,
        }
      : null,
  };

  const reviewSnippets = (place.reviews || []).slice(0, 5).map(r => ({
    text: r.text || '',
    rating: r.rating,
    when: r.time || '',
  })).filter(r => r.text);

  const placeMeta = {
    name: place.name || place.displayName?.text,
    address: place.address || place.formattedAddress,
    rating: place.rating,
    reviewCount: place.userRatingCount,
    primaryType: place.primaryTypeDisplay || place.primaryType,
    websiteUri: place.websiteUri,
  };

  if (reviewSnippets.length === 0 && !place.editorialSummary) {
    const stub = {
      bestDish: null,
      alsoRecommended: [],
      worthIt: 'strong_nearby_pick',
      cardCompatibility: null,
      atmOperatorFee: null,
      withdrawalLimits: null,
      locationContext: null,
      safety: null,
      dccWarning: true,
      crowd: null,
      bestTime: null,
      vibe: null,
      value: null,
      goodToKnow: [],
      travelerNotes: null,
      gsStars: 1,
      gsRedFlag: false,
      gsVerdict: 'Not enough review data yet — check the ATM screen before confirming any withdrawal.',
      verifiedFacts,
      _sources: { worthIt: 'estimated', gsVerdict: 'estimated' },   // canned fallback verdict is an estimate, not review-derived (T2.3)
      websiteUri: placeMeta.websiteUri || null,
      placeName: placeMeta.name || null,
    };
    if (env.GLOBESKIMMERS_KV) {
      await env.GLOBESKIMMERS_KV.put(aiCacheKey, JSON.stringify(stub), { expirationTtl: ATM_AI_DETAILS_TTL_SECONDS }).catch(() => {});
    }
    return jsonResponse({ aiDetails: stub, _cache: 'miss-stub' });
  }

  const userContent = `PLACE METADATA:\n${JSON.stringify(placeMeta, null, 2)}\n\nVERIFIED FACTS (Google place data — already known):\n${JSON.stringify(verifiedFacts, null, 2)}\n\nREVIEW SNIPPETS (up to 5 from Google):\n${JSON.stringify(reviewSnippets, null, 2)}\n\nGenerate the ATM AI Details JSON per the voice and honesty rules above. Tag each filled field's source in _sources.`;

  let aiDetails;
  try {
    const apiRes = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'x-api-key': env.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json'
      },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 1800,  // headroom for the richer ATM schema + _sources map
        system: buildAtmAIDetailsSystemPrompt(),
        messages: [{ role: 'user', content: userContent }],
      })
    });
    if (!apiRes.ok) {
      const errText = await apiRes.text();
      return jsonResponse({ error: 'Claude API error', status: apiRes.status, details: errText }, 502);
    }
    const data = await apiRes.json();
    const raw = data?.content?.[0]?.text?.trim() || '';
    const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
    aiDetails = JSON.parse(cleaned);
    aiDetails.websiteUri = placeMeta.websiteUri || null;
    aiDetails.placeName = placeMeta.name || null;
    aiDetails.verifiedFacts = verifiedFacts;
    aiDetails.bestDish = null;
    aiDetails.alsoRecommended = [];

    // Defensive normalization.
    const sanitizeStr = (v) => (typeof v === 'string' && v.trim() ? v.trim() : null);
    const sanitizeNum = (v) => {
      const n = typeof v === 'number' ? v : Number(v);
      return Number.isFinite(n) ? n : null;
    };

    let stars = parseInt(aiDetails.gsStars, 10);
    if (isNaN(stars)) stars = 1;
    if (stars < 1) stars = 1;
    if (stars > 5) stars = 5;
    aiDetails.gsStars = stars;
    aiDetails.gsRedFlag = !!aiDetails.gsRedFlag;
    aiDetails.dccWarning = aiDetails.dccWarning === false ? false : true;

    const WORTH_ENUM = new Set([
      'worth_the_stop', 'strong_nearby_pick', 'craving_match',
      'know_before_you_go', 'better_if_convenient',
    ]);
    if (!WORTH_ENUM.has(aiDetails.worthIt)) aiDetails.worthIt = 'strong_nearby_pick';

    // cardCompatibility: array of { network, accepted } objects.
    const VALID_NETWORKS = new Set(['visa', 'mastercard', 'plus', 'cirrus', 'maestro', 'unionpay', 'jcb', 'discover', 'amex']);
    if (Array.isArray(aiDetails.cardCompatibility)) {
      const seen = new Set();
      aiDetails.cardCompatibility = aiDetails.cardCompatibility
        .map(item => {
          if (!item || typeof item !== 'object') return null;
          const net = typeof item.network === 'string' ? item.network.toLowerCase().trim() : null;
          if (!net || !VALID_NETWORKS.has(net) || seen.has(net)) return null;
          seen.add(net);
          return { network: net, accepted: !!item.accepted };
        })
        .filter(Boolean);
      if (aiDetails.cardCompatibility.length === 0) aiDetails.cardCompatibility = null;
    } else {
      aiDetails.cardCompatibility = null;
    }

    // atmOperatorFee object.
    const CONF_ENUM = new Set(['confirmed', 'reported', 'estimated']);
    if (aiDetails.atmOperatorFee && typeof aiDetails.atmOperatorFee === 'object') {
      const f = aiDetails.atmOperatorFee;
      const amount = sanitizeNum(f.amount);
      const currency = sanitizeStr(f.currency);
      const confidence = CONF_ENUM.has(f.confidence) ? f.confidence : 'estimated';
      aiDetails.atmOperatorFee = (amount != null && amount >= 0 && currency)
        ? { amount, currency: currency.toUpperCase().slice(0, 4), confidence }
        : null;
    } else {
      aiDetails.atmOperatorFee = null;
    }

    // withdrawalLimits object.
    if (aiDetails.withdrawalLimits && typeof aiDetails.withdrawalLimits === 'object') {
      const w = aiDetails.withdrawalLimits;
      const perTransaction = sanitizeNum(w.perTransaction);
      const daily = sanitizeNum(w.daily);
      const currency = sanitizeStr(w.currency);
      const confidence = CONF_ENUM.has(w.confidence) ? w.confidence : 'estimated';
      const dependsOnCard = w.dependsOnCard === false ? false : true;
      aiDetails.withdrawalLimits = (perTransaction != null || daily != null)
        ? {
            perTransaction,
            daily,
            currency: currency ? currency.toUpperCase().slice(0, 4) : null,
            dependsOnCard,
            confidence,
          }
        : null;
    } else {
      aiDetails.withdrawalLimits = null;
    }

    // locationContext.
    const VALID_VENUES = new Set(['airport', 'bank_branch', 'mall', 'grocery', 'convenience', 'hotel', 'restaurant', 'transit', 'outdoor', 'other']);
    if (aiDetails.locationContext && typeof aiDetails.locationContext === 'object') {
      const l = aiDetails.locationContext;
      const venueType = typeof l.venueType === 'string' && VALID_VENUES.has(l.venueType) ? l.venueType : null;
      const subLocation = sanitizeStr(l.subLocation);
      const summary = sanitizeStr(l.summary);
      aiDetails.locationContext = (venueType || summary) ? { venueType, subLocation, summary } : null;
    } else {
      aiDetails.locationContext = null;
    }

    // safety flags.
    if (aiDetails.safety && typeof aiDetails.safety === 'object') {
      const SAFETY_KEYS = ['indoor', 'wellLit', 'securityGuard', 'bankBranch', 'cameras', 'highFootTraffic', 'open24h', 'skimmerReports'];
      const out = {};
      for (const k of SAFETY_KEYS) {
        if (typeof aiDetails.safety[k] === 'boolean') out[k] = aiDetails.safety[k];
      }
      aiDetails.safety = Object.keys(out).length > 0 ? out : null;
    } else {
      aiDetails.safety = null;
    }

    // goodToKnow.
    if (!Array.isArray(aiDetails.goodToKnow)) aiDetails.goodToKnow = [];
    else aiDetails.goodToKnow = aiDetails.goodToKnow.map(sanitizeStr).filter(Boolean).slice(0, 4);

    // _sources map — validate tier strings.
    const VALID_TIERS = new Set(['verified', 'confirmed', 'reported', 'reviews', 'estimated', 'call']);
    if (!aiDetails._sources || typeof aiDetails._sources !== 'object') {
      aiDetails._sources = {};
    } else {
      const cleanedSources = {};
      for (const [k, v] of Object.entries(aiDetails._sources)) {
        if (typeof v === 'string' && VALID_TIERS.has(v)) cleanedSources[k] = v;
      }
      aiDetails._sources = cleanedSources;
    }
    // Override _sources.atmOperatorFee with the actual confidence value
    // so the stamp always agrees with the fee object's confidence field.
    if (aiDetails.atmOperatorFee?.confidence) {
      aiDetails._sources['atmOperatorFee'] = aiDetails.atmOperatorFee.confidence;
    }
    if (aiDetails.withdrawalLimits?.confidence) {
      aiDetails._sources['withdrawalLimits'] = aiDetails.withdrawalLimits.confidence;
    }
  } catch (e) {
    return jsonResponse({ error: 'Claude parse error: ' + e.message }, 500);
  }

  if (env.GLOBESKIMMERS_KV) {
    await env.GLOBESKIMMERS_KV.put(
      aiCacheKey,
      JSON.stringify(aiDetails),
      { expirationTtl: ATM_AI_DETAILS_TTL_SECONDS }
    ).catch(() => {});
  }

  return jsonResponse({ aiDetails, _cache: 'miss' });
}

// ============================================================================
// NAME LANGUAGE HELP — Haiku 4.5 returns { romanization, translation } for
// any place name. Used by the <NameLanguageHelp> frontend component which
// renders "🔤 Pronounce" + "🌐 Translate" buttons under business names that
// aren't plain English. Single call returns both so user can tap either
// without a second round trip.
//
// Cached 90 days per placeId — names rarely change. ~$0.0002 per fresh call.
// ============================================================================

const NAME_INFO_TTL_SECONDS = 90 * 24 * 60 * 60;  // 90 days
const NAME_INFO_PROMPT_VERSION = 'v3';  // v2->v3: added `nativeScript` field

const NAME_INFO_SYSTEM_PROMPT = `You translate and romanize business names for English-speaking travelers, and provide the native script + language code so the device's Text-to-Speech can pronounce the name authentically.

Given a business name, return STRICT JSON with FOUR fields:
{
  "romanization": "<how to pronounce the name in Latin alphabet, or null if the original is already pure Latin>",
  "translation": "<what the name means in English, or null if it's already a recognizable English phrase / person's name>",
  "lang": "<BCP-47 language code: 'ja-JP', 'zh-CN', 'ko-KR', 'ar-SA', 'it-IT', 'fr-FR', 'es-MX', 'en-US', etc.>",
  "nativeScript": "<the SAME name written in the original/native script, when the displayed name is a romanization of a non-Latin language (e.g. 'Daimaru Tokyo' -> '大丸東京', 'Tokyo Station' -> '東京駅'). Return null if the displayed name is already in its native script, OR if the language natively uses Latin alphabet (Italian/French/Spanish/etc.).>"
}

WHY nativeScript matters: iOS/Android TTS voices pronounce native-script text far more naturally than romanized text. Kyoko (Japanese voice) speaking "大丸東京" sounds like a native Japanese speaker. The same voice trying to read "Daimaru Tokyo" may spell letters out. So when the displayed name is a romanization of CJK/Arabic/etc., give us the original script.

EXAMPLES:
Input: "寿司"
Output: {"romanization": "Sushi", "translation": "Sushi", "lang": "ja-JP", "nativeScript": null}

Input: "Daimaru Tokyo"
Output: {"romanization": null, "translation": null, "lang": "ja-JP", "nativeScript": "大丸東京"}

Input: "Tokyo Station"
Output: {"romanization": null, "translation": null, "lang": "ja-JP", "nativeScript": "東京駅"}

Input: "Mitsukoshi Ginza"
Output: {"romanization": null, "translation": null, "lang": "ja-JP", "nativeScript": "三越銀座"}

Input: "Lotte World"
Output: {"romanization": null, "translation": null, "lang": "ko-KR", "nativeScript": "롯데월드"}

Input: "イマーシブ脱出ゲーム（横浜店）"
Output: {"romanization": "Imāshibu Dasshutsu Gēmu (Yokohama-ten)", "translation": "Immersive Escape Game (Yokohama Branch)", "lang": "ja-JP", "nativeScript": null}

Input: "Trattoria della Nonna"
Output: {"romanization": null, "translation": "Grandmother's Trattoria", "lang": "it-IT", "nativeScript": null}

Input: "Joe's Pizza"
Output: {"romanization": null, "translation": null, "lang": "en-US", "nativeScript": null}

Input: "मसाला हाउस"
Output: {"romanization": "Masala House", "translation": "Spice House", "lang": "hi-IN", "nativeScript": null}

Input: "Café du Monde"
Output: {"romanization": null, "translation": "Café of the World", "lang": "fr-FR", "nativeScript": null}

Input: "北京烤鸭店"
Output: {"romanization": "Běijīng Kǎoyā Diàn", "translation": "Beijing Roast Duck Restaurant", "lang": "zh-CN", "nativeScript": null}

RULES:
- Romanization: ONLY include if the original has non-Latin characters. Use widely-accepted transliteration (Hepburn for Japanese, Pinyin for Chinese, etc.). Preserve original parentheses / punctuation structure.
- Translation: ONLY include if the meaning is non-obvious to an English speaker. Leave null for plain English names.
- For partial-translation cases (e.g., "Sushi Sato"): translate only the non-English parts in context.
- Person's names: leave translation null.
- Lang: ALWAYS return a BCP-47 language code (region-tagged). For Chinese: 'zh-CN' simplified, 'zh-TW' traditional. For Spanish: infer regional ('es-MX', 'es-ES') else 'es-419'. Default to the most common local variant when uncertain.
- NativeScript: ONLY for romanized non-Latin-script languages (Japanese, Chinese, Korean, Russian, Arabic, Hebrew, Thai, Hindi, Greek, etc.). Don't fabricate — only include if you're confident in the native form (well-known brands / common terms / geographic names). For languages that natively use Latin alphabet, this is always null.
- Return JSON only. No markdown, no commentary.`;

async function handleNameInfo(request, env) {
  if (!env.ANTHROPIC_API_KEY) {
    return jsonResponse({ error: 'ANTHROPIC_API_KEY not configured' }, 500);
  }
  let body;
  try { body = await request.json(); } catch (_e) {
    return jsonResponse({ error: 'Invalid JSON body' }, 400);
  }
  const placeId = body?.placeId;
  const name = (body?.name || '').toString().trim();
  if (!placeId || !name) {
    return jsonResponse({ error: 'placeId + name required' }, 400);
  }

  // Cache key includes prompt version so changes invalidate cleanly.
  const cacheKey = `name_info:${placeId}:${NAME_INFO_PROMPT_VERSION}`;
  if (env.GLOBESKIMMERS_KV) {
    const cached = await env.GLOBESKIMMERS_KV.get(cacheKey, { type: 'json' }).catch(() => null);
    if (cached) {
      return jsonResponse({ ...cached, _cache: 'hit' });
    }
  }

  let nameInfo;
  try {
    const apiRes = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'x-api-key': env.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
      },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 200,
        system: NAME_INFO_SYSTEM_PROMPT,
        messages: [{ role: 'user', content: `Business name: ${name}` }],
      }),
    });
    if (!apiRes.ok) {
      const errText = await apiRes.text();
      return jsonResponse({ error: 'Claude API error', status: apiRes.status, details: errText }, 502);
    }
    const data = await apiRes.json();
    const raw = data?.content?.[0]?.text?.trim() || '';
    const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
    nameInfo = JSON.parse(cleaned);
    // Defensive normalization — guarantee keys exist as string|null.
    // `lang` is BCP-47 (e.g. 'ja-JP'). Loose regex validation so the
    // browser's speechSynthesis gets a usable code.
    const rawLang = typeof nameInfo.lang === 'string' ? nameInfo.lang.trim() : '';
    const validLang = /^[a-z]{2,3}(-[A-Za-z0-9]{2,8})*$/i.test(rawLang) ? rawLang : null;
    nameInfo = {
      romanization: typeof nameInfo.romanization === 'string' && nameInfo.romanization.trim() ? nameInfo.romanization.trim() : null,
      translation: typeof nameInfo.translation === 'string' && nameInfo.translation.trim() ? nameInfo.translation.trim() : null,
      lang: validLang,
      nativeScript: typeof nameInfo.nativeScript === 'string' && nameInfo.nativeScript.trim() ? nameInfo.nativeScript.trim() : null,
    };
  } catch (e) {
    return jsonResponse({ error: 'Claude parse error: ' + e.message }, 500);
  }

  if (env.GLOBESKIMMERS_KV) {
    await env.GLOBESKIMMERS_KV.put(cacheKey, JSON.stringify(nameInfo), { expirationTtl: NAME_INFO_TTL_SECONDS }).catch(() => {});
  }
  return jsonResponse({ ...nameInfo, _cache: 'miss' });
}

// ============================================================================
// PARSE-INTENT — LLM intent fallback for long-tail dish/restaurant queries.
// Used when getRestaurants' keyword-based parseSearchIntent can't confidently
// route the query (e.g. "chicken inasal" -> the generic /chicken/ pattern
// instead of filipino_restaurant). Triggered by Strategy B in entry.ts:
// GENERAL intents AND dish matches that left unrecognized words in the query.
//
// Returns structured intent matching the existing DISH_MAP shape so the
// downstream tier classifier doesn't need to know the LLM ever touched it.
// Cached in KV (24h TTL) per normalized query -- expected ~80% cache hit
// rate after a week of accumulation.
// ============================================================================

const PARSE_INTENT_TTL_SECONDS = 24 * 60 * 60;  // 24 hours
const PARSE_INTENT_PROMPT_VERSION = 'v1';

// Valid Google Places API (New) Table A primary types we use in the app.
// Claude is instructed to ONLY emit types from this set; anything else is
// dropped during normalization.
const VALID_GOOGLE_PLACE_TYPES = new Set([
  // Cuisine-specific restaurants
  'african_restaurant','american_restaurant','asian_restaurant','brazilian_restaurant',
  'breakfast_restaurant','brunch_restaurant','chinese_restaurant','filipino_restaurant',
  'french_restaurant','greek_restaurant','hamburger_restaurant','indian_restaurant',
  'indonesian_restaurant','italian_restaurant','japanese_restaurant','korean_restaurant',
  'lebanese_restaurant','mediterranean_restaurant','mexican_restaurant',
  'middle_eastern_restaurant','pizza_restaurant','ramen_restaurant','restaurant',
  'sandwich_shop','seafood_restaurant','spanish_restaurant','steak_house',
  'sushi_restaurant','thai_restaurant','turkish_restaurant','vegan_restaurant',
  'vegetarian_restaurant','vietnamese_restaurant',
  // Specialty / casual
  'bagel_shop','bakery','bar','barbecue_restaurant','cafe','cafeteria','chocolate_shop',
  'coffee_shop','deli','dessert_restaurant','dessert_shop','diner','donut_shop',
  'fast_food_restaurant','fine_dining_restaurant','food_court','ice_cream_shop',
  'juice_shop','meal_delivery','meal_takeaway','pastry_shop','pub','tea_house',
  'wine_bar',
]);

const PARSE_INTENT_SYSTEM_PROMPT = `You are a restaurant-search intent parser for Globeskimmers, a travel app. Given a free-text query, return STRICT JSON describing the search intent so the app can find matching restaurants.

OUTPUT SCHEMA (return EXACTLY this shape — no extra keys, no markdown):
{
  "dishLabel": "<canonical short English label for the dish/cuisine, max 30 chars>" | null,
  "cuisine": "<lowercase cuisine slug, e.g. 'filipino', 'japanese', 'mexican'>" | null,
  "tier1Types": ["<1-3 Google primary types for the specialist place>"],
  "tier2Types": ["<0-3 related Google primary types>"],
  "nameKeywords": ["<chain names + signature dish words for name-based matching, max 8>"],
  "mealTime": "breakfast" | "brunch" | "lunch" | "dinner" | null,
  "strict": <true|false>,
  "strictPrimaryTypes": ["<REQUIRED if strict=true: allowlist of valid types>"],
  "confidence": <0.0-1.0>
}

VALID GOOGLE PRIMARY TYPES (use ONLY these — anything else will be dropped):
african_restaurant, american_restaurant, asian_restaurant, brazilian_restaurant,
breakfast_restaurant, brunch_restaurant, chinese_restaurant, filipino_restaurant,
french_restaurant, greek_restaurant, hamburger_restaurant, indian_restaurant,
indonesian_restaurant, italian_restaurant, japanese_restaurant, korean_restaurant,
lebanese_restaurant, mediterranean_restaurant, mexican_restaurant,
middle_eastern_restaurant, pizza_restaurant, ramen_restaurant, restaurant,
sandwich_shop, seafood_restaurant, spanish_restaurant, steak_house, sushi_restaurant,
thai_restaurant, turkish_restaurant, vegan_restaurant, vegetarian_restaurant,
vietnamese_restaurant, bagel_shop, bakery, bar, barbecue_restaurant, cafe, cafeteria,
chocolate_shop, coffee_shop, deli, dessert_restaurant, dessert_shop, diner, donut_shop,
fast_food_restaurant, fine_dining_restaurant, food_court, ice_cream_shop, juice_shop,
meal_delivery, meal_takeaway, pastry_shop, pub, tea_house, wine_bar

RULES:
1. dishLabel: canonical English. "chicken inasal" stays "chicken inasal"; "kare-kare" stays "kare-kare"; "pho" stays "pho". Set to null if the query isn't food-related.
2. cuisine: lowercase snake_case slug. Set to null if cross-cuisine (e.g. "salad", "sandwich" -- no single cuisine).
3. strict: TRUE if the dish is so cuisine-specific that a non-cuisine restaurant serving it would be a misleading result. Examples: TRUE for inasal/sisig/butter chicken/ramen/pho. FALSE for chicken/salad/burger/pizza (cross-cuisine).
4. strictPrimaryTypes (required when strict=true): the allowlist of Google primary types that ARE legitimate for this dish. For chicken inasal: ['filipino_restaurant']. For ramen: ['ramen_restaurant','japanese_restaurant'].
5. mealTime: only set if the dish is tied to a specific meal (e.g. "pancakes" -> breakfast). Leave null for all-day foods.
6. nameKeywords: chain names + obvious signature words. For inasal: ['inasal','mang inasal','bacolod']. For pho: ['pho','phở','pho 79','pho saigon']. Max 8.
7. confidence: 0.0-1.0. Below 0.5 means "I'm not sure" and the app should ignore your output.
8. If the query is a brand/restaurant name (not a dish), set dishLabel = null and only fill cuisine + tier1Types + nameKeywords with the brand name.
9. Return ONLY JSON. No prose, no markdown fences, no commentary.

EXAMPLES:

Input: "chicken inasal"
Output: {"dishLabel":"chicken inasal","cuisine":"filipino","tier1Types":["filipino_restaurant"],"tier2Types":["barbecue_restaurant"],"nameKeywords":["inasal","chicken inasal","mang inasal","bacolod chicken house"],"mealTime":null,"strict":true,"strictPrimaryTypes":["filipino_restaurant"],"confidence":0.95}

Input: "pho"
Output: {"dishLabel":"pho","cuisine":"vietnamese","tier1Types":["vietnamese_restaurant"],"tier2Types":[],"nameKeywords":["pho","phở","pho 79","pho saigon","pho hoa"],"mealTime":null,"strict":true,"strictPrimaryTypes":["vietnamese_restaurant"],"confidence":0.98}

Input: "bibimbap"
Output: {"dishLabel":"bibimbap","cuisine":"korean","tier1Types":["korean_restaurant"],"tier2Types":[],"nameKeywords":["bibimbap","dolsot","korean bbq"],"mealTime":null,"strict":true,"strictPrimaryTypes":["korean_restaurant"],"confidence":0.97}

Input: "rendang"
Output: {"dishLabel":"rendang","cuisine":"indonesian","tier1Types":["indonesian_restaurant"],"tier2Types":["malaysian_restaurant"],"nameKeywords":["rendang","nasi padang"],"mealTime":null,"strict":true,"strictPrimaryTypes":["indonesian_restaurant","malaysian_restaurant"],"confidence":0.95}

Input: "salad"
Output: {"dishLabel":"salad","cuisine":null,"tier1Types":["vegan_restaurant","vegetarian_restaurant"],"tier2Types":["cafe","restaurant"],"nameKeywords":["salad","sweetgreen","tossed","chop'd"],"mealTime":null,"strict":false,"strictPrimaryTypes":[],"confidence":0.85}

Input: "asdfqwer"
Output: {"dishLabel":null,"cuisine":null,"tier1Types":[],"tier2Types":[],"nameKeywords":[],"mealTime":null,"strict":false,"strictPrimaryTypes":[],"confidence":0.1}`;

// Best-effort D1 logger for intent fallback events. Fire-and-forget,
// never blocks the response. session_id is 'worker' since the Worker
// doesn't know which user session triggered the call (would require
// passing it through from Base44 -- not needed for the aggregate
// analytics we care about: trigger volume, cache rate, top queries).
async function writeIntentFallbackEvent(env, payload) {
  if (!env.DB) return;
  try {
    const ts = Math.floor(Date.now() / 1000);
    await env.DB.prepare(
      `INSERT INTO events (ts, user_id, session_id, event_type, page, payload, ua_summary)
       VALUES (?, ?, ?, ?, ?, ?, ?)`
    ).bind(ts, null, 'worker', 'intent_llm_fallback', null, JSON.stringify(payload), null).run();
  } catch (_e) { /* swallow -- analytics never breaks the response */ }
}

async function handleParseIntent(request, env) {
  if (!env.ANTHROPIC_API_KEY) {
    return jsonResponse({ error: 'ANTHROPIC_API_KEY not configured' }, 500);
  }
  let body;
  try { body = await request.json(); } catch (_e) {
    return jsonResponse({ error: 'Invalid JSON body' }, 400);
  }
  const query = (body?.query || '').toString().trim().toLowerCase();
  if (!query) {
    return jsonResponse({ error: 'query required' }, 400);
  }

  const startedAt = Date.now();

  // Normalize query for cache key: collapse whitespace, drop punctuation that
  // doesn't change meaning. "Chicken Inasal!" and "chicken  inasal" share a key.
  const normalizedQuery = query.replace(/[^\w\s]/g, '').replace(/\s+/g, ' ').trim();
  const cacheKey = `parse_intent:${PARSE_INTENT_PROMPT_VERSION}:${normalizedQuery}`;

  if (env.GLOBESKIMMERS_KV) {
    const cached = await env.GLOBESKIMMERS_KV.get(cacheKey, { type: 'json' }).catch(() => null);
    if (cached) {
      writeIntentFallbackEvent(env, {
        query: normalizedQuery,
        cache: 'hit',
        success: true,
        dishLabel: cached.dishLabel,
        cuisine: cached.cuisine,
        strict: cached.strict,
        confidence: cached.confidence,
        latencyMs: Date.now() - startedAt,
      });
      return jsonResponse({ ...cached, _cache: 'hit' });
    }
  }

  let intent;
  try {
    const apiRes = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: {
        'x-api-key': env.ANTHROPIC_API_KEY,
        'anthropic-version': '2023-06-01',
        'content-type': 'application/json',
      },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 400,
        // Cache the long system prompt -- repeat queries within 5 min hit
        // the cache at ~10% the input cost.
        system: [{ type: 'text', text: PARSE_INTENT_SYSTEM_PROMPT, cache_control: { type: 'ephemeral' } }],
        messages: [{ role: 'user', content: `Query: ${query}` }],
      }),
    });
    if (!apiRes.ok) {
      const errText = await apiRes.text();
      writeIntentFallbackEvent(env, { query: normalizedQuery, cache: 'miss', success: false, error: `claude_api_${apiRes.status}`, latencyMs: Date.now() - startedAt });
      return jsonResponse({ error: 'Claude API error', status: apiRes.status, details: errText }, 502);
    }
    const data = await apiRes.json();
    const raw = data?.content?.[0]?.text?.trim() || '';
    const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
    intent = JSON.parse(cleaned);
  } catch (e) {
    writeIntentFallbackEvent(env, { query: normalizedQuery, cache: 'miss', success: false, error: 'parse_' + (e.message || 'unknown').slice(0, 80), latencyMs: Date.now() - startedAt });
    return jsonResponse({ error: 'Claude parse error: ' + e.message }, 500);
  }

  // Defensive normalization: clamp shape, validate types against known set,
  // drop unknown types instead of letting them poison the downstream tier
  // classifier with strings Google doesn't recognize.
  const filterValidTypes = (arr) => Array.isArray(arr)
    ? arr.filter((t) => typeof t === 'string' && VALID_GOOGLE_PLACE_TYPES.has(t.trim()))
    : [];
  const tier1Types = filterValidTypes(intent.tier1Types);
  const tier2Types = filterValidTypes(intent.tier2Types);
  const strictPrimaryTypes = filterValidTypes(intent.strictPrimaryTypes);
  const confidence = typeof intent.confidence === 'number' ? Math.max(0, Math.min(1, intent.confidence)) : 0;
  const validMealTimes = new Set(['breakfast','brunch','lunch','dinner']);
  const mealTime = (typeof intent.mealTime === 'string' && validMealTimes.has(intent.mealTime)) ? intent.mealTime : null;

  const normalized = {
    dishLabel: typeof intent.dishLabel === 'string' && intent.dishLabel.trim() ? intent.dishLabel.trim() : null,
    cuisine: typeof intent.cuisine === 'string' && intent.cuisine.trim() ? intent.cuisine.trim().toLowerCase() : null,
    tier1Types,
    tier2Types,
    nameKeywords: Array.isArray(intent.nameKeywords)
      ? intent.nameKeywords.filter((k) => typeof k === 'string' && k.trim()).slice(0, 8).map((k) => k.trim().toLowerCase())
      : [],
    mealTime,
    // Strict only allowed if we have at least one valid allowlist type.
    strict: intent.strict === true && strictPrimaryTypes.length > 0,
    strictPrimaryTypes,
    confidence,
  };

  if (env.GLOBESKIMMERS_KV) {
    await env.GLOBESKIMMERS_KV.put(cacheKey, JSON.stringify(normalized), { expirationTtl: PARSE_INTENT_TTL_SECONDS }).catch(() => {});
  }
  writeIntentFallbackEvent(env, {
    query: normalizedQuery,
    cache: 'miss',
    success: true,
    dishLabel: normalized.dishLabel,
    cuisine: normalized.cuisine,
    strict: normalized.strict,
    confidence: normalized.confidence,
    latencyMs: Date.now() - startedAt,
  });
  return jsonResponse({ ...normalized, _cache: 'miss' });
}

// ============================================================================
// /parse-search — cheap free-text → {category, scope, place, query} parser for
// the Smart-Search spine. Modeled on handleParseIntent: Haiku 4.5, prompt-cached
// system prompt (~10% input cost on repeats), KV 24h per query+scope. Only
// called on a CLIENT rule-miss, so volume is the ambiguous minority. ~$0.0009 a
// miss vs ~$0.045 via the generic /invoke-llm it replaces for the spine.
// ============================================================================
const PARSE_SEARCH_TTL_SECONDS = 24 * 60 * 60;
const PARSE_SEARCH_PROMPT_VERSION = 'v7';  // v7: drinks are eat; keep the place as specific as typed; v6: water bodies → waterfront district; v5: country/state/region → best city + region (founder 2026-10-07); v4: a place typed in the query beats the tapped scope (founder 2026-10-07); v3: no hotel / ride categories
const PARSE_SEARCH_CATEGORIES = new Set(['eat', 'coffee', 'things', 'events', 'shopping', 'atm', 'money', 'convenience', 'restroom', 'weather', 'none']);
const PARSE_SEARCH_SCOPES = new Set(['near_me', 'at_stay', 'named_place', 'unknown']);

const PARSE_SEARCH_SYSTEM_PROMPT = `You parse a traveler's free-text search for Globeskimmers into STRICT JSON so the app can route them to the right finder, scoped to the right place.

OUTPUT SCHEMA (return EXACTLY this shape — no extra keys, no markdown):
{
  "category": "eat" | "coffee" | "things" | "events" | "shopping" | "atm" | "money" | "convenience" | "restroom" | "weather" | "none",
  "scope": "near_me" | "at_stay" | "named_place" | "unknown",
  "place": "<city/place name if scope is named_place, else empty string>",
  "query": "<the core thing to search, cleaned of scope words, e.g. ramen, viral desserts>",
  "confidence": <0.0-1.0>,
  "region": "<the country/state/region typed, when place was narrowed to its best city; else empty string>",
  "dream_destination": {"name": "<place>", "city": "<city/region>", "country": "<country>"} | null
}

CATEGORY = which finder fits:
- eat = any food / restaurant / dish / bakery / dessert — AND drinking out: beer, breweries, pubs, bars, wine, cocktails
- coffee = coffee, café, tea, boba (never beer, wine or bars)
- things = things to do, attractions, museums, tours, hikes, sightseeing
- events = dated happenings: concerts, shows, plays, musicals, games (NBA, NFL…), festivals, fairs, choirs, orchestras, "what's on" / "what's happening today", things for kids this weekend, free events — and a named show, team, artist or choir
- shopping = shops, malls, souvenirs
- atm = cash / ATM ; money = currency exchange
- convenience = convenience store ; restroom = toilet ; weather = forecast
- none = the query is ONLY a place name (no thing to find), e.g. "Positano" — and for hotels, lodging, flights, taxis or car rentals, which the app does not offer (keep any named place).

SCOPE:
- near_me = near the user now ("near me", "nearby", "around here")
- at_stay = near their hotel/accommodation ("near my hotel", "by our airbnb")
- named_place = a specific city/place they named ("in Tokyo", "Positano restaurants")
- unknown = no location cue.

RULES:
1. query: strip scope words. "ramen near my hotel" -> query "ramen". "best coffee in Lisbon" -> query "coffee", place "Lisbon".
2. place: ONLY when scope is named_place; the bare place name, else empty string.
3. If the whole query is just a place name, category = "none", query = "".
4. confidence: 0.0-1.0. Below 0.4 = unsure.
5. Return ONLY JSON — no prose, no markdown fences.
6. dream_destination: ONLY when the query expresses a travel EXPERIENCE or dream not tied to the traveler's current surroundings — a phenomenon, activity, or sight someone would travel FOR ("see bears catch fish", "northern lights", "swim with whale sharks", "cherry blossoms"). Name the single best-known real place for it. Everything else (including all near-me/at-stay searches): "dream_destination": null. Never invent places.
7. A place NAMED IN THE QUERY always wins over the tapped scope: "southern food in Atlanta" with scope near_me tapped -> scope "named_place", place "Atlanta". A bare landmark or city ("Eiffel Tower", "Seattle") is also named_place with that place.
8. If the named place is a COUNTRY, STATE, PROVINCE or other area bigger than one city ("Germany", "Spain", "Hawaii", "Tuscany"), set "place" to the single best real CITY in it for this query (beer in Germany -> "Munich"; ATV in Hawaii -> "Honolulu"; activities for seniors in Spain -> a city that suits it) and set "region" to the area as typed. Otherwise "region" is "".
9. If the named place is a BODY OF WATER (bay, lake, sea, river, gulf), set "place" to the waterfront city district travelers actually go to (Manila Bay -> "Roxas Boulevard, Manila"; Lake Tahoe -> "South Lake Tahoe").
10. Keep the place AS SPECIFIC as the traveler typed it — a campus, landmark, street or neighborhood stays itself ("near DLSU Taft" -> place "De La Salle University, Taft Avenue, Manila"; "by Santa Monica Pier" -> "Santa Monica Pier"), never generalized to the city. Read obvious typos ("dear X" means "near X").

EXAMPLES:
Input: "ramen near my hotel"
Output: {"category":"eat","scope":"at_stay","place":"","query":"ramen","confidence":0.95}
Input: "things to do in Tokyo"
Output: {"category":"things","scope":"named_place","place":"Tokyo","query":"things to do","confidence":0.96}
Input: "viral desserts my kids would love"
Output: {"category":"eat","scope":"unknown","place":"","query":"viral desserts","confidence":0.8}
Input: "Positano"
Output: {"category":"none","scope":"named_place","place":"Positano","query":"","confidence":0.9}
Input: "where can I exchange money"
Output: {"category":"money","scope":"unknown","place":"","query":"currency exchange","confidence":0.9}
Input: "see bears catch fish"
Output: {"category":"things","scope":"unknown","place":"","query":"bear viewing","confidence":0.85,"dream_destination":{"name":"Brooks Falls","city":"Katmai National Park, Alaska","country":"United States"}}`;

async function handleParseSearch(request, env) {
  if (!env.ANTHROPIC_API_KEY) return jsonResponse({ error: 'ANTHROPIC_API_KEY not configured' }, 500);
  let body;
  try { body = await request.json(); } catch (_e) { return jsonResponse({ error: 'Invalid JSON body' }, 400); }
  const query = (body?.query || '').toString().trim();
  const scopeChip = (body?.scope || '').toString().trim();
  const activePhrase = (body?.activePhrase || '').toString().trim();
  if (!query) return jsonResponse({ error: 'query required' }, 400);

  // Cache key = query + scope only (place-extraction is query-driven); active
  // city is a prompt hint but not keyed, to keep the cache small.
  const normalizedQuery = query.toLowerCase().replace(/[^\w\s]/g, '').replace(/\s+/g, ' ').trim();
  const cacheKey = `parse_search:${PARSE_SEARCH_PROMPT_VERSION}:${scopeChip || 'auto'}:${normalizedQuery}`;

  if (env.GLOBESKIMMERS_KV) {
    const cached = await env.GLOBESKIMMERS_KV.get(cacheKey, { type: 'json' }).catch(() => null);
    if (cached) return jsonResponse({ ...cached, _cache: 'hit' });
  }

  let parsed;
  try {
    const userMsg = `Query: ${query}` +
      (scopeChip ? `\nThe user tapped scope: ${scopeChip}` : '') +
      (activePhrase ? `\nThe user is currently in: ${activePhrase}` : '');
    const apiRes = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001',
        max_tokens: 256,
        system: [{ type: 'text', text: PARSE_SEARCH_SYSTEM_PROMPT, cache_control: { type: 'ephemeral' } }],
        messages: [{ role: 'user', content: userMsg }],
      }),
    });
    if (!apiRes.ok) return jsonResponse({ error: 'Claude API error', status: apiRes.status }, 502);
    const data = await apiRes.json();
    const raw = data?.content?.[0]?.text?.trim() || '';
    const cleaned = raw.replace(/^```(?:json)?\s*/i, '').replace(/\s*```\s*$/i, '').trim();
    parsed = JSON.parse(cleaned);
  } catch (e) {
    return jsonResponse({ error: 'Claude parse error: ' + (e.message || 'unknown') }, 500);
  }

  // Dream-intent destination, grounded against the owned attractions DB when a
  // matching world/national-tier row exists (brief Part Three S1). Ungrounded
  // suggestions still surface — labeled grounded:false, never with invented
  // coordinates.
  let destination = null;
  const dd = parsed.dream_destination;
  if (dd && typeof dd === 'object' && typeof dd.name === 'string' && dd.name.trim()) {
    destination = {
      grounded: false,
      name: dd.name.trim().slice(0, 80),
      city: typeof dd.city === 'string' ? dd.city.trim().slice(0, 80) : '',
      country: typeof dd.country === 'string' ? dd.country.trim().slice(0, 60) : '',
    };
    if (env.ATTRACTIONS_DB) {
      try {
        const row = await env.ATTRACTIONS_DB.prepare(
          `SELECT id, name, city, country, lat, lng, qid FROM attractions
            WHERE name LIKE ?1 AND coalesce(founder_scope, scope) IN ('world','national')
              AND (class_ban IS NULL OR class_ban = '' OR class_ban LIKE 'review:%')
            ORDER BY (popularity IS NULL) ASC, popularity DESC, sitelinks DESC LIMIT 1`
        ).bind(`%${destination.name.replace(/[%_]/g, '')}%`).first();
        if (row) destination = { grounded: true, id: row.id, name: row.name, city: row.city || '', country: row.country || '', lat: row.lat, lng: row.lng, qid: row.qid || null };
      } catch { /* ungrounded suggestion stands */ }
    }
  }

  const category = (typeof parsed.category === 'string' && PARSE_SEARCH_CATEGORIES.has(parsed.category)) ? parsed.category : 'none';
  const scope = (typeof parsed.scope === 'string' && PARSE_SEARCH_SCOPES.has(parsed.scope)) ? parsed.scope : 'unknown';
  const normalized = {
    category: category === 'none' ? null : category,
    scope,
    place: (typeof parsed.place === 'string' && parsed.place.trim()) ? parsed.place.trim() : null,
    query: typeof parsed.query === 'string' ? parsed.query.trim() : '',
    confidence: typeof parsed.confidence === 'number' ? Math.max(0, Math.min(1, parsed.confidence)) : 0.5,
    region: (typeof parsed.region === 'string' && parsed.region.trim()) ? parsed.region.trim().slice(0, 60) : null,
    destination,
  };

  if (env.GLOBESKIMMERS_KV) {
    await env.GLOBESKIMMERS_KV.put(cacheKey, JSON.stringify(normalized), { expirationTtl: PARSE_SEARCH_TTL_SECONDS }).catch(() => {});
  }
  return jsonResponse({ ...normalized, _cache: 'miss' });
}

// SHA-256 → lowercase hex. (Lived in the removed price-scanner block; shared.)
async function sha256Hex(str) {
  const enc = new TextEncoder().encode(str);
  const buf = await crypto.subtle.digest('SHA-256', enc);
  return Array.from(new Uint8Array(buf)).map(b => b.toString(16).padStart(2, '0')).join('');
}

// ─────────────────────────────────────────────────────────────────────
// Phase C — AI details permanent D1 cache (for /attraction-ai-details)
// ─────────────────────────────────────────────────────────────────────
// Replaces the 30-day KV TTL cache with a permanent D1 cache so we
// only ever pay Haiku ONCE per attraction. Every subsequent request
// for the same placeId returns the cached JSON in <50ms, $0.

// Read a cached AI details payload from D1 keyed by placeId. Returns
// null on miss (D1 binding absent, no row, prompt version drift, or
// any DB error). Designed to be best-effort — a D1 hiccup falls
// through to the existing KV/Haiku path silently.
async function readAttractionAiFromD1(env, placeId, promptVersion) {
  if (!env.ATTRACTIONS_DB) return null;
  try {
    const row = await env.ATTRACTIONS_DB
      .prepare('SELECT ai_json, prompt_version FROM attraction_ai_details WHERE place_id = ?')
      .bind(placeId)
      .first();
    if (!row) return null;
    // Reject rows generated under an older prompt version — forces a
    // regeneration with the current prompt schema rather than serving
    // stale shape that the frontend may no longer understand.
    if (row.prompt_version !== promptVersion) return null;
    try { return JSON.parse(row.ai_json); } catch { return null; }
  } catch {
    return null;
  }
}

// Persist an AI details payload to D1 for permanent reuse. INSERT OR
// REPLACE so a fresh prompt-version regen overwrites the older row
// for the same place_id. Best-effort — any DB error is swallowed
// because the call site already returned the response to the user.
async function writeAttractionAiToD1(env, placeId, promptVersion, aiDetails, placeName) {
  if (!env.ATTRACTIONS_DB) return;
  try {
    await env.ATTRACTIONS_DB.prepare(`
      INSERT OR REPLACE INTO attraction_ai_details
        (place_id, place_name, prompt_version, ai_json, generated_at)
      VALUES (?, ?, ?, ?, datetime('now'))
    `).bind(
      placeId,
      placeName || null,
      promptVersion,
      JSON.stringify(aiDetails),
    ).run();
  } catch (e) {
    console.error('attraction_ai_details write failed:', e?.message);
  }
}

// Cafe work-profile D1 cache (same best-effort pattern as the attraction helpers).
async function readCafeWorkFromD1(env, placeId, promptVersion) {
  if (!env.ATTRACTIONS_DB) return null;
  try {
    const row = await env.ATTRACTIONS_DB
      .prepare('SELECT work_json, prompt_version FROM cafe_work_profiles WHERE place_id = ?')
      .bind(placeId)
      .first();
    if (!row || row.prompt_version !== promptVersion) return null;
    try { return JSON.parse(row.work_json); } catch { return null; }
  } catch {
    return null;
  }
}

async function writeCafeWorkToD1(env, placeId, promptVersion, workProfile, placeName) {
  if (!env.ATTRACTIONS_DB) return;
  try {
    await env.ATTRACTIONS_DB.prepare(`
      INSERT OR REPLACE INTO cafe_work_profiles
        (place_id, place_name, prompt_version, work_json, generated_at)
      VALUES (?, ?, ?, ?, datetime('now'))
    `).bind(
      placeId,
      placeName || null,
      promptVersion,
      JSON.stringify(workProfile),
    ).run();
  } catch (e) {
    console.error('cafe_work_profiles write failed:', e?.message);
  }
}

// ============================================================================
// LOCATION — reverse geocode (coords→city) + location text search.
// Ported from base44/functions/{reverseGeocode,searchLocation} for the native
// data path (Phase 7). OPEN routes (no per-user data), use env.GOOGLE_API_KEY.
// NOTE: /reverse-geocode needs the Geocoding API enabled on that key.
// ============================================================================
async function handleReverseGeocode(request, env) {
  let body;
  try { body = await request.json(); } catch (_e) { return jsonResponse({ error: 'Invalid JSON body' }, 400); }
  const { latitude, longitude } = body || {};
  if (latitude == null || longitude == null) {
    return jsonResponse({ error: 'Latitude and longitude are required' }, 400);
  }

  // Transient performance cache (ToS-safe BRIDGE, ~30d). A coarse ~0.1° (~11km)
  // tile's city/state/country basically never changes, so caching it slashes
  // repeat Google Geocoding calls (and speeds every location naming in the app).
  // NOT a permanent copy of Google data — only coarse ADMIN fields are cached
  // (never the precise street formatted_address), for a bounded TTL. Retires
  // entirely once we reverse-geocode from our own OSM/Overture data.
  // `precise: true` (2026-10-11) is the border-crossing check: a ~110 m tile,
  // so a tile straddling a state line can't name the wrong state — used only
  // when a crossing is suspected, so it costs a call or two per crossing.
  const step = body?.precise === true ? 1000 : 10;
  const rLat = Math.round(Number(latitude) * step) / step;
  const rLng = Math.round(Number(longitude) * step) / step;
  const revKey = `${step === 1000 ? 'revgeoP_' : 'revgeo_'}${rLat}_${rLng}`;
  const REVGEO_TTL_SECONDS = 30 * 24 * 60 * 60;
  const canCache = env.GLOBESKIMMERS_KV && Number.isFinite(rLat) && Number.isFinite(rLng);
  if (canCache) {
    const hit = await env.GLOBESKIMMERS_KV.get(revKey, { type: 'json' }).catch(() => null);
    // A UK tile cached before `region` existed can't name its nation: fetch again.
    if (hit && hit.country != null && !(hit.region === undefined && hit.country === 'United Kingdom')) {
      const formatted_address = [hit.city, hit.state_or_country].filter(Boolean).join(', ');
      return jsonResponse({ ...hit, latitude, longitude, formatted_address, cached: true });
    }
  }

  const apiKey = env.GOOGLE_API_KEY;
  if (!apiKey) return jsonResponse({ error: 'Google API key not configured' }, 500);
  try {
    const url = `https://maps.googleapis.com/maps/api/geocode/json?latlng=${latitude},${longitude}&key=${apiKey}`;
    const response = await fetch(url);
    if (!response.ok) return jsonResponse({ error: 'Geocoding API request failed', details: await response.text() }, 502);
    const data = await response.json();
    if (data.status !== 'OK' || !data.results?.length) {
      return jsonResponse({ error: 'Geocoding error', details: data.status }, 502);
    }
    const result = data.results[0];
    const comps = result.address_components || [];
    const cityComponent = comps.find(c =>
      c.types.includes('locality') || c.types.includes('sublocality') ||
      c.types.includes('postal_town') || c.types.includes('administrative_area_level_3') ||
      c.types.includes('administrative_area_level_2'));
    const stateComponent = comps.find(c => c.types.includes('administrative_area_level_1'));
    const countryComponent = comps.find(c => c.types.includes('country'));
    const city = cityComponent?.long_name || '';
    const country = countryComponent?.long_name || '';
    const stateOrCountry = (countryComponent?.short_name === 'US' || countryComponent?.short_name === 'CA')
      ? (stateComponent?.long_name || country) : country;
    // The first-level region for every country (England / Scotland / Wales /
    // Northern Ireland in the UK) — what the crossing prompts compare.
    const region = stateComponent?.long_name || '';

    // Cache only the coarse admin fields (~30d). The precise street
    // formatted_address is returned fresh but NOT cached (not coarse-safe).
    if (canCache) {
      await env.GLOBESKIMMERS_KV.put(revKey, JSON.stringify({ city, state_or_country: stateOrCountry, country, region }), { expirationTtl: REVGEO_TTL_SECONDS }).catch(() => {});
    }

    return jsonResponse({ city, state_or_country: stateOrCountry, country, region, latitude, longitude, formatted_address: result.formatted_address });
  } catch (e) {
    return jsonResponse({ error: 'Internal server error', details: e.message }, 500);
  }
}

function haversineMilesLoc(lat1, lon1, lat2, lon2) {
  const R = 3959, toRad = (d) => d * Math.PI / 180;
  const dLat = toRad(lat2 - lat1), dLon = toRad(lon2 - lon1);
  const a = Math.sin(dLat / 2) ** 2 + Math.cos(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.sin(dLon / 2) ** 2;
  return R * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
}

// Largest administrative unit /search-location still treats as a destination
// (viewport half-diagonal, miles). Measured live 2026-09-08: Hong Kong ≤60,
// Da Nang 67, Tuscany 103, Tokyo 105 (its viewport spans the Izu islands),
// Lapland 207, Hawaii 236, Maldives 321, Vietnam 581. 110 admits every
// province-level CITY seen so far; region-sized units that slip under it
// (Tuscany) are handled by the composer's curated city chips, and a US
// state or a country stays broad. The `location` Google returns for an
// admitted unit is its main-city point, not the viewport centroid.
const SEARCH_REGION_MAX_HALF_DIAG_MI = 110;
// Google omits `types` on some address components (Bali's, live 2026-09-08)
// — a bare `.types.includes` threw and turned the whole search into an
// error. Every component lookup goes through this.
const hasType = (x, t) => Array.isArray(x?.types) && x.types.includes(t);

async function handleSearchLocation(request, env) {
  let body;
  try { body = await request.json(); } catch (_e) { return jsonResponse({ error: 'Invalid request', results: [] }, 200); }
  const query = body?.query;
  if (!query || typeof query !== 'string') {
    return jsonResponse({ error: 'Query required', message: 'Please enter a search term', results: [] }, 200);
  }
  const apiKey = env.GOOGLE_API_KEY;
  if (!apiKey) return jsonResponse({ error: 'Service unavailable', results: [] }, 200);

  const isHotelSearch = /hotel|lodging|accommodation/i.test(query);
  const requestBody = { textQuery: query, ...(isHotelSearch && { includedType: 'lodging', rankPreference: 'RELEVANCE' }) };

  let response;
  // One retry on a rate limit or a Google server error (2026-10-07: about one
  // lookup in three failed during a busy minute, leaving search un-centered).
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      response = await fetch('https://places.googleapis.com/v1/places:searchText', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'X-Goog-Api-Key': apiKey,
          'X-Goog-FieldMask': 'places.id,places.displayName,places.formattedAddress,places.location,places.viewport,places.addressComponents,places.types,places.primaryType',
        },
        body: JSON.stringify(requestBody),
      });
    } catch (_e) { if (attempt) return jsonResponse({ error: 'Network error', results: [] }, 200); continue; }
    if (response.ok || !(response.status === 429 || response.status >= 500)) break;
    if (!attempt) await new Promise((r) => setTimeout(r, 400));
  }
  if (!response?.ok) {
    const detail = response ? await response.text().catch(() => '') : '';
    console.warn(`search-location: Google ${response?.status} ${detail.slice(0, 200)}`);
    return jsonResponse({ error: 'Location search unavailable', status: response?.status || null, results: [] }, 200);
  }

  let data;
  try { data = await response.json(); } catch (_e) { return jsonResponse({ error: 'Invalid response', results: [] }, 200); }
  if (data.error) return jsonResponse({ error: `Google API Error: ${data.error.message || data.error.status}`, results: [] }, 200);
  if (!data.places?.length) {
    return jsonResponse({ results: [], message: isHotelSearch ? 'No hotels found. Try a specific hotel name or area.' : 'No locations found. Try a different search term.' }, 200);
  }

  const results = [];
  let rejectedTooBroadCount = 0;
  const tooBroad = [];
  for (const place of data.places.slice(0, 8)) {
    const types = place.types || [];
    const primaryType = place.primaryType || '';
    const hasSpecificType = types.some(t => ['street_address','premise','point_of_interest','establishment','airport','train_station','transit_station','bus_station','subway_station','tourist_attraction','lodging','restaurant','park','shopping_mall','store','museum','stadium','university','school','cafe'].includes(t))
      || ['airport','lodging','tourist_attraction','shopping_mall','store','restaurant','train_station','museum','park'].includes(primaryType);
    const isStreetAddress = types.includes('street_address') || types.includes('premise');
    // Italian comuni and other European municipalities (Naples, Florence) come
    // back typed administrative_area_level_3/4, never locality.
    const isCity = types.includes('locality') || types.includes('sublocality') || types.includes('postal_town')
      || types.includes('administrative_area_level_3') || types.includes('administrative_area_level_4');
    const isState = types.includes('administrative_area_level_1') && !isCity;
    const isCountry = types.includes('country') && !types.includes('administrative_area_level_1') && !isCity;
    let granularity;
    if (isStreetAddress) granularity = 'address';
    else if (hasSpecificType) granularity = 'place';
    else if (isCity) granularity = 'city';
    else if (isState) granularity = 'state';
    else if (isCountry) granularity = 'country';
    else granularity = 'place';
    // Viewport half-diagonal: how big this place is on the ground.
    let halfDiagMi = null;
    {
      const vp = place.viewport;
      if (vp?.high?.latitude != null && vp?.low?.latitude != null) {
        halfDiagMi = haversineMilesLoc(vp.high.latitude, vp.high.longitude, vp.low.latitude, vp.low.longitude) / 2;
      }
    }
    // City-sized administrative units — Da Nang, Tokyo, Bali, Hong Kong —
    // come back typed administrative_area_level_1 or country, never
    // locality, yet they are destinations, not "too broad". Keep any whose
    // footprint is at most SEARCH_REGION_MAX_HALF_DIAG_MI across as a
    // 'region'. Genuinely broad places (a country, a US state) are still
    // rejected, but reported in `tooBroad` so the caller can offer their
    // cities instead of dead-ending on a disabled button.
    if (granularity === 'state' || granularity === 'country') {
      if (halfDiagMi != null && halfDiagMi <= SEARCH_REGION_MAX_HALF_DIAG_MI) {
        granularity = 'region';
      } else {
        rejectedTooBroadCount++;
        const cc = (place.addressComponents || []).find(x => hasType(x,'country'));
        tooBroad.push({
          name: place.displayName?.text || '',
          kind: granularity,
          country: cc?.longText || '',
          halfDiagMi: halfDiagMi == null ? null : Math.round(halfDiagMi),
        });
        continue;
      }
    }

    const c = place.addressComponents || [];
    const streetNumber = c.find(x => hasType(x,'street_number'))?.longText || '';
    const route = c.find(x => hasType(x,'route'))?.longText || '';
    const street = streetNumber && route ? `${streetNumber} ${route}` : route || streetNumber;
    const city = c.find(x => hasType(x,'locality'))?.longText || c.find(x => hasType(x,'sublocality'))?.longText || c.find(x => hasType(x,'postal_town'))?.longText || '';
    const state = c.find(x => hasType(x,'administrative_area_level_1'))?.shortText || '';
    const region = c.find(x => hasType(x,'administrative_area_level_2'))?.longText || '';
    const postalCode = c.find(x => hasType(x,'postal_code'))?.longText || '';
    const countryComp = c.find(x => hasType(x,'country'));
    const country = countryComp?.longText || '';
    const stateOrCountry = (countryComp?.shortText === 'US' || countryComp?.shortText === 'CA') ? (state || country) : country;

    let placeType = 'location';
    if (types.includes('airport') || primaryType === 'airport') placeType = 'airport';
    else if (types.includes('lodging') || primaryType === 'lodging') placeType = 'hotel';
    else if (types.includes('restaurant') || primaryType === 'restaurant') placeType = 'restaurant';
    else if (types.includes('shopping_mall') || types.includes('store') || primaryType === 'shopping_mall') placeType = 'shopping';
    else if (types.includes('tourist_attraction') || types.includes('museum') || primaryType === 'tourist_attraction') placeType = 'attraction';
    else if (types.includes('park') || primaryType === 'park') placeType = 'park';
    else if (types.includes('transit_station') || types.includes('train_station') || types.includes('bus_station') || primaryType === 'train_station') placeType = 'transit';

    let suggestedRadius = null;
    if (granularity === 'city' || granularity === 'region') {
      suggestedRadius = halfDiagMi != null ? Math.max(5, Math.min(25, Math.round(halfDiagMi))) : 15;
    }

    results.push({
      placeId: place.id,
      placeName: place.displayName?.text || '',
      granularity,
      suggestedRadius,
      address: { formatted: place.formattedAddress || '', street, city, region, state, postalCode, country, countryCode: countryComp?.shortText || '' },
      coordinates: { latitude: place.location?.latitude || 0, longitude: place.location?.longitude || 0 },
      placeType,
      types,
      city: place.displayName?.text || city,
      state_or_country: stateOrCountry,
      latitude: place.location?.latitude || 0,
      longitude: place.location?.longitude || 0,
      full_name: place.formattedAddress || '',
    });
  }

  // Search only (touristCenter): a city that shares its state's name — Oaxaca,
  // Puebla, Guanajuato — comes back as just the state. Retry once as "<name> city".
  if (results.length === 0 && rejectedTooBroadCount > 0 && body?.touristCenter && !body.cityRetry && !/\bcity\b/i.test(query)) {
    return handleSearchLocation(new Request(request.url, { method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ ...body, query: `${query} city`, cityRetry: true }) }), env);
  }
  if (results.length === 0) {
    const message = rejectedTooBroadCount > 0
      ? "That's too broad — please add a city (e.g. \"Paris, France\") or pick a specific address or landmark."
      : 'No locations found. Try a different search term.';
    return jsonResponse({ results: [], message, tooBroad }, 200);
  }
  // Tourist center (Round 2, 2026-10-07): when SEARCH looks up a city, center
  // it where the city's most famous landmarks cluster — not its geographic
  // middle ("Tokyo" sat in suburban Suginami; Singapore in Toa Payoh; NYC at
  // City Hall). Opt-in via touristCenter, so the location picker is unchanged.
  if (body?.touristCenter && results[0] && (results[0].granularity === 'city' || results[0].granularity === 'region')) {
    try {
      const r0 = results[0];
      const tc = await gsTouristCenter(env, r0.coordinates.latitude, r0.coordinates.longitude, r0.address?.countryCode, r0.address?.country);
      if (tc) {
        r0.geoCenter = { ...r0.coordinates };
        r0.coordinates = { latitude: tc.lat, longitude: tc.lng };
        r0.latitude = tc.lat; r0.longitude = tc.lng;
        r0.touristCenter = tc;
      }
    } catch { /* the geographic center stands */ }
  }
  return jsonResponse({ results }, 200);
}

// The median point of the 15 most famous stampable landmarks within ~25 km —
// the owned attractions DB already knows where visitors go. Null below 5.
// Same country only: Tijuana's center otherwise drifted to the San Diego Zoo.
// The attractions table mixes ISO codes and full names, so both are matched.
async function gsTouristCenter(env, lat, lng, countryCode = '', countryName = '') {
  if (!env.ATTRACTIONS_DB || !Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  const dLat = 0.22, dLng = 0.22 / Math.max(0.2, Math.cos(lat * Math.PI / 180));
  const { results: rows } = await env.ATTRACTIONS_DB.prepare(
    `SELECT lat, lng, name FROM attractions
      WHERE lat BETWEEN ?1 AND ?2 AND lng BETWEEN ?3 AND ?4
        AND coalesce(founder_scope, scope) IN ('world','national')
        AND (class_ban IS NULL OR class_ban = '' OR class_ban LIKE 'review:%')
        AND (?5 = '' OR country IS NULL OR country = '' OR country IN (?5, ?6))
      ORDER BY (popularity IS NULL) ASC, popularity DESC, sitelinks DESC LIMIT 15`
  ).bind(lat - dLat, lat + dLat, lng - dLng, lng + dLng, String(countryCode || ''), String(countryName || '')).all();
  if (!rows || rows.length < 5) return null;
  const med = (xs) => { const s = [...xs].sort((a, b) => a - b); const m = s.length >> 1; return s.length % 2 ? s[m] : (s[m - 1] + s[m]) / 2; };
  return { lat: med(rows.map((r) => r.lat)), lng: med(rows.map((r) => r.lng)), landmarks: rows.slice(0, 5).map((r) => r.name) };
}

// ─────────────────────────────────────────────────────────────────────
// Phase B helpers — auto-seed for non-launch cities
// ─────────────────────────────────────────────────────────────────────
// When a user visits a city not in the Phase A curated launch seed,
// /attractions/nearby returns empty, the Base44 backend falls back to
// the slow Places-based discovery path, AND in the background the
// Worker fires off a one-time seed task. The next visitor to that
// same city gets the fast D1 path automatically — the app self-seeds.

// Google Places type -> our D1 category enum. Any returned types not
// in this map cause the place to be REJECTED (we don't want
// restaurants, hotels, gas stations, etc. polluting the static
// attractions DB).
const PLACES_TYPE_TO_CATEGORY = {
  tourist_attraction:   'landmark',
  museum:               'museum',
  art_gallery:          'art_gallery',
  park:                 'park',
  national_park:        'national_park',
  amusement_park:       'theme_park',
  water_park:           'theme_park',
  zoo:                  'zoo',
  aquarium:             'aquarium',
  natural_feature:      'viewpoint',
  beach:                'beach',
  historical_landmark:  'historic',
  monument:             'monument',
  church:               'religious',
  mosque:               'mosque',
  hindu_temple:         'temple',
  synagogue:            'religious',
  place_of_worship:     'religious',
  garden:               'garden',
  observation_deck:     'observation_deck',
  fortress:             'fortress',
  castle:               'palace',
  shrine:               'shrine',
};

// Places types we explicitly do NOT want — these have to fall fully
// outside the staple categories or get filtered out even when they
// also carry a usable type. Belt-and-suspenders against Places
// returning a museum that's "also" a cafe.
const PLACES_REJECT_TYPES = new Set([
  'restaurant','food','cafe','bar','night_club','bakery',
  'lodging','hotel','rv_park',
  'shopping_mall','store','clothing_store','grocery_store','supermarket',
  'gas_station','parking','car_rental','car_dealer','car_repair',
  'bank','atm','accounting','insurance_agency','real_estate_agency',
  'hospital','doctor','dentist','pharmacy','health',
  'school','university','library','primary_school','secondary_school',
  'gym','beauty_salon','hair_care','spa',
  'post_office','police','courthouse','embassy',
  'movie_theater','bowling_alley','casino','liquor_store',
  'taxi_stand','transit_station','airport','bus_station','subway_station',
]);

// Slug helper for auto-seeded ids. Mirrors emit_d1_seed.py's logic so
// curated and auto-seeded entries share the same id format.
function autoSeedSlug(name, country, city) {
  const parts = [country.toLowerCase().replace(/\s+/g, '-')];
  if (city) parts.push(city.toLowerCase().replace(/\s+/g, '-'));
  parts.push(
    name.toLowerCase()
        .replace(/[^a-z0-9]+/g, '-')
        .replace(/-+/g, '-')
        .replace(/^-|-$/g, '')
        .slice(0, 80)
  );
  return 'auto:' + parts.join('-');
}

// Pick the best D1 category for a Place. Walks `types` in order, takes
// the first hit on PLACES_TYPE_TO_CATEGORY, and rejects (returns null)
// if any reject type is present.
function categorizePlace(place) {
  const types = place.types || [];
  if (types.some((t) => PLACES_REJECT_TYPES.has(t))) return null;
  for (const t of types) {
    if (PLACES_TYPE_TO_CATEGORY[t]) return PLACES_TYPE_TO_CATEGORY[t];
  }
  // No staple-type match — reject. We only seed places we can confidently
  // categorize, not generic POIs.
  return null;
}

// Auto-marquee: a place qualifies as marquee when it's strongly rated
// AND broadly reviewed. Tuned conservatively so the auto-seed doesn't
// flood the marquee tier with random parks that happen to have
// 5-star ratings from 50 reviewers.
function isAutoMarquee(place) {
  const rating = place.rating || 0;
  const count = place.userRatingCount || 0;
  return rating >= 4.5 && count >= 1500;
}

// Determine free_to_visit from category. Conservative — only flag
// categories where the answer is almost always yes (parks, viewpoints,
// public plazas). Museums / theme parks / observation decks default
// to false even though some are free; the live Places hit at detail-
// tap time corrects this when needed.
const FREE_CATEGORIES = new Set([
  'park','national_park','viewpoint','beach','waterfall',
  'nature_reserve','garden','river','lake','square','district',
]);

// Quality filter — only seed places that meet the bar. Returns true if
// the place is worth saving.
function passesSeedQuality(place) {
  if (!place.displayName?.text && !place.name) return false;
  if (!place.location?.latitude || !place.location?.longitude) return false;
  if ((place.rating || 0) < 4.0) return false;
  if ((place.userRatingCount || 0) < 100) return false;
  return true;
}

// Build the D1 row record from a Google Places result.
function placeToAttractionRow(place, city, country) {
  const cat = categorizePlace(place);
  if (!cat) return null;
  if (!passesSeedQuality(place)) return null;

  const name = (place.displayName?.text || place.name || '').trim();
  const lat = place.location.latitude;
  const lng = place.location.longitude;
  const desc = (place.editorialSummary?.text || place.editorialSummary || '').toString().trim();
  const marquee = isAutoMarquee(place);
  const freeToVisit = FREE_CATEGORIES.has(cat);

  // Typical visit duration heuristic by category — same buckets the
  // curators used for the hand-seeded launch set, just programmatic
  // instead of human-judged.
  const minutesByCategory = {
    museum: 120, art_gallery: 90, theme_park: 240, water_park: 240,
    zoo: 180, aquarium: 90, national_park: 240, park: 60,
    viewpoint: 30, beach: 120, waterfall: 60, garden: 60,
    landmark: 60, monument: 30, historic: 60,
    religious: 45, mosque: 45, temple: 45, shrine: 45,
    cathedral: 60, palace: 90, tower: 60, observation_deck: 60,
    fortress: 90, district: 90, square: 30, market: 90,
    nature_reserve: 180, river: 45, lake: 60, wildlife: 180,
    experience: 120,
  };

  return {
    id: autoSeedSlug(name, country, city),
    name,
    category: cat,
    lat,
    lng,
    city: city || '',
    country,
    description: desc,
    why_visit: '',  // empty — only the human-curated launch set has why_visit
    typical_minutes: minutesByCategory[cat] || 60,
    rating: place.rating || null,
    is_marquee: marquee ? 1 : 0,
    free_to_visit: freeToVisit ? 1 : 0,
  };
}

// One round of seed queries for a region. Hits the Worker's own
// /places/text-search via internal request (which uses the existing
// GLOBESKIMMERS_KV cache, so repeat runs are free).
const SEED_QUERY_TEMPLATES = [
  'top tourist attractions in {region}',
  'famous landmarks in {region}',
  'must see places in {region}',
  'museums in {region}',
  'parks in {region}',
  'historic sites in {region}',
  'temples in {region}',
  'monuments in {region}',
];

async function runSeedDiscovery(env, city, country, lat, lng) {
  const region = city || country;
  const tasks = SEED_QUERY_TEMPLATES.map(async (tpl) => {
    const query = tpl.replace('{region}', region);
    const url = new URL('https://internal/places/text-search');
    url.searchParams.set('query', query);
    url.searchParams.set('latitude', String(lat));
    url.searchParams.set('longitude', String(lng));
    url.searchParams.set('radius', '40000'); // 40km — covers a major city
    url.searchParams.set('maxResults', '15');
    url.searchParams.set('cacheTtl', String(60 * 60 * 24 * 7)); // 7-day TTL
    try {
      const res = await handleTextSearch(new Request(url), env);
      if (!res.ok) return [];
      const data = await res.json();
      return data.places || [];
    } catch {
      return [];
    }
  });
  const batches = await Promise.all(tasks);
  // Dedupe by place id
  const byId = new Map();
  for (const batch of batches) {
    for (const p of batch) {
      if (p.id) byId.set(p.id, p);
    }
  }
  return [...byId.values()];
}

// Returns true if this region was attempted recently and we should
// skip a fresh seed run. Conservative 24h throttle window.
async function wasSeededRecently(env, regionKey) {
  if (!env.ATTRACTIONS_DB) return true; // no DB → can't throttle, assume yes (skip)
  try {
    const stmt = env.ATTRACTIONS_DB
      .prepare("SELECT attempted_at FROM seed_attempts WHERE region_key = ?");
    const row = await stmt.bind(regionKey).first();
    if (!row) return false;
    const last = new Date(row.attempted_at).getTime();
    return Date.now() - last < 24 * 3600 * 1000;
  } catch {
    return true; // err on the side of "skip" so a broken throttle doesn't loop-seed
  }
}

// Run the actual seed for a region. Discovery + categorize + filter +
// INSERT OR IGNORE + record attempt. Designed to run inside
// ctx.waitUntil() so it doesn't block the user response.
async function seedCityNow(env, lat, lng, cityName, countryName) {
  if (!env.ATTRACTIONS_DB) return;
  const city = (cityName || '').trim();
  const country = (countryName || '').trim();
  if (!country) return;

  const regionKey = `${city.toLowerCase()}::${country.toLowerCase()}`;

  if (await wasSeededRecently(env, regionKey)) return;

  let foundCount = 0;
  let insertedCount = 0;
  let status = 'ok';
  let notes = '';

  try {
    const places = await runSeedDiscovery(env, city, country, lat, lng);
    foundCount = places.length;

    const rows = [];
    for (const p of places) {
      const row = placeToAttractionRow(p, city, country);
      if (row) rows.push(row);
    }

    if (rows.length > 0) {
      // Bulk INSERT OR IGNORE. SQLite supports multi-row VALUES but D1's
      // statement size limit is generous (~1MB) — fits hundreds of rows
      // easily, but we batch in groups of 50 to keep query plans
      // predictable and avoid hitting any per-statement quirks.
      const insertSql = `
        INSERT OR IGNORE INTO attractions
          (id, name, category, lat, lng, city, country, description,
           why_visit, typical_minutes, rating, is_marquee, free_to_visit,
           source, last_reviewed)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'auto-seeded', date('now'))
      `;
      for (const r of rows) {
        try {
          const result = await env.ATTRACTIONS_DB
            .prepare(insertSql)
            .bind(r.id, r.name, r.category, r.lat, r.lng, r.city, r.country,
                  r.description, r.why_visit, r.typical_minutes, r.rating,
                  r.is_marquee, r.free_to_visit)
            .run();
          // D1's run() returns { meta: { changes: 0|1 } } — 0 means the
          // OR IGNORE took (row already existed).
          if (result?.meta?.changes > 0) insertedCount += 1;
        } catch (e) {
          notes = (e?.message || 'insert failed').slice(0, 500);
        }
      }
    } else {
      notes = 'no_quality_matches';
    }
  } catch (e) {
    status = 'error';
    notes = (e?.message || 'discovery failed').slice(0, 500);
  }

  // Record the attempt regardless of outcome (so the throttle works
  // even when discovery returned nothing).
  try {
    await env.ATTRACTIONS_DB.prepare(`
      INSERT OR REPLACE INTO seed_attempts
        (region_key, city, country, trigger_lat, trigger_lng,
         attempted_at, found_count, inserted_count, status, notes)
      VALUES (?, ?, ?, ?, ?, datetime('now'), ?, ?, ?, ?)
    `).bind(
      regionKey, city, country, lat, lng,
      foundCount, insertedCount, status, notes
    ).run();
  } catch (e) {
    console.error('seed_attempts insert failed:', e?.message);
  }

  console.log(`🌱 seed-city: ${city || '(no city)'}, ${country} → found=${foundCount}, inserted=${insertedCount}, status=${status}${notes ? ', notes=' + notes : ''}`);
}

// HTTP endpoint version. Lets you trigger a seed manually for testing:
//   curl -X POST .../attractions/seed-city -d '{...}'
// In production, this is mostly invoked indirectly via ctx.waitUntil
// from handleAttractionsNearby when D1 returns sparse.
async function handleSeedCity(request, env) {
  if (!env.ATTRACTIONS_DB) {
    return jsonResponse({ ok: false, reason: 'ATTRACTIONS_DB binding not present' }, 200);
  }
  let body;
  try { body = await request.json(); }
  catch { return jsonResponse({ error: 'Invalid JSON' }, 400); }
  const { latitude, longitude, cityName, countryName } = body || {};
  if (typeof latitude !== 'number' || typeof longitude !== 'number') {
    return jsonResponse({ error: 'latitude and longitude required' }, 400);
  }
  if (!countryName || !String(countryName).trim()) {
    return jsonResponse({ error: 'countryName required' }, 400);
  }
  // Synchronous when called as an HTTP endpoint so you can see the
  // result. When called via waitUntil from handleAttractionsNearby it
  // already runs asynchronously without blocking the response.
  await seedCityNow(env, latitude, longitude, cityName || '', countryName);
  return jsonResponse({ ok: true });
}

// ─────────────────────────────────────────────────────────────────────
// /attractions/nearby — D1 attractions seed lookup
// ─────────────────────────────────────────────────────────────────────
// Reads the static attractions D1 database (table `attractions`) and
// returns nearby marquee + regional icons in a single round-trip.
// Replaces ~70 sequential Places calls with one SQL query, cutting
// ThingsToDo mobile cold-load from 30s → ~500ms.
//
// See cloudflare-worker/handlers/handleAttractionsNearby.js for the
// reference design + full doc comment. This in-file copy is the
// version the deployed Worker actually loads.
//
// Phase B: when ctx is passed in AND the D1 query returns sparse
// results (<5) AND the request body includes cityName + countryName,
// schedules a background seed-city task via ctx.waitUntil so the next
// visitor to this region gets the fast D1 path automatically. The
// background task is rate-limited via the seed_attempts table (1
// attempt per region per 24h).
// ── Dream shelf (founder, 2026-10-08) ─────────────────────────────────────────
// Visitors come to "Los Angeles", not to Arcadia or Santa Clarita: a region's
// famous places are spread out (Disneyland in Anaheim, Six Flags in Valencia,
// the Hollywood Sign, Griffith) and belong on every shelf in that region.
// POST /dream/shelf { latitude, longitude } →
//   { metro: { name, lat, lng }, tiers: [{ key, title, items }] }
//   icons   — world/national stamps within 90 km of the REGION's center
//   local   — regional stamps there, titled "Customer favorites" (founder, 2026-10-12)
//   daytrip — world (and the most famous national) stamps 90–300 km out
// The region's center is the median point of the most famous stamps within
// 60 km of the traveler, so every suburb lands on the same center; with fewer
// than 5 famous places nearby it is the traveler's own spot.
const DREAM_REGION_KM = 90, DREAM_DAYTRIP_KM = 250;
// Event venues (stadiums, arenas, concert halls) are for the events lane, not
// the shelf of places to see; the Hollywood Bowl-type icons stay via founder_scope.
const DREAM_VENUE = /\b(stadium|arena|forum|auditorium|speedway|raceway|ballpark|cinema|cinemark|amc|regal|pavilion|coliseum|field)\b/i;
async function handleDreamShelf(request, env) {
  if (!env.ATTRACTIONS_DB) return jsonResponse({ metro: null, tiers: [] });
  const b = await request.json().catch(() => ({}));
  const lat = Number(b.latitude), lng = Number(b.longitude);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return jsonResponse({ error: 'latitude and longitude required' }, 400);
  const LIVE = "(class_ban IS NULL OR class_ban = '' OR class_ban LIKE 'review:%') AND (tier IS NULL OR tier != 'secret')";
  const box = (cLat, cLng, km) => { const dLat = km / 111, dLng = km / (111 * Math.max(0.2, Math.cos(cLat * Math.PI / 180))); return [cLat - dLat, cLat + dLat, cLng - dLng, cLng + dLng]; };
  try {
    const near = (await env.ATTRACTIONS_DB.prepare(
      `SELECT lat, lng, city FROM attractions WHERE lat BETWEEN ?1 AND ?2 AND lng BETWEEN ?3 AND ?4 AND ${LIVE}
         AND coalesce(founder_scope, scope) IN ('world','national')
       ORDER BY is_marquee DESC, (popularity IS NULL) ASC, popularity DESC LIMIT 25`
    ).bind(...box(lat, lng, 60)).all()).results || [];
    const med = (xs) => { const v = [...xs].sort((a, c) => a - c); const m = v.length >> 1; return v.length % 2 ? v[m] : (v[m - 1] + v[m]) / 2; };
    const cLat = near.length >= 5 ? med(near.map((r) => r.lat)) : lat;
    const cLng = near.length >= 5 ? med(near.map((r) => r.lng)) : lng;
    const rows = (await env.ATTRACTIONS_DB.prepare(
      `SELECT * FROM attractions WHERE lat BETWEEN ?1 AND ?2 AND lng BETWEEN ?3 AND ?4 AND ${LIVE}
         AND coalesce(founder_scope, scope) IN ('world','national','regional')
       ORDER BY (popularity IS NULL) ASC, popularity DESC, sitelinks DESC LIMIT 800`
    ).bind(...box(cLat, cLng, DREAM_DAYTRIP_KM)).all()).results || [];
    const seen = new Set();
    const items = [];
    for (const r of rows) {
      if (DREAM_VENUE.test(r.name) && !r.founder_scope) continue;
      const key = r.qid || `${String(r.name).toLowerCase()}|${Math.round(r.lat * 200)}|${Math.round(r.lng * 200)}`;
      if (seen.has(key)) continue; // a place listed twice shows once
      seen.add(key);
      const fromCenter = calcDistance(cLat, cLng, r.lat, r.lng);
      const fromYou = calcDistance(lat, lng, r.lat, r.lng);
      items.push({
        id: r.id, name: r.name, category: r.category, lat: r.lat, lng: r.lng, city: r.city || '', country: r.country,
        photoUrl: r.photo_url || null, isMarquee: r.is_marquee === 1, popularity: r.popularity ?? null,
        footprint_radius_m: r.footprint_radius_m ?? null, parentId: r.parent_id || null, tier: r.tier || 'page', qid: r.qid || null,
        scope: r.founder_scope || r.scope, fromCenterKm: fromCenter, distanceKm: fromYou, distanceMiles: fromYou * 0.621371,
      });
    }
    const inRegion = (x) => x.fromCenterKm <= DREAM_REGION_KM;
    const icons = items.filter((x) => inRegion(x) && (x.scope === 'world' || x.scope === 'national')).slice(0, 30);
    const local = items.filter((x) => inRegion(x) && x.scope === 'regional').slice(0, 30);
    const daytrip = items.filter((x) => !inRegion(x) && x.fromCenterKm <= DREAM_DAYTRIP_KM && (x.scope === 'world' || (x.scope === 'national' && (x.popularity ?? 0) >= 1000000))).slice(0, 20);
    // The region's name: the city most of its icons sit in ("Los Angeles, CA" → "Los Angeles").
    const counts = {};
    for (const x of icons.slice(0, 15)) { const c = String(x.city || '').split(',')[0].trim(); if (c) counts[c] = (counts[c] || 0) + 1; }
    const metroName = Object.entries(counts).sort((a, c) => c[1] - a[1])[0]?.[0] || String(b.cityName || '').trim() || null;
    return jsonResponse({
      metro: { name: metroName, lat: cLat, lng: cLng },
      tiers: [
        { key: 'icons', title: metroName ? `Icons of ${metroName}` : 'Icons nearby', items: icons },
        // "Customer favorites" (founder, 2026-10-12): "Local favorite" now names
        // the crowd-sourced stamp from Suggest a Place, so this row of official
        // regional stamps took a name of its own.
        { key: 'local', title: 'Customer favorites', items: local },
        { key: 'daytrip', title: 'Worth a day trip', items: daytrip },
      ].filter((t) => t.items.length),
    });
  } catch (e) { return jsonResponse({ metro: null, tiers: [], error: e.message }); }
}

async function handleAttractionsNearby(request, env, ctx) {
  const startedAt = Date.now();

  // Tolerate missing binding so the Base44 backend can roll out a
  // call to this endpoint BEFORE D1 is provisioned. Returns empty
  // payload, not an error, so the existing Places-based path takes over.
  if (!env.ATTRACTIONS_DB) {
    return jsonResponse({
      source: 'd1',
      attractions: [],
      tookMs: Date.now() - startedAt,
      note: 'ATTRACTIONS_DB binding not present — falling back to Places',
    });
  }

  let body;
  try { body = await request.json(); }
  catch { return jsonResponse({ error: 'Invalid JSON body' }, 400); }

  const {
    latitude,
    longitude,
    radiusKm = 80,
    categories = null,
    limit = 60,
    marqueeOnly = false,
    // Stamps rail only: return rows that cleared the stamp-worthiness bar
    // (scope world/national/regional; founder_scope always wins). Unscored
    // rows (scope NULL — fresh auto-seeds) are NOT stamps until scored, which
    // is the gate that keeps neighborhood parks out of the passport. Secrets
    // (tier='secret') are founder-designated and pass regardless.
    stampsOnly = false,
    // Passport proximity path only: include tier='secret' rows (inside their
    // rotation window). General browse never sees secrets — they're found by
    // being there.
    includeSecrets = false,
    // Phase B: client passes these so the Worker can trigger a
    // background seed when D1 returns sparse coverage. Empty strings
    // are tolerated (and skip seeding) for fresh-GPS lookups before
    // reverse-geocode has resolved.
    cityName = '',
    countryName = '',
  } = body || {};

  if (typeof latitude !== 'number' || typeof longitude !== 'number') {
    return jsonResponse({ error: 'latitude and longitude required' }, 400);
  }

  // Opt-in (body.includeCityTemp === true): current temp at the searched
  // coords, °F — the DreamShelf data line. $0 via destTempsF's 3h-KV
  // Open-Meteo path; started here so it runs concurrently with the D1 query.
  // Opt-in keeps the hot ThingsToDo cold-load path (and the internal
  // /attractions/nearby self-calls in home-rows assembly) round-trip-free.
  const cityTempPromise = body.includeCityTemp === true
    ? destTempsF(env, [[latitude, longitude]]).then((t) => t[0] ?? null).catch(() => null)
    : Promise.resolve(null);

  // Bounding box prefilter. 1° lat ≈ 111 km; longitude width shrinks
  // toward the poles by cos(lat). The box is a CHEAP indexed query
  // (uses the indexed lat/lng columns); we re-rank by true great-circle
  // distance after the rows come back. Slightly larger box than the
  // requested radius lets the haversine pass do the precise circle clip
  // without missing edge cases.
  const latDelta = (radiusKm * 1.05) / 111;
  const lngDelta = (radiusKm * 1.05) / (111 * Math.cos(latitude * Math.PI / 180) || 1);
  const minLat = latitude - latDelta;
  const maxLat = latitude + latDelta;
  const minLng = longitude - lngDelta;
  const maxLng = longitude + lngDelta;

  // Rows the fame scorer banned (wrong class: airports, prisons, …), rows a
  // dedup pass demoted (class_ban='duplicate' — an icon/founder row with the
  // same qid survives), and wrong city matches never browse. review:* rows are
  // legit places awaiting a founder verdict — they stay browsable (the stamp
  // bar already excludes them until scored).
  const wheres = ['lat BETWEEN ? AND ?', 'lng BETWEEN ? AND ?',
    "(class_ban IS NULL OR class_ban = '' OR class_ban LIKE 'review:%')"];
  const params = [minLat, maxLat, minLng, maxLng];

  if (Array.isArray(categories) && categories.length > 0) {
    const placeholders = categories.map(() => '?').join(',');
    wheres.push(`category IN (${placeholders})`);
    params.push(...categories);
  }

  if (marqueeOnly === true) {
    wheres.push('is_marquee = 1');
  }
  // Secret stamps (tier='secret') are hidden from general browse. Only the
  // passport proximity path asks for them (includeSecrets), and even then only
  // inside their rotation window (secret_from/secret_until are 'YYYY-MM-DD').
  if (includeSecrets === true) {
    wheres.push(`(tier != 'secret' OR ((secret_from IS NULL OR secret_from <= date('now')) AND (secret_until IS NULL OR secret_until >= date('now'))))`);
  } else {
    wheres.push(`(tier IS NULL OR tier != 'secret')`);
  }

  if (stampsOnly === true) {
    wheres.push(`(tier = 'secret' OR coalesce(founder_scope, scope) IN ('world','national','regional'))`);
  }

  const safeLimit = Math.max(1, Math.min(Number(limit) || 60, 200));

  // popularity = median monthly Wikipedia pageviews from the seed pipeline —
  // the ranking signal the seed was built for. NULL (unranked) rows sort after
  // ranked ones; rating breaks ties.
  const sql = `
    SELECT *
      FROM attractions
     WHERE ${wheres.join(' AND ')}
  ORDER BY is_marquee DESC, (popularity IS NULL) ASC, popularity DESC, rating DESC
     LIMIT ${safeLimit};
  `;

  let rows;
  try {
    const stmt = env.ATTRACTIONS_DB.prepare(sql).bind(...params);
    const result = await stmt.all();
    rows = result.results || [];
  } catch (err) {
    // Graceful degradation: log + return empty so caller falls back
    // to Places. Worker logs surface this during dev; we don't want
    // a D1 hiccup to take down ThingsToDo.
    console.error('attractions/nearby D1 query failed:', err?.message);
    return jsonResponse({
      source: 'd1',
      attractions: [],
      tookMs: Date.now() - startedAt,
      error: err?.message || 'D1 query failed',
    });
  }

  // Haversine pass — refine the bounding-box prefilter to a true
  // circular radius and compute distance miles for each row.
  const R_KM = 6371;
  const toRad = (d) => (d * Math.PI) / 180;
  const enriched = rows.map((r) => {
    const dLat = toRad(r.lat - latitude);
    const dLng = toRad(r.lng - longitude);
    const a = Math.sin(dLat / 2) ** 2 +
              Math.cos(toRad(latitude)) * Math.cos(toRad(r.lat)) *
              Math.sin(dLng / 2) ** 2;
    const distKm = R_KM * 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return {
      id: r.id,
      name: r.name,
      category: r.category,
      lat: r.lat,
      lng: r.lng,
      city: r.city || '',
      country: r.country,
      description: r.description || '',
      whyVisit: r.why_visit || '',
      typicalMinutes: r.typical_minutes ?? null,
      photoUrl: r.photo_url || null,
      rating: r.rating ?? null,
      isMarquee: r.is_marquee === 1,
      freeToVisit: r.free_to_visit === 1,
      website: r.website || null,
      ticket_price: r.ticket_price || null,
      ticket_url: r.ticket_url || null,
      parking_text: r.parking_text || null,
      popularity: r.popularity ?? null,
      // Per-row stamp footprint (metres) — read by src/lib/stampRadius.js; the
      // client heuristic stays as fallback for rows without one.
      footprint_radius_m: r.footprint_radius_m ?? null,
      parentId: r.parent_id || null,
      tier: r.tier || 'page',
      qid: r.qid || null,
      distanceKm: distKm,
      distanceMiles: distKm * 0.621371,
    };
  });

  // Drop rows outside the true circle (bounding box can include
  // corners up to ~1.4x the radius). Re-sort by marquee-first +
  // rating + distance — stable so distance ties preserve the D1
  // ordering.
  const within = enriched.filter((r) => r.distanceKm <= radiusKm);
  within.sort((a, b) => {
    if (a.isMarquee !== b.isMarquee) return a.isMarquee ? -1 : 1;
    const pa = a.popularity ?? -1, pb = b.popularity ?? -1;   // seed ranking first, unranked last
    if (pa !== pb) return pb - pa;
    const ra = a.rating ?? 0, rb = b.rating ?? 0;
    if (ra !== rb) return rb - ra;
    return a.distanceKm - b.distanceKm;
  });

  // Movie scene stamps: the film behind a spot rides along as `film`.
  const films = await filmsForAttractions(env, within.map((r) => r.id));
  for (const r of within) { const f = films.get(r.id); if (f) r.film = f; }

  // Phase B background seed trigger. When D1 has sparse coverage for
  // this region AND we have the city/country labels to identify it,
  // kick off a discovery+seed task that runs after the response. The
  // throttle inside seedCityNow() means we attempt at most once per
  // region per 24h, so a stampede of users hitting Boise on day 1
  // results in a SINGLE seed run, not 10,000.
  if (ctx && within.length < 5 && countryName) {
    ctx.waitUntil(seedCityNow(env, latitude, longitude, cityName, countryName));
  }

  return jsonResponse({
    source: 'd1',
    tookMs: Date.now() - startedAt,
    attractions: within,
    // Additive; null unless the request opted in via includeCityTemp: true.
    cityTempF: await cityTempPromise,
  });
}

// ============================================================================
// LIVING HOMEPAGE ROWS — POST /home/rows
// Assembles 2–3 photo-forward carousels ENTIRELY from owned data (ATTRACTIONS_DB
// / D1) + light context (day-part, weather, season — passed by the client from
// homeContext.js). ZERO new Google Places calls. The assembled bundle is cached
// in KV so repeat opens are one KV read; rows reshuffle across the day because
// the cache key includes dayPart + weather.
// Body: { latitude, longitude, localHour?, weather?, season?, cityName?, countryName? }
// Returns: { rows:[{ key, title, subtitle, seeAll, cards:[...] }], dayPart, cached }
// FOLLOW-UPS (not yet wired): Unsplash inspiration rows (needs UNSPLASH_ACCESS_KEY,
// makes rows global beyond the ~25 seeded cities); opportunistic finder-cache rows
// (restaurants/coffee); Wave-2 "Because you saved" (needs saves→Supabase).
// ============================================================================

// Assembled-response freshness — NOT the place data (that lives longer in D1 /
// Google cache). Just how long we keep the assembled bundle before rebuilding.
// Tunable: attraction rows are stable for hours, and the key already changes per
// day-part so the homepage reshuffles through the day regardless.
const HOME_ROWS_TTL_SECONDS = 6 * 60 * 60;

// Static, hemisphere-correct destination lists for the global "Where to next"
// inspiration row (Unsplash-powered). Curated; free to expand later.
const HOME_SEASONAL_DESTINATIONS = {
  summer:   ['Santorini, Greece', 'Amalfi Coast, Italy', 'Barcelona, Spain', 'Maui, Hawaii', 'Nice, France', 'Dubrovnik, Croatia'],
  winter:   ['Zermatt, Switzerland', 'Kyoto, Japan', 'Vienna, Austria', 'Reykjavik, Iceland', 'Quebec City, Canada', 'Lapland, Finland'],
  spring:   ['Amsterdam, Netherlands', 'Kyoto, Japan', 'Paris, France', 'Marrakech, Morocco', 'Lisbon, Portugal', 'Charleston, USA'],
  fall:     ['Kyoto, Japan', 'Munich, Germany', 'Tuscany, Italy', 'Seoul, South Korea', 'Vermont, USA', 'Quebec City, Canada'],
  tropical: ['Bali, Indonesia', 'Phuket, Thailand', 'Tulum, Mexico', 'Maldives', 'Boracay, Philippines', 'Cairns, Australia'],
};

// Approximate [lat, lng] for every HOME_SEASONAL_DESTINATIONS entry, keyed by
// the exact string above. Feeds the whereToNext cards' lat/lng + live tempF
// (Open-Meteo, $0) so the Home dream rail can show a real "right now" data
// line. Region-scale entries use a well-known representative point (noted).
// A missing key degrades gracefully — the card ships lat/lng/tempF = null.
const HOME_SEASONAL_COORDS = {
  'Santorini, Greece':      [36.39, 25.46],    // Thira (Fira)
  'Amalfi Coast, Italy':    [40.63, 14.60],    // Amalfi town
  'Barcelona, Spain':       [41.39, 2.17],
  'Maui, Hawaii':           [20.80, -156.33],  // island center
  'Nice, France':           [43.70, 7.27],
  'Dubrovnik, Croatia':     [42.65, 18.09],
  'Zermatt, Switzerland':   [46.02, 7.75],
  'Kyoto, Japan':           [35.01, 135.77],
  'Vienna, Austria':        [48.21, 16.37],
  'Reykjavik, Iceland':     [64.15, -21.94],
  'Quebec City, Canada':    [46.81, -71.21],
  'Lapland, Finland':       [66.50, 25.73],    // Rovaniemi
  'Amsterdam, Netherlands': [52.37, 4.90],
  'Paris, France':          [48.86, 2.35],
  'Marrakech, Morocco':     [31.63, -8.01],
  'Lisbon, Portugal':       [38.72, -9.14],
  'Charleston, USA':        [32.78, -79.93],   // Charleston, SC
  'Munich, Germany':        [48.14, 11.58],
  'Tuscany, Italy':         [43.77, 11.25],    // Florence
  'Seoul, South Korea':     [37.57, 126.98],
  'Vermont, USA':           [44.26, -72.58],   // Montpelier
  'Bali, Indonesia':        [-8.65, 115.22],   // Denpasar
  'Phuket, Thailand':       [7.88, 98.39],
  'Tulum, Mexico':          [20.21, -87.47],
  'Maldives':               [4.17, 73.51],     // Malé
  'Boracay, Philippines':   [11.97, 121.92],
  'Cairns, Australia':      [-16.92, 145.77],
};

const HOME_WEATHER_ACCENT = { hot: 'It’s hot out', cold: 'Bundle up', rain: 'Rainy-day picks', mild: 'Nice out' };

function homeRowsDayPart(hour) {
  const h = Number(hour);
  if (!Number.isFinite(h)) return 'midday';
  if (h >= 5 && h < 8) return 'earlyMorning';
  if (h >= 8 && h < 11) return 'morning';
  if (h >= 11 && h < 15) return 'midday';
  if (h >= 15 && h < 17) return 'afternoon';
  if (h >= 17 && h < 22) return 'evening';
  return 'lateNight';
}

// Fetch a real Creative-Commons photo for a place from Openverse (free, no API
// key; aggregates Flickr + Wikimedia + museums). Commercial-licensed photos only,
// cached in KV (30d). Returns { url, photographer, license, link, credit } or null.
// Replaces Unsplash (Getty-owned, strict per-photo photographer+UTM attribution).
async function fetchOpenversePhoto(env, query, _ctx) {
  const q = String(query || '').trim();
  if (!q) return null;
  const cacheKey = `openverse:v2:${q.toLowerCase()}`;   // v2: content-safe picker (v1 cached a Hitler/Mussolini photo for "Munich")
  const cached = await env.GLOBESKIMMERS_KV.get(cacheKey, { type: 'json' }).catch(() => null);
  if (cached && cached.url) return cached;
  try {
    // Bias the search toward scenery and REJECT people/war-history results by
    // title+tags. Measured failure: bare "Munich" returned a WWII photo of
    // Hitler and Mussolini into the "Dreaming of your next trip" row. A
    // destination card shows places, never people or atrocities; when nothing
    // safe matches, show no photo (the card falls back gracefully).
    const url = `https://api.openverse.org/v1/images/?q=${encodeURIComponent(q + ' travel landmark')}&license_type=commercial&mature=false&aspect_ratio=wide&category=photograph&page_size=8`;
    const res = await fetch(url, { headers: { 'User-Agent': 'Globeskimmers/1.0 (+https://globeskimmers.io)' } });
    if (!res.ok) return null; // rate-limited/none → caller falls back gracefully
    const data = await res.json();
    const UNSAFE = /hitler|mussolini|stalin|nazi|führer|fuhrer|reich|wehrmacht|gestapo|\bss\b|swastika|holocaust|propaganda|dictator|war\b|battle|soldier|troops|military|massacre|execution|funeral|corpse|protest|riot|portrait of|bust of/i;
    const p = (data?.results || []).find((x) => {
      if (!x || !x.url) return false;
      const hay = `${x.title || ''} ${(x.tags || []).map((t) => t && t.name).join(' ')}`;
      return !UNSAFE.test(hay);
    }) || null;
    if (!p?.url) return null;
    const lic = (p.license || '').toUpperCase();
    const photo = {
      url: p.url,
      photographer: p.creator || '',
      license: lic,
      link: p.foreign_landing_url || p.creator_url || '',
      // Simple credit line — a one-liner, not Unsplash's photographer-UTM gauntlet.
      credit: `${p.creator || 'Unknown'}${lic ? ` · CC ${lic}` : ''}`,
    };
    await env.GLOBESKIMMERS_KV.put(cacheKey, JSON.stringify(photo), { expirationTtl: 30 * 24 * 60 * 60 }).catch(() => {});
    return photo;
  } catch { return null; }
}

// Canonical Commons hero for a QID-keyed attraction — Wikidata P18 by KNOWN
// QID: no name search, no wrong-match risk (brief Part Five #2, "end photo
// roulette"). Openverse text search remains ONLY for qid-less rows. 180d cache;
// misses cached 30d so a P18-less entity doesn't refetch per render.
async function getWikiPhotoByQid(env, qid) {
  const q = String(qid || '').trim();
  if (!/^Q\d+$/.test(q)) return null;
  const cacheKey = `wikiphoto_qid:v1:${q}`;
  const cached = await env.GLOBESKIMMERS_KV.get(cacheKey, { type: 'json' }).catch(() => null);
  if (cached) return cached.none ? null : cached;
  try {
    const e = await wikiJson(`https://www.wikidata.org/w/api.php?action=wbgetentities&ids=${q}&props=claims&format=json`);
    const p18 = e.entities?.[q]?.claims?.P18?.[0]?.mainsnak?.datavalue?.value;
    if (!p18 || badWikiFile(p18)) {
      await env.GLOBESKIMMERS_KV.put(cacheKey, JSON.stringify({ none: true }), { expirationTtl: 30 * 24 * 60 * 60 }).catch(() => {});
      return null;
    }
    const photo = {
      url: commonsThumb(p18),
      photographer: '',
      license: 'CC',
      link: `https://commons.wikimedia.org/wiki/File:${encodeURIComponent(p18)}`,
      credit: 'Wikimedia Commons',
    };
    await env.GLOBESKIMMERS_KV.put(cacheKey, JSON.stringify(photo), { expirationTtl: 180 * 24 * 60 * 60 }).catch(() => {});
    return photo;
  } catch { return null; }
}

// Current temperature (°F, integer) for up to 8 [lat, lng] pairs — $0 rule:
// Open-Meteo only (free, no key), same API the masthead forecast uses
// (handleWeatherForecast). All KV misses go out as ONE batched request —
// Open-Meteo accepts comma-separated latitude/longitude lists and returns an
// array of results in the same order. Per-coordinate KV cache (1-decimal
// rounding, ~11km cells) at 3h: warm calls are pure KV reads. Returns an array
// the same length as `points`; any failure (bad point, fetch error, missing
// KV) yields null in that slot — never throws.
async function destTempsF(env, points) {
  const pts = (Array.isArray(points) ? points : []).slice(0, 8);
  const out = new Array(pts.length).fill(null);
  try {
    const kv = env.GLOBESKIMMERS_KV;
    const keys = pts.map((p) =>
      // p[x] != null guards matter: Number(null) === 0, and an unmapped
      // destination would otherwise fetch (0°,0°) — open ocean — as its "NOW" temp.
      Array.isArray(p) && p[0] != null && p[1] != null && Number.isFinite(Number(p[0])) && Number.isFinite(Number(p[1]))
        ? `temp:v1:${roundCoordinate(Number(p[0]), 1)}:${roundCoordinate(Number(p[1]), 1)}`
        : null
    );
    const hits = await Promise.all(keys.map((k) => (k && kv ? kv.get(k).catch(() => null) : Promise.resolve(null))));
    const missIdx = [];
    hits.forEach((h, i) => {
      const n = h == null ? NaN : Number(h);
      if (Number.isFinite(n)) out[i] = Math.round(n);
      else if (keys[i]) missIdx.push(i);
    });
    if (missIdx.length > 0) {
      const lats = missIdx.map((i) => Number(pts[i][0])).join(',');
      const lngs = missIdx.map((i) => Number(pts[i][1])).join(',');
      const url = `https://api.open-meteo.com/v1/forecast?latitude=${lats}&longitude=${lngs}` +
        `&current=temperature_2m&temperature_unit=fahrenheit`;
      const res = await fetch(url, { headers: { Accept: 'application/json' } });
      if (res.ok) {
        const d = await res.json();
        const arr = Array.isArray(d) ? d : [d];   // single-point requests return a bare object
        for (let j = 0; j < missIdx.length; j++) {
          const i = missIdx[j];
          const t = Number(arr[j]?.current?.temperature_2m);
          if (Number.isFinite(t)) {
            out[i] = Math.round(t);
            if (kv && keys[i]) await kv.put(keys[i], String(out[i]), { expirationTtl: 3 * 60 * 60 }).catch(() => {});
          }
        }
      }
    }
  } catch { /* leave nulls — the data line just doesn't render */ }
  return out;
}

// Build the global "Where to next" inspiration row from Openverse destination
// photos. No API key needed now (free) — returns null only if too few resolve.
async function buildWhereToNextRow(env, seasonKey, ctx) {
  const dests = (HOME_SEASONAL_DESTINATIONS[seasonKey] || HOME_SEASONAL_DESTINATIONS.summer).slice(0, 6);
  const cards = [];
  for (const dest of dests) {
    // Canonical imagery first: Wikidata/Commons via the curated destination name
    // (quality-gated ≥1000×600, badWikiFile blacklist, 180d cache). Openverse is
    // the fallback only — this row's one job is selling the dream, and it never
    // again leads with CC-search roulette (measured failure: Hitler for "Munich").
    const name = dest.split(',')[0].trim();
    let photo = null;
    try {
      const wiki = await getWikiPhotos(env, name, NaN, NaN);
      const w = wiki?.photos?.[0];
      if (w?.url) photo = { url: w.url, photographer: '', credit: w.credit || 'Wikimedia Commons', link: '' };
    } catch { /* fall through to Openverse */ }
    if (!photo) photo = await fetchOpenversePhoto(env, dest, ctx);
    if (photo?.url) {
      // Additive: lat/lng from the curated coords map (null when unmapped) so
      // the client can deep-link SmartPackages / compute flight-time lines.
      const coords = HOME_SEASONAL_COORDS[dest] || null;
      cards.push({ id: `esc_${dest}`, name, whyVisit: dest, photoUrl: photo.url, photographer: photo.photographer, credit: photo.credit, creditLink: photo.link, lat: coords ? coords[0] : null, lng: coords ? coords[1] : null });
    }
  }
  if (cards.length < 3) return null;
  // Live "right now" temp per destination — one batched Open-Meteo call for
  // all KV-cold cards ($0, 3h KV). Unmapped/failed cards carry tempF = null.
  const temps = await destTempsF(env, cards.map((c) => [c.lat, c.lng]));
  cards.forEach((c, i) => { c.tempF = temps[i]; });
  return { key: 'whereToNext', title: 'Where to next ✈️', subtitle: 'Dreaming of your next trip', seeAll: { action: 'Things to Do' }, cards };
}

// Residential junk that Overture mis-tags as 'landmark_and_historical_building'
// (condos, staffhouses, townhomes — rampant in PH/SE-Asia). Mirrors the SQL
// exclusion in scripts/finders/attractions.sql, but applied HERE too so the
// filter takes effect the moment the worker deploys — even before that SQL is
// re-run in Supabase. Word-boundary so "Palace" etc. is never hit.
const HOMEROW_RESIDENTIAL_RE = /\b(condo|condominium|condominiums|residence|residences|townhome|townhomes|townhouse|townhouses|apartment|apartments|apartelle|staff\s*house|staffhouse|subdivision|dormitory|dorm)\b/i;
function looksResidential(name) {
  return HOMEROW_RESIDENTIAL_RE.test(String(name || ''));
}

// Build a clean photo-search query from a (possibly messy) owned place name.
// Overture names in less-curated regions carry non-Latin scripts ("Seng Guan
// Temple 信願寺"), ALL-CAPS shouting ("Hindu Temple MANILA"), and no city context
// — all of which make Openverse/Wikimedia text search MISS the real attraction
// and fall back to the brown placeholder. This normalizes the name and always
// appends "{city}, {country}" so the search lands. Returns a plain string.
function cleanPhotoQuery(name, city, country) {
  let n = String(name || '')
    .normalize('NFKD')
    .replace(/[^\x20-\x7E]/g, ' ')          // drop non-Latin (CJK/Thai/etc.)
    .replace(/\s{2,}/g, ' ')
    .trim();
  // De-shout ALL-CAPS words (>=3 letters) → Title Case so search matches.
  n = n.replace(/\b[A-Z]{3,}\b/g, (w) => w.charAt(0) + w.slice(1).toLowerCase());
  const parts = [];
  const nLow = n.toLowerCase();
  if (n) parts.push(n);
  if (city && !nLow.includes(String(city).toLowerCase())) parts.push(String(city).trim());
  if (country && !nLow.includes(String(country).toLowerCase())) parts.push(String(country).trim());
  return parts.filter(Boolean).join(', ') || String(city || country || '').trim();
}

// Fallback pool for the living home rows when there's no CURATED owned coverage
// (i.e. outside the ~seeded cities): pull nearby attractions from the OWNED PLANET
// DB (75M places) so the carousels populate almost everywhere, not just seeded
// cities. Hydrates Wikimedia photos for the top cards so the rows stay photo-forward.
// Shape matches what handleHomeRows' `trim()` expects.
async function homeRowsPlanetPool(env, latitude, longitude) {
  try {
    if (!env.SUPABASE_URL || !env.SUPABASE_SERVICE_KEY) return [];
    const r = await fetch(`${env.SUPABASE_URL}/rest/v1/rpc/nearby_attractions`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', apikey: env.SUPABASE_SERVICE_KEY, Authorization: `Bearer ${env.SUPABASE_SERVICE_KEY}` },
      body: JSON.stringify({ in_lat: latitude, in_lng: longitude, in_radius_m: 60000, in_limit: 40 }),
    });
    if (!r.ok) return [];
    const rows = (await r.json()) || [];
    const cards = rows
      // Drop residential junk mis-tagged as landmarks (belt-and-suspenders with
      // the SQL exclusion) so tourists never see condos where sights should be.
      .filter((p) => !looksResidential(p.name))
      .map((p) => ({
        id: p.id, name: p.name, category: p.category, city: p.city || '', country: p.country || '',
        photoUrl: null, rating: null, whyVisit: '',
        distanceMiles: (p.meters || 0) / 1609.34, freeToVisit: null, lat: p.lat, lng: p.lng,
      }));
    // Hydrate real Wikimedia photos for the top cards (free, cached 180d) — the
    // rows are photo-forward, and the client also hydrates any left without one.
    // Go a bit deeper (24) so the notability gate below has photo signal.
    await Promise.all(cards.slice(0, 24).map(async (c) => {
      try { const wp = await getWikiPhotos(env, c.name, c.lat, c.lng); if (wp.photos?.length) c.photoUrl = wp.photos[0].url; } catch { /* leave photoless; client hydrates */ }
    }));
    // Notability gate for Overture's generic 'landmark_and_historical_building' —
    // a pollution-heavy catch-all in less-curated regions (Cebu: condos, boarding
    // houses, "Cdc Building" mis-tagged as landmarks). Keep such a row ONLY if it
    // resolved a REAL photo: famous historic buildings have a Wikidata/Commons
    // image, ordinary condos don't. Specific-category attractions (church_cathedral,
    // monument, temple, museum, park…) are NEVER gated, so genuine sights with
    // sparse free-photo coverage (many PH temples) still show. Globally safe:
    // real historic buildings in well-mapped cities keep their photo → survive.
    return cards.filter((c) => String(c.category || '') !== 'landmark_and_historical_building' || c.photoUrl);
  } catch (e) { console.error('home/rows planet pool failed:', e?.message); return []; }
}

// /attractions/get — one attraction row by id, for deep-linked / shared
// ActivityDetail URLs (?id=...). Same graceful degradation as /attractions/nearby.
// Film behind each attraction (film_scenes, cloudflare-worker/sql/13_film_scenes.sql).
// Separate query so a missing table (not yet applied) never breaks the list —
// it just means no film info. → Map(attraction_id → film).
function filmFromRow(f) {
  if (!f || !f.work_title) return null;
  const cast = [[f.cast1, f.role1], [f.cast2, f.role2]].filter(([a]) => a).map(([actor, role]) => ({ actor, role: role || null }));
  return { title: f.work_title, year: f.year ?? null, type: f.work_type || 'film', cast, scene: f.scene || null, alsoIn: f.also_in || null };
}
async function filmsForAttractions(env, ids) {
  const out = new Map();
  const list = (ids || []).filter(Boolean).slice(0, 200);
  if (!env.ATTRACTIONS_DB || !list.length) return out;
  try {
    const rs = await env.ATTRACTIONS_DB.prepare(
      `SELECT attraction_id, work_title, work_type, year, cast1, role1, cast2, role2, scene, also_in
         FROM film_scenes WHERE attraction_id IN (${list.map(() => '?').join(',')})`
    ).bind(...list).all();
    for (const f of rs.results || []) { const film = filmFromRow(f); if (film) out.set(f.attraction_id, film); }
  } catch { /* table not applied yet → no film info */ }
  return out;
}

async function handleAttractionsGet(request, env) {
  if (!env.ATTRACTIONS_DB) return jsonResponse({ attraction: null, note: 'ATTRACTIONS_DB binding not present' });
  let body;
  try { body = await request.json(); }
  catch { return jsonResponse({ error: 'Invalid JSON body' }, 400); }
  const id = String(body?.id || '').trim();
  if (!id || id.length > 200) return jsonResponse({ error: 'id required' }, 400);
  try {
    const row = await env.ATTRACTIONS_DB.prepare(
      `SELECT *
         FROM attractions WHERE id = ?1 LIMIT 1`
    ).bind(id).first();
    if (!row) return jsonResponse({ attraction: null }, 404);
    const film = (await filmsForAttractions(env, [row.id])).get(row.id) || null;
    return jsonResponse({ attraction: {
      id: row.id, name: row.name, category: row.category, lat: row.lat, lng: row.lng,
      city: row.city || '', country: row.country, description: row.description || '',
      whyVisit: row.why_visit || '', typicalMinutes: row.typical_minutes ?? null,
      photoUrl: row.photo_url || null, rating: row.rating ?? null,
      isMarquee: row.is_marquee === 1, freeToVisit: row.free_to_visit === 1,
      website: row.website || null, ticket_price: row.ticket_price || null,
      ticket_url: row.ticket_url || null, parking_text: row.parking_text || null,
      popularity: row.popularity ?? null, footprint_radius_m: row.footprint_radius_m ?? null,
      parentId: row.parent_id || null, tier: row.tier || 'page', qid: row.qid || null,
      film,
    } });
  } catch (err) {
    console.error('attractions/get D1 query failed:', err?.message);
    return jsonResponse({ attraction: null, error: err?.message || 'D1 query failed' }, 500);
  }
}

// ── Things to Do is the attraction page (founder, 2026-10-03) ─────────────────
// A stamp tap opens that attraction's Things to Do card; every Things to Do
// attraction can be stamped "I was here" when GPS puts you there; iconic ones
// (a stampable D1 row) get their official stamp instead of the typographic one.
function ttdIdKind(id) {
  const v = String(id || '');
  if (/^(places|owned):/.test(v)) return 'tagged';   // "I was here" stamp ids: places:<googleId> / owned:<uuid>
  if (/^[a-z]+:/.test(v) || /^[a-z]{2}-[a-z0-9-]+$/.test(v)) return 'd1';
  if (/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(v)) return 'owned';
  if (/^[A-Za-z0-9_-]{16,250}$/.test(v) && /[A-Z]/.test(v)) return 'google';   // Google ids are mixed-case
  if (/^[a-z0-9]+(?:-[a-z0-9]+)+$/.test(v)) return 'variant';                    // landmark variant slugs (stampVariants.js)
  return null;
}
async function ttdPlaceDetails(env, gid, origin) {
  if (ttdIdKind(gid) !== 'google') return null;
  const cached = await getFromCache(env, `details_${gid}`).catch(() => null);
  if (cached?.data) return cached.data;
  if (!env.GOOGLE_API_KEY) return null;
  try {
    const r = await fetch(`https://places.googleapis.com/v1/places/${gid}?languageCode=en`, { headers: { 'X-Goog-Api-Key': env.GOOGLE_API_KEY, 'X-Goog-FieldMask': CONFIG.DETAILS_FIELD_MASK } });
    if (!r.ok) return null;
    const p = normalizePlace(await r.json(), origin || '', true);
    await setInCache(env, `details_${gid}`, p, CONFIG.CACHE_TTL.DETAILS);
    return p;
  } catch { return null; }
}
const ttdUntag = (id) => String(id || '').replace(/^(places|owned):/, '');
async function ttdGidFor(env, id) {
  id = ttdUntag(id);
  const k = ttdIdKind(id);
  if (k === 'google') return id;
  if (k === 'd1') return resolveStampGid(env, id).catch(() => null);
  if (k === 'owned' && env.GLOBESKIMMERS_KV) {
    const m = await env.GLOBESKIMMERS_KV.get(`owned2gid:${id}`).catch(() => null);
    return m && m !== 'none' ? m : null;
  }
  return null;
}
const ttdStampSummary = (r) => ({ id: r.id, name: r.name, category: r.category || null, footprint_radius_m: r.footprint_radius_m ?? null, city: r.city || null, country: r.country || null, lat: +r.lat, lng: +r.lng });
// The iconic (stampable) D1 row for a place: same name, inside its footprint.
async function ttdStampFor(env, gid, name, lat, lng, { write = true } = {}) {
  // v3 (2026-10-04): the art review made 182 more Top-1,000 places stampable and
  // re-pinned 46 rows — every cached link (and 'none') is recomputed.
  // v4 (2026-10-10): duplicate rows (class_ban 'duplicate') are no longer matched.
  const kv = env.GLOBESKIMMERS_KV, key = gid ? `gid2d1v4:${gid}` : null;
  const goodInput = Number.isFinite(lat) && Number.isFinite(lng) && !!name;
  // A shaped place names its own official stamp: its Google pins can sit far
  // from our pin (the Walk of Fame's are 1.3 km apart), so no distance match.
  const shaped = gid ? ppShapeFor(null, gid) : null;
  if (shaped?.stamp_id && env.ATTRACTIONS_DB) {
    const r = await env.ATTRACTIONS_DB.prepare('SELECT * FROM attractions WHERE id = ?1 LIMIT 1').bind(shaped.stamp_id).first().catch(() => null);
    if (r) return ttdStampSummary(r);
  }
  if (key && kv) {
    const hit = await kv.get(key).catch(() => null);
    if (hit) return hit === 'none' ? null : JSON.parse(hit);
  }
  let out = null;
  if (env.ATTRACTIONS_DB && Number.isFinite(lat) && Number.isFinite(lng) && name) {
    const dLat = 0.03, dLng = 0.03 / Math.max(0.2, Math.cos(lat * Math.PI / 180));
    const q = await env.ATTRACTIONS_DB.prepare(
      `SELECT * FROM attractions WHERE lat BETWEEN ?1 AND ?2 AND lng BETWEEN ?3 AND ?4
         AND (tier = 'secret' OR coalesce(founder_scope, scope) IN ('world','national','regional'))
         AND coalesce(class_ban, '') != 'duplicate' LIMIT 80`
    ).bind(lat - dLat, lat + dLat, lng - dLng, lng + dLng).all().catch(() => null);
    const norm = (v) => String(v || '').normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/^the\s+/, '').replace(/[^a-z0-9]+/g, ' ').trim();
    const n = norm(name);
    let best = null;
    for (const r of q?.results || []) {
      const rn = norm(r.name);
      if (!rn || !n || !(rn === n || (rn.length >= 6 && n.includes(rn)) || (n.length >= 6 && rn.includes(n)))) continue;
      const m = haversineMilesLoc(lat, lng, +r.lat, +r.lng) * 1609.34;
      if (m > Math.max(600, ppStampRadius(r) * 1.5)) continue;
      // D1 has a few duplicate rows for one place: the row already resolved to
      // THIS Google place wins, then the nearest.
      const tied = gid && kv ? (await kv.get(`d1gid:${r.id}`).catch(() => null)) === gid : false;
      if (!best || (tied && !best.tied) || (tied === best.tied && m < best.m)) best = { m, r, tied };
    }
    if (best) out = ttdStampSummary(best.r);
  }
  if (write && goodInput && key && kv) await kv.put(key, out ? JSON.stringify(out) : 'none', { expirationTtl: 30 * 86400 }).catch(() => {});
  return out;
}
// Where a place really is (for the stamp distance check): our D1 row, else Google.
async function ttdPlaceTruth(env, entityId, origin) {
  // A Local favorite (lf:<id>, founder 2026-10-10): the approved suggested
  // place's own pin and a 150 m circle. Not approved = nowhere to stamp.
  if (String(entityId || '').startsWith('lf:')) {
    const lf = await psApprovedPlace(env, entityId);
    return lf ? { lat: lf.lat, lng: lf.lng, radius: 150, shape: null, name: lf.name } : null;
  }
  const k = ttdIdKind(entityId);
  if (k === 'd1' && env.ATTRACTIONS_DB) {
    const r = await env.ATTRACTIONS_DB.prepare('SELECT * FROM attractions WHERE id = ?1 LIMIT 1').bind(entityId).first().catch(() => null);
    if (r && Number.isFinite(+r.lat) && Number.isFinite(+r.lng)) return { lat: +r.lat, lng: +r.lng, radius: ppStampRadius(r), shape: ppShapeFor(entityId, null) || ppShapeNear(r.name, +r.lat, +r.lng), name: r.name || null };
    return null;
  }
  let gid = String(entityId).startsWith('places:') ? String(entityId).slice(7) : String(entityId).startsWith('owned:') ? await ttdGidFor(env, entityId) : null;
  const d = gid ? await ttdPlaceDetails(env, gid, origin) : null;
  const lat = Number(d?.latitude ?? d?.location?.latitude), lng = Number(d?.longitude ?? d?.location?.longitude);
  if (!Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  return { lat, lng, radius: ppStampRadius({ category: [d.primaryType, ...(d.types || [])].filter(Boolean).join(' ') }), shape: ppShapeFor(null, gid) || ppShapeNear(d.name, lat, lng), gid, name: d.name || null, address: d.address || null, types: [d.primaryType, ...(d.types || [])].filter(Boolean) };
}

// POST /attractions/link { placeId, name, lat, lng } → { stamp: {id,…} | null }
// Is this Things to Do place one of our iconic stamps?
async function handleAttractionLink(request, env) {
  try {
    const b = await request.json().catch(() => ({}));
    const id = String(b.placeId || '').trim();
    const k = ttdIdKind(id);
    if (!k) return jsonResponse({ stamp: null });
    if (k === 'd1') {
      const r = env.ATTRACTIONS_DB ? await env.ATTRACTIONS_DB.prepare('SELECT * FROM attractions WHERE id = ?1 LIMIT 1').bind(id).first().catch(() => null) : null;
      return jsonResponse({ stamp: r ? ttdStampSummary(r) : null, gid: r ? await resolveStampGid(env, id).catch(() => null) : null });
    }
    const gid = k === 'google' ? id : await ttdGidFor(env, id);
    // Read-only: a client's name/coords never write the shared cache.
    return jsonResponse({ stamp: await ttdStampFor(env, gid, String(b.name || '').slice(0, 160), Number(b.lat), Number(b.lng), { write: false }), gid: gid || null });
  } catch (e) { return jsonResponse({ stamp: null, error: e.message }); }
}

// POST /activities/one { id, name?, lat?, lng?, userLat?, userLng? } → { activity, stamp }
// One attraction in the Things to Do card shape, for a stamp tap anywhere in the app.
async function handleActivityOne(request, env) {
  try {
    const b = await request.json().catch(() => ({}));
    const id = ttdUntag(String(b.id || '').trim());
    const k = ttdIdKind(id);
    if (!k) return jsonResponse({ error: 'id required' }, 400);
    const origin = new URL(request.url).origin;
    let row = null;
    if (k === 'd1' && env.ATTRACTIONS_DB) row = await env.ATTRACTIONS_DB.prepare('SELECT * FROM attractions WHERE id = ?1 LIMIT 1').bind(id).first().catch(() => null);
    const gid = await ttdGidFor(env, id);
    const d = gid ? await ttdPlaceDetails(env, gid, origin) : null;
    const uLat = Number.isFinite(+b.userLat) ? +b.userLat : null, uLng = Number.isFinite(+b.userLng) ? +b.userLng : null;
    let activity = null;
    if (d) {
      const pl = Number(d.latitude ?? d.location?.latitude), pg = Number(d.longitude ?? d.location?.longitude);
      if (Number.isFinite(pl) && Number.isFinite(pg)) {
        activity = gaMapTieredPlace(d, uLat ?? pl, uLng ?? pg);
        const mi = activity.distanceMiles;
        activity.travelType = mi > 100 ? '100+ mi away' : mi > 50 ? '≈50–100 mi' : mi > 15 ? '≈15–50 mi' : '📍 Nearby';
        // Without the traveler's location there is no distance to show (not "0.0 mi").
        if (uLat == null || uLng == null) Object.assign(activity, { distanceKm: null, distanceMiles: null, distance: null, travelType: null });
      }
    } else if (row) {
      const distMi = uLat != null ? haversineMilesLoc(uLat, uLng, +row.lat, +row.lng) : 0;
      activity = gaMapD1ToActivity({ ...row, photoUrl: row.photo_url || null, whyVisit: row.why_visit || '', typicalMinutes: row.typical_minutes ?? null, distanceMiles: distMi });
    }
    if (!activity) return jsonResponse({ activity: null, stamp: row ? ttdStampSummary(row) : null }, 404);
    let stamp = row ? ttdStampSummary(row) : null;
    if (!stamp && gid) stamp = await ttdStampFor(env, gid, activity.name, Number(activity.lat), Number(activity.lng), { write: !!d });
    return jsonResponse({ activity, stamp });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// ── Tickets + parking for a stampable attraction (founder, 2026-10-03) ────────
// POST /attractions/visit-info { id } — admission by audience (adult, child,
// student, senior, military …), discounts, and parking with prices. Claude
// searches and FETCHES the official pages; CODE then keeps a price only when
// its source is a page that was actually fetched AND that page's text contains
// the amount. Nothing is estimated: unfound facts stay null and the app sends
// the traveler to the official site. Cached 30 days (3 when nothing is found).
// Sonnet 5, not Opus: a lookup reads several whole pages (Opus 5 measured 138k input
// tokens on Battleship Iowa), and code re-checks every amount against the page text.
const VISIT_INFO_MODEL = 'claude-sonnet-5';
const VISIT_INFO_VERSION = 'v5';  // v5: parking gets its own search, no search commentary in notes; v4: + web search INSIDE the official site, cited excerpts as evidence (sites built with JavaScript, like Universal's, fetch as an empty shell); v2: fetch-only from the official site when known (v1's open search burned the budget on rejected URLs)
// Kept 90 days (founder, 2026-10-03: "every 3 months"); 30 days when nothing was
// found — a place with no prices online was re-checked (and paid for) every 3 days.
const VISIT_INFO_TTL = 90 * 86400, VISIT_INFO_EMPTY_TTL = 30 * 86400;
// Never a price source — sellers' marked-up or bundled prices (search filter + code check).
const VISIT_RESELLERS = ['viator.com', 'getyourguide.com', 'klook.com', 'tiqets.com', 'headout.com', 'musement.com', 'undercovertourist.com', 'getawaytoday.com', 'tripadvisor.com', 'expedia.com', 'groupon.com', 'go-city.com', 'citypass.com', 'stubhub.com', 'vividseats.com', 'ticketnetwork.com'];
// An "official site" on one of these is a profile page, not the venue's own site.
const VISIT_PLATFORMS = ['facebook.com', 'instagram.com', 'x.com', 'twitter.com', 'linktr.ee', 'google.com', 'yelp.com', 'wikipedia.org'];
const VISIT_INFO_DAILY_CAP = 150;   // fresh lookups per day, all travelers
const VISIT_INFO_USER_CAP = 20;     // fresh lookups per traveler per day
const VISIT_AUDIENCES = new Set(['adult', 'child', 'youth', 'student', 'senior', 'military', 'resident', 'family', 'other']);
const VISIT_INFO_PROMPT = [
  'You find current visitor prices for ONE attraction, for a travel app that never guesses.',
  'Start from the OFFICIAL website when one is given: web_fetch it, then follow ITS links to the tickets/admission page and the parking (or "plan your visit", "visit", "directions", "FAQ") page. Only fetch URLs that appear in a page you already fetched or in a search result — never guess a URL. With no official website given, use web_search to find it. Fetch at most 5 pages.',
  'Many official sites are built with JavaScript and fetch as an empty shell. When an official website is given, web_search searches ONLY that site: whenever a fetched page shows no prices (right away if the home page fetches nearly empty), run one search for ticket prices and a SEPARATE search for parking prices (e.g. "<attraction> parking").',
  'Report ONLY what a page you fetched or a search result you cite states. Never use memory, never estimate, never average. Prefer the official site; use a third-party page only when the official site states nothing, and never a reseller\'s marked-up price.',
  'Before the JSON, write one short sentence for each price and parking fact you report, quoting the amount exactly as the source writes it, and cite the search result it comes from (facts from a fetched page need no citation). A fact with neither a citation nor a fetched page is dropped.',
  'For every price, give source_url = the exact URL of the fetched page or the cited search result that states it, and amount_text exactly as written there. When prices vary by date, give the lowest "from" price the source states and say "from — varies by date" in note.',
  'Audience is one of: adult, child, youth, student, senior, military, resident, family, other. Put the age range or condition in label (e.g. "Child (3–9)", "Senior (62+)").',
  'Military, veteran, teacher, first-responder, resident, AAA or similar offers go in discounts unless they have their own price.',
  'If admission is free, set free=true. If something is not stated, use null or an empty list — labels and notes are facts for travelers in the source\'s words, never comments about your search (no "not stated", "not found", "sources").',
  'Finish with ONLY the JSON object inside <json></json> tags, in this shape:',
  '{"official_site":"url|null","admission":{"free":true|false|null,"currency":"USD","prices":[{"audience":"adult","label":"Adult (10+)","amount":25,"amount_text":"$25","note":null,"source_url":"url"}],"discounts":[{"label":"Military — free with ID","source_url":"url"}],"free_days":null,"reservation":null,"buy_url":null,"source_url":null},"parking":{"options":[{"label":"On-site lot","price_text":"$25 per car","amount":25,"source_url":"url"}],"note":null,"source_url":null}}',
].join(' ');

const visitUrlKey = (u) => {
  try { const x = new URL(String(u)); return (x.hostname.replace(/^www\./, '') + x.pathname.replace(/\/+$/, '')).toLowerCase(); } catch { return null; }
};
const visitHost = (u) => { try { return new URL(String(u)).hostname.replace(/^www\./, ''); } catch { return null; } };
function visitAmountIn(text, amount) {
  if (!Number.isFinite(amount)) return false;
  if (amount === 0) return /\bfree\b/i.test(text);
  const whole = Math.trunc(amount), cents = Math.round((amount - whole) * 100);
  const intPart = String(whole).replace(/\B(?=(\d{3})+(?!\d))/g, '[,.\\s]?');
  const re = cents ? new RegExp(`(?<![\\d.,])${intPart}[.,]${String(cents).padStart(2, '0')}(?!\\d)`) : new RegExp(`(?<![\\d.,])${intPart}(?:[.,]00)?(?![\\d.,]?\\d)`);
  return re.test(text);
}
async function visitOfficialSite(row) {
  if (row.website && /^https?:\/\//i.test(row.website)) return row.website;
  const q = String(row.qid || (String(row.id).match(/Q\d+/) || [])[0] || '');
  if (!/^Q\d+$/.test(q)) return null;
  try {
    const e = await wikiJson(`https://www.wikidata.org/w/api.php?action=wbgetentities&ids=${q}&props=claims&format=json`);
    const v = e?.entities?.[q]?.claims?.P856?.[0]?.mainsnak?.datavalue?.value;
    return typeof v === 'string' && /^https?:\/\//i.test(v) ? v : null;
  } catch { return null; }
}
// One Claude turn with web search + fetch; continues across pause_turn.
// host: the official site's domain — web search then searches only that site. No
// host: search anywhere except resellers (to find the official site first).
async function visitAsk(env, userText, host, opts = {}) {
  const messages = [{ role: 'user', content: userText }];
  const system = opts.system || VISIT_INFO_PROMPT;
  const fetchMax = opts.fetchMax || 5;
  const blocks = [];
  let usage = { input_tokens: 0, output_tokens: 0, searches: 0 };
  for (let round = 0; round < 4; round++) {
    const res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'anthropic-beta': 'web-fetch-2025-09-10', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: VISIT_INFO_MODEL, max_tokens: 4000, system,
        output_config: { effort: 'low' },
        tools: [
          { type: 'web_search_20250305', name: 'web_search', max_uses: 4, ...(host ? { allowed_domains: [host] } : { blocked_domains: VISIT_RESELLERS }) },
          { type: 'web_fetch_20250910', name: 'web_fetch', max_uses: fetchMax, max_content_tokens: 8000, ...(opts.citations ? { citations: { enabled: true } } : {}) },
        ],
        messages,
      }),
    });
    if (!res.ok) return { error: `anthropic ${res.status}: ${(await res.text().catch(() => '')).slice(0, 300)}`, blocks, usage };
    const d = await res.json();
    usage = { input_tokens: usage.input_tokens + (d.usage?.input_tokens || 0), output_tokens: usage.output_tokens + (d.usage?.output_tokens || 0), searches: usage.searches + (d.usage?.server_tool_use?.web_search_requests || 0) };
    blocks.push(...(d.content || []));
    if (d.stop_reason !== 'pause_turn') return { blocks, usage, stop: d.stop_reason };
    messages.push({ role: 'assistant', content: d.content });
  }
  return { blocks, usage, stop: 'rounds' };
}
// Pages the model actually fetched → { urlKey: text }, plus every URL it saw.
function visitEvidence(blocks) {
  const pages = new Map(), seen = new Set();
  for (const b of blocks) {
    if (b?.type === 'web_fetch_tool_result') {
      const c = b.content;
      const url = c?.url || c?.content?.source?.url;
      const src = c?.content?.source;
      const text = src?.type === 'text' ? String(src.data || '') : '';
      const k = visitUrlKey(url);
      if (k && text) pages.set(k, (pages.get(k) || '') + '\n' + text);
      if (k) seen.add(k);
    } else if (b?.type === 'web_search_tool_result' && Array.isArray(b.content)) {
      for (const r of b.content) { const k = visitUrlKey(r?.url); if (k) seen.add(k); }
    } else if (b?.type === 'text' && Array.isArray(b.citations)) {
      // A search result's own words, quoted by the API (up to 150 characters) —
      // evidence for its URL exactly like a fetched page's text.
      for (const c of b.citations) {
        const k = visitUrlKey(c?.url);
        if (k && c?.cited_text) { pages.set(k, (pages.get(k) || '') + '\n' + String(c.cited_text)); seen.add(k); }
      }
    }
  }
  return { pages, seen };
}
const visitOnList = (u, list) => { const h = visitHost(u); return !!h && list.some((d) => h === d || h.endsWith('.' + d)); };
// "(exact price not stated…)", "…no parking price was found in the fetched/cited
// sources" — the model talking about its search, not a fact for travelers.
const VISIT_META_RE = /\b(not stated|not found|not listed|not specified|no specific|exact price|fetched|cited|sources?)\b/i;
const visitUnmeta = (t) => {
  if (typeof t !== 'string') return t;
  const s = t.replace(/\s*\([^)]*\)?/g, (m) => (VISIT_META_RE.test(m) ? '' : m)).trim();
  return s && !VISIT_META_RE.test(s) ? s : null;
};
function visitVerify(raw, ev) {
  const textOf = (u) => (visitOnList(u, VISIT_RESELLERS) ? null : ev.pages.get(visitUrlKey(u)) || null);
  const str = (v, n) => { const u = typeof v === 'string' && v.trim() && !/^https?:\/\//i.test(v.trim()) ? visitUnmeta(v.trim()) : null; return u ? u.slice(0, n) : null; };
  // Every number in a line must appear in the page it cites.
  const numsIn = (line, t) => !!line && !!t && (line.match(/\d+(?:[.,]\d+)?/g) || []).every((n) => visitAmountIn(t, Number(n.replace(',', '.'))));
  const wordsIn = (line, t) => { const w = String(line || '').toLowerCase().match(/[a-z]{4,}/g) || []; const tl = t.toLowerCase(); return !w.length || w.some((x) => tl.includes(x)); };
  const cap = (v) => v.charAt(0).toUpperCase() + v.slice(1);
  const a = raw?.admission || {};
  const prices = (Array.isArray(a.prices) ? a.prices : []).map((p) => {
    const t = textOf(p?.source_url); const amount = Number(p?.amount);
    if (!t || !VISIT_AUDIENCES.has(p?.audience) || !(amount >= 0) || !visitAmountIn(t, amount)) return null;
    const label = str(p.label, 60);
    return { audience: p.audience, label: label && numsIn(label, t) ? label : cap(p.audience), amount, amount_text: str(p.amount_text, 40), note: str(p.note, 100), source_url: p.source_url };
  }).filter(Boolean).slice(0, 12);
  const discounts = (Array.isArray(a.discounts) ? a.discounts : []).map((x) => {
    const t = textOf(x?.source_url); const label = str(x?.label, 90);
    if (!t || !label) return null;
    const nums = label.match(/\d+(?:[.,]\d+)?/g) || [];
    const words = label.toLowerCase().match(/[a-z]{5,}/g) || [];
    const tl = t.toLowerCase();
    if (nums.some((n) => !t.includes(n)) || (words.length && !words.some((w) => tl.includes(w)))) return null;
    return { label, source_url: x.source_url };
  }).filter(Boolean).slice(0, 8);
  const freeSrc = textOf(a.source_url) || (prices[0] && textOf(prices[0].source_url));
  const free = a.free === true && !!freeSrc && /\bfree\b/i.test(freeSrc) ? true : (prices.length ? false : null);
  const pk = raw?.parking || {};
  const options = (Array.isArray(pk.options) ? pk.options : []).map((o) => {
    const t = textOf(o?.source_url); const label = str(o?.label, 80);
    if (!t || !label || !/park/i.test(t) || !wordsIn(label, t)) return null;
    const amount = o?.amount == null ? null : Number(o.amount);
    const okAmount = amount != null && amount >= 0 && visitAmountIn(t, amount);
    const text = str(o.price_text, 120);
    const okText = text && /\d/.test(text) && numsIn(text, t);
    return { label, price_text: okText ? text : null, amount: okAmount ? amount : null, source_url: o.source_url };
  }).filter(Boolean).slice(0, 6);
  const keepUrl = (u) => (u && ev.seen.has(visitUrlKey(u)) ? String(u) : null);
  return {
    official_site: keepUrl(raw?.official_site) || null,
    admission: {
      free, currency: str(a.currency, 3), prices, discounts,
      free_days: str(a.free_days, 120) && textOf(a.source_url) && numsIn(a.free_days, textOf(a.source_url)) ? str(a.free_days, 120) : null,
      reservation: str(a.reservation, 140) && textOf(a.source_url) && numsIn(a.reservation, textOf(a.source_url)) ? str(a.reservation, 140) : null,
      buy_url: keepUrl(a.buy_url),
      source_url: textOf(a.source_url) ? a.source_url : (prices[0]?.source_url || null),
    },
    parking: {
      options,
      note: str(pk.note, 160) && textOf(pk.source_url) && numsIn(pk.note, textOf(pk.source_url)) ? str(pk.note, 160) : null,
      source_url: textOf(pk.source_url) ? pk.source_url : (options[0]?.source_url || null),
    },
  };
}

// ── "Before you go" (docs/plans/before-you-go.md, founder decisions 2026-10-11)
// The published visiting rules of ONE place — who may enter, dress, photos,
// closures, booking, bags, access — each fact either backed by the place's own
// words (an exact quote from a really-fetched page on an allowed source) or
// "unknown". Never inferred from the religion, category, country or memory.
const BYG_VERSION = 'v1';
const BYG_TTL = 90 * 86400;        // facts found
const BYG_EMPTY_TTL = 30 * 86400;  // everything unknown — recheck sooner
const BYG_DAILY_CAP = 150, BYG_USER_CAP = 20;
// Official tourism bodies outside gov domains (hand-kept, small on purpose).
const BYG_OFFICIAL_BODIES = ['japan.travel', 'visitlondon.com', 'parisjetaime.com', 'australia.com', 'visitcalifornia.com', 'nycgo.com', 'nyctourism.com', 'visitsingapore.com', 'goturkiye.com', 'visitdubai.com'];
const BYG_GOV_RE = /(^|\.)((gov|gouv|gob|go|govt)\.[a-z]{2,3}|gov|gc\.ca|govt\.nz)$/i;
// The card never editorializes about a faith or a rule; these words may appear
// only inside a source's own quote (same spirit as the AI-details word guard).
const BYG_TONE_RE = /\b(strict|conservative|unfortunately|sadly|banned|forbidden|not welcome|discriminat|backward|exotic)\b/i;
const BYG_ENTRY = new Set(['open_to_all', 'restricted', 'closed_to_visitors', 'unknown']);
const BYG_ENTRY_LIMITS = new Set(['faith', 'gender', 'age', 'tour_only', 'permit', 'dress_enforced', 'other']);
const BYG_DRESS_ITEMS = new Set(['cover_shoulders', 'cover_knees', 'women_cover_hair', 'men_cover_head', 'remove_shoes', 'wraps_provided', 'other']);
const BYG_CLOSURE_KINDS = new Set(['prayer', 'service', 'ceremony', 'weekly', 'seasonal', 'other']);
const BYG_SECURITY_ITEMS = new Set(['bag_check', 'no_large_bags', 'lockers', 'id_required', 'other']);
const BYG_PROMPT = [
  'You find the PUBLISHED visiting rules of ONE place for a travel app that never guesses.',
  'Start from the official site when given: web_fetch it, then follow ITS links to visitor information, FAQ, plan-your-visit, etiquette or rules pages (often PDFs). When pages fetch empty, web_search that site for "dress code", "visitor guidelines", "photography", "prayer times" or "mass times". Fetch at most 6 pages; only fetch URLs you saw in a fetched page or a search result.',
  'Report ONLY what a fetched page or a cited search result states. Never use what places of this kind usually require, never your memory. A rule not written on a page you read is "unknown".',
  'For EVERY backed fact: quote = the source’s exact words (20–200 characters, verbatim, original language), quote_lang = its language code, source_url = the exact page, text = our plain-English line (at most 140 characters) written neutrally and respectfully, as the place’s request, never a judgment — say who MAY enter, never who is barred; no adjectives about the faith or the rule.',
  'Finish with ONLY the JSON inside <json></json> tags:',
  '{"entry":{"value":"open_to_all|restricted|closed_to_visitors|unknown","limits":["faith|gender|age|tour_only|permit|dress_enforced|other"],"text":"...","quote":"...","quote_lang":"en","source_url":"url"},',
  '"dress":{"value":"stated|unknown","items":["cover_shoulders|cover_knees|women_cover_hair|men_cover_head|remove_shoes|wraps_provided|other"],"text":"...","quote":"...","quote_lang":"en","source_url":"url"},',
  '"photography":{"value":"allowed|restricted|not_allowed|unknown","text":"...","quote":"...","quote_lang":"en","source_url":"url"},',
  '"closures":{"value":"stated|unknown","items":[{"kind":"prayer|service|ceremony|weekly|seasonal|other","text":"...","quote":"...","quote_lang":"en","source_url":"url"}]},',
  '"reservation":{"value":"required|recommended|not_needed|unknown","text":"...","quote":"...","quote_lang":"en","source_url":"url"},',
  '"security":{"value":"stated|unknown","items":["bag_check|no_large_bags|lockers|id_required|other"],"text":"...","quote":"...","quote_lang":"en","source_url":"url"},',
  '"accessibility":{"value":"stated|unknown","text":"<only the place’s own terms>","quote":"...","quote_lang":"en","source_url":"url"},',
  '"time_needed":{"value":90,"text":"...","quote":"...","quote_lang":"en","source_url":"url"},',
  '"other_rules":[{"text":"...","quote":"...","quote_lang":"en","source_url":"url"}]}',
  'Any fact without a quote you really read: {"value":"unknown"}.',
].join(' ');

// Normalize both sides before asking "is this quote really on that page?"
// (NFKC, lower case, straight quotes, one dash, no zero-widths, one space).
function bygNorm(t) {
  return String(t || '').normalize('NFKC').toLowerCase()
    .replace(/[‘’‚‛]/g, "'").replace(/[“”„‟]/g, '"')
    .replace(/[‐-―−]/g, '-').replace(/[​-‍﻿]/g, '')
    .replace(/\s+/g, ' ').trim();
}
// Allowed source for a fact: the official site (or a subdomain), a government
// domain, or a listed tourism body. Resellers, platforms (Wikipedia included),
// blogs and news never qualify. strict (entry: restricted) drops tourism bodies.
function bygAllowedSource(url, officialHost, strict) {
  const h = visitHost(url);
  if (!h) return false;
  if (visitOnList(url, VISIT_RESELLERS) || visitOnList(url, VISIT_PLATFORMS)) return false;
  if (officialHost && (h === officialHost || h.endsWith('.' + officialHost))) return true;
  if (BYG_GOV_RE.test(h)) return true;
  if (!strict && BYG_OFFICIAL_BODIES.some((d) => h === d || h.endsWith('.' + d))) return true;
  return false;
}
// One cheap support check for the whole batch: does each quote support its
// line? (The plan priced this per fact; one batched call is the same check at
// a fraction of the cost.) Fails closed: no answer means no fact.
async function bygSupports(env, pairs) {
  if (!pairs.length) return [];
  try {
    const r = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({
        model: 'claude-haiku-4-5-20251001', max_tokens: 200,
        system: 'For each numbered pair, answer whether QUOTE (any language) genuinely supports LINE — the line claims nothing the quote does not say. Reply ONLY a JSON array of booleans, one per pair, in order.',
        messages: [{ role: 'user', content: pairs.map((x, i) => (i + 1) + '. LINE: ' + x.text + '\nQUOTE: ' + x.quote).join('\n\n') }],
      }),
    });
    if (!r.ok) return pairs.map(() => false);
    const d = await r.json();
    const m = (d.content || []).filter((x) => x.type === 'text').map((x) => x.text).join('').match(/\[[^\]]*\]/);
    const arr = m ? JSON.parse(m[0]) : null;
    return pairs.map((_, i) => arr?.[i] === true);
  } catch { return pairs.map(() => false); }
}
// Every rule enforced by code, never trusted to the model: allowed source,
// quote really on the fetched page, every number in the line present in the
// quote, tone words rejected, then the batched support check.
async function bygVerify(env, raw, ev, officialHost) {
  const UNK = { value: 'unknown' };
  const out = { entry: UNK, dress: UNK, photography: UNK, closures: UNK, reservation: UNK, security: UNK, accessibility: UNK, time_needed: UNK, other_rules: [] };
  if (!raw || typeof raw !== 'object') return out;
  const candidates = []; // { slot, fact } pending the support check
  const pageText = (u) => { const t = ev.pages.get(visitUrlKey(u)); return t ? bygNorm(t) : null; };
  const backed = (f, strict) => {
    if (!f || typeof f !== 'object') return null;
    const quote = typeof f.quote === 'string' ? f.quote.trim() : '';
    const text = typeof f.text === 'string' ? f.text.replace(/\s+/g, ' ').trim().slice(0, 140) : '';
    if (quote.length < 20 || quote.length > 220 || !text) return null;
    if (BYG_TONE_RE.test(text)) return null;
    if (!bygAllowedSource(f.source_url, officialHost, strict)) return null;
    const page = pageText(f.source_url);
    if (!page || !page.includes(bygNorm(quote))) return null;
    const nq = bygNorm(quote);
    for (const n of (text.match(/\d+(?:[.,:]\d+)?/g) || [])) { if (!nq.includes(bygNorm(n))) return null; }
    return { text, quote, quote_lang: /^[a-z]{2,3}(-[A-Za-z]{2,4})?$/.test(String(f.quote_lang || '')) ? String(f.quote_lang) : 'en', source_url: String(f.source_url) };
  };
  const take = (slot, f, extra) => { const b2 = backed(f, slot === 'entry' && f?.value === 'restricted'); if (b2) candidates.push({ slot, fact: { ...extra, ...b2 } }); };

  const e = raw.entry;
  if (e && BYG_ENTRY.has(e.value) && e.value !== 'unknown') take('entry', e, { value: e.value, limits: (Array.isArray(e.limits) ? e.limits : []).filter((x) => BYG_ENTRY_LIMITS.has(x)).slice(0, 4) });
  const dr = raw.dress;
  if (dr && dr.value === 'stated') take('dress', dr, { value: 'stated', items: (Array.isArray(dr.items) ? dr.items : []).filter((x) => BYG_DRESS_ITEMS.has(x)).slice(0, 6) });
  const ph = raw.photography;
  if (ph && ['allowed', 'restricted', 'not_allowed'].includes(ph.value)) take('photography', ph, { value: ph.value });
  for (const it of (Array.isArray(raw.closures?.items) ? raw.closures.items : []).slice(0, 4)) {
    if (BYG_CLOSURE_KINDS.has(it?.kind)) take('closure', it, { kind: it.kind });
  }
  const rv = raw.reservation;
  if (rv && ['required', 'recommended', 'not_needed'].includes(rv.value)) take('reservation', rv, { value: rv.value });
  const sec = raw.security;
  if (sec && sec.value === 'stated') take('security', sec, { value: 'stated', items: (Array.isArray(sec.items) ? sec.items : []).filter((x) => BYG_SECURITY_ITEMS.has(x)).slice(0, 5) });
  const ac = raw.accessibility;
  if (ac && ac.value === 'stated') take('accessibility', ac, { value: 'stated' });
  const tn = raw.time_needed;
  if (tn && Number.isFinite(+tn.value) && +tn.value >= 10 && +tn.value <= 24 * 60) take('time_needed', tn, { value: Math.round(+tn.value) });
  for (const orr of (Array.isArray(raw.other_rules) ? raw.other_rules : []).slice(0, 3)) take('other_rule', orr, {});

  const verdicts = await bygSupports(env, candidates.map((c) => ({ text: c.fact.text, quote: c.fact.quote })));
  const closures = [], others = [];
  candidates.forEach((c, i) => {
    if (!verdicts[i]) return; // unsupported → stays unknown
    if (c.slot === 'closure') closures.push(c.fact);
    else if (c.slot === 'other_rule') others.push(c.fact);
    else out[c.slot] = c.fact;
  });
  if (closures.length) out.closures = { value: 'stated', items: closures };
  out.other_rules = others;
  return out;
}

// POST /attractions/before-you-go { id } → the verified facts (cached 90 days;
// 30 when everything is unknown). { id, report: true } is "Something's wrong?":
// clears the saved result so the next open rechecks, and logs byg_reported.
async function handleAttractionBeforeYouGo(request, env, ctx) {
  try {
    const b = await request.json().catch(() => ({}));
    const id = String(b.id || '').trim();
    if (!id || id.length > 200) return jsonResponse({ error: 'id required' }, 400);
    const kv = env.GLOBESKIMMERS_KV;
    const cacheKey = 'byg:' + BYG_VERSION + ':' + id;
    const user = await gbUser(request, env);
    if (b.report === true) {
      if (!user) return jsonResponse({ error: 'sign_in' }, 401);
      if (kv) await kv.delete(cacheKey).catch(() => {});
      if (ctx) ctx.waitUntil(gbLogEvent(env, 'byg_reported', { id }));
      return jsonResponse({ ok: true, cleared: true });
    }
    const cached = kv ? await kv.get(cacheKey, { type: 'json' }).catch(() => null) : null;
    if (cached) return jsonResponse({ ...cached, _cache: 'hit' });
    if (!user) return jsonResponse({ error: 'sign_in', message: 'Sign in to look up visiting rules' }, 401);
    if (!env.ANTHROPIC_API_KEY) return jsonResponse({ error: 'not configured' }, 500);

    let row = null;
    if (ttdIdKind(id) === 'google') {
      const dd = await ttdPlaceDetails(env, id, new URL(request.url).origin);
      if (dd) row = { id, name: dd.name, address: dd.formattedAddress || dd.address || '', website: dd.websiteUri || dd.website || null };
    } else if (env.ATTRACTIONS_DB) {
      row = await env.ATTRACTIONS_DB.prepare('SELECT * FROM attractions WHERE id = ?1 LIMIT 1').bind(id).first().catch(() => null);
    }
    if (!row) return jsonResponse({ error: 'Not found' }, 404);

    // The founder's prewarm script runs as admin and skips the daily caps.
    let isAdmin = false;
    try { isAdmin = !(await requireAdmin(request, env)); } catch { isAdmin = false; }
    if (kv) {
      if (await kv.get('byg:lock:' + id).catch(() => null)) return jsonResponse({ pending: true });
      if (!isAdmin) {
        const day = new Date().toISOString().slice(0, 10);
        const gk = 'byg:cap:' + day, uk = 'byg:cap:' + user.id + ':' + day;
        const [g, u] = await Promise.all([kv.get(gk).catch(() => 0), kv.get(uk).catch(() => 0)]);
        if ((Number(g) || 0) >= BYG_DAILY_CAP || (Number(u) || 0) >= BYG_USER_CAP) return jsonResponse({ error: 'busy', message: 'Rule lookups are paused for today — check the official site' }, 429);
        await Promise.all([
          kv.put(gk, String((Number(g) || 0) + 1), { expirationTtl: 2 * 86400 }),
          kv.put(uk, String((Number(u) || 0) + 1), { expirationTtl: 2 * 86400 }),
        ]).catch(() => {});
      }
      await kv.put('byg:lock:' + id, '1', { expirationTtl: 120 }).catch(() => {});
    }

    const work = (async () => {
      const site = await visitOfficialSite(row);
      const where = row.address || [row.city, row.country].filter(Boolean).join(', ');
      const host = site && !visitOnList(site, VISIT_PLATFORMS) ? visitHost(site) : null;
      const ask = await visitAsk(env,
        'Place: ' + row.name + (where ? '\nWhere: ' + where : '') + (site ? '\nOfficial website (from Wikidata/our records): ' + site : '') + '\nFind this place’s published visiting rules.',
        host, { system: BYG_PROMPT, fetchMax: 6, citations: true });
      const finalText = ask.blocks.filter((x) => x?.type === 'text').map((x) => x.text).join('\n');
      const m = finalText.match(/<json>([\s\S]*?)<\/json>/);
      let raw = null;
      try { raw = m ? JSON.parse(m[1]) : null; } catch { raw = null; }
      const ev = visitEvidence(ask.blocks);
      const facts = await bygVerify(env, raw, ev, host);
      const found = ['entry', 'dress', 'photography', 'closures', 'reservation', 'security', 'accessibility', 'time_needed'].some((k) => facts[k]?.value && facts[k].value !== 'unknown') || facts.other_rules.length > 0;
      const out = { ok: true, found, checked_at: new Date().toISOString(), official_site: site || null, ...facts };
      if (kv && !ask.error) await kv.put(cacheKey, JSON.stringify(out), { expirationTtl: found ? BYG_TTL : BYG_EMPTY_TTL }).catch(() => {});
      if (kv) await kv.delete('byg:lock:' + id).catch(() => {});
      await gbLogEvent(env, 'byg_lookup', {
        id, found, facts: Object.keys(facts).filter((k) => facts[k]?.value && facts[k].value !== 'unknown').length,
        fetched: ev.pages.size, in_tok: ask.usage?.input_tokens || 0, out_tok: ask.usage?.output_tokens || 0,
        searches: ask.usage?.searches || 0, stop: ask.stop || null, error: ask.error ? ask.error.slice(0, 200) : null,
      }).catch(() => {});
      return ask.error ? { ok: false, error: 'lookup_failed', official_site: site || null } : out;
    })();
    if (ctx) ctx.waitUntil(work.catch(() => {}));
    return jsonResponse(await work);
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// ── "Why visit" + the story + what you can do (founder, 2026-10-11) ──────────
// Written ON OPEN (no prefill — demand leads), from FREE facts only — the
// encyclopedia summary (by the row's Wikidata id, or a name match within 1 km
// of the pin; never named in the app), Google's editorial summary when the
// place's details are already cached (no new paid call is ever made here),
// and our own row — and kept FOREVER (KV wv:v1, no expiry; why_visit also
// lands in D1). Every guard is code: numbers and proper names must come from
// the inputs, no 8-word run copied from a source, no prices/hours/rules words
// in the Why-visit line, no marketing words, never "wiki". A line that fails
// is simply hidden — the page never shows a guess.
const WV_VERSION = 'v1';
const WV_DAILY_CAP = 300, WV_USER_CAP = 30;
const WV_MARKETING = /\b(must[- ]see|breathtaking|hidden gem|bucket[- ]list|stunning|unforgettable|world[- ]class|jaw[- ]dropping|magical|amazing|incredible|awe[- ]inspiring|unmissable|iconic)\b/i;
const WV_RULES = /(\$|€|£|¥|\b(tickets?|admission|prices?|fees?|free entry|opens? (at|from)|closes? at|closed on|dress code|forbidden|prohibited|not allowed|must book|reservations?)\b)/i;
const WV_PROMPT = [
  'You write for a travel app that never guesses. Using ONLY the facts given (nothing from memory), write three things about ONE place, as JSON inside <json></json>:',
  '"why_visit": one or two sentences, 25 to 45 words, in plain warm English: what it is, then why people go or what they see there. No prices, hours or rules. No marketing words.',
  '"story": two short paragraphs separated by a blank line, 60 to 110 words in total: the history and the human story — who, when, why — only from the facts given.',
  '"can_do": 3 to 5 lines of at most 12 words each, each starting with a verb, about what a visitor can actually do, see or reach there — ONLY if the facts say so (climb, enter, walk, picnic, eat, touch, swim…). Fewer lines is better than an invented one; an empty list is fine.',
  'Copy no phrase of 8 or more words from the facts. Every number and every proper name you write must appear in the facts. Places of worship are described as places of worship first, respectfully. Never write the word "wiki" or name any source.',
].join(' ');

// The nearest Wikidata item with this name (within 1 km of the pin) — free,
// and the distance check keeps another town's namesake out.
async function wvFindQid(name, lat, lng) {
  if (!name || !Number.isFinite(lat) || !Number.isFinite(lng)) return null;
  const s = await wikiJson(`https://www.wikidata.org/w/api.php?action=wbsearchentities&search=${encodeURIComponent(name)}&language=en&limit=5&format=json`).catch(() => null);
  const ids = (s?.search || []).map((x) => x.id).filter((x) => /^Q\d+$/.test(x)).slice(0, 5);
  if (!ids.length) return null;
  const e = await wikiJson(`https://www.wikidata.org/w/api.php?action=wbgetentities&ids=${ids.join('|')}&props=claims&format=json`).catch(() => null);
  let best = null;
  for (const q of ids) {
    const c = e?.entities?.[q]?.claims?.P625?.[0]?.mainsnak?.datavalue?.value;
    if (!c) continue;
    const d = calcDistance(lat, lng, +c.latitude, +c.longitude) * 1000;
    if (d <= 1000 && (!best || d < best.d)) best = { q, d };
  }
  return best ? best.q : null;
}
async function wvFacts(env, row) {
  const facts = { name: row.name, where: row.address || [row.city, row.country].filter(Boolean).join(', ') || null, category: row.category || null, description: row.description || null, extract: null, wd: null, google: row.google || null };
  let q = String(row.qid || (String(row.id).match(/Q\d+/) || [])[0] || '');
  if (!/^Q\d+$/.test(q)) q = (await wvFindQid(row.name, +row.lat, +row.lng).catch(() => null)) || '';
  if (/^Q\d+$/.test(q)) {
    try {
      const e = await wikiJson(`https://www.wikidata.org/w/api.php?action=wbgetentities&ids=${q}&props=sitelinks|descriptions&format=json`);
      const ent = e?.entities?.[q];
      facts.wd = ent?.descriptions?.en?.value || null;
      const title = ent?.sitelinks?.enwiki?.title;
      if (title) {
        const sum = await wikiJson(`https://en.wikipedia.org/api/rest_v1/page/summary/${encodeURIComponent(title.replace(/ /g, '_'))}`);
        if (sum?.extract) facts.extract = String(sum.extract).slice(0, 1800);
      }
    } catch { /* free facts are best-effort */ }
  }
  // Google's editorial summary, only from a details record we already hold.
  if (!facts.google && env.GLOBESKIMMERS_KV && ttdIdKind(row.id) === 'd1') {
    try {
      const gid = await env.GLOBESKIMMERS_KV.get(`d1gid:${row.id}`);
      const d = gid && gid !== 'none' ? await getFromCache(env, `details_${gid}`) : null;
      if (typeof d?.data?.editorialSummary === 'string' && d.data.editorialSummary.trim()) facts.google = d.data.editorialSummary.trim().slice(0, 400);
    } catch { /* optional */ }
  }
  return facts;
}
function wvGuard(text, facts, { maxChars, minWords, maxWords, noRules }) {
  if (typeof text !== 'string') return null;
  const t = text.replace(/[ \t]+/g, ' ').replace(/\s*\n\s*\n\s*/g, '\n\n').replace(/ *\n */g, '\n').trim();
  if (!t || t.length > maxChars) return null;
  const words = t.split(/\s+/);
  if (words.length < minWords || words.length > maxWords) return null;
  if (/wiki/i.test(t) || WV_MARKETING.test(t) || (noRules && WV_RULES.test(t))) return null;
  const pool = [facts.name, facts.where, facts.category, facts.description, facts.extract, facts.wd, facts.google].filter(Boolean).join(' ');
  const poolLower = pool.toLowerCase();
  // Every number must be in the facts.
  for (const n of (t.match(/\d+(?:[.,]\d+)?/g) || [])) if (!pool.includes(n)) return null;
  // Every proper name (a capitalized word that doesn't open its sentence) must be in the facts.
  for (const sentence of t.split(/(?<=[.!?])\s+|\n+/)) {
    const toks = sentence.split(/\s+/);
    for (let i = 1; i < toks.length; i++) {
      const w = toks[i].replace(/^[("'“‘]+|[)"'”’.,;:!?]+$/g, '');
      if (/^[A-Z][a-zA-Z’'-]+$/.test(w) && !poolLower.includes(w.toLowerCase())) return null;
    }
  }
  // No 8-word run copied from any source text.
  const norm = (x) => String(x || '').toLowerCase().replace(/[^a-z0-9\s]/g, ' ').replace(/\s+/g, ' ').trim().split(' ');
  const outW = norm(t);
  for (const src of [facts.extract, facts.google, facts.description].filter(Boolean)) {
    const sw = norm(src); const grams = new Set();
    for (let i = 0; i + 8 <= sw.length; i++) grams.add(sw.slice(i, i + 8).join(' '));
    for (let i = 0; i + 8 <= outW.length; i++) if (grams.has(outW.slice(i, i + 8).join(' '))) return null;
  }
  return t;
}

// POST /attractions/why-visit { id } → { why_visit, story, can_do, checked_at }.
// { id, report: true } is "Something's wrong?": clears the saved text so the
// next open rewrites it, and logs wv_reported for the admin. That includes
// the copy in our own row (D1 attractions.why_visit) when the ENGINE wrote
// it: the engine marks every line it writes there (KV wv:eng:<id> = the exact
// line, no expiry — no new column, no SQL to run), and a report empties the
// column only while it still holds that exact line. A line a person wrote or
// approved carries no mark and stays (founder, 2026-10-13).
async function handleAttractionWhyVisit(request, env, ctx) {
  try {
    const b = await request.json().catch(() => ({}));
    const id = String(b.id || '').trim();
    if (!id || id.length > 200) return jsonResponse({ error: 'id required' }, 400);
    const kv = env.GLOBESKIMMERS_KV;
    const cacheKey = `wv:${WV_VERSION}:${id}`;
    const engKey = `wv:eng:${id}`;
    const user = await gbUser(request, env);
    if (b.report === true) {
      if (!user) return jsonResponse({ error: 'sign_in' }, 401);
      if (kv) await kv.delete(cacheKey).catch(() => {});
      let lineCleared = false;
      if (kv && env.ATTRACTIONS_DB && ttdIdKind(id) === 'd1') {
        const eng = await kv.get(engKey).catch(() => null);
        if (eng) {
          const res = await env.ATTRACTIONS_DB.prepare("UPDATE attractions SET why_visit = '' WHERE id = ?1 AND why_visit = ?2").bind(id, eng).run().catch(() => null);
          if (res) {
            lineCleared = Number(res.meta?.changes || 0) > 0;
            await kv.delete(engKey).catch(() => {});
          }
        }
      }
      if (ctx) ctx.waitUntil(gbLogEvent(env, 'wv_reported', { id, line_cleared: lineCleared }));
      return jsonResponse({ ok: true, cleared: true });
    }
    const cached = kv ? await kv.get(cacheKey, { type: 'json' }).catch(() => null) : null;
    if (cached) return jsonResponse({ ...cached, _cache: 'hit' });
    if (!user) return jsonResponse({ error: 'sign_in' }, 401);
    if (!env.ANTHROPIC_API_KEY) return jsonResponse({ error: 'not configured' }, 500);
    let row = null;
    if (ttdIdKind(id) === 'google') {
      const d = await ttdPlaceDetails(env, id, new URL(request.url).origin);
      if (d) row = { id, name: d.name, address: d.address || '', lat: d.latitude, lng: d.longitude, category: d.primaryTypeDisplay || null, description: null, google: d.editorialSummary || null };
    } else if (env.ATTRACTIONS_DB) {
      row = await env.ATTRACTIONS_DB.prepare('SELECT * FROM attractions WHERE id = ?1 LIMIT 1').bind(id).first().catch(() => null);
    }
    if (!row) return jsonResponse({ error: 'Not found' }, 404);
    // The founder's prewarm script runs as admin and skips the daily caps.
    let isAdmin = false;
    try { isAdmin = !(await requireAdmin(request, env)); } catch { isAdmin = false; }
    if (kv) {
      if (await kv.get(`wv:lock:${id}`).catch(() => null)) return jsonResponse({ pending: true });
      if (!isAdmin) {
        const day = new Date().toISOString().slice(0, 10);
        const gk = `wv:cap:${day}`, uk = `wv:cap:${user.id}:${day}`;
        const [g, u] = await Promise.all([kv.get(gk).catch(() => 0), kv.get(uk).catch(() => 0)]);
        if ((Number(g) || 0) >= WV_DAILY_CAP || (Number(u) || 0) >= WV_USER_CAP) return jsonResponse({ ok: false, error: 'busy' }, 429);
        await Promise.all([
          kv.put(gk, String((Number(g) || 0) + 1), { expirationTtl: 2 * 86400 }),
          kv.put(uk, String((Number(u) || 0) + 1), { expirationTtl: 2 * 86400 }),
        ]).catch(() => {});
      }
      await kv.put(`wv:lock:${id}`, '1', { expirationTtl: 90 }).catch(() => {});
    }
    const work = (async () => {
      const facts = await wvFacts(env, row);
      const enough = !!(facts.extract || facts.google || (facts.description && facts.description.length > 80));
      let why = null, story = null, canDo = [], usage = null;
      if (enough) {
        const factText = ['Name: ' + facts.name, facts.where ? 'Where: ' + facts.where : '', facts.category ? 'Category: ' + facts.category : '', facts.wd ? 'Short description: ' + facts.wd : '', facts.description ? 'Our note: ' + facts.description : '', facts.google ? 'Editorial summary: ' + facts.google : '', facts.extract ? 'Encyclopedia summary: ' + facts.extract : ''].filter(Boolean).join('\n');
        const r = await fetch('https://api.anthropic.com/v1/messages', {
          method: 'POST',
          headers: { 'x-api-key': env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
          body: JSON.stringify({ model: VISIT_INFO_MODEL, max_tokens: 700, system: WV_PROMPT, messages: [{ role: 'user', content: factText }] }),
        }).catch(() => null);
        const d = r && r.ok ? await r.json().catch(() => null) : null;
        usage = d?.usage || null;
        const txt = (d?.content || []).filter((x) => x.type === 'text').map((x) => x.text).join('');
        const m = txt.match(/<json>([\s\S]*?)<\/json>/);
        let raw = null; try { raw = m ? JSON.parse(m[1]) : null; } catch { raw = null; }
        if (raw) {
          why = wvGuard(raw.why_visit, facts, { maxChars: 300, minWords: 15, maxWords: 50, noRules: true });
          story = wvGuard(raw.story, facts, { maxChars: 800, minWords: 40, maxWords: 130, noRules: false });
          canDo = (Array.isArray(raw.can_do) ? raw.can_do : []).map((l) => wvGuard(l, facts, { maxChars: 90, minWords: 2, maxWords: 12, noRules: true })).filter(Boolean).slice(0, 5);
        }
      }
      // A line a person already blessed in D1 stays the Why-visit, forever.
      const existing = typeof row.why_visit === 'string' && row.why_visit.trim().length > 20 ? row.why_visit.trim() : null;
      const out = { ok: true, why_visit: existing || why, story, can_do: canDo, checked_at: new Date().toISOString() };
      if (kv && (out.why_visit || story || canDo.length)) await kv.put(cacheKey, JSON.stringify(out)).catch(() => {}); // no expiry: ours, forever
      if (kv) await kv.delete(`wv:lock:${id}`).catch(() => {});
      if (!existing && why && env.ATTRACTIONS_DB && ttdIdKind(id) === 'd1') {
        // The mark goes first: a stale mark is harmless (a report clears only
        // a column that still holds exactly this line), a missing one is not.
        if (kv) await kv.put(engKey, why).catch(() => {});
        await env.ATTRACTIONS_DB.prepare("UPDATE attractions SET why_visit = ?1 WHERE id = ?2 AND (why_visit IS NULL OR why_visit = '')").bind(why, id).run().catch(() => {});
      }
      await gbLogEvent(env, 'wv_written', { id, enough, why: !!out.why_visit, story: !!story, can_do: canDo.length, extract: !!facts.extract, google: !!facts.google, in_tok: usage?.input_tokens || 0, out_tok: usage?.output_tokens || 0 }).catch(() => {});
      return out;
    })();
    if (ctx) ctx.waitUntil(work.catch(() => {}));
    return jsonResponse(await work);
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

async function handleAttractionVisitInfo(request, env, ctx) {
  try {
    if (!env.ATTRACTIONS_DB) return jsonResponse({ error: 'not configured' }, 500);
    const b = await request.json().catch(() => ({}));
    const id = String(b.id || '').trim();
    if (!id || id.length > 200) return jsonResponse({ error: 'id required' }, 400);
    const cacheKey = `visit:${VISIT_INFO_VERSION}:${id}`;
    const kv = env.GLOBESKIMMERS_KV;
    const cached = kv ? await kv.get(cacheKey, { type: 'json' }).catch(() => null) : null;
    if (cached) return jsonResponse({ ...cached, _cache: 'hit' });

    // A saved result is free for anyone to read; a NEW lookup is paid (Claude +
    // search, and Google details for a Google id), so only a signed-in traveler
    // starts one (founder, 2026-10-03: the app is signed-in only — this closes
    // the door to callers outside it).
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'sign_in', message: 'Sign in to look up prices' }, 401);

    // SELECT * — the facts columns (website, ticket_price, parking_text) only
    // exist once scripts/city-icons/data/add_attraction_facts.sql has run.
    // Any Things to Do place works too: a Google id reads its name and website
    // from Google's details.
    let row = null;
    if (ttdIdKind(id) === 'google') {
      const d = await ttdPlaceDetails(env, id, new URL(request.url).origin);
      if (d) row = { id, name: d.name, address: d.formattedAddress || d.address || '', website: d.websiteUri || d.website || null };
    } else {
      row = await env.ATTRACTIONS_DB.prepare('SELECT * FROM attractions WHERE id = ?1 LIMIT 1').bind(id).first().catch(() => null);
    }
    if (!row) return jsonResponse({ error: 'Not found' }, 404);
    if (!env.ANTHROPIC_API_KEY) return jsonResponse({ error: 'not configured' }, 500);
    const who = user.id;

    if (kv) {
      if (await kv.get(`visit:lock:${id}`).catch(() => null)) return jsonResponse({ pending: true });
      const day = new Date().toISOString().slice(0, 10);
      const gk = `visit:cap:${day}`, uk = `visit:cap:${who}:${day}`;
      const [g, u] = await Promise.all([kv.get(gk).catch(() => 0), kv.get(uk).catch(() => 0)]);
      if ((Number(g) || 0) >= VISIT_INFO_DAILY_CAP || (Number(u) || 0) >= VISIT_INFO_USER_CAP) return jsonResponse({ error: 'busy', message: 'Price lookups are paused for today — check the official site' }, 429);
      await Promise.all([
        kv.put(gk, String((Number(g) || 0) + 1), { expirationTtl: 2 * 86400 }),
        kv.put(uk, String((Number(u) || 0) + 1), { expirationTtl: 2 * 86400 }),
        kv.put(`visit:lock:${id}`, '1', { expirationTtl: 120 }),
      ]).catch(() => {});
    }

    const work = (async () => {
      const site = await visitOfficialSite(row);
      const where = row.address || [row.city, row.country].filter(Boolean).join(', ');
      const host = site && !visitOnList(site, VISIT_PLATFORMS) ? visitHost(site) : null;
      const ask = await visitAsk(env, `Attraction: ${row.name}${where ? `\nWhere: ${where}` : ''}${site ? `\nOfficial website (from Wikidata/our records): ${site}` : ''}\nFind admission prices by audience, discounts, and parking with prices.`, host);
      const finalText = ask.blocks.filter((x) => x?.type === 'text').map((x) => x.text).join('\n');
      const m = finalText.match(/<json>([\s\S]*?)<\/json>/);
      let raw = null;
      try { raw = m ? JSON.parse(m[1]) : null; } catch { raw = null; }
      const ev = visitEvidence(ask.blocks);
      const info = visitVerify(raw, ev);
      if (!info.official_site && site) info.official_site = site;
      const found = info.admission.prices.length > 0 || info.admission.free === true || info.parking.options.length > 0;
      const out = { ok: true, found, checked_at: new Date().toISOString(), ...info };
      if (kv && !ask.error) await kv.put(cacheKey, JSON.stringify(out), { expirationTtl: found ? VISIT_INFO_TTL : VISIT_INFO_EMPTY_TTL }).catch(() => {});
      if (kv) await kv.delete(`visit:lock:${id}`).catch(() => {});
      await gbLogEvent(env, 'visit_info_lookup', {
        id, found, prices: info.admission.prices.length, parking: info.parking.options.length,
        fetched: ev.pages.size, raw_prices: Array.isArray(raw?.admission?.prices) ? raw.admission.prices.length : null,
        in_tok: ask.usage?.input_tokens || 0, out_tok: ask.usage?.output_tokens || 0, searches: ask.usage?.searches || 0, stop: ask.stop || null, error: ask.error ? ask.error.slice(0, 200) : null,
      }).catch(() => {});
      const _diag = { queries: ask.blocks.filter((x) => x?.type === 'server_tool_use' && x.name === 'web_search').map((x) => String(x.input?.query || '').slice(0, 80)), fetched: ev.pages.size, seen: ev.seen.size, raw_prices: Array.isArray(raw?.admission?.prices) ? raw.admission.prices.length : null, raw_parking: Array.isArray(raw?.parking?.options) ? raw.parking.options.length : null, in_tok: ask.usage?.input_tokens || 0, out_tok: ask.usage?.output_tokens || 0, stop: ask.stop || null, pages: [...ev.pages.keys()].slice(0, 6) };
      return ask.error ? { ok: false, error: 'lookup_failed', detail: ask.error.slice(0, 200), official_site: info.official_site, _diag } : { ...out, _diag };
    })();
    if (ctx) ctx.waitUntil(work.catch(() => {}));
    return jsonResponse(await work);
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

async function handleHomeRows(request, env, ctx) {
  const startedAt = Date.now();
  let body;
  try { body = await request.json(); }
  catch { return jsonResponse({ error: 'Invalid JSON body' }, 400); }

  const { latitude, longitude, localHour, weather, season, cityName = '', countryName = '' } = body || {};
  if (typeof latitude !== 'number' || typeof longitude !== 'number') {
    return jsonResponse({ error: 'latitude and longitude required' }, 400);
  }

  const dayPart = homeRowsDayPart(localHour);
  const weatherBucket = (weather || 'unknown').toString().toLowerCase();
  const seasonKey = (season || '').toString().toLowerCase();

  // Coarse (0.1°) key so nearby users share the bundle; dayPart + weather in the
  // key make the homepage reshuffle across the day.
  const rLat = Math.round(latitude * 10) / 10;
  const rLng = Math.round(longitude * 10) / 10;
  const cacheKey = `homerows_v4_${rLat}_${rLng}_${dayPart}_${weatherBucket}`;   // v4: whereToNext cards carry lat/lng/tempF (v3 bundles lack them; v3: deduped pool + P18-by-QID photos)

  const cachedBundle = await env.GLOBESKIMMERS_KV.get(cacheKey, { type: 'json' }).catch(() => null);
  if (cachedBundle && Array.isArray(cachedBundle.rows)) {
    return jsonResponse({ ...cachedBundle, cached: true, tookMs: Date.now() - startedAt });
  }

  // Owned attractions via the existing D1 handler (reuses its bounding-box query
  // + background-seed trigger). No Google Places spend.
  let attractions = [];
  try {
    const origin = new URL(request.url).origin;
    const res = await handleAttractionsNearby(new Request(`${origin}/attractions/nearby`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ latitude, longitude, radiusKm: 60, limit: 60, cityName, countryName }),
    }), env, ctx);
    const data = await res.json();
    attractions = Array.isArray(data.attractions) ? data.attractions : [];
  } catch (e) {
    console.error('home/rows attractions fetch failed:', e?.message);
  }

  // No CURATED coverage → fall back to the owned PLANET DB (75M places) so the
  // living rows populate everywhere, not just seeded cities. This is the fix for
  // "Home goes empty in suburbs like Santa Clarita."
  if (attractions.length === 0) {
    attractions = await homeRowsPlanetPool(env, latitude, longitude);
  }

  // Still nothing (rare) → empty rows so the client
  // shows its cold-start fallback, never an empty carousel. Unsplash inspiration
  // rows will fill this globally once wired.
  if (attractions.length === 0) {
    // No owned coverage — still offer global Unsplash inspiration so the page
    // isn't empty. If Unsplash isn't configured, fall back to the cold-start.
    const wtn = await buildWhereToNextRow(env, seasonKey, ctx);
    return jsonResponse({ rows: wtn ? [wtn] : [], dayPart, reason: wtn ? undefined : 'no_owned_coverage', tookMs: Date.now() - startedAt });
  }

  const trim = (a) => ({
    id: a.id, name: a.name, category: a.category, city: a.city, country: a.country,
    photoUrl: a.photoUrl, rating: a.rating, whyVisit: a.whyVisit,
    distanceMiles: a.distanceMiles, freeToVisit: a.freeToVisit, lat: a.lat, lng: a.lng,
    footprint_radius_m: a.footprint_radius_m ?? null, popularity: a.popularity ?? null, tier: a.tier || 'page',
    qid: a.qid || null,
  });
  const withPhoto = attractions.filter((a) => a.photoUrl);
  const pool = withPhoto.length >= 6 ? withPhoto : attractions;

  // Rows draw from the pool INDEPENDENTLY (mild overlap ok) so even a small owned
  // pool yields several distinct rows — each row's different ordering (rotated /
  // nearest / marquee) keeps them from looking identical.
  const take = (list, n) => list.slice(0, n).map(trim);

  const rows = [];

  // Trending row — most-tapped places (last 7d, from home_row_card_tap events)
  // that are ALSO nearby (intersect ranked place_ids with the local pool → geo-
  // scoped without fragile city-string matching). Leads when present; silently
  // skipped until there's enough data (cold-start). The title says what the
  // data IS — tapped places near you — never "Trending in {city}": the tap
  // payload's city is the CARD's city (Six Flags rows say "Valencia"), so a
  // city-string filter would silently empty the row. Reads env.DB (events
  // D1); result is cached with the bundle (6hr), one query per tile per day-part.
  if (env.DB) {
    try {
      const q = await env.DB.prepare(
        `SELECT json_extract(payload,'$.place_id') AS pid, COUNT(*) AS c
           FROM events
          WHERE event_type = 'home_row_card_tap'
            AND ts >= strftime('%s','now','-7 days')
          GROUP BY pid
          ORDER BY c DESC
          LIMIT 60`
      ).all();
      const byId = new Map(pool.map((a) => [String(a.id), a]));
      const trendingCards = [];
      for (const r of (q?.results || [])) {
        const a = byId.get(String(r.pid));
        if (a) trendingCards.push(trim(a));
        if (trendingCards.length >= 10) break;
      }
      if (trendingCards.length >= 4) {
        rows.push({
          key: 'trending',
          title: 'Trending near you',
          subtitle: 'Most-tapped nearby this week',
          seeAll: { action: 'Things to Do' },
          cards: trendingCards,
        });
      }
    } catch (e) { console.error('home/rows trending query failed:', e?.message); }
  }

  // Partition tracker: each attraction row below draws only cards no earlier
  // row used (trending claimed its cards first). This is what makes "no
  // destination twice per scroll" produce SEVERAL distinct rows instead of one
  // row plus casualties — overlap-then-dedup collapsed small pools entirely.
  const used = new Set(rows.flatMap((r) => r.cards.map((c) => String(c.id))));
  const claim = (cards) => { for (const c of cards) used.add(String(c.id)); return cards; };

  // Row 1 — rotated by day-part so morning vs evening opens differ visibly.
  // The rotation is NOT a time-of-day filter, so the title no longer claims
  // one ("Tonight nearby" put a daytime lab under an evening banner). It says
  // the two things we do know: the city, and the weather when we have it.
  const order = ['earlyMorning', 'morning', 'midday', 'afternoon', 'evening', 'lateNight'];
  const off = pool.length ? (Math.max(0, order.indexOf(dayPart)) % pool.length) : 0;
  const rotated = pool.slice(off).concat(pool.slice(0, off));
  const wAccent = HOME_WEATHER_ACCENT[weatherBucket];
  const dpCards = claim(take(rotated.filter((a) => !used.has(String(a.id))), 10));
  if (dpCards.length) rows.push({ key: 'dayPart', title: cityName ? `Around ${cityName}` : 'Around you', subtitle: wAccent || 'Worth a look', seeAll: { action: 'Things to Do' }, cards: dpCards });

  // Row 2 — nearest to you now.
  const nearest = [...pool].sort((a, b) => (a.distanceMiles ?? 1e9) - (b.distanceMiles ?? 1e9));
  const nearCards = claim(take(nearest.filter((a) => !used.has(String(a.id))), 10));
  if (nearCards.length) rows.push({ key: 'nearYou', title: 'Near you now', subtitle: 'Closest to where you are', seeAll: { action: 'Things to Do' }, cards: nearCards });

  // (The former "seasonal" row is gone: it was whatever the rows above left
  // in the pool, labelled from the calendar — "Golden-season picks" on a
  // 99°F day. seasonKey still drives the Where-to-next destinations below.)

  // Where to next — global Creative-Commons inspiration (Openverse), a nice closer.
  const wtn = await buildWhereToNextRow(env, seasonKey, ctx);
  if (wtn) rows.push(wtn);

  // Photo fallback: owned attraction cards with no photo yet → fetch a real
  // Creative-Commons photo (Openverse aggregates Wikimedia + Flickr) by
  // "{name}, {city}" so the feed is photo-forward (cached 30d). No API key needed.
  // Parallel + capped so first build stays fast; cards that already have a photo
  // are skipped.
  {
    // Photo fill, two passes. Pass 1 — canonical P18 by KNOWN QID (wrong-match-
    // proof), grouped so each QID fetches once and fills every card that shares
    // it. Pass 2 — the content-safe Openverse picker, ONLY for qid-less cards
    // (planet-pool fallback rows) or entities with no P18.
    const photoless = [];
    for (const r of rows) for (const c of r.cards) { if (!c.photoUrl && c.name) photoless.push(c); }
    const byQid = new Map();
    for (const c of photoless) {
      if (!c.qid) continue;
      if (!byQid.has(c.qid)) byQid.set(c.qid, []);
      byQid.get(c.qid).push(c);
    }
    await Promise.all([...byQid.keys()].slice(0, 40).map(async (qid) => {
      const photo = await getWikiPhotoByQid(env, qid);
      if (photo?.url) for (const c of byQid.get(qid)) { c.photoUrl = photo.url; c.photographer = photo.photographer; c.credit = photo.credit; c.creditLink = photo.link; }
    }));
    const byQuery = new Map();
    for (const c of photoless) {
      if (c.photoUrl) continue;
      const q = cleanPhotoQuery(c.name, c.city, c.country);
      if (!q) continue;
      if (!byQuery.has(q)) byQuery.set(q, []);
      byQuery.get(q).push(c);
    }
    await Promise.all([...byQuery.keys()].slice(0, 30).map(async (q) => {
      const photo = await fetchOpenversePhoto(env, q, ctx);
      if (photo?.url) for (const c of byQuery.get(q)) { c.photoUrl = photo.url; c.photographer = photo.photographer; c.credit = photo.credit; c.creditLink = photo.link; }
    }));
  }

  // One deduped pool per render (brief Part Five #3): a destination appears
  // ONCE per bundle. First appearance wins — push order makes trending >
  // dayPart > nearYou > seasonal the priority — and rows thinned under 3
  // cards are dropped rather than rendered threadbare.
  {
    const seen = new Set();
    for (const r of rows) {
      r.cards = r.cards.filter((c) => {
        const k = String(c.id || c.name);
        if (seen.has(k)) return false;
        seen.add(k);
        return true;
      });
    }
    for (let i = rows.length - 1; i >= 0; i--) {
      if (rows[i].key !== 'whereToNext' && rows[i].cards.length < 3) rows.splice(i, 1);
    }
  }

  const bundle = { rows, dayPart };
  const store = env.GLOBESKIMMERS_KV.put(cacheKey, JSON.stringify(bundle), { expirationTtl: HOME_ROWS_TTL_SECONDS }).catch(() => {});
  if (ctx && ctx.waitUntil) ctx.waitUntil(store); else await store;

  return jsonResponse({ ...bundle, cached: false, tookMs: Date.now() - startedAt });
}

