// One rule for the photos and doodles members post (founder, 2026-10-27: "remove limits to
// posting"; the same as City Board contributions): no daily allowance a traveler would feel.
// 60 a minute stops a script's burst, and 1,000 a day caps one running all day (each upload is
// a paid photo check). A refusal Response, or null.
const POST_PER_MINUTE = 60, POST_PER_DAY = 1000;
async function gbPostGuard(env, name) {
  const kv = env.GLOBESKIMMERS_KV;
  if (kv) {
    const mk = `pg:min:${name}:${Math.floor(Date.now() / 60000)}`;
    const n = Number(await kv.get(mk).catch(() => 0)) || 0;
    if (n >= POST_PER_MINUTE) return jsonResponse({ error: 'That’s a lot at once — wait a minute and keep going', code: 'slow_down' }, 429);
    await kv.put(mk, String(n + 1), { expirationTtl: 120 }).catch(() => {});
  }
  const d = await gbDayCount(env, `pg:${name}`);
  if (d != null && d > POST_PER_DAY) return jsonResponse({ error: 'That’s 1,000 photos today, the most for one day. Add the rest tomorrow.', code: 'day_full' }, 429);
  return null;
}
// Upload one guestbook photo → moderate → store in R2 → return a servable URL.
// The client resizes to ~1280px JPEG before sending (keeps payload small). The photo
// is NOT attached to an entry here; the returned {key,url} is passed to /guestbook/sign.
async function handleGuestbookPhotoUpload(request, env, ctx) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in to add a photo' }, 401);
    // A guestbook photo or doodle is a public post: the posting doors apply
    // before anything is moderated or stored (go-live round 2) — a frozen
    // account, a birth year still to confirm or a held teen can't upload one,
    // and an age that can't be read refuses. (Such an upload used to land in
    // R2 and wait for a sign that would be refused.)
    const sp = await gbSocialProfile(env, user.id).catch(() => undefined);
    if (sp === undefined) return gbAgeUnknownResp();
    if (gbUnderAge(sp)) return gbUnderAgeResp();
    if (gbAgeHeld(sp)) return gbAgeHeldResp(sp);
    if (!env.MEDIA) return jsonResponse({ error: 'Photo storage not configured' }, 500);
    const b = await request.json().catch(() => ({}));
    const entityId = gbClean(b.entity_id);
    if (!entityId) return jsonResponse({ error: 'entity_id required' }, 400);

    // Accept a data URL or a bare base64 string; jpeg/png/webp only.
    let data = String(b.image || '');
    let mediaType = 'image/jpeg';
    const m = data.match(/^data:(image\/(?:jpeg|jpg|png|webp));base64,(.*)$/i);
    if (m) { mediaType = m[1].toLowerCase() === 'image/jpg' ? 'image/jpeg' : m[1].toLowerCase(); data = m[2]; }
    else if (b.content_type && /^image\/(jpeg|png|webp)$/i.test(b.content_type)) { mediaType = String(b.content_type).toLowerCase(); }
    data = data.replace(/\s/g, '');
    if (!data) return jsonResponse({ error: 'No image data' }, 400);

    let bytes;
    try { bytes = Uint8Array.from(atob(data), (c) => c.charCodeAt(0)); }
    catch { return jsonResponse({ error: 'Bad image data' }, 400); }
    if (bytes.length > 4 * 1024 * 1024) return jsonResponse({ error: 'Photo too large (please pick a smaller image)' }, 400);
    if (bytes.length < 500) return jsonResponse({ error: 'That image is too small' }, 400);

    // The posting guard (gbPostGuard: 60 a minute, 1,000 a day; was 20 a day until 2026-10-27),
    // counted before the paid moderation call.
    const guard = await gbPostGuard(env, `gbup:${user.id}`);
    if (guard) return guard;

    // Moderate BEFORE storing (fails closed). Doodles get the drawing door.
    const isDoodle = b.doodle === true;
    const mod = isDoodle ? await gbModerateDoodle(env, data, mediaType) : await gbModeratePhoto(env, data, mediaType);
    if (!mod.allow) {
      if (ctx) ctx.waitUntil(gbLogEvent(env, 'guestbook_photo_blocked', { entity_id: entityId, doodle: isDoodle, reason: mod.reason || 'content' }));
      return jsonResponse({ error: isDoodle ? "That drawing can't be posted." : "That photo can't be posted. Please share a photo of the food, drink, or place." }, 400);
    }

    const ext = mediaType === 'image/png' ? 'png' : mediaType === 'image/webp' ? 'webp' : 'jpg';
    // Stored under the uploader (go-live round 3): gb/u/<uid>/<uuid>.<ext>,
    // so one account's files are one prefix, which the under-13 clean-up
    // lists instead of all of gb/. Keys from before named the place first
    // (gb/<place>/<uid>/…); gbUploadOwner reads both.
    const key = `gb/u/${user.id}/${crypto.randomUUID()}.${ext}`;
    await env.MEDIA.put(key, bytes, { httpMetadata: { contentType: mediaType, cacheControl: 'public, max-age=31536000, immutable' } });
    if (ctx) ctx.waitUntil(gbLogEvent(env, 'guestbook_photo_upload', { entity_id: entityId, bytes: bytes.length }));
    const origin = new URL(request.url).origin;
    return jsonResponse({ key, url: `${origin}/gb-photo/${key}`, w: parseInt(b.w, 10) || null, h: parseInt(b.h, 10) || null });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// Public media by row, never by key (go-live round 3). An upload's R2 key
// names its author's account (gb/<place>/<uid>/…, gb/u/<uid>/…, dish/<uid>/…,
// bl/<owner>/<author>/…, pp/<uid>/…), so the URLs that public reads handed
// out let anyone link an anonymous minor's notes, dish photos and doodles to
// one account — and named a public passport's owner. Public reads now hand
// out /gb-photo/n/<note id>, /dish-photo/d/<dish id>, /bl-doodle/e/<entry
// id> and /pp-photo/p/<photo id>; the server looks the key up by the row
// and serves only what that row still shows. The keys in storage are
// unchanged (the clean-ups find files by them), and the key URLs still
// serve, for an author's own upload previews and older stored links.
// gbRowMedia: the R2 object for one row, or null. `table` and `cols` are
// fixed by the callers; `ok` decides from the row whether it still shows.
async function gbRowMedia(env, table, id, col, ok) {
  if (!env.MEDIA || !BL_UUID.test(String(id || ''))) return null;
  const q = await gbRest(env, `${table}?id=eq.${id}&select=*`, {});
  const row = q.ok ? (await q.json())[0] : null;
  const key = row && ok(row) ? row[col] : null;
  if (!key || typeof key !== 'string' || key.includes('..')) return null;
  return env.MEDIA.get(key);
}
function gbMediaResp(obj, type, cache) {
  if (!obj) return new Response('Not found', { status: 404 });
  const headers = new Headers();
  headers.set('Content-Type', obj.httpMetadata?.contentType || type);
  headers.set('Cache-Control', cache);
  headers.set('Access-Control-Allow-Origin', '*');
  headers.set('X-Content-Type-Options', 'nosniff');
  if (obj.httpEtag) headers.set('ETag', obj.httpEtag);
  return new Response(obj.body, { headers });
}

// Serve a stored guestbook photo from R2 (zero-egress; long-cached at the edge).
// /gb-photo/n/<note id>: a note's photo by the note, while it isn't deleted.
async function handleGuestbookPhotoServe(request, env) {
  try {
    if (!env.MEDIA) return new Response('Not found', { status: 404 });
    const path = new URL(request.url).pathname;
    const byRow = /^\/gb-photo\/n\/([0-9a-f-]{36})$/i.exec(path);
    if (byRow) return gbMediaResp(await gbRowMedia(env, 'guestbook_entries', byRow[1], 'photo_key', (r) => !r.deleted_at && String(r.photo_key || '').startsWith('gb/')), 'image/jpeg', 'public, max-age=3600');
    const key = decodeURIComponent(path.replace(/^\/gb-photo\//, ''));
    if (!key || key.includes('..') || !key.startsWith('gb/')) return new Response('Bad key', { status: 400 });
    const obj = await env.MEDIA.get(key);
    if (!obj) return new Response('Not found', { status: 404 });
    const headers = new Headers();
    headers.set('Content-Type', obj.httpMetadata?.contentType || 'image/jpeg');
    headers.set('Cache-Control', 'public, max-age=31536000, immutable');
    headers.set('Access-Control-Allow-Origin', '*');
    if (obj.httpEtag) headers.set('ETag', obj.httpEtag);
    return new Response(obj.body, { headers });
  } catch { return new Response('Error', { status: 500 }); }
}

// ─── PASSPORT (personal, private) ────────────────────────────────────────────
// "I was here" → an EARNED, permanent stamp with the user's own photos. Private
// per user (RLS on, no client policies; Worker reads/writes with the service key,
// scoped to the user_id resolved from their JWT via gbUser). Tiered stamps (page
// vs attraction mark); three earning paths — gps / photo-proof / self — where gps
// and photo earn the ✓. See docs/PASSPORT_MEANING_MODEL.md.
const PP_KINDS = ['country', 'city', 'airport', 'icon', 'wonder', 'attraction', 'state'];
// Verification strength (founder, 2026-09-28: three ways to earn the ✓). gps =
// the phone was at the place; photo_loc = a photo's own location tag puts it
// there on the visit date; photo_ai = the place is recognised in the photo;
// photo = a memory photo, no proof; self = declared. Only the first three earn
// the ✓. A re-stamp or a new photo never lowers a stamp's rank.
// reported = granted through "I'm here, but the app is saying I'm not"
// (founder, 2026-10-10): stamped, never ✓, and any real proof outranks it.
const PP_VERIFY_RANK = { self: 0, reported: 0.5, photo: 1, photo_ai: 2, photo_loc: 3, gps: 4 };
const PP_VERIFIED = new Set(['gps', 'photo_loc', 'photo_ai']);
const ppDate = (s) => (/^\d{4}-\d{2}-\d{2}$/.test(String(s || '')) ? String(s) : null);
// How far back a visit can be stamped (founder, 2026-10-14: "all the way back from Jan 1,
// 2026"), and never later than tomorrow in UTC (a traveler ahead of UTC is already there).
// Five years back (founder, 2026-10-16: a friend wants to fill his passport; EXIF GPS+date
// verifies a 2021 photo exactly like last week's). Was 2026-01-01 from 2026-10-14 to 10-16.
const PP_EARLIEST = '2021-01-01';
const ppDateAllowed = (d) => !!d && d >= PP_EARLIEST && d <= new Date(Date.now() + 86400000).toISOString().slice(0, 10);
const ppDateRefusal = (d) => jsonResponse({ error: d < PP_EARLIEST ? 'Stamps go back to January 1, 2021' : 'That date hasn’t happened yet', code: 'date_out_of_range' }, 400);
// A place's own name when it's written in another alphabet ("東京都" beside "Tokyo";
// founder, 2026-10-14: "both names in original character and tokyo"). One in Latin
// letters ("Roma", "Tour Eiffel") adds nothing to the English name, so it isn't kept.
function ppLocalName(english, local) {
  const l = String(local || '').replace(/\s+/g, ' ').trim().slice(0, 80);
  return l && l !== String(english || '').trim() && /(?!\p{Script=Latin})\p{L}/u.test(l) ? l : null;
}
// The country's own language, where it isn't written in Latin letters: OpenStreetMap's plain
// name can mix several ("Храм Сенсодзи 金龍山 浅草寺" for Sensō-ji), its name:ja is "浅草寺".
const PP_NATIVE_LANG = {
  JP: 'ja', CN: 'zh', TW: 'zh', HK: 'zh', MO: 'zh', KR: 'ko', KP: 'ko', RU: 'ru', UA: 'uk', BY: 'be', BG: 'bg',
  RS: 'sr', MK: 'mk', KG: 'ky', MN: 'mn', GR: 'el', CY: 'el', IL: 'he', IR: 'fa', PK: 'ur', IN: 'hi', NP: 'ne',
  BD: 'bn', LK: 'si', TH: 'th', LA: 'lo', KH: 'km', MM: 'my', GE: 'ka', AM: 'hy', ET: 'am',
  SA: 'ar', AE: 'ar', EG: 'ar', JO: 'ar', LB: 'ar', SY: 'ar', IQ: 'ar', KW: 'ar', QA: 'ar', BH: 'ar', OM: 'ar', YE: 'ar', MA: 'ar', DZ: 'ar', TN: 'ar', LY: 'ar', SD: 'ar',
};
const ppNativeName = (namedetails, cc) => namedetails?.[`name:${PP_NATIVE_LANG[String(cc || '').toUpperCase()]}`] || namedetails?.name || null;
const ppSlug = (s) => String(s || '').toLowerCase().trim().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '');

// Create or update a stamp (idempotent per user+kind+entity), keeping the
// strongest verification (gps > photo > self). Returns { id, created|updated }.
async function ppUpsertStamp(env, row) {
  let existing = null;
  if (row.entity_id) {
    const q = await gbRest(env, `passport_stamps?user_id=eq.${row.user_id}&kind=eq.${row.kind}&entity_id=eq.${encodeURIComponent(row.entity_id)}&select=id,verified${row.meta ? ',meta' : ''}`, {});
    existing = (q.ok ? await q.json() : [])[0] || null;
  }
  if (existing) {
    const best = PP_VERIFY_RANK[row.verified] > PP_VERIFY_RANK[existing.verified] ? row.verified : existing.verified;
    const patch = { verified: best, updated_at: new Date().toISOString() };
    // A report ("I'm here, but the app is saying I'm not") can come from
    // anywhere, so it never moves the date of a stamp you already hold.
    if (row.visited_on && row.verified !== 'reported') patch.visited_on = row.visited_on;
    // A re-stamp adds the film to an older stamp of the same place, never replaces one.
    if (row.meta?.film && !existing.meta?.film) patch.meta = { ...(existing.meta || {}), film: row.meta.film };
    if (row.meta?.parent_id && !existing.meta?.parent_id) patch.meta = { ...(patch.meta || existing.meta || {}), parent_id: row.meta.parent_id };
    // A Local favorite keeps the count it was first stamped with; one without it gets it.
    if (row.meta?.local_favorite && !existing.meta?.local_favorite) patch.meta = { ...(patch.meta || existing.meta || {}), local_favorite: row.meta.local_favorite };
    // The rough zone only ever improves (reported < nearby < on_site < inside).
    const zNew = row.meta?.presence?.zone, zOld = existing.meta?.presence?.zone;
    if (zNew && !(zNew === 'reported' && best !== 'reported') && (!zOld || (PP_ZONE_RANK[zNew] ?? -1) > (PP_ZONE_RANK[zOld] ?? -1))) patch.meta = { ...(patch.meta || existing.meta || {}), presence: row.meta.presence };
    await gbRest(env, `passport_stamps?id=eq.${existing.id}`, { method: 'PATCH', headers: { Prefer: 'return=minimal' }, body: JSON.stringify(patch) });
    return { id: existing.id, updated: true, verified: best };
  }
  let ins = await gbRest(env, 'passport_stamps', { method: 'POST', headers: { Prefer: 'return=representation' }, body: JSON.stringify(row) });
  if (!ins.ok && row.visibility !== undefined) {
    // The ~20 s between this worker deploying and the tiers migration landing: the column
    // isn't there yet, so the stamp is made without it (it backfills like the rest).
    const { visibility, pos, ...bare } = row;
    ins = await gbRest(env, 'passport_stamps', { method: 'POST', headers: { Prefer: 'return=representation' }, body: JSON.stringify(bare) });
  }
  if (!ins.ok) throw new Error(await ins.text().catch(() => 'insert failed'));
  const created = (await ins.json())[0] || {};
  return { id: created.id, created: true, verified: row.verified };
}

// Move one of the caller's stamps (still under `fromId`) to `toId` — an "I
// was here" stamp whose place has become an official stamp — unless they
// already hold `toId`. The upsert that follows then upgrades it in place.
async function ppMoveStampTo(env, userId, stampId, kind, fromId, toId, entityType = 'place') {
  try {
    if (!fromId || !toId || fromId === toId) return;
    const have = await gbRest(env, `passport_stamps?user_id=eq.${userId}&kind=eq.${kind}&entity_id=eq.${encodeURIComponent(toId)}&select=id&limit=1`, {});
    if (!have.ok || (await have.json()).length) return;
    await gbRest(env, `passport_stamps?id=eq.${stampId}&user_id=eq.${userId}&entity_id=eq.${encodeURIComponent(fromId)}`, {
      method: 'PATCH', headers: { Prefer: 'return=minimal' },
      body: JSON.stringify({ entity_id: toId, ...(entityType ? { entity_type: entityType } : {}), updated_at: new Date().toISOString() }),
    });
  } catch { /* best-effort: at worst the old second stamp appears, as before */ }
}

let PP_CC_BY_NAME = null;
function ppCcForCountryName(name) {
  if (!name) return null;
  if (!PP_CC_BY_NAME) {
    PP_CC_BY_NAME = new Map();
    try {
      const dn = new Intl.DisplayNames(['en'], { type: 'region' });
      for (let a = 65; a <= 90; a++) for (let c = 65; c <= 90; c++) {
        const code = String.fromCharCode(a, c);
        // Retired codes ICU still names (UK, FX, SU, YU, ZR…) came later in the
        // loop and overwrote the real ones: "United Kingdom" read as UK, never
        // Cloudflare's GB (2026-10-12). Only a code that is its own canonical form counts.
        try { if (new Intl.Locale(`und-${code}`).region !== code) continue; const n = dn.of(code); if (n && n !== code) PP_CC_BY_NAME.set(n.toLowerCase(), code); } catch { /* not a region */ }
      }
    } catch { /* no ICU: the exemption just never applies */ }
  }
  return PP_CC_BY_NAME.get(String(name).toLowerCase().trim()) || null;
}

// Server copy of src/lib/stampRadius.js (keep the two in step): metres within
// which a GPS fix counts as "you were there", by footprint, else by category.
const PP_FOOTPRINTS = [
  [/national_park|national_forest|nature_reserve|wildlife_refuge/, 6000],
  [/ski_resort|state_park|regional_park|botanical_garden|arboretum/, 2500],
  [/beach|lake|waterfall|mountain|natural_feature|island/, 1800],
  [/theme_park|amusement_park|water_park|resort_world/, 900],
  [/airport|international_airport/, 2500],
  [/university|college|campus|fairground|convention_center/, 800],
  [/zoo|aquarium|safari|golf_course|cemetery|historical_park|archaeolog/, 600],
  [/(?:^|[^a-z])(?:park|garden|viewpoint)(?![a-z])/, 600],
  [/stadium|arena|race_track|marina|pier|market|bazaar|souk/, 400],
  [/shopping_mall|department_store|casino|monastery|temple_complex/, 350],
];
function ppStampRadius(place) {
  const explicit = Number(place?.footprint_radius_m);
  if (Number.isFinite(explicit) && explicit > 0) return explicit;
  const hay = String(place?.category || '').toLowerCase();
  if (hay) for (const [pattern, metres] of PP_FOOTPRINTS) if (pattern.test(hay)) return metres;
  return 250;
}

// Shaped stamp places (founder, 2026-10-10). A pin and a circle can't hold a
// long place: the Walk of Fame refused a stamp under the Dolby Theatre because
// its only pin sits at the La Brea end. A shape is a set of street centre lines
// ([lat, lng], from OpenStreetMap) plus buffer_m, which covers both sidewalks;
// GPS counts anywhere within buffer_m of a line. Matched by D1 id or Google id.
const PP_SHAPES = [
  // Inside only (founder, 2026-10-18: "only allow stamp if users are inside the building, not outside
  // … they could be at the top"): the stamp is earned within the walls — the lobby or the
  // observatory — never from the sidewalk. The outline is OpenStreetMap way 34633854 (350 Fifth
  // Avenue); a GPS reading or a photo's location tag must fall inside it, with no GPS slack, and a
  // photo is never proven by recognition (a picture of the facade is taken from outside). name_re
  // finds it from a Google listing or a Stamp-a-place visit too.
  {
    key: 'empire-state-building',
    stamp_id: 'icon:Q9188',
    ids: ['icon:Q9188', 'curated:united-states-new-york-empire-state-building', 'curated:united-states-new-york-city-empire-state-building', 'wikidata:Q9188'],
    gids: [],
    name_re: /empire\s+state\s+building/i,   // not the Empire State Diner around the corner
    inside_only: true,
    buffer_m: 0,
    polygon: [[40.748491, -73.986501], [40.747926, -73.985160], [40.748393, -73.984817], [40.748959, -73.986157], [40.748730, -73.986325], [40.748689, -73.986355], [40.748514, -73.986484]],
    inside_note: 'The Empire State Building is stamped from inside — the lobby or the observatory.',
  },
  {
    key: 'hollywood-walk-of-fame',
    stamp_id: 'icon:Q71719', // the official stamp every id of this place resolves to
    ids: ['icon:Q71719', 'curated:united-states-los-angeles-hollywood-walk-of-fame'],
    gids: ['ChIJjwu2pOa_woARViWxZ-MRAu4', 'ChIJXyC7WTu_woARPvVMCHBXd4U'],
    buffer_m: 50,
    lines: [
      [[34.10158, -118.34521], [34.10154, -118.33886], [34.10166, -118.32190]], // Hollywood Blvd, La Brea → Gower
      [[34.09800, -118.32668], [34.10377, -118.32672]],                         // Vine St, Sunset → Yucca
    ],
  },
];
function ppShapeFor(id, gid) {
  return PP_SHAPES.find((s) => (id && s.ids.includes(id)) || (gid && s.gids.includes(gid))) || null;
}
// A shaped place found by its name close to it (a Google listing whose id isn't on the shape, a
// Stamp-a-place visit, an older stamp row): within 400 m of the shape, the reach of photo proof.
function ppShapeNear(name, lat, lng) {
  if (!name || !Number.isFinite(+lat) || !Number.isFinite(+lng)) return null;
  return PP_SHAPES.find((sh) => sh.name_re && sh.name_re.test(String(name)) && ppMetersToShape(sh, +lat, +lng) <= 400) || null;
}
function ppInPolygon(poly, lat, lng) {
  let inside = false;
  for (let i = 0, j = poly.length - 1; i < poly.length; j = i++) {
    const [yi, xi] = poly[i], [yj, xj] = poly[j];
    if ((yi > lat) !== (yj > lat) && lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi) inside = !inside;
  }
  return inside;
}
// Metres from a point to the nearest line of a shape, on a flat local
// projection (exact to well under a metre across a few kilometres).
function ppMetersToShape(shape, lat, lng) {
  const ky = 110574, kx = 111320 * Math.cos(lat * Math.PI / 180);
  // A building outline: 0 inside it, else the distance to its nearest wall.
  if (shape.polygon && ppInPolygon(shape.polygon, lat, lng)) return 0;
  const lines = shape.polygon ? [[...shape.polygon, shape.polygon[0]]] : shape.lines;
  let best = Infinity;
  for (const line of lines) {
    for (let i = 0; i + 1 < line.length; i++) {
      const ax = (line[i][1] - lng) * kx, ay = (line[i][0] - lat) * ky;
      const bx = (line[i + 1][1] - lng) * kx, by = (line[i + 1][0] - lat) * ky;
      const dx = bx - ax, dy = by - ay, len2 = dx * dx + dy * dy;
      const t = len2 ? Math.max(0, Math.min(1, -(ax * dx + ay * dy) / len2)) : 0;
      best = Math.min(best, Math.hypot(ax + t * dx, ay + t * dy));
    }
  }
  return best;
}

// The rough zone a stamp keeps (founder, 2026-10-10: "rough zone only"): where
// the person stood relative to the place, in bands, never the exact spot.
// zone: on_site (inside the circle or shape) · nearby (only within GPS slack) ·
// reported (granted through "I'm here, but the app is saying I'm not").
const PP_ZONE_RANK = { reported: 0, nearby: 1, on_site: 2, inside: 3 };
const ppBand = (v, cuts) => (Number.isFinite(v) && v >= 0 ? (cuts.find((c) => v < c) ? `<${cuts.find((c) => v < c)}` : `>${cuts[cuts.length - 1]}`) : null);
function ppPresence(zone, meters, acc, truth) {
  return {
    zone,
    d: ppBand(meters, [50, 150, 500, 1500, 5000]),
    acc: ppBand(acc, [20, 65, 100, 300]),
    src: truth?.shape ? 'shape' : truth ? 'circle' : null,
  };
}

// "I'm here, but the app is saying I'm not" (founder, 2026-10-10). Every tap
// files a report for the admin list; the stamp is granted either way. Stored
// in the events D1 (table created lazily, like contact_messages). The spot is
// rounded to ~1 city block; the user is an anonymous code, not an id.
const STAMP_REPORT_SQL = `CREATE TABLE IF NOT EXISTS stamp_reports (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  created_at TEXT NOT NULL,
  place_name TEXT NOT NULL,
  entity_id TEXT,
  city TEXT,
  country TEXT,
  spot_lat REAL,
  spot_lng REAL,
  distance_m INTEGER,
  radius_m INTEGER,
  accuracy_m INTEGER,
  refusal TEXT,
  outcome TEXT NOT NULL,
  platform TEXT,
  app_version TEXT,
  user_code TEXT,
  status TEXT NOT NULL DEFAULT 'new'
)`;
async function ppFileStampReport(env, r) {
  try {
    if (!env.DB) return;
    await env.DB.prepare(STAMP_REPORT_SQL).run();
    const round3 = (v) => (Number.isFinite(v) ? Math.round(v * 1000) / 1000 : null);
    const int = (v, step = 1) => (Number.isFinite(v) ? Math.round(v / step) * step : null);
    await env.DB.prepare(
      `INSERT INTO stamp_reports (created_at, place_name, entity_id, city, country, spot_lat, spot_lng, distance_m, radius_m, accuracy_m, refusal, outcome, platform, app_version, user_code)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(
      new Date().toISOString(), String(r.name || '').slice(0, 200), r.entity_id || null, r.city || null, r.country || null,
      round3(r.fix?.lat), round3(r.fix?.lng), int(r.meters, 10), int(r.reach), int(r.fix?.acc),
      r.refusal || null, r.outcome, r.platform || null, r.app_version || null, r.user_code || null,
    ).run();
  } catch (e) { console.error('stamp report failed', e?.message || e); }
}

// Sensitive places start PRIVATE (founder + the plan she shared, 2026-10-03):
// a hospital, clinic, school, shelter, treatment centre, place of worship… —
// GPS verifies the visit, never the reason; the traveler can share it later.
// Only for "I was here" and Stamp-a-place visits (iconic stamps aren't checked).
const PP_SENSITIVE_TYPES = new Set(['hospital', 'general_hospital', 'doctor', 'dental_clinic', 'dentist', 'medical_lab', 'medical_clinic', 'physiotherapist', 'chiropractor', 'pharmacy', 'drugstore', 'health', 'school', 'primary_school', 'secondary_school', 'preschool', 'child_care_agency', 'courthouse', 'police', 'place_of_worship', 'church', 'mosque', 'synagogue', 'hindu_temple', 'buddhist_temple', 'funeral_home']);
const PP_SENSITIVE_NAME = /\b(hospitals?|medical cent(?:er|re)|clinics?|urgent care|emergency room|health cent(?:er|re)|oncology|cancer|dialysis|hospice|fertility|ivf|planned parenthood|abortion|maternity|psychiatric|mental health|behavioral health|counsell?ing|rehab(?:ilitation)?|recovery cent(?:er|re)|treatment cent(?:er|re)|detox|addiction|sober living|shelter|crisis cent(?:er|re)|elementary school|middle school|high school|primary school|secondary school|preschool|kindergarten|daycare|courthouse|jail|prison|detention cent(?:er|re)|police station|immigration|church|mosque|synagogue|temple|chapel|parish|cathedral|basilica|shrine|masjid|gurdwara|mandir|monastery|abbey|convent|priory|minster|pagoda|stupa|wat|jinja|funeral home|mortuary)\b/i;
// Places of worship named in scripts without spaces, where \b sees no word (2026-10-12).
const PP_SENSITIVE_CJK = /(神社|神宮|大社|天満宮|寺院|寺|庙|廟|教会|教堂|天主堂|礼拜堂|禮拜堂|聖堂|清真寺|モスク|사원|성당|교회|(?<![\u0E00-\u0E7F])\u0E27\u0E31\u0E14)/u;
// …and in other languages. Letters, not \b, mark the word's edges: \b can't see
// one before an accented letter ("église").
const PP_SENSITIVE_INTL = /(?<![\p{L}\p{N}])(iglesia|parroquia|catedral|capilla|mezquita|sinagoga|templo|bas[ií]lica|[ée]glise|cath[ée]drale|chapelle|mosqu[ée]e|kirche|kapelle|kloster|moschee|chiesa|cattedrale|cappella|duomo|moschea|igreja|capela|mesquita|mosteiro)(?![\p{L}\p{N}])/iu;
// Not sensitive whatever the name says ("Temple Bar", "Shelter Island Brewery").
const PP_SENSITIVE_NOT = /\b(bar|brewery|brewing|pub|tavern|restaurant|caf[eé]|coffee|grill|kitchen|bistro|bakery|island|beach|street|road|avenue|hotel|museum|park)\b/i;
// A square named after its cathedral or church ("Piazza del Duomo", "Plaza de
// la Catedral") is a public square, not a place of worship.
const PP_SQUARE_PHRASE = /(?<![\p{L}\p{N}])(?:piazza|plaza|pra[cç]a|place|platz|largo|square)\s+(?:(?:del|de la|de|do|da|du|della|dello|di|der|des|of(?: the)?)\s+)?(?:duomo|dom|catedral|cath[ée]drale|cattedrale|cathedral|iglesia|[ée]glise|chiesa|igreja|church|kirche|templo|temple|bas[ií]lica)(?![\p{L}\p{N}])/giu;
// A worship word that only names a landform or a venue ("Cathedral Rock",
// "Shrine Auditorium") is taken out before the check — a phrase, never a lone
// word, so "Canyon Ridge Hospital" or "The Rock Church" still start private.
const PP_LANDMARK_PHRASE = /\b(?:church|temple|chapel|cathedral|basilica|shrine|mosque|monastery|abbey|pagoda|minster|priory|convent)\s+(?:auditorium|theat(?:er|re)|stadium|arena|rocks?|peaks?|canyon|trail(?:head)?|spires?|butte|mountain)\b/gi;
function ppSensitivePlace(name, types) {
  const t = (types || []).map(String).filter(Boolean);
  // Google's own place types decide when we have them; the name is the fallback.
  if (t.length) return t.some((x) => PP_SENSITIVE_TYPES.has(x));
  const n = String(name || '').normalize('NFC').replace(PP_LANDMARK_PHRASE, ' ').replace(PP_SQUARE_PHRASE, ' ');
  return (PP_SENSITIVE_NAME.test(n) || PP_SENSITIVE_CJK.test(n) || PP_SENSITIVE_INTL.test(n)) && !PP_SENSITIVE_NOT.test(n);
}

// Create or update a stamp (idempotent per user+kind+entity). Keeps the STRONGEST
// verification when re-stamping (gps > photo > self).
async function handlePassportStamp(request, env, ctx) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in to stamp your passport' }, 401);
    // Kept for the report's age check and the founder's alert below. An age
    // that can't be checked refuses the stamp (fail closed, 2026-10-13).
    const stamperSp = await gbSocialProfile(env, user.id).catch(() => undefined);
    if (stamperSp === undefined) return gbAgeUnknownResp();
    if (gbUnderAge(stamperSp)) return gbUnderAgeResp();
    if (gbNeedsConfirm(stamperSp)) return gbConfirmResp();
    const b = await request.json().catch(() => ({}));
    let name = String(b.name || '').trim();   // a Local favorite takes its approved name below
    if (!name) return jsonResponse({ error: 'name required' }, 400);
    const kind = PP_KINDS.includes(String(b.kind || '').toLowerCase()) ? String(b.kind).toLowerCase() : 'attraction';
    const tier = kind === 'attraction' ? 'mark' : 'page';
    let verified = ['gps', 'photo', 'self'].includes(b.verified) ? b.verified : 'self';
    let entityId = b.entity_id != null && String(b.entity_id) ? String(b.entity_id).slice(0, 220) : null;
    const visitedOn = ppDate(b.visited_on);
    // A Stamp-a-place visit's date is the traveler's pick, so it keeps to the range; other
    // stamps carry today, or an existing stamp's own date.
    if (kind === 'city' && String(b.entity_type || '') === 'visit' && visitedOn && !ppDateAllowed(visitedOn)) return ppDateRefusal(visitedOn);
    let lat = Number.isFinite(+b.lat) ? +b.lat : null;
    let lng = Number.isFinite(+b.lng) ? +b.lng : null;

    // Anti-spoof: GPS is client-reported and spoofable, so a claimed 'gps' ✓ must be
    // corroborated. We cross-check against (1) the request's IP country (free via
    // Cloudflare's CF-IPCountry) and (2) impossible travel vs the user's last GPS
    // stamp. On any mismatch we KEEP the stamp but downgrade to 'self' (no ✓) —
    // never reject. Checks skip gracefully when the needed signal is missing.
    if (verified === 'gps') {
      const ipCC = String(request.headers.get('CF-IPCountry') || '').toUpperCase();
      const claimCC = String(b.cc || '').toUpperCase();
      // (1) GPS vs IP country — only when both are real 2-letter codes
      if (/^[A-Z]{2}$/.test(ipCC) && ipCC !== 'XX' && ipCC !== 'T1' && /^[A-Z]{2}$/.test(claimCC) && ipCC !== claimCC) {
        let roamingHome = false;
        try {
          // profiles lives in the public schema: without the header this read hit
          // the default one and failed, so the exemption never applied (2026-10-12).
          const pr = await fetch(`${GB_URL(env)}/rest/v1/profiles?id=eq.${user.id}&select=home_country`, { headers: { apikey: GB_KEY(env), Authorization: `Bearer ${GB_KEY(env)}`, 'Accept-Profile': 'public' } });
          const home = pr.ok ? (await pr.json())[0]?.home_country : null;
          roamingHome = !!home && ppCcForCountryName(home) === ipCC;
        } catch { /* treat as a mismatch */ }
        if (!roamingHome) verified = 'self';
      }
      // (2) impossible travel vs the most-recent GPS stamp (>620 mph = faster than a jet).
      // Measured from created_at: editing an old stamp's photo, date or layout bumps
      // updated_at, which made it look fresh and refused genuine travelers.
      if (verified === 'gps' && lat != null && lng != null) {
        try {
          const q = await gbRest(env, `passport_stamps?user_id=eq.${user.id}&verified=eq.gps&lat=not.is.null&order=created_at.desc&limit=1&select=lat,lng,created_at`, {});
          const last = (q.ok ? await q.json() : [])[0];
          if (last && last.lat != null && last.lng != null) {
            const miles = haversineMilesLoc(+last.lat, +last.lng, lat, lng);
            const hrs = (Date.now() - Date.parse(last.created_at || 0)) / 3.6e6;
            if (hrs > 0 && miles / hrs > 620) verified = 'self';
          }
        } catch { /* best-effort */ }
      }
    }

    // Distance check (founder, 2026-10-03: stamp only when GPS shows you're AT
    // the attraction). Every GPS attraction stamp carries the fix it was taken
    // with (`fix` {lat,lng,acc} — used for this check only, never stored) and is
    // measured against OUR coordinates, never the client's: the D1 row for a
    // stamp id; Google's location for "I was here" ids (places:<gid>/owned:<uuid>,
    // or a bare Google/owned id); a landmark variant's parent D1 row.
    const fix = b.fix && typeof b.fix === 'object' ? { lat: Number(b.fix.lat), lng: Number(b.fix.lng), acc: Number(b.fix.acc) } : null;
    // Stamp-a-place visits (kind city / entity_type visit) are checked by name.
    let startPrivate = kind === 'city' && String(b.entity_type || '') === 'visit' && ppSensitivePlace(name, []);
    // "I'm here, but the app is saying I'm not" (founder, 2026-10-10): the
    // client resends the stamp with report:true. It is ALWAYS granted (as
    // 'reported', never \u2713 unless GPS passes after all) and ALWAYS filed.
    const reporting = b.report === true && kind === 'attraction';
    const PP_REPORT_MAX_M = 1500;   // keep in step with REPORT_MAX_M in AttractionExtras.jsx
    let presence = null, refusal = null, meters = null, reach = null, reportEntity = entityId, variantParent = null;
    // The place check runs on the CLAIM (b.verified), before the anti-spoof
    // verdict above is applied (2026-10-11): a far-away reading is refused as
    // not_here with its distance even when that verdict already distrusts it,
    // and a reading inside the place that it distrusts is refused as
    // 'unconfirmed' \u2014 and counted per place either way.
    if (kind === 'attraction' && (b.verified === 'gps' || reporting)) {
      const hasFix = fix && Number.isFinite(fix.lat) && Number.isFinite(fix.lng);
      if (!hasFix && !reporting) return jsonResponse({ error: "We couldn\u2019t confirm you\u2019re here \u2014 open the place in the app while you\u2019re there and tap Stamp", code: 'proof_needed' }, 409);
      const k0 = ttdIdKind(entityId);
      const rawId = entityId;
      if (k0 === 'google') entityId = `places:${entityId}`;
      else if (k0 === 'owned') entityId = `owned:${entityId}`;
      // Verify I'm here on an older stamp stored under the bare id: that row moves
      // to the prefixed id first, so it is upgraded in place, not duplicated.
      if (entityId !== rawId && BL_UUID.test(String(b.stamp_id || ''))) await ppMoveStampTo(env, user.id, String(b.stamp_id), kind, rawId, entityId, null);
      let k1 = ttdIdKind(entityId);
      // A one-word park slug ('epcot') fails the variant pattern, which needs a
      // hyphen; arriving as a landmark, it is a variant too — but only ever
      // measured against a parent row we find, never the phone's own pin.
      const oneWordVariant = k1 == null && b.entity_type === 'landmark' && /^[a-z0-9]+$/.test(entityId || '');
      if (oneWordVariant) k1 = 'variant';
      const origin = new URL(request.url).origin;
      let truth = null;
      if (k1 === 'tagged' || k1 === 'd1') truth = await ttdPlaceTruth(env, entityId, origin);
      else if (k1 === 'variant') {
        // A park or rim is measured against its parent place. Older variant
        // stamps carry no parent id (Verify I'm here): their pin was copied
        // from the parent row, so the parent is the row at that pin — or, when
        // the row was re-pinned since (fix_parks moved the Disney rows to
        // their gates), the nearest row within ~1.5 km named like the stamp.
        if (ttdIdKind(b.parent_id) === 'd1') variantParent = String(b.parent_id);
        else if (Number.isFinite(lat) && Number.isFinite(lng) && env.ATTRACTIONS_DB) {
          const exact = await env.ATTRACTIONS_DB.prepare('SELECT id FROM attractions WHERE lat BETWEEN ?1 AND ?2 AND lng BETWEEN ?3 AND ?4 LIMIT 1')
            .bind(lat - 1e-5, lat + 1e-5, lng - 1e-5, lng + 1e-5).first().catch(() => null);
          let p = exact?.id && ttdIdKind(String(exact.id)) === 'd1' ? exact : null;
          const core = String(name || '').replace(/\b(south|north|west|east)\s+rim\b|\(.*?\)|,.*$|\bpark\b/gi, ' ').replace(/\s+/g, ' ').trim().split(' ').slice(0, 2).join(' ').toLowerCase();
          if (!p && core.length >= 4) {
            const d = 0.015;
            p = await env.ATTRACTIONS_DB.prepare('SELECT id FROM attractions WHERE lat BETWEEN ?1 AND ?2 AND lng BETWEEN ?3 AND ?4 AND lower(name) LIKE ?5 ORDER BY ((lat - ?6) * (lat - ?6) + (lng - ?7) * (lng - ?7)) LIMIT 1')
              .bind(lat - d, lat + d, lng - d, lng + d, `%${core}%`, lat, lng).first().catch(() => null);
            if (p && ttdIdKind(String(p.id)) !== 'd1') p = null;
          }
          if (p?.id) variantParent = String(p.id);
        }
        if (variantParent) truth = await ttdPlaceTruth(env, variantParent, origin);
        // The phone's own pin is a last resort only for builds that predate
        // parent_id: never when a named parent failed to resolve, and never
        // for a one-word slug.
        if (!truth && !variantParent && !oneWordVariant && ttdIdKind(b.parent_id) == null && Number.isFinite(lat) && Number.isFinite(lng)) {
          truth = { lat, lng, radius: ppStampRadius({ category: b.category }) };
        }
      }
      reportEntity = entityId;
      // Refusals are counted under the place a traveler opened: a park or
      // rim's parent, so a refused tap and the report it leads to share a row.
      const countedAs = variantParent || entityId;
      const countedName = (variantParent && truth?.name) || name;
      if (!truth && !reporting) {
        if (ctx) ctx.waitUntil(gbLogEvent(env, 'passport_stamp_refused', { code: 'unlocatable', entity_id: countedAs, name: countedName }));
        return jsonResponse({ error: 'We can\u2019t place this attraction on the map yet, so it can\u2019t be stamped right now', code: 'unlocatable' }, 409);
      }
      if (!truth) {
        refusal = 'unlocatable';
        // Sensitive places start private even when we can't place them (name check).
        if (k1 === 'tagged' || k1 == null) { b.entity_type = 'local'; startPrivate = ppSensitivePlace(name, []); }
      } else if (!hasFix) refusal = 'proof_needed';
      else {
        const slack = truth.shape?.inside_only ? 0 : Number.isFinite(fix.acc) && fix.acc >= 0 ? Math.min(fix.acc, 100) : 50;
        // A shaped place measures to its nearest line; everything else to its pin.
        meters = truth.shape ? ppMetersToShape(truth.shape, fix.lat, fix.lng) : haversineMilesLoc(truth.lat, truth.lng, fix.lat, fix.lng) * 1609.34;
        reach = truth.shape ? truth.shape.buffer_m : truth.radius;
        if (meters > reach + slack) refusal = 'not_here';
        // One parent can hold several parks or rims (a Grand Canyon footprint
        // covers both rims): Verify I'm here sends which one the reading
        // resolves to, and a different one is not this stamp. Only ever stricter.
        else if (k1 === 'variant' && typeof b.fix_variant === 'string' && b.fix_variant && b.fix_variant !== entityId) refusal = 'other_variant';
        else presence = ppPresence(meters <= reach ? 'on_site' : 'nearby', meters, fix.acc, truth);
      }
      // The anti-spoof checks above can still have taken the \u2713 away.
      if (!refusal && verified !== 'gps') refusal = 'unconfirmed';
      // A report is for GPS that drifts, from someone at or near the place (2026-10-26: the stamp
      // button is on every card now, so a report from home must not grant a stamp): it needs a
      // reading, and a reading within PP_REPORT_MAX_M of the place. Farther, or none, is refused
      // like any tap — the app shows no report button then either.
      if (reporting && truth && (!hasFix || (Number.isFinite(meters) && meters > (reach || 0) + PP_REPORT_MAX_M))) {
        if (ctx) ctx.waitUntil(gbLogEvent(env, 'passport_stamp_refused', { code: hasFix ? 'report_far' : 'report_no_fix', entity_id: countedAs, name: countedName, d: ppBand(meters, [50, 150, 500, 1500, 5000]), radius_m: reach, reported: true }));
        return jsonResponse(hasFix
          ? { error: 'Stamps open when you\u2019re there \u2014 your GPS puts you too far from this place to report it', code: 'not_here', distance_m: Math.round(meters) }
          : { error: 'Turn on location for GlobeSkimmers, then try again from the place', code: 'proof_needed' }, 409);
      }
      // An inside-only place is never granted from outside, reported or not (founder, 2026-10-18).
      if ((refusal === 'not_here' || refusal === 'proof_needed') && reporting && truth?.shape?.inside_only) {
        return jsonResponse({ error: refusal === 'not_here' ? `${truth.shape.inside_note} Your GPS shows you outside the building.` : `${truth.shape.inside_note} Turn on location and try again from inside.`, code: refusal, inside_only: true, ...(Number.isFinite(meters) ? { distance_m: Math.round(meters) } : {}) }, 409);
      }
      if (refusal) {
        // Counted per place with no position (founder: a place that fails
        // quietly still shows up), whether or not the person reports it.
        if (ctx) ctx.waitUntil(gbLogEvent(env, 'passport_stamp_refused', { code: refusal, entity_id: countedAs, name: countedName, d: ppBand(meters, [50, 150, 500, 1500, 5000]), radius_m: reach, acc: ppBand(fix?.acc, [20, 65, 100, 300]), reported: reporting }));
        if (!reporting) {
          if (refusal === 'not_here' && truth.shape?.inside_only) return jsonResponse({ error: `${truth.shape.inside_note} Your GPS shows you outside the building.`, code: 'not_here', inside_only: true, distance_m: Math.round(meters) }, 409);
          if (refusal === 'not_here' || refusal === 'other_variant') return jsonResponse({ error: 'Your GPS doesn\u2019t show you at this place yet \u2014 stamping opens when you\u2019re here', code: 'not_here', distance_m: Math.round(meters), radius_m: reach, ...(refusal === 'other_variant' ? { other_variant: true } : {}) }, 409);
          // 'unconfirmed' falls through to the proof gate below, exactly as
          // before \u2014 and a reading we don't trust keeps no zone, re-keys nothing.
          presence = null;
        } else {
          verified = 'reported';
          presence = ppPresence('reported', meters, fix?.acc, truth);
        }
      }
      if (truth && (presence || reporting)) {
        if (k1 !== 'variant') { lat = truth.lat; lng = truth.lng; }
        if (k1 === 'tagged') {
          // An iconic place becomes its official stamp (no duplicates); others stamp "I was here".
          const iconic = truth.gid ? await ttdStampFor(env, truth.gid, truth.name || name, truth.lat, truth.lng) : null;
          if (iconic) {
            // Verify I'm here on an "I was here" stamp whose place has since
            // become an official stamp: that row moves to the official id
            // instead of a second stamp appearing beside it (2026-10-11).
            if (BL_UUID.test(String(b.stamp_id || ''))) await ppMoveStampTo(env, user.id, String(b.stamp_id), kind, entityId, iconic.id);
            entityId = iconic.id; b.entity_type = 'place';
          }
          else { b.entity_type = 'local'; startPrivate = ppSensitivePlace(truth.name || name, truth.types); }
        }
      }
    }

    // Movie scene stamps keep their film (meta.film) — sanitized, never trusted
    // for anything but display. Only set when present, so ordinary stamps never
    // touch the meta column (safe even before its migration lands).
    const cleanTxt = (v, n) => (v == null ? null : String(v).replace(/\s+/g, ' ').trim().slice(0, n) || null);
    let film = null;
    if (b.film && typeof b.film === 'object' && cleanTxt(b.film.title, 120)) {
      const yr = Math.round(Number(b.film.year));
      film = {
        title: cleanTxt(b.film.title, 120),
        year: yr >= 1880 && yr <= 2100 ? yr : null,
        type: b.film.type === 'tv' ? 'tv' : 'film',
        cast: (Array.isArray(b.film.cast) ? b.film.cast : []).slice(0, 2)
          .map((c) => ({ actor: cleanTxt(c?.actor, 80), role: cleanTxt(c?.role, 80) })).filter((c) => c.actor),
        scene: cleanTxt(b.film.scene, 240),
      };
    }
    // Direction (founder, 2026-10-05): arrival/departure prints on airport
    // stamps; entry/exit on land borders (country crossings and US-state / UK-
    // nation lines, kind 'state'). A directed stamp is keyed per visit
    // (BASE:date:arr|dep) so a round trip collects both — and an audit can
    // replay the sequence from entity_id + meta.direction + visited_on. Legacy
    // stamps keep their plain ids and their look. meta.mode remembers car /
    // train / ship for the checkpoint stamp's glyph.
    const mayDirect = kind === 'airport' || kind === 'state' || (kind === 'country' && b.entity_type === 'border');
    const direction = mayDirect && ['arrival', 'departure'].includes(b.direction) ? b.direction : null;
    // 'air' (2026-10-24): the country stamp an international airport gives beside its airport stamp.
    const mode = direction && ['car', 'train', 'ship', 'air'].includes(b.mode) ? b.mode : null;
    if (direction && entityId) entityId = `${entityId.split(':')[0]}:${visitedOn || new Date().toISOString().slice(0, 10)}:${direction === 'departure' ? 'dep' : 'arr'}`;
    // A Local favorite (founder, 2026-10-10): an approved suggested place
    // stamps in its own style, never the icon art, and always carries how many
    // people recommended it (meta.local_favorite.count, at stamping time). An
    // lf: id that isn't an approved place stamps nothing.
    // Every "I'm here, but the app is saying I'm not" tap is filed, granted or
    // not, and even when saving the stamp fails. (Defined before the Local
    // favorite check, which can refuse one too; it reads the request's town,
    // which a Local favorite has already swapped for the approved place's.)
    const fileReport = async (outcome) => {
      if (!reporting || !ctx) return;
      const userCode = (await sha256Hex(`${user.id}:stamp-report`)).slice(0, 8);
      // A minor's report keeps no spot at all, only the distance (teens & minors
      // plan, 2026-10-10). Unknown age counts as a minor.
      const spotOk = stamperSp?.social_tier === 'adult';
      ctx.waitUntil(ppFileStampReport(env, {
        name, entity_id: reportEntity, city: b.city ? String(b.city).slice(0, 120) : null, country: b.country ? String(b.country).slice(0, 120) : null,
        fix: spotOk ? fix : { acc: fix?.acc }, meters, reach, refusal, outcome,
        platform: String(b.platform || '').slice(0, 20) || null, app_version: String(b.app_version || '').slice(0, 30) || null, user_code: userCode,
      }));
    };
    let localFav = null;
    if (String(entityId || '').startsWith('lf:')) {
      const lf = kind === 'attraction' ? await psApprovedPlace(env, entityId) : null;
      if (!lf) {
        // Not (or no longer) an approved Local favorite — e.g. removed after
        // reports. The tap is still filed, and a holder hears their stamp stays.
        await fileReport('refused: not an approved Local favorite');
        return jsonResponse({ error: b.stamp_id ? 'This place is no longer a Local favorite — your stamp stays in your passport.' : 'This place isn’t a Local favorite right now.', code: 'not_listed' }, 409);
      }
      b.entity_type = 'local_favorite';
      localFav = { count: lf.count };
      // The approved place speaks for itself (2026-10-12): its own name, town
      // and pin, never the request's — and a sensitive one (a chapel, a
      // clinic) starts private like any other place.
      name = lf.name || name;
      b.city = lf.city; b.region = lf.region; b.country = lf.country;
      lat = lf.lat; lng = lf.lng;
      startPrivate = ppSensitivePlace(name, []);
    } else if (String(b.entity_type || '') === 'local_favorite') {
      // Only an approved lf:<id> may carry the Local favorite look.
      b.entity_type = null;
    }
    // The page-one home-city stamp (onboarding "make your passport") marks
    // itself origin:true — the app renders it as the cover page, not a brag.
    // The place's own name in its own alphabet, beside the English one ("東京都").
    const localName = ppLocalName(name, b.local_name);
    const meta = { ...(film ? { film } : {}), ...(b.origin === true ? { origin: true } : {}), ...(b.birthday === true ? { birthday: true } : {}), ...(direction ? { direction } : {}), ...(mode ? { mode } : {}), ...(presence ? { presence } : {}),
      // A park or rim keeps its parent place, so Verify I'm here measures it the same way.
      ...(variantParent ? { parent_id: variantParent } : {}),
      ...(localFav ? { local_favorite: localFav } : {}),
      ...(localName ? { local_name: localName } : {}) };
    const row = {
      user_id: user.id, kind, tier,
      entity_type: b.entity_type ? String(b.entity_type) : null,
      entity_id: entityId, name,
      ...(Object.keys(meta).length ? { meta } : {}),
      city: b.city ? String(b.city).slice(0, 120) : null,
      region: b.region ? String(b.region).slice(0, 120) : null,
      country: b.country ? String(b.country).slice(0, 120) : null,
      lat, lng,
      visited_on: visitedOn, verified,
      // Every new stamp starts at the owner's default tier — Inner circle unless they chose
      // otherwise in Settings (founder, 2026-10-15) — and a sensitive place starts Only me.
      // A minor's stamp never starts above Inner circle (founder, 2026-10-16: their albums stay private).
      visibility: startPrivate ? 'me' : (stamperSp?.social_tier === 'teen' || gbNeedsConfirm(stamperSp)) ? (stamperSp?.default_stamp_tier === 'me' ? 'me' : 'inner')
        : (PP_TIERS.includes(stamperSp?.default_stamp_tier) ? stamperSp.default_stamp_tier : 'inner'),
      ...(startPrivate ? { hidden: true } : {}),
    };
    if (row.visibility === 'me') row.hidden = true;
    // A Stamp-a-place visit to an inside-only place: the phone measured its own GPS, which the worker
    // can't see, so it is proven by a photo taken inside instead (founder, 2026-10-18).
    const insideVisit = kind === 'city' && String(b.entity_type || '') === 'visit' ? ppShapeNear(name, lat, lng) : null;
    if (insideVisit?.inside_only && verified === 'gps') verified = 'self';
    // No stamp without proof (founder doctrine, 2026-10-03). A new stamp is
    // either GPS-corroborated, or arrives with a proof photo (await_proof —
    // the client uploads it next and deletes the stamp if it proves nothing).
    // No exceptions: birthday stamps were retired (founder, 2026-10-03). The one
    // exception since: a reported stamp (founder, 2026-10-10), filed for review.
    if (verified !== 'gps' && verified !== 'reported' && b.await_proof !== true) {
      let exists = false;
      if (entityId) {
        const ex = await gbRest(env, `passport_stamps?user_id=eq.${user.id}&kind=eq.${kind}&entity_id=eq.${encodeURIComponent(entityId)}&select=id&limit=1`, {});
        exists = ex.ok ? (await ex.json()).length > 0 : false;
      }
      if (!exists) {
        return jsonResponse({
          error: insideVisit?.inside_only
            ? `${insideVisit.inside_note} Add a photo you took inside to stamp it.`
            : b.verified === 'gps'
            ? "We couldn\u2019t confirm you\u2019re here \u2014 add a photo you took here to earn this stamp"
            : 'Stamps need proof \u2014 be there, or add a photo you took there',
          code: 'proof_needed',
        }, 409);
      }
    }
    let result;
    try { result = await ppUpsertStamp(env, row); }
    catch (e) { await fileReport(`stamp failed: ${String(e?.message || e).slice(0, 120)}`); throw e; }
    await fileReport(refusal ? 'stamped (reported)' : 'stamped (GPS passed on retry)');
    // Stamps are airport-arrival + iconic-attraction only — we do NOT auto-stamp cities.
    const localHour = Number.isFinite(+b.local_hour) && +b.local_hour >= 0 && +b.local_hour <= 23 ? Math.floor(+b.local_hour) : null;
    if (ctx) ctx.waitUntil(gbLogEvent(env, 'passport_stamp', { kind, country: row.country, city: row.city, name: row.name, verified: result.verified, updated: !!result.updated, local_hour: localHour, zone: presence?.zone || null }));
    // Private stamps (every sensitive place starts private) never reach the alert,
    // and neither does any stamp of a 13–17 traveler: their whole passport is
    // private to them (privacy policy §9), and a member number leads to a name.
    // Nor does one whose age is unknown or unconfirmed (fail closed, 2026-10-13).
    // Who stamped (founder, 2026-10-13): a member number, never a name, and a
    // tap opens that member in Admin; an admin's own stamp reads "You stamped".
    const alertable = stamperSp !== undefined && !['teen', 'blocked', 'confirm'].includes(stamperSp?.social_tier);
    // An Only-me stamp rings too (founder, 2026-10-26: "a notification when stamp was made in passport") — but
    // never says where: it stays private, and a sensitive place starts that way.
    if (ctx && result.created && row.hidden && alertable) {
      const mineP = ADMIN_EMAILS_WORKER.includes(String(user.email || '').trim().toLowerCase());
      ctx.waitUntil((async () => {
        const { who, n } = mineP ? { who: 'You', n: null } : await gbWhoLine(env, user);
        await founderAlert(env, `📍 ${who} stamped a place kept private (Only me)${gbWhereLine(request)}`, 'bell', n ? { click: gbMemberLink(n) } : {});
      })().catch(() => {}));
    }
    if (ctx && result.created && !row.hidden && alertable) {
      const where = [row.city, row.country].filter(Boolean).join(', ');
      const what = `${row.name}${where ? ` · ${where}` : ''} — ${kind} stamp${result.verified === 'gps' ? ' ✓' : ''}${result.verified === 'reported' ? ' (reported: "I’m here, but the app is saying I’m not")' : ''}${direction ? ` (${kind === 'airport' || mode === 'air' ? direction : direction === 'departure' ? 'exit' : 'entry'})` : ''}`;
      const mine = ADMIN_EMAILS_WORKER.includes(String(user.email || '').trim().toLowerCase());
      ctx.waitUntil((async () => {
        const { who, n } = mine ? { who: 'You', n: null } : await gbWhoLine(env, user);
        await founderAlert(env, `📍 ${who} stamped ${what}${gbWhereLine(request)}`, 'bell', n ? { click: gbMemberLink(n) } : {});
      })().catch(() => {}));
    }
    return jsonResponse({ id: result.id, created: !!result.created, updated: !!result.updated, verified: result.verified, reported: reporting, private: !!(result.created && startPrivate) });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// POST /passport/album/privacy { stamp_ids: [uuid…], photos: 'me' | 'inner' | 'followers' | 'public' }
// — who sees an album (founder, 2026-10-26: "albums should have a quick way to change privacy per
// album"; 2026-10-27: the same four words as everywhere, no "same as"). An album is a place's
// photos across its stamps; its photos never reach more than their stamp or the passport, so
// 'public' means "as far as each stamp goes". Only 'public' (or an old unset album) hangs them on
// the City Boards. 'same' from an older app is read as 'public'.
async function handleAlbumPrivacy(request, env) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in' }, 401);
    const b = await request.json().catch(() => ({}));
    const ids = [...new Set((Array.isArray(b.stamp_ids) ? b.stamp_ids : []).map(String).filter((x) => BL_UUID.test(x)))].slice(0, 200);
    if (!ids.length || !['same', 'inner', 'me', 'followers', 'public'].includes(b.photos)) return jsonResponse({ error: 'stamp_ids + photos required' }, 400);
    const tier = b.photos === 'same' ? 'public' : b.photos;
    const w = await gbRest(env, `passport_stamps?id=in.(${ids.join(',')})&user_id=eq.${user.id}`, { method: 'PATCH', headers: { Prefer: 'return=representation' }, body: JSON.stringify({ photos_tier: tier, updated_at: new Date().toISOString() }) });
    if (!w.ok) return jsonResponse({ error: 'Couldn’t save that — try again' }, 502);
    const rows = await w.json();
    if (!rows.length) return jsonResponse({ error: 'Not found' }, 404);
    await pcBoardsCacheBust(env);
    if (tier === 'public') await pcNoticeForStamps(env, user.id, rows.map((r) => r.id));
    return jsonResponse({ ok: true, photos: b.photos, stamp_ids: rows.map((r) => r.id) });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// POST /passport/stamp/visibility { stamp_id, hidden } — who sees a stamp:
// hidden = only me; shown = my shared passport (and friends' feeds).
async function handlePassportStampVisibility(request, env) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in' }, 401);
    const b = await request.json().catch(() => ({}));
    // The four tiers (founder, 2026-10-15). Old builds still send { hidden }, which means
    // Only me or the owner's default.
    if (PP_TIERS.includes(b.visibility)) {
      if (b.visibility === 'public' || b.visibility === 'followers') {
        const vsp = await gbSocialProfile(env, user.id).catch(() => undefined);
        if (vsp === undefined) return jsonResponse({ error: 'Couldn’t check your account — try again' }, 503);
        if (vsp?.social_tier === 'teen' || gbNeedsConfirm(vsp)) return jsonResponse({ error: 'Public stamps open at age 18 — your stamps stay private', code: 'teen_hold' }, 403);
      }
      const patch = JSON.stringify({ visibility: b.visibility, hidden: b.visibility === 'me', updated_at: new Date().toISOString() });
      if (b.all === true) {
        // "Set all my stamps to one level" — the one-tap way to go dark, or go public.
        const w = await gbRest(env, `passport_stamps?user_id=eq.${user.id}`, { method: 'PATCH', headers: { Prefer: 'return=minimal' }, body: patch });
        if (!w.ok) return jsonResponse({ error: 'Could not update' }, 502);
        if (b.visibility === 'public') await pcNoticeForStamps(env, user.id, null);
        await pcBoardsCacheBust(env);
        return jsonResponse({ ok: true, visibility: b.visibility, all: true });
      }
      const id2 = String(b.stamp_id || '');
      if (!BL_UUID.test(id2)) return jsonResponse({ error: 'stamp_id required' }, 400);
      const w = await gbRest(env, `passport_stamps?id=eq.${id2}&user_id=eq.${user.id}`, { method: 'PATCH', headers: { Prefer: 'return=representation' }, body: patch });
      const rows = w.ok ? await w.json() : [];
      if (!rows.length) return jsonResponse({ error: 'Not found' }, 404);
      if (b.visibility === 'public') await pcNoticeForStamps(env, user.id, [id2]);
      await pcBoardsCacheBust(env);
      return jsonResponse({ ok: true, visibility: rows[0].visibility, hidden: rows[0].hidden === true });
    }
    const id = String(b.stamp_id || '');
    if (!BL_UUID.test(id) || typeof b.hidden !== 'boolean') return jsonResponse({ error: 'stamp_id + hidden required' }, 400);
    const w = await gbRest(env, `passport_stamps?id=eq.${id}&user_id=eq.${user.id}`, { method: 'PATCH', headers: { Prefer: 'return=representation' }, body: JSON.stringify({ hidden: b.hidden, visibility: b.hidden ? 'me' : 'inner', updated_at: new Date().toISOString() }) });
    const rows = w.ok ? await w.json() : [];
    if (!rows.length) return jsonResponse({ error: 'Not found' }, 404);
    await pcBoardsCacheBust(env);
    return jsonResponse({ ok: true, hidden: rows[0].hidden === true });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// Load a user's whole passport (stamps + photos + stats). Shared by the owner's
// list and the public read-only view.
async function ppLoad(env, userId) {
  const q = await gbRest(env, `passport_stamps?user_id=eq.${userId}&order=visited_on.desc.nullslast,created_at.desc&select=*`, {});
  const stamps = q.ok ? await q.json() : [];
  let photos = [];
  if (stamps.length) {
    const ids = stamps.map((s) => s.id).join(',');
    // mod_status must ride along or the public serializer's ok-filter sees
    // undefined and hides every photo (found 2026-09-30 — reviewed photos were
    // invisible on public passports).
    let pq = await gbRest(env, `passport_stamp_photos?stamp_id=in.(${ids})&order=created_at.asc&select=id,stamp_id,photo_url,caption,mod_status,food_subject,board_hidden`, {});
    // The seconds between a worker deploy and its migration (2026-10-16): read without the new column.
    if (pq.status === 400) pq = await gbRest(env, `passport_stamp_photos?stamp_id=in.(${ids})&order=created_at.asc&select=id,stamp_id,photo_url,caption,mod_status,food_subject`, {});
    photos = pq.ok ? await pq.json() : [];
  }
  const byStamp = {};
  for (const p of photos) (byStamp[p.stamp_id] = byStamp[p.stamp_id] || []).push(p);
  let out = stamps.map((s) => ({ ...s, photos: byStamp[s.id] || [] }));
  // "with @friend" (2026-09-30): a claimed tag stamped tagged_by — resolve the
  // tagger's handle/name once so booklet chips need no extra call.
  const taggers = [...new Set(out.map((s) => s.tagged_by).filter(Boolean))].slice(0, 50);
  if (taggers.length) {
    const [hq, nq] = await Promise.all([
      gbRest(env, `passport_shares?user_id=in.(${taggers.join(',')})&select=user_id,handle`, {}),
      gbRest(env, `social_profiles?user_id=in.(${taggers.join(',')})&select=user_id,display_name,${GB_TIER_COLS}`, {}),
    ]);
    const who = {};
    for (const r of (hq.ok ? await hq.json() : [])) who[r.user_id] = { handle: r.handle || null };
    // A tagger who is a minor (held, frozen or unconfirmed) is never named on
    // the booklet (founder, 2026-10-13); nor is anyone when ages can't be read.
    if (!nq.ok) { for (const id of taggers) delete who[id]; }
    for (const r of (nq.ok ? await nq.json() : [])) {
      const t = gbTierRow(r);
      if (gbUnderAge(t) || gbAgeHeld(t)) { delete who[r.user_id]; continue; }
      who[r.user_id] = { ...(who[r.user_id] || {}), name: r.display_name || null };
    }
    out = out.map((s) => (s.tagged_by && who[s.tagged_by]
      ? { ...s, tagged_by_handle: who[s.tagged_by].handle || null, tagged_by_name: who[s.tagged_by].name || null }
      : s));
  }
  return { stamps: out, stats: ppStats(out) };
}
// Counts for a list of stamps. Public views pass only the stamps that aren't
// hidden, so a hidden stamp never shows up even as a number.
function ppStats(out) {
  const distinct = (pred, key) => new Set(out.filter(pred).map(key).filter(Boolean)).size;
  return {
    total: out.length,
    countries: distinct(() => true, (s) => (s.country || '').toLowerCase()),
    cities: distinct((s) => s.kind === 'city', (s) => (s.entity_id || s.name || '').toLowerCase()),
    airports: out.filter((s) => s.kind === 'airport').length,
    states: out.filter((s) => s.kind === 'state').length,
    icons: out.filter((s) => s.kind === 'icon').length,
    wonders: out.filter((s) => s.kind === 'wonder').length,
    attractions: out.filter((s) => s.kind === 'attraction').length,
    verified: out.filter((s) => PP_VERIFIED.has(s.verified)).length,
  };
}
async function handlePassportList(request, env) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ stamps: [], stats: {} });
    // The owner's own booklet: everything, plus the order it is kept in.
    const [loaded, spq, shq] = await Promise.all([
      ppLoad(env, user.id),
      gbRest(env, `social_profiles?user_id=eq.${user.id}&select=*`, {}),
      gbRest(env, `passport_shares?user_id=eq.${user.id}&select=is_public,visibility`, {}),
    ]);
    const sp = (spq.ok ? await spq.json() : [])[0] || {};
    // audience: the passport's own setting, the ceiling over every stamp (2026-10-26).
    const audience = ppAud(shq.ok ? (await shq.json())[0] : null);
    // The collectible stamps placed in it (City Boards, 2026-10-28), every level.
    const collectibles = await cbPlaced(env, user.id);
    return jsonResponse({ ...loaded, collectibles, booklet: { order: sp.booklet_order || 'newest', seed: sp.shuffle_seed ?? null, custom: Array.isArray(sp.custom_order) ? sp.custom_order : null, default_tier: PP_TIERS.includes(sp.default_stamp_tier) ? sp.default_stamp_tier : 'inner', albums: sp.albums_audience || 'passport', audience } });
  } catch (e) { return jsonResponse({ error: e.message, stamps: [], stats: {} }, 500); }
}

// Passport holder's display name (profiles is in the public schema).
async function ppHolder(env, userId) {
  try {
    const pr = await gbRest(env, `profiles?id=eq.${userId}&select=first_name,display_name`, { headers: { 'Accept-Profile': 'public' } });
    const p = (pr.ok ? await pr.json() : [])[0] || {};
    return p.first_name || p.display_name || 'A traveler';
  } catch { return 'A traveler'; }
}

// Faces (B2, 2026-10-14): the cloth each traveler's world is bound in
// (public.profiles.cloth, B1) and their photo (social_profiles.avatar_key),
// for the faces lists, feeds, activity and passports draw. Callers pass only
// the people they already name (adults, unblocked, not deleted), so a face
// never shows where a name doesn't. Before the cloth column exists PostgREST
// answers 400: no cloths, never an error. → { [user_id]: { cloth?, avatar? } }
const GB_CLOTHS = new Set(['harbour', 'forest', 'saddle', 'plum', 'slate', 'ochre', 'lapis', 'graphite']);
async function gbFaces(env, ids, origin) {
  const list = [...new Set((ids || []).filter((id) => typeof id === 'string' && /^[0-9a-f-]{36}$/i.test(id)))].slice(0, 200);
  const out = {};
  if (!list.length) return out;
  const inList = list.join(',');
  const [cq, aq] = await Promise.all([
    gbRest(env, `profiles?id=in.(${inList})&select=id,cloth`, { headers: { 'Accept-Profile': 'public' } }).catch(() => null),
    gbRest(env, `social_profiles?user_id=in.(${inList})&select=user_id,avatar_key`, {}).catch(() => null),
  ]);
  const read = async (r) => { try { return r && r.ok ? await r.json() : []; } catch { return []; } };
  for (const r of await read(cq)) if (GB_CLOTHS.has(r.cloth)) (out[r.id] = out[r.id] || {}).cloth = r.cloth;
  for (const r of await read(aq)) if (r.avatar_key) (out[r.user_id] = out[r.user_id] || {}).avatar = `${origin}/av-photo/${r.avatar_key}`;
  return out;
}

// Get-or-create the user's share row; set its audience if asked. Returns the link and the
// audience. { audience: 'me' | 'inner' | 'followers' | 'public' } (founder, 2026-10-26); old
// builds send { is_public }, which means Everyone or Friends.
async function handlePassportShare(request, env) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in' }, 401);
    const b = await request.json().catch(() => ({}));
    const q = await gbRest(env, `passport_shares?user_id=eq.${user.id}&select=slug,is_public,visibility`, {});
    let row = (q.ok ? await q.json() : [])[0] || null;
    if (!row) {
      // A new link starts at Friends; asking for public on the first call goes
      // through the same age gate as the toggle below (it used to skip it).
      const slug = crypto.randomUUID().replace(/-/g, '').slice(0, 12);
      const ins = await gbRest(env, 'passport_shares', { method: 'POST', headers: { Prefer: 'return=representation' }, body: JSON.stringify({ user_id: user.id, slug, is_public: false, visibility: 'inner' }) });
      row = (ins.ok ? (await ins.json())[0] : { slug, is_public: false, visibility: 'inner' });
    }
    const want = PP_TIERS.includes(b.audience) ? b.audience : typeof b.is_public === 'boolean' ? (b.is_public ? 'public' : 'inner') : null;
    if (want) {
      // Followers and Everyone reach people who aren't friends: a minor (or an unconfirmed
      // birth year) stays at Friends or Only me, as their stamps do.
      if (want === 'followers') {
        const sp = await gbSocialProfile(env, user.id).catch(() => undefined);
        if (sp === undefined) return jsonResponse({ error: 'Couldn’t check your account — try again' }, 503);
        if (sp?.social_tier === 'blocked') return jsonResponse({ error: 'Sharing isn\'t available on this account' }, 403);
        if (sp?.social_tier === 'teen' || gbNeedsConfirm(sp)) return jsonResponse({ error: 'Followers opens at age 18 — your passport stays with your friends', code: 'teen_hold' }, 403);
      }
      // Going PUBLIC passes the age gate (P1): no gate yet → the app asks for
      // the birthday first; under-13 never; 13–17 (and an unconfirmed birth
      // year) not public.
      if (want === 'public') {
        const sp = await gbSocialProfile(env, user.id);
        if (!sp?.birth_year) return jsonResponse({ error: 'age_required' }, 428);
        if (sp.social_tier === 'blocked') return jsonResponse({ error: 'Sharing isn\'t available on this account' }, 403);
        if (gbAgeHeld(sp)) return gbAgeHeldResp(sp);
        if (sp.social_tier === 'teen') return jsonResponse({ error: 'Public passports open at age 18 — you\'ll be able to share with friends soon' }, 403);
        // Fail-closed photo moderation the moment the journal becomes public:
        // unchecked photos get reviewed in the background; the public
        // serializer only ever shows status 'ok'.
        const pq = await gbRest(env, `passport_stamp_photos?user_id=eq.${user.id}&mod_status=is.null&select=id,photo_key,stamp_id,user_id&limit=80`, {});
        const pending = pq.ok ? await pq.json() : [];
        if (pending.length && env.MEDIA) await Promise.race([ppReviewPhotos(env, pending), new Promise((r) => setTimeout(r, 6000))]);
      }
      const w = await gbRest(env, `passport_shares?user_id=eq.${user.id}`, { method: 'PATCH', headers: { Prefer: 'return=minimal' }, body: JSON.stringify({ is_public: want === 'public', visibility: want, updated_at: new Date().toISOString() }) });
      if (!w.ok) return jsonResponse({ error: 'Couldn’t save that — try again' }, 502);
      row.is_public = want === 'public';
      row.visibility = want;
      await pcBoardsCacheBust(env);   // a passport that closes takes its photos off the board covers now
    }
    const origin = new URL(request.url).origin;
    return jsonResponse({ slug: row.slug, is_public: !!row.is_public, audience: ppAud(row), url: `${origin}/p/${row.slug}` });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// What a shared booklet shows, for share links and visits alike: names, dates,
// art and photos — never the exact coordinates of every visit (privacy audit
// 2026-09-29: select=* leaked full-precision lat/lng of the owner's whole
// history to anyone with the slug). City + country stay; the numbers go.
// Nor where the stamper stood (founder, 2026-10-13; privacy §1: the stamp's
// rough zone "only our team sees"): meta.presence and the old birthday flag
// stay on the server, and so do account ids — the owner's and a tagger's (the
// booklet shows the tagger by tagged_by_name/_handle).
// ── Stamp tiers (founder, 2026-10-15): me ⊂ inner ⊂ followers ⊂ public ─────
// A stamp's tier; rows from before the migration fall back to what they meant.
// `fb` covers rows from before the migration backfills them (the ~20 s race): they mean
// what they meant — Only me if hidden, else whatever the booklet showed (public or inner).
const ppStampTier = (st, fb = 'inner') => st.visibility || (st.hidden ? 'me' : fb);
// The viewer level a tier needs: 'me' is the owner's alone (level 3 never reaches 99 —
// the owner is answered before this is asked).
const PP_TIER_NEED = { me: 99, inner: 2, followers: 1, public: 0 };
const PP_TIERS = ['me', 'inner', 'followers', 'public'];
const ppTierVisible = (st, lvl, fb = 'inner') => lvl >= (PP_TIER_NEED[ppStampTier(st, fb)] ?? 2);
// ── The passport is the ceiling (founder, 2026-10-26: "Yes, the passport is the ceiling") ──
// Four words everywhere: Only me · Friends · Followers · Everyone ('me' | 'inner' | 'followers'
// | 'public'). passport_shares.visibility holds the passport's; is_public stays true exactly when
// it is 'public', so every public surface (City Boards, the web page, strangers) keeps reading
// is_public. Rows from before read Friends unless public ('friends' / 'private' / null — today's
// private passports became Friends). A viewer below the passport's audience sees no stamp and no
// photo, whatever each stamp says: a stamp or an album can only narrow, never widen past it.
const ppAud = (share) => (share?.is_public === true ? 'public' : share?.visibility === 'me' || share?.visibility === 'followers' ? share.visibility : 'inner');
// The level this viewer reads the booklet at: their own, or -1 (nothing) below the audience.
const ppUnder = (aud, lvl) => (lvl >= 3 || lvl >= (PP_TIER_NEED[aud] ?? 2) ? lvl : -1);
// An album (a stamp's photos) may be narrower than its stamp: photos_tier 'me' | 'inner' |
// 'followers' | 'public' (2026-10-27); unset or 'public' follows the stamp.
const ppPhotosVisible = (st, lvl) => lvl >= 3 || !st?.photos_tier || lvl >= (PP_TIER_NEED[st.photos_tier] ?? 99);
// Who this viewer is to the owner: 3 the owner, 2 inner circle (mutual accepted),
// 1 an approved follower, 0 a stranger.
async function ppViewerLevel(env, ownerId, viewerId, inner = null) {
  if (viewerId && viewerId === ownerId) return 3;
  if (!viewerId) return 0;
  if (inner === true) return 2;
  if (inner !== true && await gbMutualFriends(env, viewerId, ownerId)) return 2;
  const q = await gbRest(env, `user_follows?follower_id=eq.${viewerId}&followee_id=eq.${ownerId}&status=eq.accepted&select=follower_id&limit=1`, {});
  return (q.ok && (await q.json()).length) ? 1 : 0;
}

// May this viewer see the owner's photo albums? The owner always; otherwise the albums
// dial (founder, 2026-10-15): 'passport' follows the booklet's audience, 'inner' (the
// default) mutual friends only — a public passport shows its pages but not its photos —
// and 'me' no one.
function ppAlbumsAllowedAt(ownerSp, lvl) {
  if (lvl >= 3) return true;
  // A minor's albums are private, full stop (founder, 2026-10-16).
  if (ownerSp?.social_tier === 'teen') return false;
  // The default moved from 'inner' to 'passport' on 2026-10-16 (founder: photos follow
  // their stamp onto city boards, heads-up instead of an ask). Explicit choices stand.
  const aud = ownerSp?.albums_audience || 'passport';
  if (aud === 'me') return false;
  if (aud === 'passport') return true;
  // 'followers' (2026-10-27): friends and approved followers.
  if (aud === 'followers') return lvl >= 1;
  return lvl >= 2;
}
// ── Photo links for other people (founder, 2026-10-18: "solidify our privacy") ──────────
// Every stamp photo shown to someone other than its owner goes out signed for the level it
// was shown at — '0' a stranger, '1' a follower, '2' the inner circle, 'b' a City Board — and
// expires (PP_PHOTO_TTL past the next hour, so a link stays the same for an hour). Opening it
// checks the signature, then checks again that the photo is still visible at that level: its
// stamp's tier, the albums dial, the private-passport switch, a held or under-18 owner, and on
// a board its takedown. Narrowing a stamp, closing the albums or going private takes effect at
// once; a block (enforced where the link is handed out) within the TTL. Owners keep their own
// key links (/pp-photo/<key>), which nobody else is given.
const PP_PHOTO_TTL = 6 * 3600;
const PP_PHOTO_LEVELS = new Set(['0', '1', '2', 'b']);
let ppPhotoKeyCache = null;
async function ppPhotoSig(env, id, lvl, exp) {
  if (!ppPhotoKeyCache) ppPhotoKeyCache = await crypto.subtle.importKey('raw', new TextEncoder().encode(`pp-photo:${GB_KEY(env)}`), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const mac = new Uint8Array(await crypto.subtle.sign('HMAC', ppPhotoKeyCache, new TextEncoder().encode(`${String(id).toLowerCase()}.${lvl}.${exp}`)));
  return btoa(String.fromCharCode(...mac.slice(0, 18))).replace(/\+/g, '-').replace(/\//g, '_');
}
async function ppPhotoUrl(env, origin, id, lvl) {
  const exp = Math.ceil(Date.now() / 3600e3) * 3600 + PP_PHOTO_TTL;
  return `${origin}/pp-photo/p/${id}?l=${lvl}&e=${exp}&s=${await ppPhotoSig(env, id, String(lvl), exp)}`;
}
// The photo's key when it may still be opened at this level, else null (fail closed).
async function ppPhotoOpenable(env, id, lvl) {
  const q = await gbRest(env, `passport_stamp_photos?id=eq.${id}&select=photo_key,mod_status,board_hidden,user_id,passport_stamps(visibility,hidden,user_id,photos_tier)`, {});
  const row = q.ok ? (await q.json())[0] : null;
  const st = row?.passport_stamps;
  if (!row || row.mod_status !== 'ok' || !st || st.user_id !== row.user_id || !String(row.photo_key || '').startsWith('pp/') || String(row.photo_key).includes('..')) return null;
  const [pq, sq] = await Promise.all([
    gbRest(env, `social_profiles?user_id=eq.${st.user_id}&select=user_id,albums_audience,${GB_TIER_COLS}`, {}),
    gbRest(env, `passport_shares?user_id=eq.${st.user_id}&select=is_public,visibility`, {}),
  ]);
  if (!pq.ok || !sq.ok) return null;
  const sp = gbTierRow((await pq.json())[0]);
  const shareRow = (await sq.json())[0];
  const isPublic = shareRow?.is_public === true;
  if (gbOffSocial(sp)) return null;
  const fb = isPublic ? 'public' : 'inner';
  if (lvl === 'b') {
    if (!isPublic || st.hidden || (st.photos_tier && st.photos_tier !== 'public') || ppStampTier(st, fb) !== 'public' || row.board_hidden || !pcAdultRow(sp) || ['inner', 'me', 'followers'].includes(sp?.albums_audience)) return null;
  } else {
    // Under the passport's ceiling (a viewer below it reads -1, which opens nothing).
    const n = ppUnder(ppAud(shareRow), Number(lvl));
    if (n < 0 || (n === 0 && !isPublic)) return null;
    if (!ppTierVisible(st, n, fb) || !ppPhotosVisible(st, n) || !ppAlbumsAllowedAt(sp, n)) return null;
  }
  return row.photo_key;
}
async function ppShareStamps(env, stamps, origin, withPhotos = true, lvl = null, fb = 'inner') {
  const level = lvl === null ? 0 : lvl;
  const sign = String(Math.min(2, Math.max(0, level)));
  const list = (stamps || []).filter((st) => (lvl === null ? !st.hidden : ppTierVisible(st, lvl, fb)));
  return Promise.all(list.map(async ({ lat, lng, note, note_public, meta, tagged_by, user_id, visibility, hidden, photos_tier, ...rest }) => ({
      ...rest,
      ...(meta && typeof meta === 'object' ? { meta: (({ presence, birthday, ...m }) => m)(meta) } : {}),
      // A trip note is private unless its owner chose to share it.
      ...(note_public && note ? { note, note_public: true } : {}),
      // Fail-closed: another viewer sees only photos that PASSED moderation,
      // each by its id, never by its key (gbRowMedia).
      // The owner (level 3) keeps their key links; everyone else gets a signed one.
      // An album set narrower than its stamp (photos_tier) keeps its photos from this level.
      photos: withPhotos && ppPhotosVisible({ photos_tier }, level) ? await Promise.all((rest.photos || []).filter((p) => p.mod_status === 'ok').map(async (p) => ({ ...p, photo_url: level >= 3 && p.photo_url ? p.photo_url : await ppPhotoUrl(env, origin, p.id, sign) }))) : [],
    })));
}

// Reviews stored passport photos ({ id, photo_key }), four at a time: 'ok' or 'blocked' by
// the reviewer's answer. A review that fails (the API down) leaves the photo unchecked, so a
// later sweep tries it again; it used to block the photo for good.
async function ppReviewPhotos(env, rows) {
  const one = async (p) => {
    try {
      const obj = await env.MEDIA.get(p.photo_key);
      if (!obj) return;
      const v = await gbModeratePhoto(env, ppBytesToB64(new Uint8Array(await obj.arrayBuffer())), obj.httpMetadata?.contentType || 'image/jpeg', 'memory');
      if (!v || v.reason) return;
      await gbRest(env, `passport_stamp_photos?id=eq.${p.id}`, { method: 'PATCH', headers: { Prefer: 'return=minimal' }, body: JSON.stringify({ mod_status: v.allow ? 'ok' : 'blocked', food_subject: v.allow && v.food ? 1 : 0 }) });
      // Now that it may hang on a board (a public stamp's photo), the owner hears about it.
      if (v.allow && p.stamp_id && p.user_id) await pcNoticeForStamps(env, p.user_id, [p.stamp_id]);
    } catch { /* stays unchecked → stays hidden from others */ }
  };
  for (let i = 0; i < rows.length; i += 4) await Promise.all(rows.slice(i, i + 4).map(one));
}

// A visit reviews the owner's unchecked photos (founder, 2026-10-14: friends saw no albums on
// a private passport, whose photos were never reviewed). Up to 40, newest first, at most one
// sweep per owner every 2 minutes. The visit waits up to 4 s, so it already shows most of
// them; the rest finish after the reply. Callers check first that the viewer may see them.
async function ppSweepPhotos(env, ctx, ownerId, lvl = 3) {
  if (!env.MEDIA || !env.GLOBESKIMMERS_KV || !ownerId) return;
  try {
    const lock = `ppsweep:${ownerId}`;
    if (await env.GLOBESKIMMERS_KV.get(lock)) return;
    // Only the stamps this viewer may open (the tiers, 2026-10-15): a stranger's visit
    // never sends an inner-circle album for review. A stamp with no tier yet reads as
    // inner, the legacy meaning.
    let onStamps = '';
    if (lvl < 3) {
      const tiers = PP_TIERS.filter((t) => PP_TIER_NEED[t] <= lvl);
      const vis = lvl >= 2 ? `or=(visibility.in.(${tiers.join(',')}),visibility.is.null)` : `visibility=in.(${tiers.join(',')})`;
      const sq = await gbRest(env, `passport_stamps?user_id=eq.${ownerId}&hidden=eq.false&${vis}&select=id&limit=500`, {});
      const ids = sq.ok ? (await sq.json()).map((st) => st.id) : [];
      if (!ids.length) return;
      onStamps = `&stamp_id=in.(${ids.join(',')})`;
    }
    const pq = await gbRest(env, `passport_stamp_photos?user_id=eq.${ownerId}&mod_status=is.null${onStamps}&order=created_at.desc&select=id,photo_key,stamp_id,user_id&limit=40`, {});
    const pending = pq.ok ? await pq.json() : [];
    if (!pending.length) return;
    await env.GLOBESKIMMERS_KV.put(lock, '1', { expirationTtl: 120 });
    const job = ppReviewPhotos(env, pending);
    if (ctx) ctx.waitUntil(job);
    await Promise.race([job, new Promise((r) => setTimeout(r, 4000))]);
  } catch { /* the visit goes on; unchecked photos stay hidden */ }
}

// Read-only passport by slug. Public → anyone. Private → the owner and their
// FRIENDS (mutual accepted follows) still see it in-app (founder, 2026-10-05:
// "private is with self and friends"); everyone else gets { private: true }.
async function handlePassportPublic(request, env, ctx) {
  try {
    const b = await request.json().catch(() => ({}));
    const slug = String(b.slug || '').replace(/[^a-z0-9]/gi, '');
    if (!slug) return jsonResponse({ private: true });
    const q = await gbRest(env, `passport_shares?slug=eq.${slug}&select=user_id,is_public,visibility`, {});
    let share = (q.ok ? await q.json() : [])[0];
    // An ask-first share link (tiers, 2026-10-15): its token grants a level — the public
    // slice, or deliberately the inner view — until it expires or is turned off.
    let linkLevel = null;
    if (!share) {
      const lq = await gbRest(env, `share_links?token=eq.${slug}&select=user_id,level,expires_at,revoked_at`, {});
      const link = (lq.ok ? await lq.json() : [])[0];
      if (link && !link.revoked_at && (!link.expires_at || Date.parse(link.expires_at) > Date.now())) {
        // The private switch means private (founder, 2026-10-18): a public-level link from a
        // private passport shows nothing; an inner-circle link the owner chose to send still works.
        const oq = await gbRest(env, `passport_shares?user_id=eq.${link.user_id}&select=is_public,visibility`, {});
        if (!oq.ok) return jsonResponse({ private: true });
        const ownerRow = (await oq.json())[0];
        const ownerPublic = ownerRow?.is_public === true;
        if (link.level === 'inner' || ownerPublic) {
          share = { user_id: link.user_id, is_public: ownerPublic, visibility: ownerRow?.visibility || null, via_link: true };
          linkLevel = link.level === 'inner' ? 2 : 0;
        }
      }
    }
    if (!share) return jsonResponse({ private: true });
    // Minors stay off every public surface (founder, 2026-10-13): a held teen,
    // a frozen under-13 or an unconfirmed birth year — or an owner whose age
    // can't be checked right now — reads exactly like any private passport,
    // even through a share link minted before the hold.
    const ownerSp = await gbSocialProfile(env, share.user_id).catch(() => undefined);
    if (gbOffSocial(ownerSp)) return jsonResponse({ private: true });
    // A block hides the pair both ways (block_v2, 2026-10-13): a blocked
    // viewer gets the same answer as any private passport, public or not.
    const viewer = await gbUser(request, env).catch(() => null);
    if (viewer && viewer.id !== share.user_id && await gbBlockedEither(env, viewer.id, share.user_id, { failClosed: true })) return jsonResponse({ private: true });
    // The viewer's level, raised by a link's granted level. A stranger with no link and
    // no public booklet reads private; everyone else gets their slice — and a slice with
    // nothing in it reads private too.
    let lvl = await ppViewerLevel(env, share.user_id, viewer?.id || null);
    if (linkLevel !== null && linkLevel > lvl) lvl = linkLevel;
    // The passport is the ceiling (2026-10-26): below its audience — a stranger on a Friends
    // passport, a follower on one kept to Friends, anyone at all on Only me, a link included —
    // reads private.
    lvl = ppUnder(ppAud(share), lvl);
    if (lvl < 0) return jsonResponse({ private: true });
    const withPhotos = ppAlbumsAllowedAt(ownerSp, lvl);
    if (withPhotos && lvl < 3) await ppSweepPhotos(env, ctx, share.user_id, lvl);
    const holder = await ppHolder(env, share.user_id);
    const { stamps } = await ppLoad(env, share.user_id);
    const origin = new URL(request.url).origin;
    const shared = await ppShareStamps(env, stamps, origin, withPhotos, lvl, share.is_public ? 'public' : 'inner');
    // Collectible stamps at this viewer's level (unset reads Friends); a viewer never learns the level.
    const collectibles = (await cbPlaced(env, share.user_id))
      .filter((c) => lvl >= 3 || lvl >= (PP_TIER_NEED[c.visibility || 'inner'] ?? 2))
      .map((c) => (lvl >= 3 ? c : { id: c.id, badge: c.badge, title: c.title, earned_at: c.earned_at }));
    if (!shared.length && !collectibles.length && lvl < 3) return jsonResponse({ private: true });
    // The cloth the owner's world is bound in (B2), for the visit page's cover.
    const holderCloth = (await gbFaces(env, [share.user_id], origin))[share.user_id]?.cloth || null;
    return jsonResponse({ holder, holder_cloth: holderCloth, stamps: shared, collectibles, stats: ppStats(shared), booklet: { order: ownerSp?.booklet_order || 'newest', seed: ownerSp?.shuffle_seed ?? null, custom: Array.isArray(ownerSp?.custom_order) ? ownerSp.custom_order : null } });
  } catch (e) { return jsonResponse({ error: e.message, private: true }, 500); }
}

// POST /passport/share-link { level: 'public'|'inner', hours?: number } — mint an
// ask-first link (founder, 2026-10-15): its token carries what it may show and when it
// stops working. POST /passport/share-links {} lists the live ones; { op:'revoke', token }
// turns one off. Only-me stamps are in no link, whatever the level.
async function handlePassportShareLink(request, env, ctx) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in' }, 401);
    const sp = await gbSocialProfile(env, user.id).catch(() => undefined);
    if (sp === undefined) return gbAgeUnknownResp();
    if (gbUnderAge(sp)) return gbUnderAgeResp();
    if (gbAgeHeld(sp)) return gbAgeHeldResp(sp);
    const b = await request.json().catch(() => ({}));
    const origin = new URL(request.url).origin;
    if (b.op === 'revoke') {
      const token = String(b.token || '').replace(/[^a-z0-9]/gi, '').slice(0, 40);
      if (!token) return jsonResponse({ error: 'token required' }, 400);
      await gbRest(env, `share_links?token=eq.${token}&user_id=eq.${user.id}`, { method: 'PATCH', headers: { Prefer: 'return=minimal' }, body: JSON.stringify({ revoked_at: new Date().toISOString() }) });
      return jsonResponse({ ok: true });
    }
    if (b.op === 'list' || (b.level === undefined && b.op === undefined)) {
      const q = await gbRest(env, `share_links?user_id=eq.${user.id}&revoked_at=is.null&order=created_at.desc&select=token,level,expires_at,created_at&limit=50`, {});
      const rows = (q.ok ? await q.json() : []).filter((r) => !r.expires_at || Date.parse(r.expires_at) > Date.now());
      return jsonResponse({ links: rows.map((r) => ({ ...r, url: `${origin}/p/${r.token}` })) });
    }
    const level = b.level === 'inner' ? 'inner' : 'public';
    const hours = Number(b.hours);
    const expires = Number.isFinite(hours) && hours > 0 ? new Date(Date.now() + Math.min(hours, 24 * 365) * 3600e3).toISOString() : null;
    const token = [...crypto.getRandomValues(new Uint8Array(9))].map((x) => 'abcdefghjkmnpqrstuvwxyz23456789'[x % 31]).join('');
    const w = await gbRest(env, 'share_links', { method: 'POST', headers: { Prefer: 'return=minimal' }, body: JSON.stringify({ token, user_id: user.id, level, expires_at: expires }) });
    if (!w.ok) return jsonResponse({ error: 'Could not make the link — try again' }, 502);
    if (ctx) ctx.waitUntil(gbLogEvent(env, 'share_link_minted', { level, hours: Number.isFinite(hours) ? hours : 0 }));
    return jsonResponse({ ok: true, token, level, expires_at: expires, url: `${origin}/p/${token}` });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// Shared-booklet landing page (web teaser + open-in-app + download).
async function handlePassportShareLanding(request, env, ctx) {
  try {
    const slug = decodeURIComponent(new URL(request.url).pathname.replace(/^\/p\//, '')).replace(/[^a-z0-9]/gi, '');
    // The growth funnel's first rung: every landing view is a share that
    // worked. installs-per-share reads from these three events.
    if (ctx && slug) ctx.waitUntil(gbLogEvent(env, 'share_landing_view', { slug }));
    let holder = null, stats = null, sample = [];
    if (slug) {
      const q = await gbRest(env, `passport_shares?slug=eq.${slug}&select=user_id,is_public,visibility`, {});
      let share = (q.ok ? await q.json() : [])[0];
      let landingLvl = share && share.is_public ? 0 : null;
      if (!share) {
        const lq = await gbRest(env, `share_links?token=eq.${slug}&select=user_id,level,expires_at,revoked_at`, {});
        const link = (lq.ok ? await lq.json() : [])[0];
        if (link && !link.revoked_at && (!link.expires_at || Date.parse(link.expires_at) > Date.now())) {
          // As in the app (founder, 2026-10-18): a public-level link from a private passport shows
          // nothing; an inner-circle link still does.
          const oq = await gbRest(env, `passport_shares?user_id=eq.${link.user_id}&select=is_public,visibility`, {});
          const ownerRow = oq.ok ? (await oq.json())[0] : null;
          const ownerPublic = ownerRow?.is_public === true;
          // …and under the passport's ceiling: an inner-circle link from an Only-me passport shows nothing.
          const linkLvl = ppUnder(ppAud(ownerRow), link.level === 'inner' ? 2 : 0);
          if (ownerRow && linkLvl >= 0 && (link.level === 'inner' || ownerPublic)) { share = { user_id: link.user_id, is_public: true, owner_public: ownerPublic }; landingLvl = linkLvl; }
        }
      }
      // The web page shows a name and stamps, so it gets the in-app rule
      // (founder, 2026-10-13): a held teen, a frozen under-13, an unconfirmed
      // birth year — or an age that can't be checked — gets the same
      // friends-only invite page as any private passport.
      const ownerSp = share && share.is_public ? await gbSocialProfile(env, share.user_id).catch(() => undefined) : undefined;
      if (share && share.is_public && !gbOffSocial(ownerSp)) {
        holder = await ppHolder(env, share.user_id);
        // Only the slice this link may show reaches the web page — not as a
        // name, not as a count. Only-me stamps never, whatever the link.
        const visible = (await ppLoad(env, share.user_id)).stamps.filter((st) => ppTierVisible(st, landingLvl ?? 0, share.owner_public === false ? 'inner' : 'public'));
        stats = ppStats(visible); sample = visible.slice(0, 8);
        // Nothing this link may show reads like a private passport (as /passport/public does),
        // never a name over an empty book.
        if (!visible.length) { holder = null; stats = null; sample = []; }
      }
    }
    const esc = (s) => String(s || '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
    const scheme = `globeskimmers://passport/view?u=${encodeURIComponent(slug)}`;
    // Link previews (growth plan, 2026-10-19): the title, a line and the site's own picture —
    // never a member's photo. A private passport reads like an invitation, with no name.
    const pageUrl = `${new URL(request.url).origin}/p/${slug}`;
    const ogTitle = holder ? `${holder}’s Virtual Passport · GlobeSkimmers` : 'A Virtual Passport on GlobeSkimmers';
    const ogDesc = holder && stats
      ? `${stats.total || 0} stamps · ${stats.countries || 0} countries · ${stats.cities || 0} cities. Verified stamps carry proof.`
      : 'Collect stamps where you go. Verified stamps carry proof. Free on iPhone and Android.';
    const chips = sample.map((s) => `<span class="chip">${esc(s.name)}</span>`).join('');
    const inner = !holder
      ? `<div class="stamp">🛂</div><h1>You’re invited to Globeskimmers</h1><p class="muted">This traveler shares with friends only — get the app, follow them, and start your own.</p>
         <a class="btn primary" href="${scheme}">Open in Globeskimmers</a>
         <a class="btn" href="/go/ios?src=${encodeURIComponent(slug || 'invite')}">Download for iPhone</a>
         <a class="btn" href="/go/android?src=${encodeURIComponent(slug || 'invite')}">Download for Android</a>`
      : `<div class="stamp">🛂</div><div class="eyebrow">Globeskimmers · Virtual Passport</div>
         <h1>${esc(holder)}&rsquo;s Virtual Passport</h1>
         <div class="stats"><b>${stats.total || 0}</b> stamps · <b>${stats.countries || 0}</b> countries · <b>${stats.cities || 0}</b> cities</div>
         <div class="chips">${chips}</div>
         <p>See the full booklet — stamps, photos & memories — in the app.</p>
         <a class="btn primary" href="${scheme}">Open in Globeskimmers</a>
         <a class="btn" href="/go/ios?src=${encodeURIComponent(slug)}">Download for iPhone</a>
         <a class="btn" href="/go/android?src=${encodeURIComponent(slug)}">Download for Android</a>`;
    const html = `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(ogTitle)}</title><meta name="robots" content="noindex"><meta property="og:type" content="website"><meta property="og:site_name" content="GlobeSkimmers"><meta property="og:title" content="${esc(ogTitle)}"><meta property="og:description" content="${esc(ogDesc)}"><meta property="og:image" content="https://globeskimmers.io/img/og.jpg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:url" content="${esc(pageUrl)}"><meta name="twitter:card" content="summary_large_image"><meta name="apple-itunes-app" content="app-id=6753154199, app-argument=${esc(scheme)}"><style>body{font-family:-apple-system,BlinkMacSystemFont,system-ui,sans-serif;background:#FFFCF7;color:#16110D;margin:0;padding:36px 20px;text-align:center}.wrap{max-width:440px;margin:0 auto}.stamp{font-size:60px;margin:6px 0}.eyebrow{font:600 11px/1 ui-monospace,Menlo,monospace;letter-spacing:.22em;text-transform:uppercase;color:#B0472F}h1{font-size:27px;margin:8px 0}.stats{color:#3A3128;font-size:15px;margin:2px 0 14px}.chips{display:flex;flex-wrap:wrap;gap:7px;justify-content:center;margin-bottom:16px}.chip{background:#F3E2C7;color:#8A5410;font-size:12px;font-weight:600;padding:4px 10px;border-radius:999px}p{font-size:15px;line-height:1.5;color:#3A3128}.btn{display:block;margin:10px auto;max-width:320px;padding:14px;border-radius:14px;text-decoration:none;font-weight:700;background:#fff;color:#16110D;border:1px solid rgba(0,0,0,.12)}.btn.primary{background:#B0472F;color:#fff;border:none}.muted{color:#736657}</style></head><body><div class="wrap">${inner}</div></body></html>`;
    return new Response(html, { headers: { 'Content-Type': 'text/html; charset=utf-8', 'Cache-Control': 'no-store', 'Access-Control-Allow-Origin': '*' } });
  } catch { return new Response('Error', { status: 500 }); }
}

// Attach one of the user's OWN photos to a stamp (R2). A photo on a 'self' stamp
// is also the PROOF that upgrades it to ✓ 'photo' (and lets them set the date).
// Private memory photos → no AI moderation (it's the user's own journal); the
// client resizes to ~1280px JPEG (which also drops EXIF/GPS). Key is UUID-based
// (unguessable) — private-by-obscurity, consistent with the guestbook serve path.
// ── Photo proof (founder, 2026-09-28) ───────────────────────────────────────
// 1) The photo's own location tag: the app reads GPS + DateTimeOriginal from
//    the ORIGINAL file before it resizes (the upload itself carries no EXIF),
//    and sends only {lat, lng, taken_at}; within 400 m of the stamp (airports
//    3 km) and within 2 days of the visit date → 'photo_loc'. Not stored.
// 2) Place recognition: Claude looks at the uploaded JPEG and says whether it
//    shows THIS place (exterior, signage, a signature exhibit). Selfies and
//    generic scenes come back "unsure" and earn nothing. yes + confidence ≥ 0.8
//    → 'photo_ai'. Capped per traveler per day; skipped once a stamp already
//    has a stronger proof. Model is one constant — Opus 5 by default; Haiku 4.5
//    is the cheaper option the founder can pick (~0.2¢ vs ~1.3¢ a photo).
const PP_VISION_MODEL = 'claude-opus-5';
const PP_VISION_DAILY_CAP = 20;
const PP_VISION_PROMPT = [
  'You check whether a traveler\'s photo shows a specific place, for a travel passport stamp.',
  'Answer "yes" only when the photo itself shows something that identifies THIS place: its exterior, its name or signage, a distinctive interior, exhibit or view known to be at this place.',
  'Answer "unsure" for selfies, food, people, a generic room or a scene that could be at many places, even if it might be here.',
  'Answer "no" when the photo clearly shows a different place.',
  'confidence is a number from 0 to 1. reason is one short plain sentence.',
].join(' ');
const PP_VISION_SCHEMA = {
  type: 'object',
  properties: {
    match: { type: 'string', enum: ['yes', 'no', 'unsure'] },
    confidence: { type: 'number' },
    reason: { type: 'string' },
  },
  required: ['match', 'confidence', 'reason'],
  additionalProperties: false,
};
function ppBytesToB64(bytes) {
  let binary = '';
  for (let i = 0; i < bytes.length; i += 0x8000) binary += String.fromCharCode.apply(null, bytes.subarray(i, i + 0x8000));
  return btoa(binary);
}
function ppPhotoLocProves(stamp, exif) {
  if (!exif || !Number.isFinite(+stamp?.lat) || !Number.isFinite(+stamp?.lng)) return false;
  const lat = +exif.lat, lng = +exif.lng;
  if (!Number.isFinite(lat) || !Number.isFinite(lng) || (lat === 0 && lng === 0)) return false;
  // An inside-only place: the photo was taken inside its outline, or it proves nothing.
  const inside = ppShapeNear(stamp.name, +stamp.lat, +stamp.lng);
  const meters = inside?.inside_only ? ppMetersToShape(inside, lat, lng) : haversineMilesLoc(+stamp.lat, +stamp.lng, lat, lng) * 1609.34;
  if (inside?.inside_only ? meters > 0 : meters > (stamp.kind === 'airport' ? 3000 : 400)) return false;
  const d = String(exif.taken_at || '').slice(0, 10);
  if (stamp.visited_on && /^\d{4}-\d{2}-\d{2}$/.test(d)) {
    if (Math.abs(Date.parse(d) - Date.parse(stamp.visited_on)) / 86400000 > 2) return false;
  }
  return true;
}
async function ppVisionAllowed(env, userId) {
  if (!env.GLOBESKIMMERS_KV) return true;
  const k = `pp:vision:${userId}:${new Date().toISOString().slice(0, 10)}`;
  const n = Number(await env.GLOBESKIMMERS_KV.get(k).catch(() => 0)) || 0;
  if (n >= PP_VISION_DAILY_CAP) return false;
  await env.GLOBESKIMMERS_KV.put(k, String(n + 1), { expirationTtl: 2 * 86400 }).catch(() => {});
  return true;
}
// → { match, confidence, reason } or null (no key, timeout, refusal, bad JSON).
async function ppRecognizePlace(env, bytes, mediaType, stamp) {
  if (!env.ANTHROPIC_API_KEY || !stamp?.name) return null;
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), 20000);
  try {
    const where = [stamp.city, stamp.country].filter(Boolean).join(', ');
    const res = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST', signal: ctrl.signal,
      headers: {
        'x-api-key': env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01',
        'anthropic-beta': 'server-side-fallback-2026-07-01', 'content-type': 'application/json',
      },
      body: JSON.stringify({
        model: PP_VISION_MODEL, max_tokens: 2048, fallbacks: 'default',
        output_config: { effort: 'low', format: { type: 'json_schema', schema: PP_VISION_SCHEMA } },
        system: PP_VISION_PROMPT,
        messages: [{ role: 'user', content: [
          { type: 'image', source: { type: 'base64', media_type: mediaType, data: ppBytesToB64(bytes) } },
          { type: 'text', text: `Place: ${stamp.name}${where ? `\nWhere: ${where}` : ''}` },
        ] }],
      }),
    });
    if (!res.ok) return null;
    const d = await res.json().catch(() => null);
    if (!d || d.stop_reason === 'refusal' || d.stop_reason === 'max_tokens') return null;
    const text = (d.content || []).find((c) => c && c.type === 'text')?.text;
    const v = text ? JSON.parse(text) : null;
    if (!v || !['yes', 'no', 'unsure'].includes(v.match)) return null;
    return { match: v.match, confidence: Math.max(0, Math.min(1, Number(v.confidence) || 0)), reason: String(v.reason || '').slice(0, 200) };
  } catch { return null; }
  finally { clearTimeout(t); }
}
const ppAiProves = (v) => !!v && v.match === 'yes' && v.confidence >= 0.8;

async function handlePassportPhotoUpload(request, env, ctx) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in to add a photo' }, 401);
    const upSp = await gbSocialProfile(env, user.id).catch(() => undefined);
    if (upSp === undefined) return gbAgeUnknownResp();
    if (gbUnderAge(upSp)) return gbUnderAgeResp();
    if (gbNeedsConfirm(upSp)) return gbConfirmResp();
    if (!env.MEDIA) return jsonResponse({ error: 'Photo storage not configured' }, 500);
    const b = await request.json().catch(() => ({}));
    const stampId = String(b.stamp_id || '');
    if (!stampId) return jsonResponse({ error: 'stamp_id required' }, 400);
    const sq = await gbRest(env, `passport_stamps?id=eq.${stampId}&user_id=eq.${user.id}&select=id,verified,kind,name,city,country,lat,lng,visited_on`, {});
    const stamp = (sq.ok ? await sq.json() : [])[0];
    if (!stamp) return jsonResponse({ error: 'Stamp not found' }, 404);

    let data = String(b.image || ''); let mediaType = 'image/jpeg';
    const m = data.match(/^data:(image\/(?:jpeg|jpg|png|webp));base64,(.*)$/i);
    if (m) { mediaType = m[1].toLowerCase() === 'image/jpg' ? 'image/jpeg' : m[1].toLowerCase(); data = m[2]; }
    else if (b.content_type && /^image\/(jpeg|png|webp)$/i.test(b.content_type)) { mediaType = String(b.content_type).toLowerCase(); }
    data = data.replace(/\s/g, '');
    if (!data) return jsonResponse({ error: 'No image data' }, 400);
    let bytes;
    try { bytes = Uint8Array.from(atob(data), (c) => c.charCodeAt(0)); } catch { return jsonResponse({ error: 'Bad image data' }, 400); }
    if (bytes.length > 4 * 1024 * 1024) return jsonResponse({ error: 'Photo too large (please pick a smaller image)' }, 400);
    if (bytes.length < 500) return jsonResponse({ error: 'That image is too small' }, 400);

    const ext = mediaType === 'image/png' ? 'png' : mediaType === 'image/webp' ? 'webp' : 'jpg';
    const key = `pp/${user.id}/${stampId}/${crypto.randomUUID()}.${ext}`;
    await env.MEDIA.put(key, bytes, { httpMetadata: { contentType: mediaType, cacheControl: 'public, max-age=31536000, immutable' } });
    const origin = new URL(request.url).origin;
    const photoUrl = `${origin}/pp-photo/${key}`;
    let upCaption = b.caption ? String(b.caption).replace(/\s+/g, ' ').trim().slice(0, 200) || null : null;
    if (upCaption && !(await gbModerate(env, upCaption)).allow) upCaption = null;
    await gbRest(env, 'passport_stamp_photos', { method: 'POST', headers: { Prefer: 'return=minimal' }, body: JSON.stringify({ stamp_id: stampId, user_id: user.id, photo_key: key, photo_url: photoUrl, caption: upCaption }) });
    // Review this photo now (async): only a reviewed photo shows to anyone else. A private
    // passport is seen by its inner circle (mutual follows, 2026-10-05), so an adult's photo
    // is reviewed public or not; it used to wait for a public booklet, and friends saw no
    // albums (founder, 2026-10-14). A minor's passport is seen by no one else: no review.
    if (ctx && !gbOffSocial(upSp)) ctx.waitUntil((async () => {
      try {
        const v = await gbModeratePhoto(env, data, mediaType, 'memory');
        if (!v || v.reason) return; // the review itself failed: unchecked, so a visit retries it
        await gbRest(env, `passport_stamp_photos?photo_key=eq.${encodeURIComponent(key)}`, { method: 'PATCH', headers: { Prefer: 'return=minimal' }, body: JSON.stringify({ mod_status: v.allow ? 'ok' : 'blocked', food_subject: v.allow && v.food ? 1 : 0 }) });
      } catch { /* stays unchecked → stays owner-only until a visit retries it */ }
    })());

    // Proof from this photo — location tag first (free), then recognition.
    const patch = {};
    const asked = ppDate(b.visited_on);
    const visitedOn = asked && ppDateAllowed(asked) ? asked : null;
    if (visitedOn) patch.visited_on = visitedOn;
    const rankOf = (v) => PP_VERIFY_RANK[v] ?? 0;
    const forCheck = { ...stamp, visited_on: visitedOn || stamp.visited_on };
    const exif = b.exif && typeof b.exif === 'object' ? b.exif : null;
    // A photo taken before stamps reach back (PP_EARLIEST) proves no visit, by its location
    // or by what's in it.
    const takenDay = String(exif?.taken_at || '').slice(0, 10);
    const tooOld = /^\d{4}-\d{2}-\d{2}$/.test(takenDay) && takenDay < PP_EARLIEST;
    let proof = null, ai = null;
    if (!tooOld && rankOf(stamp.verified) < rankOf('photo_loc') && ppPhotoLocProves(forCheck, exif)) proof = 'photo_loc';
    // Recognition can't tell inside from outside (a facade photo is taken from the street), so an
    // inside-only place is proven by the photo's location tag alone.
    const insideOnly = !!ppShapeNear(stamp.name, +stamp.lat, +stamp.lng)?.inside_only;
    if (!proof && !insideOnly && !tooOld && rankOf(stamp.verified) < rankOf('photo_ai') && mediaType === 'image/jpeg' && await ppVisionAllowed(env, user.id)) {
      ai = await ppRecognizePlace(env, bytes, mediaType, stamp);
      if (ppAiProves(ai)) proof = 'photo_ai';
    }
    const earned = proof || 'photo';
    if (rankOf(earned) > rankOf(stamp.verified)) patch.verified = earned;
    if (Object.keys(patch).length) {
      patch.updated_at = new Date().toISOString();
      await gbRest(env, `passport_stamps?id=eq.${stampId}`, { method: 'PATCH', headers: { Prefer: 'return=minimal' }, body: JSON.stringify(patch) });
    }
    if (ctx) ctx.waitUntil(gbLogEvent(env, 'passport_photo', { bytes: bytes.length, has_gps: !!(exif && Number.isFinite(+exif.lat)), has_time: !!(exif && exif.taken_at), proof, ai_match: ai?.match || null, ai_confidence: ai?.confidence ?? null }));
    return jsonResponse({ key, url: photoUrl, verified: patch.verified || stamp.verified, proof, ai: ai ? { match: ai.match, confidence: ai.confidence } : null });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// POST /passport/stamp/check-photos { stamp_id } — run place recognition on a
// stamp's EXISTING memory photos (they were stored without their location
// tags, so recognition is the only proof left for them). Stops at the first
// photo that proves the visit; up to 3 photos; same daily cap.
async function handlePassportCheckPhotos(request, env, ctx) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in' }, 401);
    if (!env.MEDIA) return jsonResponse({ error: 'Photo storage not configured' }, 500);
    const b = await request.json().catch(() => ({}));
    const stampId = String(b.stamp_id || '').replace(/[^0-9a-f-]/gi, '').slice(0, 40);
    if (!stampId) return jsonResponse({ error: 'stamp_id required' }, 400);
    const sq = await gbRest(env, `passport_stamps?id=eq.${stampId}&user_id=eq.${user.id}&select=id,verified,kind,name,city,country`, {});
    const stamp = (sq.ok ? await sq.json() : [])[0];
    if (!stamp) return jsonResponse({ error: 'Stamp not found' }, 404);
    const rankOf = (v) => PP_VERIFY_RANK[v] ?? 0;
    if (rankOf(stamp.verified) >= rankOf('photo_ai')) return jsonResponse({ ok: true, verified: stamp.verified, checked: 0, already: true });
    const pq = await gbRest(env, `passport_stamp_photos?stamp_id=eq.${stampId}&user_id=eq.${user.id}&order=created_at.asc&select=photo_key&limit=3`, {});
    const photos = pq.ok ? await pq.json() : [];
    let checked = 0, best = null;
    for (const ph of photos) {
      if (!ph.photo_key || !/\.jpe?g$/i.test(ph.photo_key)) continue;
      if (!(await ppVisionAllowed(env, user.id))) return jsonResponse({ ok: false, error: 'Daily photo check limit reached — try again tomorrow', checked });
      const obj = await env.MEDIA.get(ph.photo_key).catch(() => null);
      if (!obj) continue;
      const bytes = new Uint8Array(await obj.arrayBuffer());
      const v = await ppRecognizePlace(env, bytes, 'image/jpeg', stamp);
      checked += 1;
      if (v && (!best || v.confidence > best.confidence)) best = v;
      if (ppAiProves(v)) {
        await gbRest(env, `passport_stamps?id=eq.${stampId}`, { method: 'PATCH', headers: { Prefer: 'return=minimal' }, body: JSON.stringify({ verified: 'photo_ai', updated_at: new Date().toISOString() }) });
        if (ctx) ctx.waitUntil(gbLogEvent(env, 'passport_photo_check', { checked, proof: 'photo_ai', ai_confidence: v.confidence }));
        return jsonResponse({ ok: true, verified: 'photo_ai', checked, match: v.match, confidence: v.confidence });
      }
    }
    if (ctx) ctx.waitUntil(gbLogEvent(env, 'passport_photo_check', { checked, proof: null, ai_match: best?.match || null }));
    return jsonResponse({ ok: true, verified: stamp.verified, checked, match: best?.match || null, reason: best?.reason || null });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// /go/<ios|android>?src=<slug> — the store hop, logged so installs-per-share
// has its middle rung (view → store tap → install). The src rides to the
// store page as campaign context where the store allows it.
function handleStoreGo(request, env, ctx) {
  const u = new URL(request.url);
  const store = u.pathname.replace(/^\/go\//, '').replace(/[^a-z]/g, '');
  const src = String(u.searchParams.get('src') || '').replace(/[^a-z0-9]/gi, '').slice(0, 24);
  const dest = store === 'android'
    ? `${PP_PLAY_URL}&referrer=${encodeURIComponent(`utm_source=share&utm_content=${src}`)}`
    // Apple counts a download only with BOTH pt and ct (2026-10-19); ct is a fixed code, never the slug.
    : `${PP_IOS_URL}?pt=121139771&ct=share&mt=8`;
  if (ctx) ctx.waitUntil(gbLogEvent(env, 'share_landing_store', { slug: src, store: store === 'android' ? 'android' : 'ios' }));
  return new Response(null, { status: 302, headers: { Location: dest, 'Cache-Control': 'no-store' } });
}

// Serve bespoke landmark STAMP ART from R2 (shared, public, long-cached). Files
// live at stamp-art/<slug>.png (e.g. stamp-art/eiffel-tower.png). Add art by
// uploading to R2 — no app release. Returns 404 when a landmark has no bespoke
// art yet (the app falls back to a category/emoji stamp). See docs/PASSPORT_ICON_LIST.md.
// ── Airport boundary geofence: is this GPS point INSIDE an airport? ──────────
// Uses aeroway=aerodrome polygons (OSM) bucketed by geohash-4 in KV (key
// aero:<gh4>). True "inside the fence" (terminals/runways/planes), not drive-by.
const GH_B32 = "0123456789bcdefghjkmnpqrstuvwxyz";
function geohash4(lat, lng) {
  let idx = 0, bit = 0, even = true, hash = "";
  let latMin = -90, latMax = 90, lngMin = -180, lngMax = 180;
  while (hash.length < 4) {
    if (even) { const mid = (lngMin + lngMax) / 2; if (lng >= mid) { idx = idx * 2 + 1; lngMin = mid; } else { idx *= 2; lngMax = mid; } }
    else { const mid = (latMin + latMax) / 2; if (lat >= mid) { idx = idx * 2 + 1; latMin = mid; } else { idx *= 2; latMax = mid; } }
    even = !even;
    if (++bit === 5) { hash += GH_B32[idx]; bit = 0; idx = 0; }
  }
  return hash;
}
function pointInRing(lat, lng, ring) {
  let inside = false;
  for (let i = 0, j = ring.length - 1; i < ring.length; j = i++) {
    const yi = ring[i][0], xi = ring[i][1], yj = ring[j][0], xj = ring[j][1];
    if (((yi > lat) !== (yj > lat)) && (lng < ((xj - xi) * (lat - yi)) / (yj - yi) + xi)) inside = !inside;
  }
  return inside;
}
async function handleAirportAt(request, env) {
  try {
    const url = new URL(request.url);
    const lat = parseFloat(url.searchParams.get('lat'));
    const lng = parseFloat(url.searchParams.get('lng'));
    const acc = parseFloat(url.searchParams.get('acc'));
    if (!Number.isFinite(lat) || !Number.isFinite(lng)) return jsonResponse({ error: 'lat/lng required' }, 400);
    if (Number.isFinite(acc) && acc > 300) return jsonResponse({ airport: null, reason: 'low_accuracy' });
    if (!env.GLOBESKIMMERS_KV) return jsonResponse({ airport: null });
    const raw = await env.GLOBESKIMMERS_KV.get(`aero:${geohash4(lat, lng)}`);
    if (!raw) return jsonResponse({ airport: null });
    const recs = JSON.parse(raw);
    const BUF = 0.0006; // ~65 m fence tolerance for GPS jitter
    for (const a of recs) {
      const [s, w, n, e] = a.bbox;
      if (lat < s - BUF || lat > n + BUF || lng < w - BUF || lng > e + BUF) continue;
      for (const ring of (a.rings || [])) {
        if (pointInRing(lat, lng, ring)) {
          return jsonResponse({ airport: { iata: a.iata, name: a.name, city: a.city, cc: a.cc, lat: (s + n) / 2, lng: (w + e) / 2 } });
        }
      }
    }
    return jsonResponse({ airport: null });
  } catch (e) { return jsonResponse({ error: e.message, airport: null }, 500); }
}

// ── Free place/city search for "Stamp a place" — proxies OSM Nominatim (free),
// cached 30d in KV. On-demand search (not per-keystroke) to respect OSM policy.
async function handlePlaceSearch(request, env) {
  try {
    const url = new URL(request.url);
    const q = (url.searchParams.get('q') || '').trim();
    if (q.length < 2) return jsonResponse({ results: [] });
    const near = url.searchParams.get('near'); // "lat,lng" (optional bias)
    // place2: English names (place: kept local ones, "東京都, 日本", for 30 days).
    const cacheKey = `place2:${q.toLowerCase().slice(0, 80)}${near ? '@' + near : ''}`;
    if (env.GLOBESKIMMERS_KV) { const c = await env.GLOBESKIMMERS_KV.get(cacheKey); if (c) return jsonResponse({ results: JSON.parse(c), cached: true }); }
    let viewbox = '';
    if (near) { const [la, ln] = near.split(',').map(Number); if (Number.isFinite(la) && Number.isFinite(ln)) viewbox = `&viewbox=${ln - 1.5},${la + 1.5},${ln + 1.5},${la - 1.5}`; }
    // English names, as the stamp prints them: "Tokyo, Japan" and "Eiffel Tower", not
    // "東京都, 日本" and "Tour Eiffel"; the original rides along as `local` when it's
    // another alphabet (namedetails: the place's own name tags).
    const nom = `https://nominatim.openstreetmap.org/search?format=jsonv2&addressdetails=1&namedetails=1&limit=6&accept-language=en&q=${encodeURIComponent(q)}${viewbox}`;
    const r = await fetch(nom, { headers: { 'User-Agent': 'Globeskimmers/1.0 (travel app place stamps; support@globeskimmers.io)', 'Accept': 'application/json' } });
    if (!r.ok) return jsonResponse({ results: [] });
    const raw = await r.json();
    const seen = new Set();
    const results = (Array.isArray(raw) ? raw : []).map((p) => {
      const a = p.address || {};
      const city = a.city || a.town || a.village || a.hamlet || a.municipality || a.county || '';
      const name = p.name || String(p.display_name || '').split(',')[0] || '';
      return { name, local: ppLocalName(name, ppNativeName(p.namedetails, a.country_code)), display: p.display_name, city, country: a.country || '', cc: String(a.country_code || '').toUpperCase(), lat: +p.lat, lng: +p.lon, type: p.type };
    }).filter((x) => {
      // One row per place: Paris came back three times (the city and two of its boundaries).
      const k = `${x.name}|${x.city}|${x.cc}`.toLowerCase();
      if (!Number.isFinite(x.lat) || seen.has(k)) return false;
      seen.add(k);
      return true;
    });
    if (env.GLOBESKIMMERS_KV) await env.GLOBESKIMMERS_KV.put(cacheKey, JSON.stringify(results), { expirationTtl: 2592000 });
    return jsonResponse({ results });
  } catch (e) { return jsonResponse({ error: e.message, results: [] }, 500); }
}

// POST /photo-place { lat, lng } — where a trip photo was taken, for "Stamp a place" from a
// photo (founder, 2026-10-14: "the app senses which city and state the photo was taken from
// … give three options"): the famous places within reach of that spot, and the city it's in
// with the wider one around it ("Shinjuku" in "Tokyo"). Cached a week per ~110 m.
async function handlePhotoPlace(request, env) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in' }, 401);
    const b = await request.json().catch(() => ({}));
    const lat = Math.round(Number(b.lat) * 1000) / 1000;
    const lng = Math.round(Number(b.lng) * 1000) / 1000;
    if (!Number.isFinite(lat) || !Number.isFinite(lng) || Math.abs(lat) > 90 || Math.abs(lng) > 180 || (lat === 0 && lng === 0)) return jsonResponse({ error: 'lat and lng required' }, 400);
    const key = `photoplace:v1:${lat}_${lng}`;
    if (env.GLOBESKIMMERS_KV) {
      const hit = await env.GLOBESKIMMERS_KV.get(key, { type: 'json' }).catch(() => null);
      if (hit) return jsonResponse({ ...hit, cached: true });
    }
    const [places, cities] = await Promise.all([ppPlacesNear(env, lat, lng), ppCitiesAt(env, lat, lng)]);
    if (env.GLOBESKIMMERS_KV && cities.length) await env.GLOBESKIMMERS_KV.put(key, JSON.stringify({ places, cities }), { expirationTtl: 7 * 86400 }).catch(() => {});
    return jsonResponse({ places, cities });
  } catch (e) { return jsonResponse({ error: e.message, places: [], cities: [] }, 500); }
}

// Up to 3 stamp-worthy places whose reach covers the point, nearest first: each place's own
// footprint, and never less than the 400 m a photo's location proves. No secret stamps:
// those are found by being there now.
async function ppPlacesNear(env, lat, lng) {
  if (!env.ATTRACTIONS_DB) return [];
  const dLat = 2.5 / 111, dLng = 2.5 / (111 * Math.cos(lat * Math.PI / 180) || 1);
  const rs = await env.ATTRACTIONS_DB.prepare(
    `SELECT id, name, category, city, country, lat, lng, footprint_radius_m FROM attractions
      WHERE lat BETWEEN ?1 AND ?2 AND lng BETWEEN ?3 AND ?4
        AND (class_ban IS NULL OR class_ban = '' OR class_ban LIKE 'review:%')
        AND (tier IS NULL OR tier != 'secret')
        AND coalesce(founder_scope, scope) IN ('world','national','regional')
      LIMIT 200`).bind(lat - dLat, lat + dLat, lng - dLng, lng + dLng).all().catch(() => ({ results: [] }));
  return (rs.results || [])
    .map((r) => ({ r, m: haversineMilesLoc(lat, lng, r.lat, r.lng) * 1609.34 }))
    .filter(({ r, m }) => m <= Math.max(400, ppStampRadius(r)))
    .sort((x, y) => x.m - y.m)
    .slice(0, 3)
    .map(({ r, m }) => ({ id: String(r.id), name: r.name, city: r.city || '', country: r.country || '', lat: r.lat, lng: r.lng, meters: Math.round(m) }));
}

// The city a point is in, and the wider city around it when it's a ward or district:
// [{ city, local, within, region, country, cc }]. OpenStreetMap (free) names them in English
// with the original alphabet beside it; a spot in no city takes its named area (Universal
// City, in Los Angeles County). Google's reverse geocode names the city when OpenStreetMap
// doesn't answer. region is the state, for the US and Canada.
async function ppCitiesAt(env, lat, lng) {
  const headers = { 'User-Agent': 'Globeskimmers/1.0 (travel app place stamps; support@globeskimmers.io)', Accept: 'application/json' };
  const rev = (zoom, extra) => fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${lat}&lon=${lng}&zoom=${zoom}&accept-language=en${extra}`, { headers })
    .then((r) => (r.ok ? r.json() : null)).then((d) => (d && !d.error ? d : null)).catch(() => null);
  const spot = await rev(18, '&addressdetails=1');
  const a = spot?.address || null;
  if (!a?.country) {
    try {
      const g = await (await handleReverseGeocode(new Request('https://w.local/reverse-geocode', { method: 'POST', body: JSON.stringify({ latitude: lat, longitude: lng, precise: true }) }), env)).json();
      return g?.city ? [{ city: g.city, local: null, within: null, region: g.region || null, country: g.country || '', cc: '' }] : [];
    } catch { return []; }
  }
  const cc = String(a.country_code || '').toUpperCase();
  const base = { region: cc === 'US' || cc === 'CA' ? a.state || null : null, country: a.country, cc };
  const out = [];
  const add = (city, local, within) => {
    const c = String(city || '').trim();
    if (!c || out.some((o) => o.city.toLowerCase() === c.toLowerCase())) return;
    out.push({ city: c, local: ppLocalName(c, local), within: within || null, ...base });
  };
  // Zoom 10 is the city or ward; zoom 8, asked only for a ward or district, the city it's in.
  const town = await rev(10, '&namedetails=1');
  const wider = town && Number(town.place_rank) >= 14 ? await rev(8, '&namedetails=1') : null;
  const wide = wider?.addresstype === 'city' && wider.name && wider.name !== town?.name ? wider : null;
  if (!(a.city || a.town || a.village || a.municipality)) add(a.quarter || a.suburb || a.hamlet, null, town?.name);
  add(town?.name || a.city || a.town || a.village || a.municipality, ppNativeName(town?.namedetails, cc), wide?.name);
  if (wide) add(wide.name, ppNativeName(wide.namedetails, cc), null);
  return out.slice(0, 3);
}

async function handleStampArtServe(request, env) {
  try {
    if (!env.MEDIA) return new Response('Not found', { status: 404 });
    const rel = decodeURIComponent(new URL(request.url).pathname.replace(/^\/stamp-art\//, ''));
    // Subpaths are legal now (luggage faces live at luggage/<type>/<face>.<ext>);
    // only traversal and odd characters are not.
    if (!rel || rel.includes('..') || !/^[a-z0-9][a-z0-9/_.-]*$/i.test(rel)) return new Response('Bad key', { status: 400 });
    let obj = await env.MEDIA.get(`stamp-art/${rel}`);
    // Extension-forgiving: the app asks for .webp, but whatever the founder
    // actually exported (.png/.jpg) serves from the same URL — no re-OTA.
    if (!obj) {
      const m = rel.match(/^(.*)\.(webp|png|jpe?g)$/i);
      if (m) {
        for (const ext of ['webp', 'png', 'jpg', 'jpeg']) {
          if (ext === m[2].toLowerCase()) continue;
          obj = await env.MEDIA.get(`stamp-art/${m[1]}.${ext}`);
          if (obj) break;
        }
      }
    }
    if (!obj) return new Response('Not found', { status: 404 });
    const headers = new Headers();
    headers.set('Content-Type', obj.httpMetadata?.contentType || 'image/png');
    headers.set('Cache-Control', 'public, max-age=2592000'); // 30d
    headers.set('Access-Control-Allow-Origin', '*');
    if (/svg/i.test(headers.get('Content-Type') || '')) {
      // Flag art is SVG: opened directly it may never run script on our origin.
      headers.set('Content-Security-Policy', "default-src 'none'; style-src 'unsafe-inline'; img-src data:");
      headers.set('X-Content-Type-Options', 'nosniff');
    }
    if (obj.httpEtag) headers.set('ETag', obj.httpEtag);
    return new Response(obj.body, { headers });
  } catch { return new Response('Error', { status: 500 }); }
}

// POST /passport/stamp/move { stamp_id, pos } — drag-to-arrange (founder, 2026-10-15):
// the stamp's place in the owner's own ordering (a fractional number between its new
// neighbours). The app sets booklet_order 'custom' through social/profile.
async function handlePassportStampMove(request, env) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in' }, 401);
    const b = await request.json().catch(() => ({}));
    const id = String(b.stamp_id || '');
    const pos = Number(b.pos);
    if (!BL_UUID.test(id) || !Number.isFinite(pos)) return jsonResponse({ error: 'stamp_id + pos required' }, 400);
    const w = await gbRest(env, `passport_stamps?id=eq.${id}&user_id=eq.${user.id}`, { method: 'PATCH', headers: { Prefer: 'return=minimal' }, body: JSON.stringify({ pos, updated_at: new Date().toISOString() }) });
    if (!w.ok) return jsonResponse({ error: 'Could not move' }, 502);
    return jsonResponse({ ok: true });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// POST /passport/stamp/note { stamp_id, note?, public? } — the trip note on a
// stamp ("what was this trip for?"). Private by default; sharing it on the
// passport passes the text moderation door first.
async function handlePassportStampNote(request, env) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in' }, 401);
    const b = await request.json().catch(() => ({}));
    const id = String(b.stamp_id || '');
    if (!BL_UUID.test(id)) return jsonResponse({ error: 'Not found' }, 404);
    const q = await gbRest(env, `passport_stamps?id=eq.${id}&user_id=eq.${user.id}&select=note,note_public`, {});
    const cur = (q.ok ? await q.json() : [])[0];
    if (!cur) return jsonResponse({ error: 'Not found' }, 404);
    const note = b.note !== undefined ? (String(b.note || '').replace(/\s+/g, ' ').trim().slice(0, 280) || null) : cur.note;
    const isPublic = b.public !== undefined ? b.public === true : cur.note_public === true;
    if (isPublic && note) {
      const mod = await gbModerate(env, note);
      if (!mod.allow) return jsonResponse({ error: 'Let\u2019s keep shared notes kind \u2014 edit it, or untick sharing to keep it private. Nothing was saved.' }, 422);
    }
    const w = await gbRest(env, `passport_stamps?id=eq.${id}&user_id=eq.${user.id}`, { method: 'PATCH', headers: { Prefer: 'return=minimal' }, body: JSON.stringify({ note, note_public: !!(isPublic && note) }) });
    if (!w.ok) return jsonResponse({ error: 'Could not save' }, 502);
    return jsonResponse({ ok: true, note, note_public: !!(isPublic && note) });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// POST /passport/photo/caption { photo_id, caption } — the owner's line under
// a photo (≤200 chars, moderated like guestbook notes; '' clears it).
async function handlePassportPhotoCaption(request, env) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in' }, 401);
    const b = await request.json().catch(() => ({}));
    const id = String(b.photo_id || '');
    if (!BL_UUID.test(id)) return jsonResponse({ error: 'Not found' }, 404);
    const caption = String(b.caption || '').replace(/\s+/g, ' ').trim().slice(0, 200);
    if (caption) {
      const mod = await gbModerate(env, caption);
      if (!mod.allow) return jsonResponse({ error: 'Let\u2019s keep captions kind \u2014 try different words' }, 422);
    }
    const w = await gbRest(env, `passport_stamp_photos?id=eq.${id}&user_id=eq.${user.id}`, { method: 'PATCH', headers: { Prefer: 'return=representation' }, body: JSON.stringify({ caption: caption || null }) });
    const rows = w.ok ? await w.json() : [];
    if (!rows.length) return jsonResponse({ error: 'Not found' }, 404);
    return jsonResponse({ ok: true, caption: caption || null });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// ── "Add your dish" (founder, 2026-10-03) ─────────────────────────────────────
// A traveler's photo of what they ordered, posted only with proof they were
// there — device GPS within DISH_PROOF_M of the place, or the photo's own
// location tag within it — and only after the photo review passes AND food or a
// drink is the main subject. Posts are anonymous; "ordered by N travelers"
// counts them (one per traveler per dish per place); "· N loved it" counts the
// travelers who said so — the only verdict ever shown; "⭐ favorite of N" counts
// the travelers who called it their favorite dish here (one per traveler per
// place, founder 2026-10-05).
const DISH_PROOF_M = 150;
const DISH_PROOF_ATTRACTION_M = 1500;

const dishKey = (v) => String(v || '').normalize('NFKD').replace(/[̀-ͯ]/g, '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, ' ').trim();
// Canonical place id: an owned uuid becomes its Google id once one is known,
// so the same restaurant collects one set of dishes. Reads check both.
// Things to Do's own ids ("icon:Q…", "wikidata:…", 2026-10-26) resolve the way the
// guestbook's do, so a card and its attraction page share one set of photos.
async function dishPlaceIds(env, raw) {
  const id = String(raw || '').trim();
  if (/^[a-z]+:[A-Za-z0-9:_.-]{1,190}$/.test(id) && !id.startsWith('board:')) {
    const g = await gbEntityIds(env, id).catch(() => null);
    const gid = g && g.canon !== id && /^[A-Za-z0-9_-]{8,200}$/.test(g.canon) ? g.canon : null;
    return gid ? { canon: gid, all: [gid, id] } : { canon: id, all: [id] };
  }
  if (!/^[A-Za-z0-9_-]{8,200}$/.test(id)) return null;
  if (/^[0-9a-f]{8}-[0-9a-f]{4}-/i.test(id) && env.GLOBESKIMMERS_KV) {
    const gid = await env.GLOBESKIMMERS_KV.get(`owned2gid:${id}`).catch(() => null);
    if (gid && gid !== 'none' && /^[A-Za-z0-9_-]{8,200}$/.test(gid)) return { canon: gid, all: [gid, id] };
  }
  return { canon: id, all: [id] };
}
// A dish photo goes out by the dish post's id, never by its key (gbRowMedia).
function dishSummary(rows, origin) {
  const by = new Map();
  for (const r of rows) {
    const g = by.get(r.dish_key) || { dish: r.dish, travelers: new Set(), loved: new Set(), favorite: new Set(), photos: [], last: r.created_at };
    g.travelers.add(r.user_id);
    if (r.liked === true) g.loved.add(r.user_id);
    if (r.favorite === true) g.favorite.add(r.user_id);
    if (g.photos.length < 6) g.photos.push({ id: r.id, url: r.photo_url ? `${origin}/dish-photo/d/${r.id}` : null });
    by.set(r.dish_key, g);
  }
  return [...by.values()]
    .map((g) => ({ dish: g.dish, travelers: g.travelers.size, loved: g.loved.size, favorites: g.favorite.size, photos: g.photos, last: g.last }))
    .sort((a, b) => b.travelers - a.travelers || b.favorites - a.favorites || b.loved - a.loved || String(b.last).localeCompare(String(a.last)));
}

// POST /places/dishes { place_id } → { dishes: [{ dish, travelers, photos }], mine: [{ id, dish }] }
async function handlePlaceDishes(request, env) {
  try {
    const b = await request.json().catch(() => ({}));
    const ids = await dishPlaceIds(env, b.place_id);
    if (!ids) return jsonResponse({ dishes: [], mine: [] });
    const inList = ids.all.map((x) => `"${x}"`).join(',');
    const base = `place_dishes?place_id=in.(${inList})&mod_status=eq.ok&order=created_at.desc&limit=200&select=id,user_id,dish,dish_key,photo_url,liked,created_at`;
    // favorite arrives with migration 20261005090000; until then read without it.
    let q = await gbRest(env, `${base},favorite`, {});
    if (!q.ok) q = await gbRest(env, base, {});
    const rows = q.ok ? await q.json() : [];
    const user = await gbUser(request, env).catch(() => null);
    const mine = user ? rows.filter((r) => r.user_id === user.id).map((r) => ({ id: r.id, dish: r.dish, url: r.photo_url })) : [];
    return jsonResponse({ dishes: dishSummary(rows, new URL(request.url).origin), mine });
  } catch (e) { return jsonResponse({ error: e.message, dishes: [], mine: [] }, 500); }
}

// POST /places/traveler-photos { place_ids: [...] } → { photos: { <id as sent>: [{ id, url, caption }] } }
// Travelers' reviewed photos (dish, drink, find and visit posts) for a page of cards
// in one call, so each card's photo strip carries them next to Google's (founder,
// 2026-10-26: "all photos added by users also go to the restaurant's photos").
// Newest first, six per place; anonymous, like every post.
async function handleTravelerPhotos(request, env) {
  try {
    const b = await request.json().catch(() => ({}));
    const sent = Array.isArray(b.place_ids) ? [...new Set(b.place_ids.map((x) => String(x || '').trim()).filter(Boolean))].slice(0, 40) : [];
    const out = Object.fromEntries(sent.map((id) => [id, []]));
    const resolved = await Promise.all(sent.map((id) => dishPlaceIds(env, id).catch(() => null)));
    const askers = new Map(); // stored place_id → the ids as sent
    resolved.forEach((r, i) => { for (const x of r?.all || []) askers.set(x, [...(askers.get(x) || []), sent[i]]); });
    if (!askers.size) return jsonResponse({ photos: out });
    const inList = [...askers.keys()].map((x) => `"${encodeURIComponent(x)}"`).join(',');
    const q = await gbRest(env, `place_dishes?place_id=in.(${inList})&mod_status=eq.ok&photo_key=not.is.null&order=created_at.desc&limit=400&select=id,place_id,dish`, {});
    const rows = q.ok ? await q.json() : [];
    const origin = new URL(request.url).origin;
    for (const r of rows) {
      for (const id of askers.get(r.place_id) || []) {
        const list = out[id];
        if (list.length < 6 && !list.some((p) => p.id === r.id)) list.push({ id: r.id, url: `${origin}/dish-photo/d/${r.id}`, caption: r.dish || null });
      }
    }
    return jsonResponse({ photos: out });
  } catch (e) { return jsonResponse({ error: e.message, photos: {} }, 500); }
}

// POST /places/dishes/add { place_id, place_name, place_lat, place_lng, kind, dish, liked, favorite, image, lat, lng, acc, exif }
async function handlePlaceDishAdd(request, env, ctx) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in to share your dish' }, 401);
    if (!env.MEDIA) return jsonResponse({ error: 'Photo storage not configured' }, 500);
    const b = await request.json().catch(() => ({}));
    const ids = await dishPlaceIds(env, b.place_id);
    if (!ids) return jsonResponse({ error: 'Unknown place' }, 400);
    // store (founder, 2026-10-05): a convenience store — "what you got here",
    // which can be anything, so the food-as-subject check is skipped.
    // attraction (2026-10-26): a photo from a visit to a Things to Do place — any
    // subject, a caption optional (it files under the place's name), and proof within
    // DISH_PROOF_ATTRACTION_M, since a park or a landmark is bigger than a café.
    const kind = b.kind === 'coffee' ? 'coffee' : b.kind === 'store' ? 'store' : b.kind === 'attraction' ? 'attraction' : 'restaurant';
    const favorite = b.favorite === true && kind !== 'attraction';
    const dish = (String(b.dish || '').replace(/\s+/g, ' ').trim() || (kind === 'attraction' ? String(b.place_name || '').replace(/\s+/g, ' ').trim() : '')).slice(0, 60);
    const key = dishKey(dish);
    if (key.length < 2) return jsonResponse({ error: kind === 'coffee' ? 'What did you order?' : kind === 'store' ? 'What did you get?' : kind === 'attraction' ? 'Add a few words about the photo' : 'What dish is this?' }, 400);

    const sp = await gbSocialProfile(env, user.id).catch(() => undefined);
    if (sp === undefined) return gbAgeUnknownResp();
    // Teens plan (2026-10-10): an unknown age may not post publicly — the
    // birthday gate is the age check, and it must hold at every posting door.
    if (!sp?.birth_year) return jsonResponse({ error: 'Add your birthday in Settings to share photos', code: 'age_required' }, 428);
    if (sp.social_tier === 'blocked') return jsonResponse({ error: 'Sharing isn\'t available on this account' }, 403);
    if (gbAgeHeld(sp)) return gbAgeHeldResp(sp);

    // Where the place is: Google's location from the details cache when we have
    // it, otherwise the coordinates the finder listed it at.
    let pLat = Number(b.place_lat), pLng = Number(b.place_lng);
    if (!/^[0-9a-f]{8}-[0-9a-f]{4}-/i.test(ids.canon)) {
      const cached = await getFromCache(env, `details_${ids.canon}`).catch(() => null);
      const d = cached?.data;
      if (d && Number.isFinite(+d.latitude) && Number.isFinite(+d.longitude)) { pLat = +d.latitude; pLng = +d.longitude; }
    }
    if (!Number.isFinite(pLat) || !Number.isFinite(pLng) || (pLat === 0 && pLng === 0)) return jsonResponse({ error: 'We couldn\'t place this restaurant on the map' }, 400);
    const metersTo = (lat, lng) => (Number.isFinite(lat) && Number.isFinite(lng) && !(lat === 0 && lng === 0)) ? haversineMilesLoc(pLat, pLng, lat, lng) * 1609.34 : Infinity;
    const acc = Number(b.acc);
    const proofM = kind === 'attraction' ? DISH_PROOF_ATTRACTION_M : DISH_PROOF_M;
    const gpsOk = (!Number.isFinite(acc) || acc <= 100) && metersTo(Number(b.lat), Number(b.lng)) <= proofM;
    const exif = b.exif && typeof b.exif === 'object' ? b.exif : null;
    const exifOk = !!exif && metersTo(Number(exif.lat), Number(exif.lng)) <= proofM;
    const proof = gpsOk ? 'gps' : exifOk ? 'photo_loc' : null;
    if (!proof) return jsonResponse({ error: 'proof_needed', message: kind === 'attraction' ? 'Share it while you\'re here, or pick a photo that has its location on.' : 'Share your dish while you\'re here, or pick a photo that has its location on.' }, 409);

    // The posting guard (gbPostGuard: 60 a minute, 1,000 a day; was 12 a day until 2026-10-27).
    const guard = await gbPostGuard(env, `dish:${user.id}`);
    if (guard) return guard;

    let data = String(b.image || '');
    const m = data.match(/^data:image\/(?:jpeg|jpg);base64,(.*)$/i);
    if (m) data = m[1];
    data = data.replace(/\s/g, '');
    let bytes;
    try { bytes = Uint8Array.from(atob(data), (c) => c.charCodeAt(0)); } catch { return jsonResponse({ error: 'Bad image data' }, 400); }
    if (bytes.length < 500 || bytes.length > 4 * 1024 * 1024 || bytes[0] !== 0xff || bytes[1] !== 0xd8) return jsonResponse({ error: 'Please pick a photo (JPEG, under 4 MB)' }, 400);

    if (!(await gbModerate(env, dish)).allow) return jsonResponse({ error: 'Let’s keep dish names kind' }, 422);
    const v = await gbModeratePhoto(env, data, 'image/jpeg');
    if (!v?.allow) return jsonResponse({ error: 'This photo can’t be shared here' }, 422);
    if (!v.food && kind !== 'store' && kind !== 'attraction') return jsonResponse({ error: kind === 'coffee' ? 'Make the drink or treat the star of the photo' : 'Make the dish the star of the photo — get close to the plate' }, 422);

    const photoKey = `dish/${user.id}/${crypto.randomUUID()}.jpg`;
    await env.MEDIA.put(photoKey, bytes, { httpMetadata: { contentType: 'image/jpeg', cacheControl: 'public, max-age=31536000, immutable' } });
    const photoUrl = `${new URL(request.url).origin}/dish-photo/${photoKey}`;

    // One post per traveler per dish per place: a new photo replaces the old one.
    const oq = await gbRest(env, `place_dishes?user_id=eq.${user.id}&place_id=eq.${encodeURIComponent(ids.canon)}&dish_key=eq.${encodeURIComponent(key)}&select=id,photo_key`, {});
    const old = (oq.ok ? await oq.json() : [])[0];
    const row = { user_id: user.id, place_id: ids.canon, place_name: String(b.place_name || '').slice(0, 120) || null, kind, dish, dish_key: key, photo_key: photoKey, photo_url: photoUrl, proof, mod_status: 'ok', created_at: new Date().toISOString(), ...(typeof b.liked === 'boolean' ? { liked: b.liked } : {}) };
    const save = (r) => (old
      ? gbRest(env, `place_dishes?id=eq.${old.id}`, { method: 'PATCH', headers: { Prefer: 'return=representation' }, body: JSON.stringify(r) })
      : gbRest(env, 'place_dishes', { method: 'POST', headers: { Prefer: 'return=representation' }, body: JSON.stringify(r) }));
    let w = await save({ ...row, favorite });
    if (!w.ok && w.status === 400) w = await save(row);   // before the favorite column lands
    if (!w.ok) { await env.MEDIA.delete(photoKey).catch(() => {}); return jsonResponse({ error: (kind === 'store' || kind === 'attraction') && w.status === 400 ? 'Photos here open in a few minutes — try again shortly' : 'Could not save — try again' }, 502); }
    if (old?.photo_key && ctx) ctx.waitUntil(env.MEDIA.delete(old.photo_key).catch(() => {}));
    const saved = (await w.json())[0] || {};
    // One favorite per traveler per place: this one replaces any earlier pick.
    if (favorite && saved.id) {
      const inList = ids.all.map((x) => `"${x}"`).join(',');
      await gbRest(env, `place_dishes?user_id=eq.${user.id}&place_id=in.(${inList})&favorite=eq.true&id=neq.${saved.id}`, { method: 'PATCH', headers: { Prefer: 'return=minimal' }, body: JSON.stringify({ favorite: false }) }).catch(() => {});
    }
    if (ctx) ctx.waitUntil(gbLogEvent(env, 'dish_post', { kind, proof, replaced: !!old, favorite }));
    return jsonResponse({ ok: true, id: saved.id, dish, url: photoUrl, proof, replaced: !!old });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// ── Suggest a Place to Stamp (founder decisions 2026-10-10) ──────────────────
// Crowd-sourced Local favorites. LOCALS (home within 50 km) and VISITORS (a
// proven stamp within 25 km) suggest a real, public place with one reason. The
// same name within 1 km is the same place, so a duplicate adds to its count;
// one person counts once per place (a repeat updates their reason or photo,
// never the count). Everyone sees every suggestion with its count, and likes
// have no limit. At 5 suggestions the founder reviews a place
// (/admin/place-suggestions) and nothing goes live without that approval: an
// approved place becomes a "Local favorite" stamp (entity id lf:<id>) that
// always discloses how many people recommended it and never uses the icon
// art. Tables live in the events D1, created lazily once per isolate. Counts
// are derived on read, never stored, so a deletion can't make them drift; a
// place with no suggestions left is hidden everywhere. Teens are held from
// suggesting (it is publishing) but may like; frozen accounts get nothing.
const PS_REASONS = [
  { key: 'views', label: 'Breathtaking views or a great photo spot', short: 'Views & photos' },
  { key: 'walk', label: 'A fun walk, hike or place to explore', short: 'Walk or hike' },
  { key: 'history', label: 'Local history or culture', short: 'History & culture' },
  { key: 'family', label: 'Great for families and kids', short: 'Families' },
  { key: 'gem', label: 'A hidden gem locals love', short: 'Hidden gem' },
  { key: 'other', label: 'Other (write your own)', short: 'Other' },
];
const PS_REASON_KEYS = new Set(PS_REASONS.map((r) => r.key));
const PS_REVIEW_AT = 5;     // suggestions before the founder reviews a place
const PS_DAILY_MAX = 10;    // suggestions per person per day: the default until the founder decides
const PS_LOCAL_KM = 50, PS_VISITOR_KM = 25, PS_SAME_KM = 1, PS_NEAR_KM = 60;
const PS_SQL = [
  `CREATE TABLE IF NOT EXISTS ps_places (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  name TEXT NOT NULL,
  name_key TEXT NOT NULL,
  lat REAL NOT NULL,
  lng REAL NOT NULL,
  city TEXT,
  region TEXT,
  country TEXT,
  status TEXT NOT NULL DEFAULT 'open',
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  decided_at TEXT
)`,
  'CREATE INDEX IF NOT EXISTS ps_places_geo ON ps_places(lat, lng)',
  `CREATE TABLE IF NOT EXISTS ps_votes (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  place_id INTEGER NOT NULL,
  user_id TEXT NOT NULL,
  reason TEXT NOT NULL,
  other_text TEXT,
  who TEXT NOT NULL,
  photo_key TEXT,
  created_at TEXT NOT NULL,
  updated_at TEXT NOT NULL,
  UNIQUE(place_id, user_id)
)`,
  // "My suggestions" (the Home notice) and the account purge look votes up by person.
  'CREATE INDEX IF NOT EXISTS ps_votes_user ON ps_votes(user_id)',
  `CREATE TABLE IF NOT EXISTS ps_likes (
  place_id INTEGER NOT NULL,
  user_id TEXT NOT NULL,
  reason TEXT NOT NULL DEFAULT '',
  created_at TEXT NOT NULL,
  UNIQUE(place_id, user_id, reason)
)`,
  // Reports (2026-10-12): a suggestion is public from its first vote, so anyone
  // can report one; one report per person per place. resolved = the founder
  // kept or removed the place.
  `CREATE TABLE IF NOT EXISTS ps_reports (
  place_id INTEGER NOT NULL,
  user_id TEXT NOT NULL,
  reason TEXT NOT NULL,
  created_at TEXT NOT NULL,
  resolved INTEGER NOT NULL DEFAULT 0,
  UNIQUE(place_id, user_id)
)`,
  'CREATE INDEX IF NOT EXISTS ps_reports_open ON ps_reports(resolved, place_id)',
  // The daily suggestion count, counted in one atomic statement (KV's
  // read-then-write let a burst of requests past the limit).
  `CREATE TABLE IF NOT EXISTS ps_rate (
  user_id TEXT NOT NULL,
  day TEXT NOT NULL,
  n INTEGER NOT NULL,
  UNIQUE(user_id, day)
)`,
];
let PS_READY = false;
async function psEnsure(env) {
  if (PS_READY) return;
  await env.DB.batch(PS_SQL.map((s) => env.DB.prepare(s)));
  PS_READY = true;
}

// The duplicate key (also how cities are compared): accents stripped, lower
// case, anything but letters and digits one space, a leading "the " dropped.
// Letters of every script count: [a-z0-9] alone would leave a Japanese or
// Greek name an empty key that matched every other one nearby.
const psNameKey = (s) => String(s || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase()
  .replace(/[^\p{L}\p{N}\p{M}]+/gu, ' ').trim().replace(/^the /, '');
const psKm = (lat1, lng1, lat2, lng2) => haversineMilesLoc(lat1, lng1, lat2, lng2) * 1.609344;
const psText = (v, n) => (v == null ? null : String(v).replace(/\s+/g, ' ').trim().slice(0, n) || null);
// A place id from 12, "12" or "lf:12".
const psId = (v) => { const m = /^(?:lf:)?(\d{1,12})$/.exec(String(v ?? '').trim()); return m ? Number(m[1]) : null; };
// open | approved | declined | held (hidden by reports until the founder
// decides) | removed (taken down by the founder). Only open and approved show.
const psStatus = (status, count) => (status && status !== 'open' ? status : count >= PS_REVIEW_AT ? 'review' : 'open');
const PS_REPORT_REASONS = new Set(['not_real', 'offensive', 'private', 'spam', 'other']);
// The pin others may see (2026-10-12): an open place's to 3 decimals (~110 m),
// since "Use my location" may have pinned it where a suggester lives; an
// approved place, which the founder has looked at, exactly (it is stamped
// there). Every public use — the pin shown, the distance, the near list's cut-
// off and order — goes through this, so the exact pin can't be worked out.
const psPubPin = (p, admin = false) => (admin || p.status === 'approved'
  ? { lat: p.lat, lng: p.lng }
  : { lat: Math.round(p.lat * 1000) / 1000, lng: Math.round(p.lng * 1000) / 1000 });
const PS_REPORTS_HIDE = 3;   // distinct reports that hide an open place until the founder decides
const psMapUrl = (p) => `https://www.google.com/maps/search/?api=1&query=${p.lat},${p.lng}`;
// A real point, kept to 5 decimals (about a metre); null when missing or 0,0.
function psPoint(b) {
  const num = (v) => (v == null || v === '' ? NaN : Number(v));
  const lat = num(b?.lat), lng = num(b?.lng);
  if (!Number.isFinite(lat) || !Number.isFinite(lng) || Math.abs(lat) > 90 || Math.abs(lng) > 180 || (lat === 0 && lng === 0)) return null;
  return { lat: Math.round(lat * 1e5) / 1e5, lng: Math.round(lng * 1e5) / 1e5 };
}
// A lat/lng box around a point: the index-friendly first cut (the exact
// distance is checked after). Near a pole or the 180th meridian the
// longitude is left open.
function psBox(lat, lng, km) {
  const dLat = (km / 111.195) * 1.01, cos = Math.cos(lat * Math.PI / 180);
  const dLng = cos > 0.05 ? (km / 111.195 / cos) * 1.05 : 360;
  const open = lng - dLng < -180 || lng + dLng > 180;
  return { lat1: lat - dLat, lat2: lat + dLat, lng1: open ? -180 : lng - dLng, lng2: open ? 180 : lng + dLng, open };
}

// The town, region and country at a point, worked out here (2026-10-12): a
// client's values are never stored or trusted — they were shown to everyone
// unchecked, and the no-pin "local" check compared against them. The same
// precise ~110 m tile and KV cache as /reverse-geocode with precise:true, so
// the form's own lookup a moment earlier has usually warmed it. null when the
// point can't be named (a later suggestion fills the gaps).
async function psGeoAt(env, lat, lng) {
  const key = `revgeoP_${Math.round(lat * 1000) / 1000}_${Math.round(lng * 1000) / 1000}`;
  const kv = env.GLOBESKIMMERS_KV;
  const pick = (h) => ({ city: psText(h.city, 120), region: psText(h.region, 120), country: psText(h.country, 120) });
  if (kv) {
    const hit = await kv.get(key, { type: 'json' }).catch(() => null);
    if (hit && hit.country != null && hit.region !== undefined) return pick(hit);
  }
  if (!env.GOOGLE_API_KEY) return null;
  try {
    const r = await fetch(`https://maps.googleapis.com/maps/api/geocode/json?latlng=${lat},${lng}&key=${env.GOOGLE_API_KEY}`);
    if (!r.ok) return null;
    const d = await r.json();
    if (d.status !== 'OK' || !d.results?.length) return null;
    const comps = d.results[0].address_components || [];
    const cityC = comps.find((c) => hasType(c, 'locality') || hasType(c, 'sublocality') || hasType(c, 'postal_town') || hasType(c, 'administrative_area_level_3') || hasType(c, 'administrative_area_level_2'));
    const stateC = comps.find((c) => hasType(c, 'administrative_area_level_1'));
    const countryC = comps.find((c) => hasType(c, 'country'));
    const country = countryC?.long_name || '';
    // The same coarse admin fields /reverse-geocode caches, in its format.
    const out = { city: cityC?.long_name || '', state_or_country: (countryC?.short_name === 'US' || countryC?.short_name === 'CA') ? (stateC?.long_name || country) : country, country, region: stateC?.long_name || '' };
    if (kv) await kv.put(key, JSON.stringify(out), { expirationTtl: 30 * 86400 }).catch(() => {});
    return pick(out);
  } catch { return null; }
}

// Who may suggest at a point: a LOCAL (home pin within 50 km; with no pin,
// the same home city, case and accents ignored) or a VISITOR (a proven stamp
// — gps, photo_loc or photo_ai — within 25 km). Profiles live in the public
// schema; stamps in the default one.
async function psEligibility(env, userId, lat, lng, city) {
  let home = null;
  try {
    const pr = await gbRest(env, `profiles?id=eq.${userId}&select=home_city,home_lat,home_lng,home_country`, { headers: { 'Accept-Profile': 'public' } });
    home = pr.ok ? (await pr.json())[0] || null : null;
  } catch { /* no profile read: not a local */ }
  const homeCity = psText(home?.home_city, 120);
  const pinned = home?.home_lat != null && home?.home_lng != null && Number.isFinite(+home.home_lat) && Number.isFinite(+home.home_lng);
  const local = pinned
    ? psKm(+home.home_lat, +home.home_lng, lat, lng) <= PS_LOCAL_KM
    : !!psNameKey(homeCity) && psNameKey(homeCity) === psNameKey(city);
  if (local) return { eligible: true, who: 'local', home_city: homeCity };
  try {
    const bx = psBox(lat, lng, PS_VISITOR_KM), f = (v) => v.toFixed(6);
    const lngs = bx.open ? '' : `&lng=gte.${f(bx.lng1)}&lng=lte.${f(bx.lng2)}`;
    const r = await gbRest(env, `passport_stamps?user_id=eq.${userId}&verified=in.(gps,photo_loc,photo_ai)&lat=gte.${f(bx.lat1)}&lat=lte.${f(bx.lat2)}${lngs}&select=lat,lng&limit=200`, {});
    const near = (r.ok ? await r.json() : []).some((s) => s.lat != null && s.lng != null && psKm(lat, lng, +s.lat, +s.lng) <= PS_VISITOR_KM);
    if (near) return { eligible: true, who: 'visitor', home_city: homeCity };
  } catch { /* no stamps read: not a visitor */ }
  return { eligible: false, who: null, home_city: homeCity };
}

// The place a suggestion belongs to: the same name key within 1 km, whatever
// its status (a declined place keeps its decision). The oldest row wins, so
// two people adding the same new place at once end up on one.
async function psFindPlace(env, key, lat, lng) {
  const bx = psBox(lat, lng, PS_SAME_KM + 0.1);   // a public pin sits at most ~56 m from the stored one
  const { results } = await env.DB.prepare('SELECT * FROM ps_places WHERE name_key = ?1 AND lat BETWEEN ?2 AND ?3 AND lng BETWEEN ?4 AND ?5 ORDER BY id LIMIT 50')
    .bind(key, bx.lat1, bx.lat2, bx.lng1, bx.lng2).all();
  // Measured from the public pin (psPubPin, 2026-10-12): which place a probe
  // point lands on must not reveal more than the lists already show.
  return (results || []).find((p) => { const pin = psPubPin(p); return psKm(lat, lng, pin.lat, pin.lng) <= PS_SAME_KM; }) || null;
}

// The approved place behind a Local favorite stamp id (lf:<id>) with its
// suggestion count, or null (unknown, not approved, or no table yet).
async function psApprovedPlace(env, entityId) {
  const m = /^lf:(\d{1,12})$/.exec(String(entityId || ''));
  if (!m || !env.DB) return null;
  const p = await env.DB.prepare("SELECT p.*, (SELECT COUNT(*) FROM ps_votes v WHERE v.place_id = p.id) AS cnt FROM ps_places p WHERE p.id = ? AND p.status = 'approved'")
    .bind(Number(m[1])).first().catch(() => null);
  if (!p || !Number.isFinite(+p.lat) || !Number.isFinite(+p.lng)) return null;
  return { id: p.id, name: p.name, lat: +p.lat, lng: +p.lng, city: p.city || null, region: p.region || null, country: p.country || null, count: Number(p.cnt) || 0 };
}

// PlaceSummary for each row, in order, counted right now. `me` fills `my`
// (my suggestion and my likes), `at` the distance from a point, and `texts`
// every "Other" text, newest first. `admin` (the founder's desk and export)
// adds the locals/visitors split, up to 6 photos whatever the status, and the
// exact pin. Everyone else (2026-10-12) gets an open place's pin to 3 decimals
// (~110 m) — "Use my location" may have pinned it where a suggester lives —
// with the distance measured from that same rounded pin; an approved place,
// which the founder has looked at, keeps its exact pin for stamping.
async function psSummaries(env, rows, { me = null, at = null, origin = '', texts = false, admin = false } = {}) {
  if (!rows.length) return [];
  const reads = [];
  for (let i = 0; i < rows.length; i += 90) {   // D1 binds at most 100 values a query
    const ids = rows.slice(i, i + 90).map((p) => p.id), qs = ids.map(() => '?').join(',');
    reads.push(['votes', env.DB.prepare(`SELECT place_id, reason, who, COUNT(*) AS n FROM ps_votes WHERE place_id IN (${qs}) GROUP BY place_id, reason, who`).bind(...ids)]);
    reads.push(['likes', env.DB.prepare(`SELECT place_id, reason, COUNT(*) AS n FROM ps_likes WHERE place_id IN (${qs}) GROUP BY place_id, reason`).bind(...ids)]);
    // The newest photo: SQLite takes a bare column from the MAX() row.
    reads.push(['covers', env.DB.prepare(`SELECT place_id, photo_key, MAX(updated_at) AS newest FROM ps_votes WHERE place_id IN (${qs}) AND photo_key IS NOT NULL GROUP BY place_id`).bind(...ids)]);
    if (me) {
      reads.push(['mine', env.DB.prepare(`SELECT place_id, reason FROM ps_votes WHERE user_id = ? AND place_id IN (${qs})`).bind(me, ...ids)]);
      reads.push(['myLikes', env.DB.prepare(`SELECT place_id, reason FROM ps_likes WHERE user_id = ? AND place_id IN (${qs})`).bind(me, ...ids)]);
    }
    if (texts) reads.push(['others', env.DB.prepare(`SELECT place_id, other_text FROM ps_votes WHERE place_id IN (${qs}) AND other_text IS NOT NULL ORDER BY updated_at DESC`).bind(...ids)]);
    if (admin) reads.push(['photos', env.DB.prepare(`SELECT place_id, photo_key FROM ps_votes WHERE place_id IN (${qs}) AND photo_key IS NOT NULL ORDER BY updated_at DESC`).bind(...ids)]);
  }
  const res = await env.DB.batch(reads.map((r) => r[1]));
  const got = {};   // read name → place id → rows
  res.forEach((out, i) => {
    const m = got[reads[i][0]] || (got[reads[i][0]] = new Map());
    for (const r of out.results || []) { if (!m.has(r.place_id)) m.set(r.place_id, []); m.get(r.place_id).push(r); }
  });
  const of = (name, id) => got[name]?.get(id) || [];
  return rows.map((p) => {
    let count = 0, locals = 0, visitors = 0;
    const n = {}, liked = {};
    for (const v of of('votes', p.id)) {
      count += v.n;
      if (v.who === 'local') locals += v.n; else if (v.who === 'visitor') visitors += v.n;
      n[v.reason] = (n[v.reason] || 0) + v.n;
    }
    for (const l of of('likes', p.id)) liked[l.reason] = l.n;
    // Most suggested first; a tie keeps the form's order.
    const reasons = PS_REASONS.filter((r) => n[r.key] > 0).map((r) => ({ ...r, n: n[r.key], likes: liked[r.key] || 0 })).sort((a, b) => b.n - a.n);
    const cover = of('covers', p.id)[0]?.photo_key;
    const mine = of('mine', p.id)[0];
    const myLikes = of('myLikes', p.id).map((l) => l.reason);
    const { lat, lng } = psPubPin(p, admin);
    return {
      id: p.id, name: p.name, city: p.city || null, region: p.region || null, country: p.country || null, lat, lng,
      status: psStatus(p.status, count), count, likes: liked[''] || 0,
      reasons, top_reason: reasons[0]?.key || null,
      cover_url: cover ? `${origin}/ps-photo/${cover}` : null,
      distance_km: at ? Math.round(psKm(at.lat, at.lng, lat, lng) * 10) / 10 : null,
      my: { suggested: !!mine, reason: mine?.reason || null, liked: myLikes.includes(''), liked_reasons: myLikes.filter(Boolean) },
      ...(texts ? { other_texts: of('others', p.id).map((o) => o.other_text) } : {}),
      ...(admin ? { locals, visitors, photos: of('photos', p.id).slice(0, 6).map((r) => `${origin}/ps-photo/${r.photo_key}`) } : {}),
    };
  });
}

// POST /places/suggest/check { lat, lng } → { eligible, who, home_city }
// The Suggest form's banner, once a point is set.
async function handlePlaceSuggestCheck(request, env) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in to suggest a place' }, 401);
    const sp = await gbSocialProfile(env, user.id).catch(() => undefined);
    if (sp === undefined) return gbAgeUnknownResp();
    if (gbUnderAge(sp)) return gbUnderAgeResp();
    if (gbAgeHeld(sp)) return gbAgeHeldResp(sp);
    const b = await request.json().catch(() => ({}));
    const pt = psPoint(b);
    if (!pt) return jsonResponse({ error: 'Set where the place is first' }, 400);
    const geo = await psGeoAt(env, pt.lat, pt.lng);   // the town from the point, not the request
    return jsonResponse(await psEligibility(env, user.id, pt.lat, pt.lng, geo?.city || null));
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// POST /places/suggest { name, lat, lng, reason, other_text?, image? } (the town is worked out here)
//   → { ok, added, place: PlaceSummary }. added = false when this person had
// already suggested the place (their reason / photo is updated instead).
async function handlePlaceSuggest(request, env, ctx) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in to suggest a place' }, 401);
    if (!env.DB) return jsonResponse({ error: 'DB not configured' }, 500);
    // Suggesting is publishing: the age doors of every posting door. An
    // unknown age may not post publicly (teens plan, 2026-10-10).
    const sp = await gbSocialProfile(env, user.id).catch(() => undefined);
    if (sp === undefined) return jsonResponse({ error: 'Couldn’t check your account — try again' }, 503);
    if (gbUnderAge(sp)) return gbUnderAgeResp();
    if (gbAgeHeld(sp)) return gbAgeHeldResp(sp);
    if (!sp?.birth_year) return jsonResponse({ error: 'Add your birthday in Settings to suggest a place', code: 'age_required' }, 428);
    const b = await request.json().catch(() => ({}));
    const pt = psPoint(b);
    if (!pt) return jsonResponse({ error: 'Set where the place is first' }, 400);
    const name = psText(b.name, 200) || '';
    const key = psNameKey(name);
    if (name.length < 2 || name.length > 80 || !key) return jsonResponse({ error: 'Enter the place’s name (2–80 characters)' }, 400);
    const reason = String(b.reason || '');
    if (!PS_REASON_KEYS.has(reason)) return jsonResponse({ error: 'Pick why you recommend it' }, 400);
    const other = reason === 'other' ? psText(b.other_text, 400) || '' : null;
    if (other !== null && (other.length < 2 || other.length > 140)) return jsonResponse({ error: 'Tell us why (2–140 characters)' }, 400);
    // A place the founder already declined or removed keeps that decision, and
    // one hidden by reports waits for it: say so now, before a photo is checked
    // or a vote is kept that no list would show.
    await psEnsure(env);
    const prior = (await psFindPlace(env, key, pt.lat, pt.lng))?.status;
    if (prior === 'declined' || prior === 'removed') {
      return jsonResponse({ error: 'We’ve already reviewed this place, and it won’t become a stamp.', code: 'declined' }, 409);
    }
    if (prior === 'held') return jsonResponse({ error: 'This place is being reviewed — try again later.', code: 'held' }, 409);
    // The optional photo: a data URL or bare base64, JPEG / PNG / WebP by its
    // own bytes, up to 4 MB. Moderated below, before anything is stored.
    let img = null;
    if (b.image) {
      if (!env.MEDIA) return jsonResponse({ error: 'Photo storage not configured' }, 500);
      const data = String(b.image).replace(/^data:image\/[a-z0-9.+-]+;base64,/i, '').replace(/\s/g, '');
      let bytes;
      try { bytes = Uint8Array.from(atob(data), (c) => c.charCodeAt(0)); } catch { return jsonResponse({ error: 'Bad image data' }, 400); }
      const type = bytes[0] === 0xff && bytes[1] === 0xd8 ? 'image/jpeg'
        : bytes[0] === 0x89 && bytes[1] === 0x50 && bytes[2] === 0x4e && bytes[3] === 0x47 ? 'image/png'
        : String.fromCharCode(...bytes.slice(8, 12)) === 'WEBP' ? 'image/webp' : null;
      if (!type || bytes.length < 500 || bytes.length > 4 * 1024 * 1024) return jsonResponse({ error: 'Please pick a photo (JPEG, PNG or WebP, under 4 MB)' }, 400);
      img = { data, bytes, type, ext: type === 'image/png' ? 'png' : type === 'image/webp' ? 'webp' : 'jpg' };
    }
    // 10 a day, counted per attempt like guestbook notes — in one atomic D1
    // statement, so a burst of parallel requests can't slip past it.
    const day = new Date().toISOString().slice(0, 10);
    const rate = await env.DB.prepare('INSERT INTO ps_rate (user_id, day, n) VALUES (?1, ?2, 1) ON CONFLICT(user_id, day) DO UPDATE SET n = n + 1 RETURNING n')
      .bind(user.id, day).first();
    if (Number(rate?.n) === 1 && ctx) {   // once a day per person: drop counts older than yesterday
      const old = new Date(Date.now() - 2 * 86400e3).toISOString().slice(0, 10);
      ctx.waitUntil(env.DB.prepare('DELETE FROM ps_rate WHERE day < ?').bind(old).run().catch(() => {}));
    }
    if (Number(rate?.n) > PS_DAILY_MAX) return jsonResponse({ error: 'That’s a lot of suggestions for one day — try again tomorrow', code: 'busy' }, 429);
    // The name and the reason are public at once: no links, and the moderation door.
    if (/https?:\/\/|\bwww\./i.test(`${name} ${other || ''}`) || !(await gbModerate(env, other ? `${name}\n${other}` : name)).allow) {
      return jsonResponse({ error: 'Please keep it about the place, and kind.', code: 'moderated' }, 400);
    }
    // The town comes from the point, never the request: it is shown to
    // everyone, and the no-pin "local" check compares against it.
    const geo = await psGeoAt(env, pt.lat, pt.lng);
    const city = geo?.city || null, region = geo?.region || null, country = geo?.country || null;
    const elig = await psEligibility(env, user.id, pt.lat, pt.lng, city);
    if (!elig.eligible) return jsonResponse({ error: "Suggestions come from locals and people who've been — get a stamp near here first.", code: 'not_eligible' }, 403);
    if (img) {
      const v = await gbModeratePhoto(env, img.data, img.type);   // fails closed
      if (!v.allow) {
        if (ctx) ctx.waitUntil(gbLogEvent(env, 'place_suggest_photo_blocked', { reason: v.reason || 'content' }));
        return jsonResponse({ error: "That photo can't be used — please share a photo of the place.", code: 'photo_blocked' }, 400);
      }
    }

    const now = new Date().toISOString();
    let place = await psFindPlace(env, key, pt.lat, pt.lng);
    const orphan = place?.status === 'open' && !(await env.DB.prepare('SELECT 1 AS x FROM ps_votes WHERE place_id = ? LIMIT 1').bind(place.id).first());
    if (orphan) {
      // Nobody's suggestion is left on this row (its suggester deleted their
      // account): it starts over as this person's — their name, pin and town.
      await env.DB.prepare('UPDATE ps_places SET name = ?1, lat = ?2, lng = ?3, city = ?4, region = ?5, country = ?6, created_at = ?7, updated_at = ?7 WHERE id = ?8')
        .bind(name, pt.lat, pt.lng, city, region, country, now, place.id).run();
      place = { ...place, name, lat: pt.lat, lng: pt.lng, city, region, country, created_at: now, updated_at: now };
    } else if (place) {
      await env.DB.prepare('UPDATE ps_places SET updated_at = ?1, city = COALESCE(city, ?2), region = COALESCE(region, ?3), country = COALESCE(country, ?4) WHERE id = ?5')
        .bind(now, city, region, country, place.id).run();
      place = { ...place, city: place.city || city, region: place.region || region, country: place.country || country };
    } else {
      const ins = await env.DB.prepare("INSERT INTO ps_places (name, name_key, lat, lng, city, region, country, status, created_at, updated_at) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, 'open', ?8, ?8)")
        .bind(name, key, pt.lat, pt.lng, city, region, country, now).run();
      const newId = ins?.meta?.last_row_id;
      place = await psFindPlace(env, key, pt.lat, pt.lng);
      // Someone added the same place a moment earlier: theirs wins, the empty twin goes.
      if (place && newId && place.id !== newId) await env.DB.prepare('DELETE FROM ps_places WHERE id = ?1 AND NOT EXISTS (SELECT 1 FROM ps_votes WHERE place_id = ?1)').bind(newId).run().catch(() => {});
      if (!place) return jsonResponse({ error: 'Could not save — try again' }, 502);
    }
    const prev = await env.DB.prepare('SELECT photo_key FROM ps_votes WHERE place_id = ? AND user_id = ?').bind(place.id, user.id).first();
    let photoKey = null;
    if (img) {
      // No account id in a public link (2026-10-12): the vote row keeps the key,
      // so the purge still finds every photo without it.
      photoKey = `ps/${place.id}/${crypto.randomUUID()}.${img.ext}`;
      await env.MEDIA.put(photoKey, img.bytes, { httpMetadata: { contentType: img.type, cacheControl: 'public, max-age=31536000, immutable' } });
    }
    // One vote per person per place: a repeat updates the reason (and the
    // photo, when a new one comes), never the count.
    try {
      await env.DB.prepare(`INSERT INTO ps_votes (place_id, user_id, reason, other_text, who, photo_key, created_at, updated_at) VALUES (?1, ?2, ?3, ?4, ?5, ?6, ?7, ?7)
        ON CONFLICT(place_id, user_id) DO UPDATE SET reason = excluded.reason, other_text = excluded.other_text, who = excluded.who,
          photo_key = COALESCE(excluded.photo_key, ps_votes.photo_key), updated_at = excluded.updated_at`)
        .bind(place.id, user.id, reason, other, elig.who, photoKey, now).run();
    } catch (e) {
      if (photoKey) await env.MEDIA.delete(photoKey).catch(() => {});
      throw e;
    }
    // A new photo replaces the older one, which comes down from R2.
    if (photoKey && prev?.photo_key && prev.photo_key !== photoKey) await env.MEDIA.delete(prev.photo_key).catch(() => {});
    const added = !prev;
    const [summary] = await psSummaries(env, [place], { me: user.id, origin: new URL(request.url).origin });
    if (ctx) ctx.waitUntil(gbLogEvent(env, 'place_suggest', { place_id: place.id, added, who: elig.who, reason, count: summary.count }));
    return jsonResponse({ ok: true, added, place: summary });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// POST /places/suggestions { lat?, lng?, sort: 'near'|'liked'|'new'|'mine', limit? } → { places }
// Open and approved places with at least one suggestion, never declined ones.
// near: within 60 km by distance (nothing without a point); liked: most
// liked first; new: newest first; mine: the ones I suggested. Any signed-in
// traveler may read.
async function handlePlaceSuggestions(request, env) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in', places: [] }, 401);
    const spRead = gbSocialProfile(env, user.id).catch(() => null);
    if (!env.DB) return jsonResponse({ places: [] });
    await psEnsure(env);
    const b = await request.json().catch(() => ({}));
    const at = psPoint(b);
    const sort = ['near', 'liked', 'new', 'mine'].includes(b.sort) ? b.sort : at ? 'near' : 'new';
    const limit = Math.min(50, Math.max(1, parseInt(b.limit, 10) || 20));
    const LIVE = "p.status IN ('open', 'approved') AND EXISTS (SELECT 1 FROM ps_votes v WHERE v.place_id = p.id)";
    let rows = [];
    if (sort === 'near' && at) {
      const bx = psBox(at.lat, at.lng, PS_NEAR_KM), k = Math.max(0.05, Math.cos(at.lat * Math.PI / 180));
      // The first cut orders by the public pin too (see psPubPin), so a crowded
      // area's 200-row limit can't hint at an exact one.
      const PLAT = "(CASE WHEN p.status = 'approved' THEN p.lat ELSE ROUND(p.lat, 3) END)", PLNG = "(CASE WHEN p.status = 'approved' THEN p.lng ELSE ROUND(p.lng, 3) END)";
      const { results } = await env.DB.prepare(`SELECT p.* FROM ps_places p WHERE ${LIVE} AND p.lat BETWEEN ?1 AND ?2 AND p.lng BETWEEN ?3 AND ?4
          ORDER BY (${PLAT} - ?5) * (${PLAT} - ?5) + ((${PLNG} - ?6) * ?7) * ((${PLNG} - ?6) * ?7), p.id LIMIT 200`)
        .bind(bx.lat1, bx.lat2, bx.lng1, bx.lng2, at.lat, at.lng, k).all();
      // Cut off and ordered by the public pin, never the exact one.
      rows = (results || []).map((p) => { const pin = psPubPin(p); return { p, km: psKm(at.lat, at.lng, pin.lat, pin.lng) }; })
        .filter((x) => x.km <= PS_NEAR_KM).sort((x, y) => x.km - y.km || x.p.id - y.p.id).slice(0, limit).map((x) => x.p);
    } else if (sort === 'liked') {
      const { results } = await env.DB.prepare(`SELECT p.*, (SELECT COUNT(*) FROM ps_likes l WHERE l.place_id = p.id AND l.reason = '') AS lk,
          (SELECT COUNT(*) FROM ps_votes v WHERE v.place_id = p.id) AS cnt
        FROM ps_places p WHERE ${LIVE} ORDER BY lk DESC, cnt DESC, p.id DESC LIMIT ?1`).bind(limit).all();
      rows = results || [];
    } else if (sort === 'new') {
      const { results } = await env.DB.prepare(`SELECT p.* FROM ps_places p WHERE ${LIVE} ORDER BY p.created_at DESC, p.id DESC LIMIT ?1`).bind(limit).all();
      rows = results || [];
    } else if (sort === 'mine') {
      // The places I suggested that are still open, and the ones approved
      // AFTER my suggestion, latest decision first: how Home keeps "We'll let
      // you know if it becomes a stamp". Recommending a place that was already
      // a Local favorite is never announced as my place becoming one. (Both
      // times are toISOString(), so comparing the text compares the time; a
      // repeat suggestion keeps its first created_at.)
      const { results } = await env.DB.prepare(`SELECT p.* FROM ps_places p JOIN ps_votes v ON v.place_id = p.id AND v.user_id = ?1
          WHERE p.status = 'open' OR (p.status = 'approved' AND p.decided_at > v.created_at)
          ORDER BY COALESCE(p.decided_at, p.updated_at) DESC, p.id DESC LIMIT ?2`).bind(user.id, limit).all();
      rows = results || [];
    }
    if (gbUnderAge(await spRead)) return gbUnderAgeResp();
    return jsonResponse({ places: await psSummaries(env, rows, { me: user.id, at, origin: new URL(request.url).origin }) });
  } catch (e) { return jsonResponse({ error: e.message, places: [] }, 500); }
}

// POST /places/suggestion { id, lat?, lng? } → { place: PlaceDetail }: the
// summary plus the 5 newest "Other" texts and the 6 newest photos. 404 for an
// unknown, declined, held or removed place, or one with no suggestions left.
async function handlePlaceSuggestion(request, env) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in' }, 401);
    if (gbUnderAge(await gbSocialProfile(env, user.id).catch(() => null))) return gbUnderAgeResp();
    const b = await request.json().catch(() => ({}));
    const id = psId(b.id);
    if (!id || !env.DB) return jsonResponse({ error: 'Not found' }, 404);
    await psEnsure(env);
    const p = await env.DB.prepare('SELECT * FROM ps_places WHERE id = ?').bind(id).first();
    if (!p || !['open', 'approved'].includes(p.status)) return jsonResponse({ error: 'Not found' }, 404);
    const origin = new URL(request.url).origin;
    const [s] = await psSummaries(env, [p], { me: user.id, at: psPoint(b), origin });
    if (!s.count) return jsonResponse({ error: 'Not found' }, 404);
    const [texts, photos] = await env.DB.batch([
      env.DB.prepare('SELECT other_text FROM ps_votes WHERE place_id = ? AND other_text IS NOT NULL ORDER BY updated_at DESC LIMIT 5').bind(id),
      env.DB.prepare('SELECT photo_key FROM ps_votes WHERE place_id = ? AND photo_key IS NOT NULL ORDER BY updated_at DESC LIMIT 6').bind(id),
    ]);
    return jsonResponse({ place: { ...s, other_texts: (texts.results || []).map((r) => r.other_text), photos: (photos.results || []).map((r) => `${origin}/ps-photo/${r.photo_key}`) } });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// POST /places/like { id, reason?: '' | key, on } → { ok, likes, reason_likes, my }
// Likes have no limit (founder): one per person per place and per reason
// ("I agree"), as a toggle, and the totals just grow. Teens may like.
async function handlePlaceLike(request, env) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in to like a place' }, 401);
    const likeSp = await gbSocialProfile(env, user.id).catch(() => undefined);
    if (likeSp === undefined) return gbAgeUnknownResp();
    if (gbUnderAge(likeSp)) return gbUnderAgeResp();
    if (gbNeedsConfirm(likeSp)) return gbConfirmResp();
    if (!env.DB) return jsonResponse({ error: 'DB not configured' }, 500);
    const b = await request.json().catch(() => ({}));
    const id = psId(b.id);
    const reason = b.reason == null ? '' : String(b.reason);
    if (!id || typeof b.on !== 'boolean' || (reason && !PS_REASON_KEYS.has(reason))) return jsonResponse({ error: 'id, on and a known reason required' }, 400);
    await psEnsure(env);
    const live = await env.DB.prepare("SELECT id FROM ps_places WHERE id = ?1 AND status IN ('open', 'approved') AND EXISTS (SELECT 1 FROM ps_votes WHERE place_id = ?1)").bind(id).first();
    if (!live) return jsonResponse({ error: 'Not found' }, 404);
    if (b.on) await env.DB.prepare('INSERT OR IGNORE INTO ps_likes (place_id, user_id, reason, created_at) VALUES (?, ?, ?, ?)').bind(id, user.id, reason, new Date().toISOString()).run();
    else await env.DB.prepare('DELETE FROM ps_likes WHERE place_id = ? AND user_id = ? AND reason = ?').bind(id, user.id, reason).run();
    const [all, vote, mine] = await env.DB.batch([
      env.DB.prepare('SELECT reason, COUNT(*) AS n FROM ps_likes WHERE place_id = ? GROUP BY reason').bind(id),
      env.DB.prepare('SELECT reason FROM ps_votes WHERE place_id = ? AND user_id = ?').bind(id, user.id),
      env.DB.prepare('SELECT reason FROM ps_likes WHERE place_id = ? AND user_id = ?').bind(id, user.id),
    ]);
    const reasonLikes = Object.fromEntries(PS_REASONS.map((r) => [r.key, 0]));
    let likes = 0;
    for (const r of all.results || []) { if (r.reason === '') likes = r.n; else if (PS_REASON_KEYS.has(r.reason)) reasonLikes[r.reason] = r.n; }
    const myVote = (vote.results || [])[0], myLikes = (mine.results || []).map((r) => r.reason);
    return jsonResponse({ ok: true, likes, reason_likes: reasonLikes, my: { suggested: !!myVote, reason: myVote?.reason || null, liked: myLikes.includes(''), liked_reasons: myLikes.filter(Boolean) } });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// POST /places/report { id, reason } → { ok, already } (2026-10-12)
// A suggestion is public from its first vote, so anyone signed in may report
// one — teens too: reporting is a safety door, not publishing. One report per
// person per place. Three distinct reports hide an open place ('held') until
// the founder decides on the admin desk's Reported tab; an approved place
// stays up (people hold its stamp) and is only flagged. The founder's bell
// rings for a place's first report and when one is hidden.
async function handlePlaceReport(request, env, ctx) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in to report a place' }, 401);
    if (gbUnderAge(await gbSocialProfile(env, user.id).catch(() => null))) return gbUnderAgeResp();
    if (!env.DB) return jsonResponse({ error: 'DB not configured' }, 500);
    const b = await request.json().catch(() => ({}));
    const id = psId(b.id);
    const reason = String(b.reason || '');
    if (!id || !PS_REPORT_REASONS.has(reason)) return jsonResponse({ error: 'id and a known reason required' }, 400);
    // The App's one daily report allowance (gbReportCapped).
    const capped = await gbReportCapped(env, user.id);
    if (capped) return capped;
    await psEnsure(env);
    const p = await env.DB.prepare("SELECT id, name, status FROM ps_places WHERE id = ? AND status IN ('open', 'approved', 'held')").bind(id).first();
    if (!p) return jsonResponse({ error: 'Not found' }, 404);
    const now = new Date().toISOString();
    // The insert and the count in one batch (one transaction): of two reports
    // landing together, exactly one sees n = 1 and rings the bell.
    const [ins, open] = await env.DB.batch([
      env.DB.prepare('INSERT OR IGNORE INTO ps_reports (place_id, user_id, reason, created_at) VALUES (?, ?, ?, ?)').bind(id, user.id, reason, now),
      env.DB.prepare('SELECT COUNT(*) AS n FROM ps_reports WHERE place_id = ? AND resolved = 0').bind(id),
    ]);
    const already = !(Number(ins?.meta?.changes) > 0);
    if (!already) {
      const n = Number(open?.results?.[0]?.n) || 0;
      let hidden = false;
      if (p.status === 'open' && n >= PS_REPORTS_HIDE) {
        const up = await env.DB.prepare("UPDATE ps_places SET status = 'held', updated_at = ? WHERE id = ? AND status = 'open'").bind(now, id).run();
        hidden = Number(up?.meta?.changes) > 0;
      }
      // Every report rings (founder, 2026-10-26: "when any report is selected/submitted"), within one reporter's
      // daily allowance (founderAlert's `by`).
      if (ctx) {
        ctx.waitUntil(founderAlert(env, `🚩 A place suggestion was reported${hidden ? ` ${n} times — hidden until you decide` : n > 1 ? ` (${n} open reports)` : ''}: "${p.name}" (${reason}). Admin → Place suggestions → Reported.`, 'report', { by: user.id }));
      }
      if (ctx) ctx.waitUntil(gbLogEvent(env, 'place_report', { place_id: id, reason, n, hidden }));
    }
    return jsonResponse({ ok: true, already });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

// Signed photo links for the founder's desk (2026-10-12): /ps-photo/ serves
// only open and approved places, but deciding Keep / Remove on a place that
// reports hid means seeing its photos. An <img> can't carry the admin's
// sign-in, so the desk's links carry a one-hour signature instead.
const PS_SIGN_TTL = 3600;
async function psPhotoSig(env, key, exp) {
  const secret = env.PS_PHOTO_SECRET || env.SUPABASE_SERVICE_ROLE_KEY || env.SUPABASE_SERVICE_KEY;
  if (!secret) return null;
  const k = await crypto.subtle.importKey('raw', new TextEncoder().encode(`ps-photo:${secret}`), { name: 'HMAC', hash: 'SHA-256' }, false, ['sign']);
  const mac = new Uint8Array(await crypto.subtle.sign('HMAC', k, new TextEncoder().encode(`${key}|${exp}`)));
  return [...mac.slice(0, 16)].map((x) => x.toString(16).padStart(2, '0')).join('');
}
async function psSignedPhotoUrl(env, url, exp) {
  const key = String(url).split('/ps-photo/')[1];
  const sig = key ? await psPhotoSig(env, key, exp) : null;
  return sig ? `${url}?exp=${exp}&sig=${sig}` : url;
}

// GET /ps-photo/<key> — a suggestion photo from R2: public like guestbook
// photos, moderated before it was stored. Only ps/ keys, and only while the
// place is open or approved.
async function handlePlaceSuggestPhotoServe(request, env) {
  try {
    if (!env.MEDIA) return new Response('Not found', { status: 404 });
    const key = decodeURIComponent(new URL(request.url).pathname.replace(/^\/ps-photo\//, ''));
    if (!/^ps\/\d{1,12}\/(?:[0-9a-f-]{36}\/)?[0-9a-f-]{36}\.(?:jpg|png|webp)$/i.test(key)) return new Response('Bad key', { status: 400 });
    // Only an open or approved place's photos are served (2026-10-12): a place
    // hidden by reports or removed by the founder takes its photos down too.
    const gone = new Response('Not found', { status: 404, headers: { 'Cache-Control': 'no-store' } });
    if (!env.DB) return gone;
    const place = await env.DB.prepare('SELECT status FROM ps_places WHERE id = ?').bind(Number(/^ps\/(\d{1,12})\//.exec(key)[1])).first().catch(() => null);
    if (!place) return gone;
    const shown = ['open', 'approved'].includes(place.status);
    if (!shown) {
      // The founder's desk: a signed, unexpired link (see psPhotoSig).
      const q = new URL(request.url).searchParams;
      const exp = Number(q.get('exp')), sig = String(q.get('sig') || '');
      const want = Number.isFinite(exp) && exp > Date.now() / 1000 ? await psPhotoSig(env, key, exp) : null;
      let same = !!want && want.length === sig.length;
      for (let i = 0; same && i < want.length; i++) same = want.charCodeAt(i) === sig.charCodeAt(i);
      if (!same) return gone;
    }
    const obj = await env.MEDIA.get(key);
    if (!obj) return new Response('Not found', { status: 404 });
    const headers = new Headers();
    headers.set('Content-Type', obj.httpMetadata?.contentType || 'image/jpeg');
    // A day, not a year: a takedown has to reach phones that saw the photo.
    // A hidden place's photo (the desk's signed link) is never cached.
    headers.set('Cache-Control', shown ? 'public, max-age=86400' : 'private, no-store');
    headers.set('Access-Control-Allow-Origin', '*');
    headers.set('X-Content-Type-Options', 'nosniff');
    if (obj.httpEtag) headers.set('ETag', obj.httpEtag);
    return new Response(obj.body, { headers });
  } catch { return new Response('Error', { status: 500 }); }
}

// POST /admin/place-suggestions { op: 'list'|'decide'|'csv', tab?, id?, decision?, as? }
// The founder's review desk: places with 5 or more suggestions, plus any
// reported place. list → { places: AdminPlace[], counts }: Ready (open, 5+) /
// Approved / Declined / Reported (unresolved reports or hidden by them, any
// count; each place carries reports { n, reasons }). decide → Approve (a Local
// favorite stamp) or Decline a place with 5+; Remove (a takedown) or Keep (the
// reports were wrong) at any count. csv → every place with 5+ as a
// spreadsheet Excel opens directly.
async function handleAdminPlaceSuggestions(request, env, ctx) {
  const denied = await requireAdmin(request, env);
  if (denied) return denied;
  try {
    if (!env.DB) return jsonResponse({ error: 'DB not configured', places: [] }, 500);
    await psEnsure(env);
    const body = await request.json().catch(() => ({}));
    const op = ['list', 'decide', 'csv'].includes(body?.op) ? body.op : 'list';
    const origin = new URL(request.url).origin;
    const CNT = '(SELECT COUNT(*) FROM ps_votes v WHERE v.place_id = p.id)';
    const HAS = 'EXISTS (SELECT 1 FROM ps_votes v WHERE v.place_id = p.id)';
    // Unresolved reports, or hidden by them: the Reported tab (2026-10-12).
    const REPORTED = "(p.status = 'held' OR EXISTS (SELECT 1 FROM ps_reports r WHERE r.place_id = p.id AND r.resolved = 0))";
    if (op === 'decide') {
      const id = psId(body?.id);
      const decision = ['approved', 'declined', 'removed', 'keep'].includes(body?.decision) ? body.decision : null;
      if (!id || !decision) return jsonResponse({ error: 'id and decision required' }, 400);
      const p = await env.DB.prepare(`SELECT p.id, p.status, ${CNT} AS cnt FROM ps_places p WHERE p.id = ?`).bind(id).first();
      if (!p) return jsonResponse({ error: 'Not found' }, 404);
      // Approve and Decline are the review, at 5 or more. Remove (a takedown)
      // and Keep (the reports were wrong) work at any count (2026-10-12).
      if ((decision === 'approved' || decision === 'declined') && p.cnt < PS_REVIEW_AT) {
        return jsonResponse({ error: `A place is reviewed once ${PS_REVIEW_AT} people suggest it` }, 409);
      }
      const now = new Date().toISOString();
      const resolve = env.DB.prepare('UPDATE ps_reports SET resolved = 1 WHERE place_id = ?').bind(id);
      if (decision === 'keep') {
        await env.DB.batch([resolve, env.DB.prepare("UPDATE ps_places SET status = 'open', updated_at = ?1 WHERE id = ?2 AND status = 'held'").bind(now, id)]);
      } else if (decision === 'removed') {
        // A takedown is final for the photos (2026-10-12): they come out of R2.
        const { results: ph } = await env.DB.prepare('SELECT photo_key FROM ps_votes WHERE place_id = ? AND photo_key IS NOT NULL').bind(id).all();
        await env.DB.batch([
          env.DB.prepare('UPDATE ps_places SET status = ?1, decided_at = ?2, updated_at = ?2 WHERE id = ?3').bind(decision, now, id),
          resolve,
          env.DB.prepare('UPDATE ps_votes SET photo_key = NULL WHERE place_id = ?').bind(id),
        ]);
        if (env.MEDIA) await Promise.all((ph || []).map((r) => env.MEDIA.delete(r.photo_key).catch(() => {})));
      } else {
        // Only from 'open': a card loaded before reports hid the place, or
        // before it was decided on another device, can't publish it.
        const up = await env.DB.prepare("UPDATE ps_places SET status = ?1, decided_at = ?2, updated_at = ?2 WHERE id = ?3 AND status = 'open'").bind(decision, now, id).run();
        if (!(Number(up?.meta?.changes) > 0)) return jsonResponse({ error: 'This place changed since the list loaded. Reload to see where it stands.', code: 'stale' }, 409);
      }
      if (ctx) ctx.waitUntil(gbLogEvent(env, 'place_decided', { place_id: id, decision, count: p.cnt, from: p.status }));
      return jsonResponse({ ok: true });
    }
    if (op === 'csv') {
      const { results } = await env.DB.prepare(`SELECT p.*, ${CNT} AS cnt FROM ps_places p WHERE ${CNT} >= ? ORDER BY cnt DESC, p.id LIMIT 5000`).bind(PS_REVIEW_AT).all();
      const rows = results || [];
      const places = await psSummaries(env, rows, { origin, texts: true, admin: true });
      const head = ['Place', 'City', 'Region', 'Country', 'Lat', 'Lng', 'Map link', 'Status', 'Suggestions', 'Locals', 'Visitors', 'Likes', 'Top reasons', 'Other texts', 'First suggested', 'Decided'];
      const statusName = { open: 'Ready', review: 'Ready', approved: 'Approved', declined: 'Declined', held: 'Hidden by reports', removed: 'Removed' };
      const when = (v) => String(v || '').replace('T', ' ').slice(0, 16);
      const lines = places.map((s, i) => [
        s.name, s.city, s.region, s.country, s.lat, s.lng, psMapUrl(s), statusName[s.status], s.count, s.locals, s.visitors, s.likes,
        s.reasons.map((r) => `${r.short} (${r.n})`).join(', '), s.other_texts.join(' | '), when(rows[i].created_at), when(rows[i].decided_at),
      ].map(csvCell).join(','));
      // The byte-order mark makes Excel read accents and curly quotes correctly.
      const csv = '\uFEFF' + [head.map(csvCell).join(','), ...lines].join('\r\n');
      const filename = `place-suggestions-${new Date().toISOString().slice(0, 10)}.csv`;
      // The app's admin page asks for it as JSON (its HTTP layer reads JSON) and
      // hands it to the share sheet; a browser gets the file.
      if (body?.as === 'json') return jsonResponse({ filename, csv, rows: places.length });
      return new Response(csv, { status: 200, headers: { 'Content-Type': 'text/csv; charset=utf-8', 'Content-Disposition': `attachment; filename="${filename}"`, ...CORS_HEADERS } });
    }
    const tab = ['ready', 'approved', 'declined', 'reported'].includes(body?.tab) ? body.tab : 'ready';
    const limit = Math.min(500, Math.max(1, parseInt(body?.limit, 10) || 200));
    const OPEN_REPORTS = '(SELECT COUNT(*) FROM ps_reports r WHERE r.place_id = p.id AND r.resolved = 0)';
    const list = tab === 'ready'
      ? env.DB.prepare(`SELECT p.*, ${CNT} AS cnt FROM ps_places p WHERE p.status = 'open' AND ${CNT} >= ?1 ORDER BY cnt DESC, p.id LIMIT ?2`).bind(PS_REVIEW_AT, limit)
      : tab === 'reported'
        // Any count — a takedown can't wait for 5 suggestions. Most reported first.
        ? env.DB.prepare(`SELECT p.* FROM ps_places p WHERE p.status IN ('open', 'approved', 'held') AND ${REPORTED} ORDER BY ${OPEN_REPORTS} DESC, p.updated_at DESC LIMIT ?1`).bind(limit)
        : env.DB.prepare(`SELECT p.* FROM ps_places p WHERE p.status = ?1 AND ${HAS} ORDER BY p.decided_at DESC, p.id DESC LIMIT ?2`).bind(tab, limit);
    const [{ results }, { results: totals }] = await env.DB.batch([list, env.DB.prepare(`SELECT
        COALESCE(SUM(CASE WHEN p.status = 'open' AND ${CNT} >= ?1 THEN 1 ELSE 0 END), 0) AS ready,
        COALESCE(SUM(CASE WHEN p.status = 'approved' AND ${HAS} THEN 1 ELSE 0 END), 0) AS approved,
        COALESCE(SUM(CASE WHEN p.status = 'declined' AND ${HAS} THEN 1 ELSE 0 END), 0) AS declined,
        COALESCE(SUM(CASE WHEN p.status IN ('open', 'approved', 'held') AND ${REPORTED} THEN 1 ELSE 0 END), 0) AS reported
      FROM ps_places p`).bind(PS_REVIEW_AT)]);
    const rows = results || [];
    // Each place's unresolved reports by reason (D1 binds at most 100 values a query).
    const reports = new Map();
    for (let i = 0; i < rows.length; i += 90) {
      const ids = rows.slice(i, i + 90).map((r) => r.id);
      const { results: rr } = await env.DB.prepare(`SELECT place_id, reason, COUNT(*) AS n FROM ps_reports WHERE resolved = 0 AND place_id IN (${ids.map(() => '?').join(',')}) GROUP BY place_id, reason`).bind(...ids).all();
      for (const r of rr || []) {
        const m = reports.get(r.place_id) || { n: 0, reasons: {} };
        m.n += Number(r.n) || 0; m.reasons[r.reason] = Number(r.n) || 0;
        reports.set(r.place_id, m);
      }
    }
    const places = (await psSummaries(env, rows, { origin, texts: true, admin: true }))
      .map((s, i) => ({ ...s, created_at: rows[i].created_at, decided_at: rows[i].decided_at || null, map_url: psMapUrl(s), reports: reports.get(rows[i].id) || { n: 0, reasons: {} } }));
    // Signed for an hour, so the desk sees a hidden or declined place's photos too.
    const exp = Math.floor(Date.now() / 1000) + PS_SIGN_TTL;
    for (const pl of places) pl.photos = await Promise.all((pl.photos || []).map((u) => psSignedPhotoUrl(env, u, exp)));
    const t = totals?.[0] || {};
    return jsonResponse({ places, counts: { ready: t.ready || 0, approved: t.approved || 0, declined: t.declined || 0, reported: t.reported || 0 } });
  } catch (e) {
    return jsonResponse({ error: e?.message || 'Failed', places: [] }, 500);
  }
}

// ── Private messages to a place's owner (founder, 2026-10-05) ────────────────
// A traveler writes to the owner of a restaurant, café, store or attraction.
// Never posted. Screened first: complaints and blunt criticism are fine (that is
// what this is for); threats, slurs, sexual content, extortion, spam and
// personal details of staff are blocked; insults aimed at staff and accusations
// of crimes wait for our team. Fails closed to 'hold'. Kept until the owner
// claims and verifies the place. Anonymous unless the traveler signs it.
async function ownerNoteScreen(env, text, placeName) {
  if (!env.ANTHROPIC_API_KEY) return { verdict: 'hold', reason: 'screen-unavailable' };
  try {
    const system = 'You screen PRIVATE messages from customers to the owner of a business (' + String(placeName || 'a place').slice(0, 80) + '). The owner reads them; they are never published. Complaints, criticism, bad experiences, suggestions and compliments are ALLOWED, even blunt ones, even with mild profanity. Reply with ONLY {"verdict":"ok"|"hold"|"block","reason":"<3-6 words>"}. block: threats of violence or harm, hate slurs, sexual content, extortion or demands for money, spam/ads, or personal details of staff (home addresses, phone numbers). hold: insults or harassment aimed at a named or described staff member, accusations of crimes (theft, poisoning, assault), or heavy abusive profanity. ok: everything else.';
    const r = await fetch('https://api.anthropic.com/v1/messages', {
      method: 'POST',
      headers: { 'x-api-key': env.ANTHROPIC_API_KEY, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
      body: JSON.stringify({ model: 'claude-haiku-4-5-20251001', max_tokens: 40, system, messages: [{ role: 'user', content: `MESSAGE:\n${text}` }] }),
    });
    if (!r.ok) return { verdict: 'hold', reason: 'screen-error' };
    const d = await r.json();
    const t = (d.content && d.content[0] && d.content[0].text) || '';
    const v = (t.match(/"verdict"\s*:\s*"(ok|hold|block)"/i) || [])[1];
    const reason = ((t.match(/"reason"\s*:\s*"([^"]{0,80})"/i) || [])[1]) || null;
    return { verdict: v ? v.toLowerCase() : 'hold', reason };
  } catch { return { verdict: 'hold', reason: 'screen-exception' }; }
}

// POST /places/owner-note { entity_type, entity_id, entity_name, body, include_name }
async function handleOwnerNote(request, env, ctx) {
  try {
    const user = await gbUser(request, env);
    if (!user) return jsonResponse({ error: 'Sign in to send a private message' }, 401);
    const b = await request.json().catch(() => ({}));
    const ids = await gbEntityIds(env, gbClean(b.entity_id));
    if (!ids) return jsonResponse({ error: 'Unknown place' }, 400);
    const entityType = ['attraction', 'restaurant', 'coffee', 'store'].includes(b.entity_type) ? b.entity_type : 'place';
    const text = String(b.body || '').replace(/\s+/g, ' ').trim();
    if (text.length < 2) return jsonResponse({ error: 'Write a short message first' }, 400);
    if (text.length > 1000) return jsonResponse({ error: 'Message too long (max 1000 characters)' }, 400);
    const entityName = gbClean(b.entity_name).slice(0, 160) || null;

    const sp = await gbSocialProfile(env, user.id).catch(() => undefined);
    if (sp === undefined) return jsonResponse({ error: 'Couldn’t check your account — try again' }, 503);
    if (!sp?.birth_year) return jsonResponse({ error: 'age_required', message: 'Add your birth year in Settings to send messages.' }, 428);
    if (sp.social_tier === 'blocked') return jsonResponse({ error: 'Messages aren’t available on this account' }, 403);
    if (gbAgeHeld(sp)) return gbAgeHeldResp(sp);
    if (env.GLOBESKIMMERS_KV) {
      const ck = `ownernote:${user.id}:${new Date().toISOString().slice(0, 10)}`;
      const n = Number(await env.GLOBESKIMMERS_KV.get(ck).catch(() => 0)) || 0;
      if (n >= 10) return jsonResponse({ error: 'That’s a lot of messages for one day — try again tomorrow' }, 429);
      await env.GLOBESKIMMERS_KV.put(ck, String(n + 1), { expirationTtl: 2 * 86400 }).catch(() => {});
    }

    const screen = await ownerNoteScreen(env, text, entityName);
    if (screen.verdict === 'block') return jsonResponse({ error: 'We can’t send this — messages can’t include threats, slurs or anyone’s personal details.' }, 422);

    // The name comes from the profile, never the client — and only when the
    // traveler chose to sign. Under-18s are always anonymous. Tier, not raw
    // year math: the tier is exact-birthday aware (founder, 2026-10-05).
    let senderName = null;
    if (b.include_name === true && sp.social_tier === 'adult') {
      try {
        const pr = await gbRest(env, `profiles?id=eq.${user.id}&select=first_name`, { headers: { 'Accept-Profile': 'public' } });
        senderName = ((pr.ok ? await pr.json() : [])[0] || {}).first_name || null;
      } catch { /* sent anonymously */ }
    }
    const row = { user_id: user.id, entity_type: entityType, entity_id: ids.canon, entity_name: entityName, body: text, sender_name: senderName,
      status: screen.verdict === 'ok' ? 'ok' : 'held', screen_reason: screen.reason };
    const w = await gbRest(env, 'owner_notes', { method: 'POST', headers: { Prefer: 'return=minimal' }, body: JSON.stringify(row) });
    if (!w.ok) return jsonResponse({ error: w.status === 404 || w.status === 400 ? 'Private messages open in a few minutes — try again shortly' : 'Could not send — try again' }, 502);
    if (ctx) ctx.waitUntil(gbLogEvent(env, 'owner_note', { entity_type: entityType, status: row.status, signed: !!senderName }));
    return jsonResponse({ ok: true, held: row.status === 'held', signed: !!senderName });
  } catch (e) { return jsonResponse({ error: e.message }, 500); }
}

